INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37132, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "減らす", "is_correct": true, "explanation": "正解。「へらす」は数を少なくするという意味。"}, {"text": "からす", "is_correct": false, "explanation": "「からす」は最初の音が「か」で、「へ」と違う。"}, {"text": "くらす", "is_correct": false, "explanation": "「くらす」は最初の音が「く」で、「へ」と違う。"}, {"text": "ぬらす", "is_correct": false, "explanation": "「ぬらす」は最初の音が「ぬ」で、「へ」と違う。"}, {"text": "そらす", "is_correct": false, "explanation": "「そらす」は最初の音が「そ」で、「へ」と違う。"}], "explanations": {"減らす": "正解。「へらす」は数を少なくするという意味。", "からす": "「からす」は最初の音が「か」で、「へ」と違う。", "くらす": "「くらす」は最初の音が「く」で、「へ」と違う。", "ぬらす": "「ぬらす」は最初の音が「ぬ」で、「へ」と違う。", "そらす": "「そらす」は最初の音が「そ」で、「へ」と違う。"}, "sentence_index": null, "correct_answer": "減らす"}, "level_3": {"options": [{"text": "減らし", "is_correct": true, "explanation": "社員の数を少なくするという意味で、文脈に合う。"}, {"text": "洗い", "is_correct": false, "explanation": "形は合うが、社員の数を洗うという意味が合わない。"}, {"text": "焼き", "is_correct": false, "explanation": "形は合うが、社員の数を焼くという意味が合わない。"}, {"text": "折り", "is_correct": false, "explanation": "形は合うが、社員の数を折るという意味が合わない。"}], "explanations": {"減らし": "社員の数を少なくするという意味で、文脈に合う。", "洗い": "形は合うが、社員の数を洗うという意味が合わない。", "焼き": "形は合うが、社員の数を焼くという意味が合わない。", "折り": "形は合うが、社員の数を折るという意味が合わない。"}, "sentence_index": 0, "correct_answer": "減らし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去年より事故の数が減らす予定だ。", "explanation": "「減らす」は他動詞で、「事故の数が」を主語にして使えない。「減る」が正しい。"}, {"text": "友人に荷物を減らすつもりです。", "explanation": "「減らす」は物を届ける意味ではない。「送る」の意味と混同している。"}, {"text": "熱が高いので、体温を減らすつもりだ。", "explanation": "「体温」とは「減らす」を組み合わせない。「下げる」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_