INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37132, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "減らす", "is_correct": true, "explanation": "正解。「へらす」は数を少なくするという意味。"}, {"text": "ならす", "is_correct": false, "explanation": "「ならす」は最初の音が「な」で、「へ」と違う。"}, {"text": "はらす", "is_correct": false, "explanation": "「はらす」は最初の音が「は」で、「へ」と違う。"}, {"text": "ふらす", "is_correct": false, "explanation": "「ふらす」は最初の音が「ふ」で、「へ」と違う。"}, {"text": "さらす", "is_correct": false, "explanation": "「さらす」は最初の音が「さ」で、「へ」と違う。"}], "explanations": {"減らす": "正解。「へらす」は数を少なくするという意味。", "ならす": "「ならす」は最初の音が「な」で、「へ」と違う。", "はらす": "「はらす」は最初の音が「は」で、「へ」と違う。", "ふらす": "「ふらす」は最初の音が「ふ」で、「へ」と違う。", "さらす": "「さらす」は最初の音が「さ」で、「へ」と違う。"}, "sentence_index": null, "correct_answer": "減らす"}, "level_3": {"options": [{"text": "減らされて", "is_correct": true, "explanation": "人数を少なくされて仕事が回らない、という意味で文脈に合う。"}, {"text": "洗われて", "is_correct": false, "explanation": "形は合うが、人数を洗われるという意味が合わない。"}, {"text": "焼かれて", "is_correct": false, "explanation": "形は合うが、人数を焼かれるという意味が合わない。"}, {"text": "折られて", "is_correct": false, "explanation": "形は合うが、人数を折られるという意味が合わない。"}], "explanations": {"減らされて": "人数を少なくされて仕事が回らない、という意味で文脈に合う。", "洗われて": "形は合うが、人数を洗われるという意味が合わない。", "焼かれて": "形は合うが、人数を焼かれるという意味が合わない。", "折られて": "形は合うが、人数を折られるという意味が合わない。"}, "sentence_index": 6, "correct_answer": "減らされて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天気が悪くて客の数が減らした。", "explanation": "「減らす」は他動詞で、「客の数が」を主語にして使えない。「減った」が正しい。"}, {"text": "祖母に小包を減らしてもらった。", "explanation": "「減らす」は物を届ける意味ではない。「送って」の意味と混同している。"}, {"text": "暑いので、部屋の温度を減らしてもらった。", "explanation": "「温度」とは「減らす」を組み合わせない。「下げて」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_