INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37132, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "使う紙の枚数が減らすために、両面印刷にする。", "corrected_sentence": "使う紙の枚数を減らすために、両面印刷にする。", "error_description": "他動詞「減らす」の対象は「を」で表す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "減らした", "is_correct": true, "explanation": "文末の過去形で、「回数を減らした」と正しい。"}, {"text": "減らさ", "is_correct": false, "explanation": "未然形のままでは文が終わらない。"}, {"text": "減らし", "is_correct": false, "explanation": "連用形のままでは文が終わらない。"}, {"text": "減らされ", "is_correct": false, "explanation": "受身の連用形のままでは文が終わらない。"}], "correct_form": "減らした", "base_form": "減らす", "form_label": "過去形（た形）", "sentence_index": 1, "explanations": {"減らした": "文末の過去形で、「回数を減らした」と正しい。", "減らさ": "未然形のままでは文が終わらない。", "減らし": "連用形のままでは文が終わらない。", "減らされ": "受身の連用形のままでは文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37132, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室の机の数を減れば、広く使える。", "corrected_sentence": "教室の机の数を減らせば、広く使える。", "error_description": "「数を」に続くのは他動詞「減らす」。自動詞「減る」は使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "減らし", "is_correct": true, "explanation": "「ましょう」に続く連用形で、正しい。"}, {"text": "減らさ", "is_correct": false, "explanation": "未然形は「ましょう」に直接つながらない。"}, {"text": "減らして", "is_correct": false, "explanation": "て形に「ましょう」は続かない。"}, {"text": "減らせ", "is_correct": false, "explanation": "可能形の語幹は「ましょう」に直接つながらない。"}], "correct_form": "減らし", "base_form": "減らす", "form_label": "連用形（ます形）", "sentence_index": 7, "explanations": {"減らし": "「ましょう」に続く連用形で、正しい。", "減らさ": "未然形は「ましょう」に直接つながらない。", "減らして": "て形に「ましょう」は続かない。", "減らせ": "可能形の語幹は「ましょう」に直接つながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37133, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「雑音を減らす」と、減らす対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "「雑音に減らし」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「雑音と減らし」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「雑音を減らす」と、減らす対象を表す。", "に": "「雑音に減らし」は文として成り立たない。", "へ": "「へ」は方向を表し、対象を表せない。", "と": "「雑音と減らし」は文として成り立たない。"}, "error_tags": {"に": "target_vs_object", "へ": "direction_vs_object", "と": "companion_vs_object"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増やす", "is_correct": true, "explanation": "数量や程度を高くする意味で、「減らす」の反対。"}, {"text": "削る", "is_correct": false, "explanation": "「削る」は減らすに近い意味で、反対ではない。"}, {"text": "縮める", "is_correct": false, "explanation": "「縮める」は小さくする意味で、反対ではない。"}, {"text": "止める", "is_correct": false, "explanation": "「止める」は続くものを終わらせる意味で、反対ではない。"}], "correct_answer": "増やす", "explanations": {"増やす": "数量や程度を高くする意味で、「減らす」の反対。", "削る": "「削る」は減らすに近い意味で、反対ではない。", "縮める": "「縮める」は小さくする意味で、反対ではない。", "止める": "「止める」は続くものを終わらせる意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
