INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37133, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "数量や程度を低くする。", "primary_collocate": null, "pronunciation": "へらす", "ipa": "heɾasɯ", "syllable_count": 3, "sentences": [{"text": "これらは視覚的な雑音を減らし、心の豊かさを追求する手段となっています。", "target_word": "減らし", "complexity_tier": "T5", "furigana": "これらは視覚的[しかくてき]な雑音[ざつおん]を減[へ]らし、心[こころ]の豊[ゆた]かさを追求[ついきゅう]する手段[しゅだん]となっています。", "sentence_source": "mined"}, {"text": "砂糖を減らします。", "target_word": "減らし", "complexity_tier": "T2", "furigana": "砂糖[さとう]を減[へ]らします。", "sentence_source": "generated"}, {"text": "仕事の量を減らした。", "target_word": "減らした", "complexity_tier": "T2", "furigana": "仕事[しごと]の量[りょう]を減[へ]らした。", "sentence_source": "generated"}, {"text": "無駄な支出を減らして貯金したい。", "target_word": "減らして", "complexity_tier": "T3", "furigana": "無駄[むだ]な支出[ししゅつ]を減[へ]らして貯金[ちょきん]したい。", "sentence_source": "generated"}, {"text": "塩分を減らす食事を心がけている。", "target_word": "減らす", "complexity_tier": "T3", "furigana": "塩分[えんぶん]を減[へ]らす食事[しょくじ]を心[こころ]がけている。", "sentence_source": "generated"}, {"text": "睡眠時間を減らしても、疲れは取れない。", "target_word": "減らしても", "complexity_tier": "T3", "furigana": "睡眠時間[すいみんじかん]を減[へ]らしても、疲[つか]れは取[と]れない。", "sentence_source": "generated"}, {"text": "騒音を減らすために、窓を二重にした。", "target_word": "減らす", "complexity_tier": "T4", "furigana": "騒音[そうおん]を減[へ]らすために、窓[まど]を二重[にじゅう]にした。", "sentence_source": "generated"}, {"text": "負担を減らせるなら、手伝ってもらいたい。", "target_word": "減らせる", "complexity_tier": "T4", "furigana": "負担[ふたん]を減[へ]らせるなら、手伝[てつだ]ってもらいたい。", "sentence_source": "generated"}, {"text": "薬の量を減らさないでください。", "target_word": "減らさ", "complexity_tier": "T3", "furigana": "薬[くすり]の量[りょう]を減[へ]らさないでください。", "sentence_source": "generated"}, {"text": "作業を減らされて、かえって困っている。", "target_word": "減らされて", "complexity_tier": "T4", "furigana": "作業[さぎょう]を減[へ]らされて、かえって困[こま]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "減らし", "label": "活用"}, {"form": "減らした", "label": "活用"}, {"form": "減らせる", "label": "活用"}, {"form": "減らされる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 数量や程度を下げて小さくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be06c00-e07b-4845-a5a1-5b9d6c46fb56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37133, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "減らす", "is_correct": true, "explanation": "正解。「へらす」は数量や程度を低くするという意味。"}, {"text": "からす", "is_correct": false, "explanation": "「からす」は最初の音が「か」で、「へ」と違う。"}, {"text": "くらす", "is_correct": false, "explanation": "「くらす」は最初の音が「く」で、「へ」と違う。"}, {"text": "ぬらす", "is_correct": false, "explanation": "「ぬらす」は最初の音が「ぬ」で、「へ」と違う。"}, {"text": "そらす", "is_correct": false, "explanation": "「そらす」は最初の音が「そ」で、「へ」と違う。"}], "explanations": {"減らす": "正解。「へらす」は数量や程度を低くするという意味。", "からす": "「からす」は最初の音が「か」で、「へ」と違う。", "くらす": "「くらす」は最初の音が「く」で、「へ」と違う。", "ぬらす": "「ぬらす」は最初の音が「ぬ」で、「へ」と違う。", "そらす": "「そらす」は最初の音が「そ」で、「へ」と違う。"}, "sentence_index": null, "correct_answer": "減らす"}, "level_3": {"options": [{"text": "減らし", "is_correct": true, "explanation": "雑音を低くするという意味で、文脈に合う。"}, {"text": "増やし", "is_correct": false, "explanation": "形は合うが、雑音を増やすと心の豊かさの追求に合わない。"}, {"text": "伸ばし", "is_correct": false, "explanation": "形は合うが、雑音を伸ばすという意味が合わない。"}, {"text": "集め", "is_correct": false, "explanation": "形は合うが、雑音を集めると豊かさの手段という意味が合わない。"}], "explanations": {"減らし": "雑音を低くするという意味で、文脈に合う。", "増やし": "形は合うが、雑音を増やすと心の豊かさの追求に合わない。", "伸ばし": "形は合うが、雑音を伸ばすという意味が合わない。", "集め": "形は合うが、雑音を集めると豊かさの手段という意味が合わない。"}, "sentence_index": 0, "correct_answer": "減らし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最近は客が減らして、店が静かだ。", "explanation": "「減らす」は他動詞なので「客が減らす」とは言えない。「客が減って」が正しい。"}, {"text": "友達に誕生日のプレゼントを減らした。", "explanation": "「減らす」は数量を低くする意味で、物を渡す意味はない。「送った」「あげた」の意味と混同している。"}, {"text": "店の人に値段を減らしてもらって、うれしかった。", "explanation": "「値段」とは「減らす」を組み合わせない。「下げる」「安くする」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37133, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "減らす", "is_correct": true, "explanation": "正解。「へらす」は数量や程度を低くするという意味。"}, {"text": "ならす", "is_correct": false, "explanation": "「ならす」は最初の音が「な」で、「へ」と違う。"}, {"text": "はらす", "is_correct": false, "explanation": "「はらす」は最初の音が「は」で、「へ」と違う。"}, {"text": "ふらす", "is_correct": false, "explanation": "「ふらす」は最初の音が「ふ」で、「へ」と違う。"}, {"text": "さらす", "is_correct": false, "explanation": "「さらす」は最初の音が「さ」で、「へ」と違う。"}], "explanations": {"減らす": "正解。「へらす」は数量や程度を低くするという意味。", "ならす": "「ならす」は最初の音が「な」で、「へ」と違う。", "はらす": "「はらす」は最初の音が「は」で、「へ」と違う。", "ふらす": "「ふらす」は最初の音が「ふ」で、「へ」と違う。", "さらす": "「さらす」は最初の音が「さ」で、「へ」と違う。"}, "sentence_index": null, "correct_answer": "減らす"}, "level_3": {"options": [{"text": "減らす", "is_correct": true, "explanation": "騒音を低くするために窓を二重にした、という文脈に合う。"}, {"text": "増やす", "is_correct": false, "explanation": "形は合うが、窓を二重にする目的と意味が合わない。"}, {"text": "強める", "is_correct": false, "explanation": "形は合うが、騒音を強める目的で窓を二重にはしない。"}, {"text": "広げる", "is_correct": false, "explanation": "形は合うが、騒音を広げるという意味が文脈に合わない。"}], "explanations": {"減らす": "騒音を低くするために窓を二重にした、という文脈に合う。", "増やす": "形は合うが、窓を二重にする目的と意味が合わない。", "強める": "形は合うが、騒音を強める目的で窓を二重にはしない。", "広げる": "形は合うが、騒音を広げるという意味が文脈に合わない。"}, "sentence_index": 6, "correct_answer": "減らす"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "最近は雨の日が減らして、洗濯が楽だ。", "explanation": "「減らす」は他動詞なので「雨の日が減らす」とは言えない。「減って」が正しい。"}, {"text": "友達から手紙を減らされて、うれしかった。", "explanation": "「減らす」には届けるという意味がない。「送られて」の意味と混同している。"}, {"text": "急に気温を減らされて、風邪をひいた。", "explanation": "「気温」とは「減らす」を組み合わせない。「下がる」「下げる」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDE