INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37133, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お酒の量を減るようにしている。", "corrected_sentence": "お酒の量を減らすようにしている。", "error_description": "「量を」に続くのは他動詞「減らす」で、自動詞「減る」は使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "減らし", "is_correct": true, "explanation": "「ます」に続く連用形で、正しい。"}, {"text": "減らさ", "is_correct": false, "explanation": "未然形は「ます」に直接つながらない。"}, {"text": "減らす", "is_correct": false, "explanation": "終止形は「ます」に直接つながらない。"}, {"text": "減らした", "is_correct": false, "explanation": "た形に「ます」は続かない。"}], "correct_form": "減らし", "base_form": "減らす", "form_label": "連用形（ます形）", "sentence_index": 1, "explanations": {"減らし": "「ます」に続く連用形で、正しい。", "減らさ": "未然形は「ます」に直接つながらない。", "減らす": "終止形は「ます」に直接つながらない。", "減らした": "た形に「ます」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37133, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ストレスが減らして、気持ちが楽になった。", "corrected_sentence": "ストレスを減らして、気持ちが楽になった。", "error_description": "他動詞「減らす」の対象は「を」で表す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "減らせる", "is_correct": true, "explanation": "「なら」に続く可能形で、「減らすことができる」の意味になる。"}, {"text": "減らして", "is_correct": false, "explanation": "て形に「なら」は続かない。"}, {"text": "減らさ", "is_correct": false, "explanation": "未然形は「なら」に直接つながらない。"}, {"text": "減らし", "is_correct": false, "explanation": "連用形は「なら」に直接つながらない。"}], "correct_form": "減らせる", "base_form": "減らす", "form_label": "可能形", "sentence_index": 7, "explanations": {"減らせる": "「なら」に続く可能形で、「減らすことができる」の意味になる。", "減らして": "て形に「なら」は続かない。", "減らさ": "未然形は「なら」に直接つながらない。", "減らし": "連用形は「なら」に直接つながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37134, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「たまる」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「たまる」は自動詞なので、目的語の「を」は取れない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す「で」で、主語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する「の」で、動詞の前には置けない。"}], "correct_answer": "が", "explanations": {"が": "「たまる」の主語を示す「が」。", "を": "「たまる」は自動詞なので、目的語の「を」は取れない。", "で": "場所や手段を表す「で」で、主語にはならない。", "の": "名詞を修飾する「の」で、動詞の前には置けない。"}, "error_tags": {"を": "自動詞", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37134, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「入れる」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「入れる」は他動詞で、ガスは入れられる対象なので「が」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表す「に」で、「ガスに入れる」は目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」は目的語を示せず、「ガスで入れる」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「入れる」の目的語を示す「を」。", "が": "「入れる」は他動詞で、ガスは入れられる対象なので「が」では文が成り立たない。", "に": "位置や相手を表す「に」で、「ガスに入れる」は目的語にならない。", "で": "手段や場所の「で」は目的語を示せず、「ガスで入れる」は不自然。"}, "error_tags": {"が": "主格", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37134, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気のように目に見えない気体。においや毒を持つものもある。", "primary_collocate": null, "pronunciation": "がす", "ipa": "ɡasɯ", "syllable_count": 2, "sentences": [{"text": "台所でガスのにおいがしたので、すぐに窓を開けた。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "台所[だいどころ]でガスのにおいがしたので、すぐに窓[まど]を開[あ]けた。", "sentence_source": "generated"}, {"text": "この部屋にはガスがたまっていて、危ない。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "この部屋[へや]にはガスがたまっていて、危[あぶ]ない。", "sentence_source": "generated"}, {"text": "ガスは目に見えないので、機械で調べる。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "ガスは目[め]に見[み]えないので、機械[きかい]で調[しら]べる。", "sentence_source": "generated"}, {"text": "火山からガスが出ているため、山に近づけない。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "火山[かざん]からガスが出[で]ているため、山[やま]に近[ちか]づけない。", "sentence_source": "generated"}, {"text": "ガスを吸うと気分が悪くなるので、外に出よう。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "ガスを吸[す]うと気分[きぶん]が悪[わる]くなるので、外[そと]に出[で]よう。", "sentence_source": "generated"}, {"text": "古い井戸の中には、毒のあるガスがたまっていることがある。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "古[ふる]い井戸[いど]の中[なか]には、毒[どく]のあるガスがたまっていることがある。", "sentence_source": "generated"}, {"text": "ガスが漏れていないか、毎晩確認している。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "ガスが漏[も]れていないか、毎晩[まいばん]確認[かくにん]している。", "sentence_source": "generated"}, {"text": "風船にガスを入れると、空に浮かぶ。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "風船[ふうせん]にガスを入[い]れると、空[そら]に浮[う]かぶ。", "sentence_source": "generated"}, {"text": "ガスは見えないが、においで気づくことが多い。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "ガスは見[み]えないが、においで気[き]づくことが多[おお]い。", "sentence_source": "generated"}, {"text": "工場の事故でガスが広がり、近くの人は避難した。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "工場[こうじょう]の事故[じこ]でガスが広[ひろ]がり、近[ちか]くの人[ひと]は避難[ひなん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ガス", "label": "基本形"}, {"form": "ガスが", "label": "主格"}, {"form": "ガスを", "label": "目的格"}, {"form": "ガスの", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "空気のように目に見えない気体の物質（においや毒を持つこともある）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0888c172-05ca-47fc-b033-bf6b11e5f019') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37134, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ガス", "is_correct": true, "explanation": "「ガスのにおい」の形で、台所で感じたにおいの元になる気体を指す。"}, {"text": "甘く", "is_correct": false, "explanation": "形容詞の連用形で、「甘くのにおい」とは続かない。"}, {"text": "強く", "is_correct": false, "explanation": "形容詞の連用形で、「強くのにおい」とは続かない。"}, {"text": "出て", "is_correct": false, "explanation": "動詞のテ形で、名詞「におい」の前には置けない。"}], "explanations": {"ガス": "「ガスのにおい」の形で、台所で感じたにおいの元になる気体を指す。", "甘く": "形容詞の連用形で、「甘くのにおい」とは続かない。", "強く": "形容詞の連用形で、「強くのにおい」とは続かない。", "出て": "動詞のテ形で、名詞「におい」の前には置けない。"}, "sentence_index": 0, "correct_answer": "ガス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みにガスがすっかり伸びた。", "explanation": "ここは〈髪〉の場面。伸びるのは髪などで、ガスは伸びるものではない。"}, {"text": "庭に赤いガスが咲いた。", "explanation": "ここは〈花〉の場面。咲くのは花で、ガスには使わない。"}, {"text": "午後からガスが降り始めた。", "explanation": "ここは〈雨〉の場面。降るのは雨や雪で、ガスは降らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37134, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ガス", "is_correct": true, "explanation": "「ガスが漏れていないか」の形で、確認の対象となる気体を指す。"}, {"text": "毎晩", "is_correct": false, "explanation": "時を表す語で、「毎晩が漏れていないか」とは続かない。"}, {"text": "確認", "is_correct": false, "explanation": "行為を表す名詞で、漏れる主体にはならない。"}, {"text": "乾燥", "is_correct": false, "explanation": "状態を表す語で、「乾燥が漏れていないか」とは続かない。"}], "explanations": {"ガス": "「ガスが漏れていないか」の形で、確認の対象となる気体を指す。", "毎晩": "時を表す語で、「毎晩が漏れていないか」とは続かない。", "確認": "行為を表す名詞で、漏れる主体にはならない。", "乾燥": "状態を表す語で、「乾燥が漏れていないか」とは続かない。"}, "sentence_index": 6, "correct_answer": "ガス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭でガスが跳ね回って、子どもが喜んだ。", "explanation": "ここは〈ボール〉の場面。跳ね回るのはボールや動物などで、目に見えないガスには使わない。"}, {"text": "夜中にガスが降り積もって、朝は道がすっかり埋まっていた。", "explanation": "ここは〈雪〉の場面。降り積もるのは雪で、目に見えないガスには使わない。"}, {"text": "澄んだガスが広がり、遠くの山まで見えた。", "explanation": "ここは〈空気〉の場面。澄むのは空気や水などで、ガスには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37134, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "実験室で有害なガスに集めた。", "corrected_sentence": "実験室で有害なガスを集めた。", "error_description": "「集める」の目的語は「を」で示す。「ガスに集めた」は誤りで、「に」を「を」に直す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37134, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ガスが漏れられている場所を探した。", "corrected_sentence": "ガスが漏れている場所を探した。", "error_description": "「漏れる」は自動詞なので、受け身の「漏れられる」にはできない。「漏れている」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37135, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ガスの匂い」と名詞をつなぐ連体修飾の「の」。"}, {"text": "に", "is_correct": false, "explanation": "「ガスに匂い」とは続かず、位置を表す「に」は名詞の間に入らない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動詞の目的語を示すので、名詞同士の間には入らない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す「で」で、「ガスで匂い」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「ガスの匂い」と名詞をつなぐ連体修飾の「の」。", "に": "「ガスに匂い」とは続かず、位置を表す「に」は名詞の間に入らない。", "を": "「を」は動詞の目的語を示すので、名詞同士の間には入らない。", "で": "場所や手段を表す「で」で、「ガスで匂い」は意味が通らない。"}, "error_tags": {"に": "位置・相手", "を": "目的語", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37135, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「溜まる」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「溜まる」は自動詞なので、目的語の「を」は取れない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す「で」で、主語にはならず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する「の」で、動詞の前には置けない。"}], "correct_answer": "が", "explanations": {"が": "「溜まる」の主語を示す「が」。", "を": "「溜まる」は自動詞なので、目的語の「を」は取れない。", "で": "場所や手段を表す「で」で、主語にはならず文が成り立たない。", "の": "名詞を修飾する「の」で、動詞の前には置けない。"}, "error_tags": {"を": "自動詞", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37135, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "気体の総称。特に、燃料として使われるものや、空気中に存在する物質を指す。", "primary_collocate": null, "pronunciation": "がす", "ipa": "ɡasɯ", "syllable_count": 2, "sentences": [{"text": "人為的な要因によって大気中に放出された過剰なガスは、放射強制力を変化させ、全球規模での気候変動を加速させている。", "target_word": "ガス", "complexity_tier": "T4", "furigana": "人為的[じんいてき]な要因[よういん]によって大気[たいき]中[ちゅう]に放出[ほうしゅつ]された過剰[かじょう]なガスは、放射[ほうしゃ]強制力[きょうせいりょく]を変化[へんか]させ、全球[ぜんきゅう]規模[きぼ]での気候[きこう]変動[へんどう]を加速[かそく]させている。", "sentence_source": "generated"}, {"text": "台所でガスの匂いがしたので、すぐに窓を開けた。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "台所[だいどころ]でガスの匂[にお]いがしたので、すぐに窓[まど]を開[あ]けた。", "sentence_source": "generated"}, {"text": "冬は暖房を使うので、ガスの料金が高くなる。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "冬[ふゆ]は暖房[だんぼう]を使[つか]うので、ガスの料金[りょうきん]が高[たか]くなる。", "sentence_source": "generated"}, {"text": "火山からは有毒なガスが出ているので、近づいてはいけない。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "火山[かざん]からは有毒[ゆうどく]なガスが出[で]ているので、近[ちか]づいてはいけない。", "sentence_source": "generated"}, {"text": "工事のため、今日の午後はガスが止まる。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、今日[きょう]の午後[ごご]はガスが止[と]まる。", "sentence_source": "generated"}, {"text": "風船にヘリウムというガスを入れると、空に浮かぶ。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "風船[ふうせん]にヘリウムというガスを入[い]れると、空[そら]に浮[う]かぶ。", "sentence_source": "generated"}, {"text": "ガスの火を消し忘れて、鍋を焦がしてしまった。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "ガスの火[ひ]を消[け]し忘[わす]れて、鍋[なべ]を焦[こ]がしてしまった。", "sentence_source": "generated"}, {"text": "炭鉱では、ガスが溜まると爆発の危険がある。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "炭鉱[たんこう]では、ガスが溜[た]まると爆発[ばくはつ]の危険[きけん]がある。", "sentence_source": "generated"}, {"text": "理科の実験で、水を電気で分けると二種類のガスが出た。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "理科[りか]の実験[じっけん]で、水[みず]を電気[でんき]で分[わ]けると二種類[にしゅるい]のガスが出[で]た。", "sentence_source": "generated"}, {"text": "古い家ではガスを使わず、電気だけで生活している。", "target_word": "ガス", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]ではガスを使[つか]わず、電気[でんき]だけで生活[せいかつ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ガス", "label": "基本形"}, {"form": "ガスの", "label": "連体形"}, {"form": "ガスが", "label": "主格"}], "register": "neutral", "sense_fingerprint": "気体の総称。燃料用の気体や空気中に存在する気体物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0888c172-05ca-47fc-b033-bf6b11e5f019') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37135, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ガス", "is_correct": true, "explanation": "「過剰なガス」の形で、大気中に放出された気体を指す。"}, {"text": "挨拶", "is_correct": false, "explanation": "「過剰な挨拶」は意味をなさず、放射強制力を変える文に合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "「過剰な音楽」は大気中への放出とも気候変動とも結びつかず、文に合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「過剰な散歩」は放射強制力を変化させる主語にならず、文に合わない。"}], "explanations": {"ガス": "「過剰なガス」の形で、大気中に放出された気体を指す。", "挨拶": "「過剰な挨拶」は意味をなさず、放射強制力を変える文に合わない。", "音楽": "「過剰な音楽」は大気中への放出とも気候変動とも結びつかず、文に合わない。", "散歩": "「過剰な散歩」は放射強制力を変化させる主語にならず、文に合わない。"}, "sentence_index": 0, "correct_answer": "ガス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、窓からガスが差し込んで、部屋が明るくなった。", "explanation": "ここは〈光〉の場面。差し込むのは光で、ガスは窓から差し込んで明るくするものではない。"}, {"text": "夜になると、遠くからガスが響いてきた。", "explanation": "ここは〈音〉の場面。響くのは音で、ガスについて響くという使い方はしない。"}, {"text": "玄関のガスが鳴ったので、ドアを開けた。", "explanation": "ここは〈チャイム〉の場面。鳴るのは呼び鈴などの音で、ガスは鳴らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37135, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ガス", "is_correct": true, "explanation": "「ガスの火」の形で、ガスを燃やす火を表し、消し忘れた火の話に合う。"}, {"text": "水", "is_correct": false, "explanation": "「水の火」とは言わず、消し忘れた火の説明にならない。"}, {"text": "煙", "is_correct": false, "explanation": "「煙の火」とは言わず、火そのものを表す語にならない。"}, {"text": "砂", "is_correct": false, "explanation": "「砂の火」とは言わず、火を修飾する語として不自然。"}], "explanations": {"ガス": "「ガスの火」の形で、ガスを燃やす火を表し、消し忘れた火の話に合う。", "水": "「水の火」とは言わず、消し忘れた火の説明にならない。", "煙": "「煙の火」とは言わず、火そのものを表す語にならない。", "砂": "「砂の火」とは言わず、火を修飾する語として不自然。"}, "sentence_index": 6, "correct_answer": "ガス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "強風で砂のガスが舞い上がり、視界が悪くなった。", "explanation": "ここは〈砂ぼこり〉の場面。舞い上がるのは砂ぼこりなどの細かい粒で、気体のガスには使わない。"}, {"text": "先生が黒板にガスを書いた。", "explanation": "ここは〈文字〉の場面。書くのは文字で、気体のガスは書けない。"}, {"text": "鉛筆のガスが折れて、字が書けなくなった。", "explanation": "ここは〈芯〉の場面。折れるのは鉛筆の芯で、気体のガスは折れない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37135, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬は暖房でガスが使うので、料金が高くなる。", "corrected_sentence": "冬は暖房でガスを使うので、料金が高くなる。", "error_description": "「使う」の目的語は「を」で示す。「ガスが使う」は誤りで、「が」を「を」に直す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37135, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ガスで止めてから、部屋を出た。", "corrected_sentence": "ガスを止めてから、部屋を出た。", "error_description": "「止める」は他動詞で、目的語は「を」で示す。「で」は誤りで、「で」を「を」に直す必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
