INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37136, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や空気を外に送り出すこと。", "primary_collocate": null, "pronunciation": "だす", "ipa": "dasɯ", "syllable_count": 2, "sentences": [{"text": "深呼吸では、息をゆっくり出すことが大切だ。", "target_word": "出す", "complexity_tier": "T3", "furigana": "深呼吸[しんこきゅう]では、息[いき]をゆっくり出[だ]すことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "窓を開けて、部屋にこもった煙を外に出した。", "target_word": "出した", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けて、部屋[へや]にこもった煙[けむり]を外[そと]に出[だ]した。", "sentence_source": "generated"}, {"text": "ポケットから財布を出して、レジでお金を払った。", "target_word": "出して", "complexity_tier": "T3", "furigana": "ポケットから財布[さいふ]を出[だ]して、レジでお金[かね]を払[はら]った。", "sentence_source": "generated"}, {"text": "古い雑誌をひもでしばって、ごみの日に出した。", "target_word": "出した", "complexity_tier": "T3", "furigana": "古[ふる]い雑誌[ざっし]をひもでしばって、ごみの日[ひ]に出[だ]した。", "sentence_source": "generated"}, {"text": "兄は毎朝、犬を庭に出して遊ばせている。", "target_word": "出して", "complexity_tier": "T3", "furigana": "兄[あに]は毎朝[まいあさ]、犬[いぬ]を庭[にわ]に出[だ]して遊[あそ]ばせている。", "sentence_source": "generated"}, {"text": "机の中からはさみを出して、箱のテープを切った。", "target_word": "出して", "complexity_tier": "T3", "furigana": "机[つくえ]の中[なか]からはさみを出[だ]して、箱[はこ]のテープを切[き]った。", "sentence_source": "generated"}, {"text": "風呂の栓を抜いて、お湯を全部外に出した。", "target_word": "出した", "complexity_tier": "T3", "furigana": "風呂[ふろ]の栓[せん]を抜[ぬ]いて、お湯[ゆ]を全部[ぜんぶ]外[そと]に出[だ]した。", "sentence_source": "generated"}, {"text": "卵は室温に戻すため、焼く前に冷蔵庫から出しておく。", "target_word": "出し", "complexity_tier": "T3", "furigana": "卵[たまご]は室温[しつおん]に戻[もど]すため、焼[や]く前[まえ]に冷蔵庫[れいぞうこ]から出[だ]しておく。", "sentence_source": "generated"}, {"text": "ストローから空気を出すと、水の中に泡ができる。", "target_word": "出す", "complexity_tier": "T3", "furigana": "ストローから空気[くうき]を出[だ]すと、水[みず]の中[なか]に泡[あわ]ができる。", "sentence_source": "generated"}, {"text": "風船の口を放して、中の空気を一気に出した。", "target_word": "出した", "complexity_tier": "T3", "furigana": "風船[ふうせん]の口[くち]を放[はな]して、中[なか]の空気[くうき]を一気[いっき]に出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出す", "label": "辞書形"}, {"form": "出し", "label": "連用形"}, {"form": "出さ", "label": "未然形"}, {"form": "出して", "label": "て形"}, {"form": "出した", "label": "た形"}, {"form": "出せば", "label": "仮定形"}, {"form": "出せる", "label": "可能形"}, {"form": "出そう", "label": "意志形"}], "register": "標準（常体）", "sense_fingerprint": "物や空気を内から外へ移す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: しばっ (Zipf 2.15)']::text[], 'b809ef64-f595-4298-95cf-ff21c951f823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37136, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出して", "is_correct": false, "explanation": "て形で、「〜ことが大切だ」の名詞節に続かないので合わない。"}, {"text": "出す", "is_correct": true, "explanation": "正解。息を外へ送り出すという意味で、「〜ことが大切だ」に続く辞書形。"}, {"text": "出せば", "is_correct": false, "explanation": "仮定形で、「〜ことが」の名詞節に続かないので合わない。"}, {"text": "出そう", "is_correct": false, "explanation": "意志形は「〜ことが」に続かず、文に入らない。"}], "explanations": {"出して": "て形で、「〜ことが大切だ」の名詞節に続かないので合わない。", "出す": "正解。息を外へ送り出すという意味で、「〜ことが大切だ」に続く辞書形。", "出せば": "仮定形で、「〜ことが」の名詞節に続かないので合わない。", "出そう": "意志形は「〜ことが」に続かず、文に入らない。"}, "sentence_index": 0, "correct_answer": "出す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い雑誌を本棚に出して、きちんと並べた。", "explanation": "ここは〈入れる〉の意味。本棚へしまうのは入れる。出すは外へ送る意味なので、内側へ移す場面には合わない。"}, {"text": "部屋が暗くなったので、天井の電気を出した。", "explanation": "ここは〈つける〉の意味。電気を点けるのは「つける」で、出すとは言わないので合わない。"}, {"text": "鍵を鍵穴に出して、ドアを開けた。", "explanation": "ここは〈差し込む〉の意味。出すは外へ移す動きで、鍵穴に差し込む動きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37136, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "閉めた", "is_correct": false, "explanation": "「お湯を全部外に閉めた」は文意に合わず、お湯を外へ送る動作と合わない。"}, {"text": "出した", "is_correct": true, "explanation": "正解。お湯を外へ送り出したという過去の動作を表すた形。"}, {"text": "抱いた", "is_correct": false, "explanation": "お湯を外に抱くのは文意に合わない。"}, {"text": "数えた", "is_correct": false, "explanation": "お湯を外に数えるのは意味が通らない。"}], "explanations": {"閉めた": "「お湯を全部外に閉めた」は文意に合わず、お湯を外へ送る動作と合わない。", "出した": "正解。お湯を外へ送り出したという過去の動作を表すた形。", "抱いた": "お湯を外に抱くのは文意に合わない。", "数えた": "お湯を外に数えるのは意味が通らない。"}, "sentence_index": 6, "correct_answer": "出した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝早く起きて、お皿をきれいに出した。", "explanation": "ここは〈磨く〉の意味。皿をきれいにするのは磨くことで、出すの意味では合わない。"}, {"text": "将来に大きな希望を出した。", "explanation": "ここは〈表明する〉の意味。希望を出すは要望を申し出る言い方で、物を外へ送る意味ではない。"}, {"text": "寝ている子を起こさないように、ドアをそっと出した。", "explanation": "ここは〈閉める〉の意味。ドアを静かに閉める動作で、出すとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37136, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を開けて、煙が外に出す。", "corrected_sentence": "窓を開けて、煙を外に出す。", "error_description": "誤りは「煙が」。「出す」は他動詞なので、目的語の「煙」には「を」が必要。「が」だと煙が出る主体になり語が合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "出さ", "is_correct": false, "explanation": "未然形で、過去の「た」と続かないので、事実を述べる文には合わない。"}, {"text": "出した", "is_correct": true, "explanation": "正解。煙を外に送り出したという過去の動作を表すた形。"}, {"text": "出せる", "is_correct": false, "explanation": "可能形になり「出すことができた」の意味で、事実の動作を述べる文と異なる。"}, {"text": "出す", "is_correct": false, "explanation": "終止形で、過去を表す「た」が必要な文には合わない。"}], "correct_form": "出した", "base_form": "出す", "form_label": "た形", "sentence_index": 1, "explanations": {"出さ": "未然形で、過去の「た」と続かないので、事実を述べる文には合わない。", "出した": "正解。煙を外に送り出したという過去の動作を表すた形。", "出せる": "可能形になり「出すことができた」の意味で、事実の動作を述べる文と異なる。", "出す": "終止形で、過去を表す「た」が必要な文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37136, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍋のふたを開けて、湯気を外に出し冷ます。", "corrected_sentence": "鍋のふたを開けて、湯気を外に出して冷ます。", "error_description": "誤りは「出し冷ます」。「て」が抜けている。連用形「出し」の後には「て」が必要で、正しくは「出して冷ます」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "出し", "is_correct": true, "explanation": "正解。連用形で、「〜ておく」に続く形。"}, {"text": "出せ", "is_correct": false, "explanation": "命令形で、「〜ておく」の文には合わない。"}, {"text": "出した", "is_correct": false, "explanation": "た形は「〜ておく」に続かず、準備の文と合わない。"}, {"text": "出さない", "is_correct": false, "explanation": "否定形は「〜ておく」に続かず、文に入らない。"}], "correct_form": "出し", "base_form": "出す", "form_label": "連用形", "sentence_index": 7, "explanations": {"出し": "正解。連用形で、「〜ておく」に続く形。", "出せ": "命令形で、「〜ておく」の文には合わない。", "出した": "た形は「〜ておく」に続かず、準備の文と合わない。", "出さない": "否定形は「〜ておく」に続かず、文に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
