INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37137, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを内側から外側へ送り出す。また、声やにおいなどを発生させる。", "primary_collocate": null, "pronunciation": "だす", "ipa": "dasɯ", "syllable_count": 2, "sentences": [{"text": "箱の奥から古いアルバムを出した瞬間、懐かしい写真が目に入った。", "target_word": "出し", "complexity_tier": "T3", "furigana": "箱[はこ]の奥[おく]から古[ふる]いアルバムを出[だ]した瞬間[しゅんかん]、懐[なつ]かしい写真[しゃしん]が目[め]に入[はい]った。", "sentence_source": "generated"}, {"text": "大きな声を出して、遠くにいる友だちを呼んだ。", "target_word": "出して", "complexity_tier": "T3", "furigana": "大[おお]きな声[こえ]を出[だ]して、遠[とお]くにいる友[とも]だちを呼[よ]んだ。", "sentence_source": "generated"}, {"text": "箱から古い手紙を出して、もう一度ゆっくり読み返した。", "target_word": "出して", "complexity_tier": "T3", "furigana": "箱[はこ]から古[ふる]い手紙[てがみ]を出[だ]して、もう一度[いちど]ゆっくり読[よ]み返[かえ]した。", "sentence_source": "generated"}, {"text": "工場の煙突は、毎朝白い煙を出している。", "target_word": "出して", "complexity_tier": "T3", "furigana": "工場[こうじょう]の煙突[えんとつ]は、毎朝[まいあさ]白[しろ]い煙[けむり]を出[だ]している。", "sentence_source": "generated"}, {"text": "カレーは強いにおいを出すので、調理中に換気扇を回す。", "target_word": "出す", "complexity_tier": "T3", "furigana": "カレーは強[つよ]いにおいを出[だ]すので、調理中[ちょうりちゅう]に換気扇[かんきせん]を回[まわ]す。", "sentence_source": "generated"}, {"text": "雨が降りそうなので、洗濯物を外に出さないでおこう。", "target_word": "出さ", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]りそうなので、洗濯物[せんたくもの]を外[そと]に出[だ]さないでおこう。", "sentence_source": "generated"}, {"text": "犬が鳴くので、ドアを開けて外に出してやった。", "target_word": "出して", "complexity_tier": "T3", "furigana": "犬[いぬ]が鳴[な]くので、ドアを開[あ]けて外[そと]に出[だ]してやった。", "sentence_source": "generated"}, {"text": "客が来たので、冷蔵庫から冷たいお茶を出した。", "target_word": "出した", "complexity_tier": "T3", "furigana": "客[きゃく]が来[き]たので、冷蔵庫[れいぞうこ]から冷[つめ]たいお茶[ちゃ]を出[だ]した。", "sentence_source": "generated"}, {"text": "笛を吹いたが、うまく音が出せなくて悔しかった。", "target_word": "出せ", "complexity_tier": "T3", "furigana": "笛[ふえ]を吹[ふ]いたが、うまく音[おと]が出[だ]せなくて悔[くや]しかった。", "sentence_source": "generated"}, {"text": "壁の穴から顔を出したネズミが、すぐに引っ込んだ。", "target_word": "出した", "complexity_tier": "T3", "furigana": "壁[かべ]の穴[あな]から顔[かお]を出[だ]したネズミが、すぐに引[ひ]っ込[こ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出す", "label": "辞書形"}, {"form": "出し", "label": "連用形"}, {"form": "出さ", "label": "未然形"}, {"form": "出して", "label": "て形"}, {"form": "出した", "label": "た形"}, {"form": "出せば", "label": "仮定形"}, {"form": "出せる", "label": "可能形"}, {"form": "出そう", "label": "意志形"}], "register": "標準（常体）", "sense_fingerprint": "物を内から外へ移す、または声・音・においなどを発する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b809ef64-f595-4298-95cf-ff21c951f823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37137, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出す", "is_correct": false, "explanation": "「出すた」となり、辞書形に「た」は直接続かず語形が合わない。"}, {"text": "出し", "is_correct": true, "explanation": "正解。「出した」の連用形で、「た」に続く形。"}, {"text": "出さ", "is_correct": false, "explanation": "未然形は「出さた」と続かず、語形が合わない。"}, {"text": "出そう", "is_correct": false, "explanation": "意志形は「出そうた」と続かず、文に入らない。"}], "explanations": {"出す": "「出すた」となり、辞書形に「た」は直接続かず語形が合わない。", "出し": "正解。「出した」の連用形で、「た」に続く形。", "出さ": "未然形は「出さた」と続かず、語形が合わない。", "出そう": "意志形は「出そうた」と続かず、文に入らない。"}, "sentence_index": 0, "correct_answer": "出し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "財布を箱に出して、ふたを閉めた。", "explanation": "ここは〈入れる〉の意味。出すは内から外へ移す動きなので、箱の中へ物を入れる場面には合わない。"}, {"text": "部屋が暗くなったので、玄関の電気を出した。", "explanation": "ここは〈つける〉の意味。電気を点けるのは「つける」で、出すとは言わないので合わない。"}, {"text": "コンセントにプラグを出して、電源を入れた。", "explanation": "ここは〈差し込む〉の意味。出すは外へ移す動きで、プラグを穴に差し込む動きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37137, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "閉めて", "is_correct": false, "explanation": "「外に閉めてやった」は文意に合わず、ドアを外へ送る動作と合わない。"}, {"text": "出して", "is_correct": true, "explanation": "正解。ドアを開けて犬を外へ送り出すという文意に合う「て形」。"}, {"text": "呼んで", "is_correct": false, "explanation": "「外に呼んでやった」は場所と動作がかみ合わず不自然。"}, {"text": "待って", "is_correct": false, "explanation": "犬を外へ送るのであって、「外に待ってやった」では文意が通らない。"}], "explanations": {"閉めて": "「外に閉めてやった」は文意に合わず、ドアを外へ送る動作と合わない。", "出して": "正解。ドアを開けて犬を外へ送り出すという文意に合う「て形」。", "呼んで": "「外に呼んでやった」は場所と動作がかみ合わず不自然。", "待って": "犬を外へ送るのであって、「外に待ってやった」では文意が通らない。"}, "sentence_index": 6, "correct_answer": "出して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "エレベーターに乗り、階のボタンを出した。", "explanation": "ここは〈押す〉の意味。出すは外へ送り出す動きで、ボタンを押す動作には合わない。"}, {"text": "朝早く起きて、床をきれいに出した。", "explanation": "ここは〈磨く〉の意味。床をきれいにするのは磨くことで、出すの意味では合わない。"}, {"text": "試験の結果に、大きな期待を出した。", "explanation": "ここは〈抱く〉の意味。期待は抱くもので、出すとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37137, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ポケットにハンカチを出して、汗をふいた。", "corrected_sentence": "ポケットからハンカチを出して、汗をふいた。", "error_description": "誤りは「ポケットに」。「出す」は中から外へ取り出す動きなので起点の「から」が必要。「に」は到着点を示すため不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "出せ", "is_correct": false, "explanation": "命令形で、「〜て、呼んだ」の流れに続かず文が成り立たない。"}, {"text": "出して", "is_correct": true, "explanation": "正解。「大声を出して、友だちを呼んだ」の「て形」。"}, {"text": "出せる", "is_correct": false, "explanation": "可能形になり「声が出せる」の意味で、大声を出す動作の文と異なる。"}, {"text": "出せば", "is_correct": false, "explanation": "仮定形は条件の意味になり、「〜て、呼んだ」の連結に合わない。"}], "correct_form": "出して", "base_form": "出す", "form_label": "て形", "sentence_index": 1, "explanations": {"出せ": "命令形で、「〜て、呼んだ」の流れに続かず文が成り立たない。", "出して": "正解。「大声を出して、友だちを呼んだ」の「て形」。", "出せる": "可能形になり「声が出せる」の意味で、大声を出す動作の文と異なる。", "出せば": "仮定形は条件の意味になり、「〜て、呼んだ」の連結に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37137, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ハンカチを出すて、涙をふいた。", "corrected_sentence": "ハンカチを出して、涙をふいた。", "error_description": "誤りは「出すて」。正しくは連用形の「出し」に「て」がついた「出して」。辞書形に直接「て」は付かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "出し", "is_correct": false, "explanation": "連用形で、文末の「た」と続かず、語形が合わない。"}, {"text": "出した", "is_correct": true, "explanation": "正解。客に冷たいお茶を出したという過去の事実を述べるた形。"}, {"text": "出せ", "is_correct": false, "explanation": "命令形で、過去の出来事を述べる文には合わない。"}, {"text": "出さない", "is_correct": false, "explanation": "否定形になり、「出した」という事実と逆の意味になるので合わない。"}], "correct_form": "出した", "base_form": "出す", "form_label": "た形", "sentence_index": 7, "explanations": {"出し": "連用形で、文末の「た」と続かず、語形が合わない。", "出した": "正解。客に冷たいお茶を出したという過去の事実を述べるた形。", "出せ": "命令形で、過去の出来事を述べる文には合わない。", "出さない": "否定形になり、「出した」という事実と逆の意味になるので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37138, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「外へ排気する」の「へ」は排気の向かう先を示す。ガスは外へ出すので「へ」が正しい。"}, {"text": "の", "is_correct": false, "explanation": "「外の排気しないと」は名詞の間に入る「の」なので、動詞に続かず文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「外と排気しないと」は外と排気を並べる形になり、文の意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる言葉なので、「外より排気しないと」では比較の意味になり、ここでは意味が通らない。"}], "correct_answer": "へ", "explanations": {"へ": "「外へ排気する」の「へ」は排気の向かう先を示す。ガスは外へ出すので「へ」が正しい。", "の": "「外の排気しないと」は名詞の間に入る「の」なので、動詞に続かず文が成り立たない。", "と": "「外と排気しないと」は外と排気を並べる形になり、文の意味が通らない。", "より": "「より」は比べる言葉なので、「外より排気しないと」では比較の意味になり、ここでは意味が通らない。"}, "error_tags": {"へ": "方向", "の": "連体修飾", "と": "並列", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸気", "is_correct": true, "explanation": "吸気は外の空気を機械の中へ取り入れることで、排気の反対語として辞書に載る。"}, {"text": "換気", "is_correct": false, "explanation": "換気は空気を入れ替えることで、排気と同じ空気の流れを含むので反対語ではない。"}, {"text": "排水", "is_correct": false, "explanation": "排水は水を外へ流すことで、排気とは対象が違い、反対語にはならない。"}, {"text": "注入", "is_correct": false, "explanation": "注入は中へ液体などを入れることで、中へ入れる点は吸気に近いが、排気の対義語として載る語ではない。"}], "correct_answer": "吸気", "explanations": {"吸気": "吸気は外の空気を機械の中へ取り入れることで、排気の反対語として辞書に載る。", "換気": "換気は空気を入れ替えることで、排気と同じ空気の流れを含むので反対語ではない。", "排水": "排水は水を外へ流すことで、排気とは対象が違い、反対語にはならない。", "注入": "注入は中へ液体などを入れることで、中へ入れる点は吸気に近いが、排気の対義語として載る語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37138, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「排気を集めて」の「を」は集める対象を示す目的語で、自然につながる。"}, {"text": "に", "is_correct": false, "explanation": "「排気に集めて」では排気が集める先の場所になり、ガスは場所ではないので不自然。"}, {"text": "が", "is_correct": false, "explanation": "「排気が集めて」では排気が集める主体になるが、集めるのは先生なので文が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「排気へ集めて」は行き先の形だが、排気は集める先となる場所ではなく意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「排気を集めて」の「を」は集める対象を示す目的語で、自然につながる。", "に": "「排気に集めて」では排気が集める先の場所になり、ガスは場所ではないので不自然。", "が": "「排気が集めて」では排気が集める主体になるが、集めるのは先生なので文が合わない。", "へ": "「排気へ集めて」は行き先の形だが、排気は集める先となる場所ではなく意味が通らない。"}, "error_tags": {"を": "直接の対象", "に": "位置・相手", "が": "動作主", "へ": "行き先"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸気", "is_correct": true, "explanation": "吸気は機械の中へ空気を取り入れることで、排気の反対語として辞書に載る。"}, {"text": "燃焼", "is_correct": false, "explanation": "燃焼は燃料を燃やすことで、排気の元になる現象だが、反対語ではない。"}, {"text": "冷却", "is_correct": false, "explanation": "冷却は熱をさます作業で、熱い排気と関係はあるが、反対語ではない。"}, {"text": "振動", "is_correct": false, "explanation": "振動は物が細かく揺れることで、排気とは反対の意味にはならない。"}], "correct_answer": "吸気", "explanations": {"吸気": "吸気は機械の中へ空気を取り入れることで、排気の反対語として辞書に載る。", "燃焼": "燃焼は燃料を燃やすことで、排気の元になる現象だが、反対語ではない。", "冷却": "冷却は熱をさます作業で、熱い排気と関係はあるが、反対語ではない。", "振動": "振動は物が細かく揺れることで、排気とは反対の意味にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37138, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "車や機械から、いらない空気やけむりを出すこと。", "primary_collocate": null, "pronunciation": "はいき", "ipa": "haiki", "syllable_count": 3, "sentences": [{"text": "この車は排気が少なく、町の空気をよごさない。", "target_word": "排気", "complexity_tier": "T3", "furigana": "この車[くるま]は排気[はいき]が少[すく]なく、町[まち]の空気[くうき]をよごさない。", "sentence_source": "generated"}, {"text": "工場の機械は、外へ排気しないと、部屋に煙がたまってしまう。", "target_word": "排気", "complexity_tier": "T3", "furigana": "工場[こうじょう]の機械[きかい]は、外[そと]へ排気[はいき]しないと、部屋[へや]に煙[けむり]がたまってしまう。", "sentence_source": "generated"}, {"text": "古いバスは排気のにおいが強いので、近くを歩くとつらい。", "target_word": "排気", "complexity_tier": "T3", "furigana": "古[ふる]いバスは排気[はいき]のにおいが強[つよ]いので、近[ちか]くを歩[ある]くとつらい。", "sentence_source": "generated"}, {"text": "車のうしろから排気が出て、歩いていた人がせきをした。", "target_word": "排気", "complexity_tier": "T3", "furigana": "車[くるま]のうしろから排気[はいき]が出[で]て、歩[ある]いていた人[ひと]がせきをした。", "sentence_source": "generated"}, {"text": "寒い朝は、車の排気が白く見える。", "target_word": "排気", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]は、車[くるま]の排気[はいき]が白[しろ]く見[み]える。", "sentence_source": "generated"}, {"text": "エンジンを止めたので、もう排気は出ていない。", "target_word": "排気", "complexity_tier": "T3", "furigana": "エンジンを止[と]めたので、もう排気[はいき]は出[で]ていない。", "sentence_source": "generated"}, {"text": "部屋でストーブを使うときは、排気が中にたまらないように窓をあける。", "target_word": "排気", "complexity_tier": "T3", "furigana": "部屋[へや]でストーブを使[つか]うときは、排気[はいき]が中[なか]にたまらないように窓[まど]をあける。", "sentence_source": "generated"}, {"text": "先生はトラックの排気を集めて、空気のよごれを調べた。", "target_word": "排気", "complexity_tier": "T3", "furigana": "先生[せんせい]はトラックの排気[はいき]を集[あつ]めて、空気[くうき]のよごれを調[しら]べた。", "sentence_source": "generated"}, {"text": "バイクの排気が顔にかかって、いやな気分になった。", "target_word": "排気", "complexity_tier": "T3", "furigana": "バイクの排気[はいき]が顔[かお]にかかって、いやな気分[きぶん]になった。", "sentence_source": "generated"}, {"text": "この機械は排気の音が大きいので、夜は使わないことにした。", "target_word": "排気", "complexity_tier": "T3", "furigana": "この機械[きかい]は排気[はいき]の音[おと]が大[おお]きいので、夜[よる]は使[つか]わないことにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "排気", "label": "基本形"}, {"form": "排気する", "label": "サ変動詞"}, {"form": "排気した", "label": "過去形"}, {"form": "排気しないと", "label": "否定条件形"}], "register": "neutral", "sense_fingerprint": "車やバイクなどの乗り物や機械が、いらない空気やけむりを外へ出すこと、またその出たもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: よごさ (Zipf 1.22)']::text[], '8da5f40a-19ae-49fd-abf3-80abdb2562f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37138, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排気", "is_correct": true, "explanation": "「排気が少ない」は車が出すガスの量の話で、町の空気を汚さないという結果と文が自然につながる。"}, {"text": "車輪", "is_correct": false, "explanation": "車輪が少ないことは町の空気の汚れと関係がなく、「車輪が少なく、町の空気をよごさない」は意味が通らない。"}, {"text": "座席", "is_correct": false, "explanation": "座席の数が少ないことと空気がよごれないことはつながらず、文の理由にならない。"}, {"text": "信号", "is_correct": false, "explanation": "信号が少ないことと町の空気がよごれないことは関係がなく、文の理由にならない。"}], "explanations": {"排気": "「排気が少ない」は車が出すガスの量の話で、町の空気を汚さないという結果と文が自然につながる。", "車輪": "車輪が少ないことは町の空気の汚れと関係がなく、「車輪が少なく、町の空気をよごさない」は意味が通らない。", "座席": "座席の数が少ないことと空気がよごれないことはつながらず、文の理由にならない。", "信号": "信号が少ないことと町の空気がよごれないことは関係がなく、文の理由にならない。"}, "sentence_index": 0, "correct_answer": "排気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い書類は、まとめて排気してください。", "explanation": "ここは同音の〈廃棄〉（はいき）の意味。排気は機械から出る気体に使う言葉で、書類を捨てる意味では使わないので合わない。"}, {"text": "工場は汚れた水を川へ排気している。", "explanation": "ここは〈排水〉の意味。排気は気体やガスに使う言葉なので、水を流す場合には合わない。"}, {"text": "赤ちゃんは排気がうまくできないので、病院へ行った。", "explanation": "ここは〈排泄〉の意味。排気は機械から出る気体を指し、人の体から出すものには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37138, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排気", "is_correct": true, "explanation": "ストーブの排気が中にたまらないように窓をあける、と読めば、排気が部屋にたまる物として文が通る。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団が部屋の中にたまるという話は、換気の文脈では意味が通らない。"}, {"text": "電池", "is_correct": false, "explanation": "電池が中にたまらないように窓をあけるのは、換気の目的に合わず文として成り立たない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除機が中にたまらないように窓をあけるという内容は、文の意味として通らない。"}], "explanations": {"排気": "ストーブの排気が中にたまらないように窓をあける、と読めば、排気が部屋にたまる物として文が通る。", "座布団": "座布団が部屋の中にたまるという話は、換気の文脈では意味が通らない。", "電池": "電池が中にたまらないように窓をあけるのは、換気の目的に合わず文として成り立たない。", "掃除機": "掃除機が中にたまらないように窓をあけるという内容は、文の意味として通らない。"}, "sentence_index": 6, "correct_answer": "排気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "太陽は強い光を排気している。", "explanation": "ここは〈放出〉の意味。排気は機械の内部から出るガスに使う言葉なので、光には使わないので合わない。"}, {"text": "電話で排気がとぎれた。", "explanation": "ここは〈通信〉の意味。排気は気体やガスに使い、電話の回線の状態には使わないので合わない。"}, {"text": "彼の成功に、みんなの排気が集まった。", "explanation": "ここは〈注目〉の意味。排気は機械から出る気体のことで、人の関心を集める意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37138, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の駐車場で、車の排気を白く立ちのぼる。", "corrected_sentence": "夜の駐車場で、車の排気が白く立ちのぼる。", "error_description": "「排気」に続く助詞が誤り。主語を示す「が」が正しいが、「を」にすると「排気を立ちのぼる」となり、動詞「立ちのぼる」と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37138, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い機械は、排気をしなくと部屋が煙でいっぱいになる。", "corrected_sentence": "古い機械は、排気をしないと部屋が煙でいっぱいになる。", "error_description": "「排気をしないと」の「しないと」が「しなくと」になっている。「しなくと」は誤った形で、条件を表す「しないと」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37139, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「排気がうまくいかない」の「が」は主語で、「うまくいかない」の主語として自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「排気をうまくいかない」では目的語になるが、「うまくいかない」は目的語を取らないので不自然。"}, {"text": "の", "is_correct": false, "explanation": "「排気のうまくいかないと」は名詞が続く形で、動詞が成り立たず文が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「排気へうまくいかないと」は方向の形になり、排気を向かう先とするのは意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「排気がうまくいかない」の「が」は主語で、「うまくいかない」の主語として自然につながる。", "を": "「排気をうまくいかない」では目的語になるが、「うまくいかない」は目的語を取らないので不自然。", "の": "「排気のうまくいかないと」は名詞が続く形で、動詞が成り立たず文が通らない。", "へ": "「排気へうまくいかないと」は方向の形になり、排気を向かう先とするのは意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸気", "is_correct": true, "explanation": "吸気は外の空気を機械の中へ取り入れることで、排気の反対語として辞書に載る。"}, {"text": "換気", "is_correct": false, "explanation": "換気は空気を入れ替えることで、排気と同じ空気の流れを含むので反対語ではない。"}, {"text": "排水", "is_correct": false, "explanation": "排水は水を外へ流すことで、排気とは対象が違い、反対語にはならない。"}, {"text": "注入", "is_correct": false, "explanation": "注入は中へ液体などを入れることで、排気の対義語として載る語ではない。"}], "correct_answer": "吸気", "explanations": {"吸気": "吸気は外の空気を機械の中へ取り入れることで、排気の反対語として辞書に載る。", "換気": "換気は空気を入れ替えることで、排気と同じ空気の流れを含むので反対語ではない。", "排水": "排水は水を外へ流すことで、排気とは対象が違い、反対語にはならない。", "注入": "注入は中へ液体などを入れることで、排気の対義語として載る語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
