INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37139, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "機械の内部で生じた不要な気体やガスを外部に放出すること。また、その気体。", "primary_collocate": null, "pronunciation": "はいき", "ipa": "haiki", "syllable_count": 3, "sentences": [{"text": "機械の中にたまったガスは、排気で外へ出す。", "target_word": "排気", "complexity_tier": "T3", "furigana": "機械[きかい]の中[なか]にたまったガスは、排気[はいき]で外[そと]へ出[だ]す。", "sentence_source": "generated"}, {"text": "排気がうまくいかないと、機械の中の圧力が上がって危ない。", "target_word": "排気", "complexity_tier": "T3", "furigana": "排気[はいき]がうまくいかないと、機械[きかい]の中[なか]の圧力[あつりょく]が上[あ]がって危[あぶ]ない。", "sentence_source": "generated"}, {"text": "この実験室では、排気のためのファンが一日中回っている。", "target_word": "排気", "complexity_tier": "T3", "furigana": "この実験室[じっけんしつ]では、排気[はいき]のためのファンが一日中[いちにちじゅう]回[まわ]っている。", "sentence_source": "generated"}, {"text": "作業のあとに、機械の排気を確かめるのが決まりだ。", "target_word": "排気", "complexity_tier": "T3", "furigana": "作業[さぎょう]のあとに、機械[きかい]の排気[はいき]を確[たし]かめるのが決[き]まりだ。", "sentence_source": "generated"}, {"text": "工場では、排気で出るガスの量を毎月記録している。", "target_word": "排気", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、排気[はいき]で出[で]るガスの量[りょう]を毎月[まいつき]記録[きろく]している。", "sentence_source": "generated"}, {"text": "排気が止まったので、機械の中に熱いガスがたまってしまった。", "target_word": "排気", "complexity_tier": "T3", "furigana": "排気[はいき]が止[と]まったので、機械[きかい]の中[なか]に熱[あつ]いガスがたまってしまった。", "sentence_source": "generated"}, {"text": "発電機の排気は、パイプを通って建物の外へ出る。", "target_word": "排気", "complexity_tier": "T3", "furigana": "発電機[はつでんき]の排気[はいき]は、パイプを通[とお]って建物[たてもの]の外[そと]へ出[で]る。", "sentence_source": "generated"}, {"text": "新しい機械は排気が少なく、まわりの人にも安心だ。", "target_word": "排気", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]は排気[はいき]が少[すく]なく、まわりの人[ひと]にも安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "機械の排気に問題がないか、技術者が点検している。", "target_word": "排気", "complexity_tier": "T3", "furigana": "機械[きかい]の排気[はいき]に問題[もんだい]がないか、技術者[ぎじゅつしゃ]が点検[てんけん]している。", "sentence_source": "generated"}, {"text": "排気の熱でパイプが熱くなっているので、さわってはいけない。", "target_word": "排気", "complexity_tier": "T3", "furigana": "排気[はいき]の熱[ねつ]でパイプが熱[あつ]くなっているので、さわってはいけない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "排気", "label": "基本形"}, {"form": "排気する", "label": "サ変動詞"}, {"form": "排気した", "label": "過去形"}, {"form": "排気の", "label": "連体形（の）"}], "register": "neutral", "sense_fingerprint": "機械の内部にできた不要なガスを外へ放出すること、またそのガス", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8da5f40a-19ae-49fd-abf3-80abdb2562f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37139, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排気", "is_correct": true, "explanation": "機械の中のガスを外へ出す手段として排気を入れると、文の意味が通る。"}, {"text": "燃料", "is_correct": false, "explanation": "燃料はガスを外へ出す手段ではなく、燃料で外へ出すという言い方は文として成り立たない。"}, {"text": "圧縮", "is_correct": false, "explanation": "圧縮はガスを小さくまとめる操作で、外へ出す手段としては文が通らない。"}, {"text": "点検", "is_correct": false, "explanation": "点検は調べることで、ガスを外へ出す手段にはならず、文の意味が合わない。"}], "explanations": {"排気": "機械の中のガスを外へ出す手段として排気を入れると、文の意味が通る。", "燃料": "燃料はガスを外へ出す手段ではなく、燃料で外へ出すという言い方は文として成り立たない。", "圧縮": "圧縮はガスを小さくまとめる操作で、外へ出す手段としては文が通らない。", "点検": "点検は調べることで、ガスを外へ出す手段にはならず、文の意味が合わない。"}, "sentence_index": 0, "correct_answer": "排気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い電池は、まとめて排気してください。", "explanation": "ここは同音の〈廃棄〉（はいき）の意味。排気は機械から出るガスに使う語で、電池を捨てる意味では使わないので合わない。"}, {"text": "大雨のあと、たまった水を側溝へ排気した。", "explanation": "ここは〈排水〉の意味。排気は気体に使う語で、水を流すことには使わないので合わない。"}, {"text": "冷蔵庫の食材が減ったので、毎週排気している。", "explanation": "ここは〈補充〉の意味。排気は機械の中の気体を外へ出す語で、食材を足す意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37139, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排気", "is_correct": true, "explanation": "発電機の内部から出るガスの流れとして、排気がパイプを通って外へ出るのは自然な文になる。"}, {"text": "電圧", "is_correct": false, "explanation": "電圧はパイプを通って外へ出るものではなく、文の主語として意味が通らない。"}, {"text": "燃焼", "is_correct": false, "explanation": "燃焼はものが燃えることで、パイプを通って建物の外へ出る主語には合わない。"}, {"text": "出力", "is_correct": false, "explanation": "出力は発電機が送る電気の量で、パイプを通って外へ出る気体の話にはならない。"}], "explanations": {"排気": "発電機の内部から出るガスの流れとして、排気がパイプを通って外へ出るのは自然な文になる。", "電圧": "電圧はパイプを通って外へ出るものではなく、文の主語として意味が通らない。", "燃焼": "燃焼はものが燃えることで、パイプを通って建物の外へ出る主語には合わない。", "出力": "出力は発電機が送る電気の量で、パイプを通って外へ出る気体の話にはならない。"}, "sentence_index": 6, "correct_answer": "排気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ろうそくに火を入れるため、マッチを排気した。", "explanation": "ここは〈点火〉の意味。排気は機械の内部から出る不要なガスを外へ出すことで、火をつける意味では使わないので合わない。"}, {"text": "煙の色がだんだん排気していった。", "explanation": "ここは〈薄れる〉の意味。排気は気体を外へ出すことで、色が弱くなる意味では使わないので合わない。"}, {"text": "捕まっていた鳥を排気した。", "explanation": "ここは〈解放〉の意味。排気は機械から気体を出す語で、生き物を自由にする意味には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37139, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ファンを回して、排気を外へ出る。", "corrected_sentence": "ファンを回して、排気を外へ出す。", "error_description": "「排気を」と組む動詞は他動詞の「出す」。「出る」は自動詞なので、目的語の「排気を」と合わず誤り。正しくは「出す」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37139, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "機械の排気を、部屋の空気を汚している。", "corrected_sentence": "機械の排気が、部屋の空気を汚している。", "error_description": "「排気」に続く助詞が「を」になっている。ここは「排気」が主語になる「が」が正しい。「を」だと排気が目的語のように扱われ、意味が逆になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37140, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「水」が「汚染されて」の主語。受け身では、よごされる対象が「が」で示される。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示すが、「汚染される」は受け身なので「を」は入らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、受け身「汚染されて」の主語にはならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「水と汚染された」は並列や相手を示すが、受け身の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「水」が「汚染されて」の主語。受け身では、よごされる対象が「が」で示される。", "を": "「を」は他動詞の目的語を示すが、「汚染される」は受け身なので「を」は入らない。", "へ": "「へ」は方向を示すが、受け身「汚染されて」の主語にはならず不自然。", "と": "「水と汚染された」は並列や相手を示すが、受け身の主語にはならない。"}, "error_tags": {"を": "目的語（受け身では不可）", "へ": "方向（不適）", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37140, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「汚染」が「ひどい」の主語。形容詞の主語は「が」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "「汚染へ」は方向を示すが、「ひどい」の主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「汚染より」は比較の基準を示すが、「ひどい」の主語を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示すが、形容詞「ひどい」の主語にはならず「汚染をひどい」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「汚染」が「ひどい」の主語。形容詞の主語は「が」で示す。", "へ": "「汚染へ」は方向を示すが、「ひどい」の主語にはならない。", "より": "「汚染より」は比較の基準を示すが、「ひどい」の主語を示せない。", "を": "「を」は他動詞の目的語を示すが、形容詞「ひどい」の主語にはならず「汚染をひどい」は成り立たない。"}, "error_tags": {"へ": "方向（不適）", "より": "比較", "を": "目的語（形容詞文には不可）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37140, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "空気や水が、きたないものにまざって、よごれること。", "primary_collocate": null, "pronunciation": "おせん", "ipa": "osen", "syllable_count": 3, "sentences": [{"text": "工場の煙で、空気が汚染された。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "工場[こうじょう]の煙[けむり]で、空気[くうき]が汚染[おせん]された。", "sentence_source": "generated"}, {"text": "川の水が汚染されて、魚がいなくなった。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が汚染[おせん]されて、魚[さかな]がいなくなった。", "sentence_source": "generated"}, {"text": "汚染された水は、そのまま飲めません。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "汚染[おせん]された水[みず]は、そのまま飲[の]めません。", "sentence_source": "generated"}, {"text": "この町は、空気の汚染がひどくて、空が白く見える。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "この町[まち]は、空気[くうき]の汚染[おせん]がひどくて、空[そら]が白[しろ]く見[み]える。", "sentence_source": "generated"}, {"text": "池の水が汚染されているので、泳いではいけません。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "池[いけ]の水[みず]が汚染[おせん]されているので、泳[およ]いではいけません。", "sentence_source": "generated"}, {"text": "水の汚染を防ぐため、台所の油は流さない。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "水[みず]の汚染[おせん]を防[ふせ]ぐため、台所[だいどころ]の油[あぶら]は流[なが]さない。", "sentence_source": "generated"}, {"text": "川の汚染の原因は、上流の工場から流された排水だった。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "川[かわ]の汚染[おせん]の原因[げんいん]は、上流[じょうりゅう]の工場[こうじょう]から流[なが]された排水[はいすい]だった。", "sentence_source": "generated"}, {"text": "汚染がひどい井戸の水を飲んで、子どもが病気になった。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "汚染[おせん]がひどい井戸[いど]の水[みず]を飲[の]んで、子[こ]どもが病気[びょうき]になった。", "sentence_source": "generated"}, {"text": "水が汚染されると、魚も植物も育たなくなる。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "水[みず]が汚染[おせん]されると、魚[さかな]も植物[しょくぶつ]も育[そだ]たなくなる。", "sentence_source": "generated"}, {"text": "きれいな湖が、油で汚染されて悲しい。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "きれいな湖[みずうみ]が、油[あぶら]で汚染[おせん]されて悲[かな]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "汚染", "label": "基本形"}, {"form": "汚染する", "label": "辞書形（サ変動詞）"}, {"form": "汚染される", "label": "受身形"}, {"form": "汚染された", "label": "受身・過去形"}], "register": "標準（中立）", "sense_fingerprint": "空気や水にきたないものがまざってよごれること（身近な水・空気のよごれ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37140, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汚染", "is_correct": true, "explanation": "「空気が汚染された」の「汚染」。工場の煙で空気がよごれたという文に合う。"}, {"text": "腐敗", "is_correct": false, "explanation": "食品などがくさることで、空気の状態を表す語ではない。"}, {"text": "蒸発", "is_correct": false, "explanation": "液体が気体になって消えることで、煙によって空気がよごれた文とは合わない。"}, {"text": "劣化", "is_correct": false, "explanation": "品質が落ちることで、煙できたないものがまざる文脈に合わない。"}], "explanations": {"汚染": "「空気が汚染された」の「汚染」。工場の煙で空気がよごれたという文に合う。", "腐敗": "食品などがくさることで、空気の状態を表す語ではない。", "蒸発": "液体が気体になって消えることで、煙によって空気がよごれた文とは合わない。", "劣化": "品質が落ちることで、煙できたないものがまざる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "汚染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は無実なのに、汚染を着せられた。", "explanation": "ここは〈汚名〉（悪い評判）の意味。汚染は空気や水などのよごれを言うので、人の評判には使わない。"}, {"text": "この布は、赤い糸で汚染されている。", "explanation": "ここは〈染める〉（色をつける）の意味。汚染はよごれることなので、色をつけて布を仕上げる文には合わない。"}, {"text": "図書館の本を汚染して、弁償することになった。", "explanation": "ここは〈汚損〉（物をよごしてだめにすること）の意味。汚染は空気や水などの環境に使うので、本の損傷には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37140, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汚染", "is_correct": true, "explanation": "「川の汚染」は川がよごされることを指し、その原因を説明する文に合う。"}, {"text": "浄化", "is_correct": false, "explanation": "きれいにすることで、排水が原因だという文脈とは合わない。"}, {"text": "雨量", "is_correct": false, "explanation": "降った雨の量を表すので、排水が原因の汚染の説明にはならない。"}, {"text": "漁獲", "is_correct": false, "explanation": "魚をとった量を表すので、川の状態の原因を示す語として成り立たない。"}], "explanations": {"汚染": "「川の汚染」は川がよごされることを指し、その原因を説明する文に合う。", "浄化": "きれいにすることで、排水が原因だという文脈とは合わない。", "雨量": "降った雨の量を表すので、排水が原因の汚染の説明にはならない。", "漁獲": "魚をとった量を表すので、川の状態の原因を示す語として成り立たない。"}, "sentence_index": 6, "correct_answer": "汚染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "インフルエンザが流行して、クラスの生徒が汚染された。", "explanation": "ここは〈感染〉（病原体がうつること）の意味。汚染は空気や水などの環境のよごれで、人の病気には使わない。"}, {"text": "子どもが床を汚染して、お母さんに叱られた。", "explanation": "ここは〈汚す〉（物をよごすこと）の意味。汚染は環境に対して使い、床をよごす行為には合わない。"}, {"text": "その事件は、会社の経歴に汚染として残った。", "explanation": "ここは〈汚点〉（評判を傷つけるきず）の意味。汚染は環境の有害物質によるよごれで、経歴には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37140, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工場の排水による汚染を、川に広がった。", "corrected_sentence": "工場の排水による汚染が、川に広がった。", "error_description": "「広がった」の主語は「汚染」なので「が」が正しい。「を」は目的語を示す助詞で、「広がる」の文には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37140, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海が汚染すると、人間も困る。", "corrected_sentence": "海が汚染されると、人間も困る。", "error_description": "「海」は汚染される側なので受け身の「汚染される」が正しい。「汚染する」は他動詞で、「海が」を主語にすると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37141, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「環境」は「汚染している」の目的語。他動詞の目的語は「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "「環境が汚染している」では環境が主語になり、「汚染する」の目的語を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「環境に汚染している」は汚染の相手として文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「環境の汚染している」は動詞の目的語を示せず、文が不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「環境」は「汚染している」の目的語。他動詞の目的語は「を」で示す。", "が": "「環境が汚染している」では環境が主語になり、「汚染する」の目的語を示せない。", "に": "「環境に汚染している」は汚染の相手として文が成り立たない。", "の": "「環境の汚染している」は動詞の目的語を示せず、文が不自然になる。"}, "error_tags": {"が": "主語（他動詞には不適）", "に": "相手（不適）", "の": "所属（不適）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37141, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「汚染」は「減らす」の目的語。他動詞「減らす」の対象は「を」で示す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「汚染で減らす」では減らす対象が示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「汚染と減らすために」では目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「汚染へ減らす」では減らす対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「汚染」は「減らす」の目的語。他動詞「減らす」の対象は「を」で示す。", "で": "「で」は手段や場所を示すが、「汚染で減らす」では減らす対象が示せない。", "と": "「と」は並列や相手を示すが、「汚染と減らすために」では目的語にならない。", "へ": "「へ」は方向を示すが、「汚染へ減らす」では減らす対象を表せない。"}, "error_tags": {"で": "手段・場所（不適）", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37141, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自然や環境が、人間の活動によって出された有害な物質で、よごされること。", "primary_collocate": null, "pronunciation": "おせん", "ipa": "osen", "syllable_count": 3, "sentences": [{"text": "工場から出た薬品で、土地が汚染された。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "工場[こうじょう]から出[で]た薬品[やくひん]で、土地[とち]が汚染[おせん]された。", "sentence_source": "generated"}, {"text": "人間の活動が、地球の環境を汚染している。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "人間[にんげん]の活動[かつどう]が、地球[ちきゅう]の環境[かんきょう]を汚染[おせん]している。", "sentence_source": "generated"}, {"text": "化学物質による汚染が、世界中に広がっている。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "化学物質[かがくぶっしつ]による汚染[おせん]が、世界中[せかいじゅう]に広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "車の排気ガスが、町の空気を汚染している。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "車[くるま]の排気[はいき]ガスが、町[まち]の空気[くうき]を汚染[おせん]している。", "sentence_source": "generated"}, {"text": "海に流れたごみやプラスチックが、海を汚染する。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "海[うみ]に流[なが]れたごみやプラスチックが、海[うみ]を汚染[おせん]する。", "sentence_source": "generated"}, {"text": "国は、川を汚染した会社に厳しい罰を与えた。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "国[くに]は、川[かわ]を汚染[おせん]した会社[かいしゃ]に厳[きび]しい罰[ばつ]を与[あた]えた。", "sentence_source": "generated"}, {"text": "農薬の使いすぎが、土の汚染につながることもある。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "農薬[のうやく]の使[つか]いすぎが、土[つち]の汚染[おせん]につながることもある。", "sentence_source": "generated"}, {"text": "汚染を減らすために、工場は新しい機械を入れた。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "汚染[おせん]を減[へ]らすために、工場[こうじょう]は新[あたら]しい機械[きかい]を入[い]れた。", "sentence_source": "generated"}, {"text": "事故で有害な物質がもれ、周りの土地が汚染された。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "事故[じこ]で有害[ゆうがい]な物質[ぶっしつ]がもれ、周[まわ]りの土地[とち]が汚染[おせん]された。", "sentence_source": "generated"}, {"text": "環境の汚染は、私たち人間の生活と深く関係している。", "target_word": "汚染", "complexity_tier": "T3", "furigana": "環境[かんきょう]の汚染[おせん]は、私[わたし]たち人間[にんげん]の生活[せいかつ]と深[ふか]く関係[かんけい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "汚染", "label": "基本形"}, {"form": "汚染する", "label": "辞書形（サ変動詞）"}, {"form": "汚染される", "label": "受身形"}, {"form": "汚染している", "label": "進行・状態形"}], "register": "標準（やや硬い）", "sense_fingerprint": "人間の活動が出した有害な物質で自然・環境がよごされること（環境問題）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37141, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汚染", "is_correct": true, "explanation": "「工場から出た薬品で土地が汚染された」の「汚染」。有害な物質による土地のよごれを表す。"}, {"text": "蒸発", "is_correct": false, "explanation": "液体が気体になって消えることで、薬品によって土地がよごれた文とは合わない。"}, {"text": "結露", "is_correct": false, "explanation": "空気中の水分が物の表面に水滴となることで、土地の状態を表す語ではない。"}, {"text": "凍結", "is_correct": false, "explanation": "水などが凍ることで、薬品によるよごれの文脈には合わない。"}], "explanations": {"汚染": "「工場から出た薬品で土地が汚染された」の「汚染」。有害な物質による土地のよごれを表す。", "蒸発": "液体が気体になって消えることで、薬品によって土地がよごれた文とは合わない。", "結露": "空気中の水分が物の表面に水滴となることで、土地の状態を表す語ではない。", "凍結": "水などが凍ることで、薬品によるよごれの文脈には合わない。"}, "sentence_index": 0, "correct_answer": "汚染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "シャツの汚染が、洗ってもなかなか落ちない。", "explanation": "ここは〈汚れ〉（物に付いたよごれ）の意味。汚染は環境や自然が有害な物質でよごされることなので、服には使わない。"}, {"text": "会社の名前に汚染がついた、と新聞に書かれた。", "explanation": "ここは〈汚点〉（評判をきずつける出来事）の意味。汚染は有害物質による環境のよごれで、評判には使わない。"}, {"text": "この布は、薄い青色に汚染されている。", "explanation": "ここは〈染める〉（色をつける）の意味。汚染はよごれることで、色をつける文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37141, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汚染", "is_correct": true, "explanation": "「土の汚染」は土がよごれることを指し、農薬の使いすぎがつながる結果として合う。"}, {"text": "換気", "is_correct": false, "explanation": "空気を入れ替えることで、土には使わない。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出すことで、農薬の使いすぎの結果としては合わない。"}, {"text": "浄水", "is_correct": false, "explanation": "水をきれいにすることで、土の状態には使わない。"}], "explanations": {"汚染": "「土の汚染」は土がよごれることを指し、農薬の使いすぎがつながる結果として合う。", "換気": "空気を入れ替えることで、土には使わない。", "採掘": "地下の資源を掘り出すことで、農薬の使いすぎの結果としては合わない。", "浄水": "水をきれいにすることで、土の状態には使わない。"}, "sentence_index": 6, "correct_answer": "汚染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い魚を食べて、その人は汚染になった。", "explanation": "ここは〈中毒〉（毒にあたって体をこわすこと）の意味。汚染は環境や物が有害物質でよごされることなので、人が毒にあたる意味では使わない。"}, {"text": "インフルエンザは、人から人へ汚染する。", "explanation": "ここは〈感染〉（病原体が人にうつること）の意味。汚染は環境のよごれを指すので、病気がうつることには使わない。"}, {"text": "服を汚染して、母に叱られた。", "explanation": "ここは〈汚す〉（物をよごすこと）の意味。汚染は環境や水などのよごれに使うので、服をよごす行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37141, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地下水への汚染を、町で問題になっている。", "corrected_sentence": "地下水への汚染が、町で問題になっている。", "error_description": "「問題になっている」の主語は「汚染」なので「が」が正しい。「を」は目的語を示す助詞で、「問題になる」の文には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37141, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "土地が汚染させると、農作物が育たない。", "corrected_sentence": "土地が汚染されると、農作物が育たない。", "error_description": "「土地」は汚染される側なので受け身の「汚染される」が正しい。「汚染させる」は使役で、主語の「土地」とは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37142, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「一人で」は単独で行うことを表し、「行きました」に続く。"}, {"text": "に", "is_correct": false, "explanation": "「一人に」では旅行の仕方が示せず、「京都へ」とも続かない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示すが、「行きました」は自動詞なので「一人を」は入らない。"}, {"text": "が", "is_correct": false, "explanation": "「一人が」だと「私は」と主語が重なり、文の構造が崩れる。"}], "correct_answer": "で", "explanations": {"で": "「一人で」は単独で行うことを表し、「行きました」に続く。", "に": "「一人に」では旅行の仕方が示せず、「京都へ」とも続かない。", "を": "「を」は他動詞の目的語を示すが、「行きました」は自動詞なので「一人を」は入らない。", "が": "「一人が」だと「私は」と主語が重なり、文の構造が崩れる。"}, "error_tags": {"に": "方向・相手（不適）", "を": "目的語（自動詞には不適）", "が": "主語（重複）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37142, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一人になりたい」の「に」。「なる」の結果を示す。"}, {"text": "の", "is_correct": false, "explanation": "「一人のなりたい」は名詞を修飾する「の」が入り、「なりたい」の結果を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「一人へなりたい」は方向を示すが、「なりたい」の結果を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「一人からなりたい」は起点を示すが、「なる」の結果は表せない。"}], "correct_answer": "に", "explanations": {"に": "「一人になりたい」の「に」。「なる」の結果を示す。", "の": "「一人のなりたい」は名詞を修飾する「の」が入り、「なりたい」の結果を示せない。", "へ": "「一人へなりたい」は方向を示すが、「なりたい」の結果を表せない。", "から": "「一人からなりたい」は起点を示すが、「なる」の結果は表せない。"}, "error_tags": {"の": "修飾（不適）", "へ": "方向（不適）", "から": "起点（不適）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37142, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人がひとりだけであること。また、ほかの人なしに、ひとりで物事をすること。", "primary_collocate": null, "pronunciation": "ひとり", "ipa": "çitoɾi", "syllable_count": 3, "sentences": [{"text": "教室には、一人しかいません。", "target_word": "一人", "complexity_tier": "T3", "furigana": "教室[きょうしつ]には、一人[ひとり]しかいません。", "sentence_source": "generated"}, {"text": "私は一人で京都へ旅行に行きました。", "target_word": "一人", "complexity_tier": "T3", "furigana": "私[わたし]は一人[ひとり]で京都[きょうと]へ旅行[りょこう]に行[い]きました。", "sentence_source": "generated"}, {"text": "兄は大学の近くで、一人で住んでいます。", "target_word": "一人", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]の近[ちか]くで、一人[ひとり]で住[す]んでいます。", "sentence_source": "generated"}, {"text": "今日は家族が出かけて、家に一人です。", "target_word": "一人", "complexity_tier": "T3", "furigana": "今日[きょう]は家族[かぞく]が出[で]かけて、家[いえ]に一人[ひとり]です。", "sentence_source": "generated"}, {"text": "先生は、生徒を一人ずつ名前で呼んだ。", "target_word": "一人", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]を一人[ひとり]ずつ名前[なまえ]で呼[よ]んだ。", "sentence_source": "generated"}, {"text": "一人の学生が手を上げて、質問をした。", "target_word": "一人", "complexity_tier": "T3", "furigana": "一人[ひとり]の学生[がくせい]が手[て]を上[あ]げて、質問[しつもん]をした。", "sentence_source": "generated"}, {"text": "小さい子どもを一人で行かせるのは心配だ。", "target_word": "一人", "complexity_tier": "T3", "furigana": "小[ちい]さい子[こ]どもを一人[ひとり]で行[い]かせるのは心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "一人になりたいときは、図書館へ行きます。", "target_word": "一人", "complexity_tier": "T3", "furigana": "一人[ひとり]になりたいときは、図書館[としょかん]へ行[い]きます。", "sentence_source": "generated"}, {"text": "会場に来たのは、一人だけだった。", "target_word": "一人", "complexity_tier": "T3", "furigana": "会場[かいじょう]に来[き]たのは、一人[ひとり]だけだった。", "sentence_source": "generated"}, {"text": "みんなで食べるほうが、一人で食べるよりおいしい。", "target_word": "一人", "complexity_tier": "T3", "furigana": "みんなで食[た]べるほうが、一人[ひとり]で食[た]べるよりおいしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一人", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "人が一名だけであること（人数の一、またほかに誰もいない状態）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37142, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一人", "is_correct": true, "explanation": "「教室には一人しかいない」の「一人」。人数が一人であることを表す。"}, {"text": "窓", "is_correct": false, "explanation": "人を表す語ではないので、「窓しかいません」は人がいるという文として成り立たない。"}, {"text": "机", "is_correct": false, "explanation": "人を表す語ではないので、「机しかいません」は成り立たない。"}, {"text": "黒板", "is_correct": false, "explanation": "人を表す語ではないので、「黒板しかいません」は文の主語にできない。"}], "explanations": {"一人": "「教室には一人しかいない」の「一人」。人数が一人であることを表す。", "窓": "人を表す語ではないので、「窓しかいません」は人がいるという文として成り立たない。", "机": "人を表す語ではないので、「机しかいません」は成り立たない。", "黒板": "人を表す語ではないので、「黒板しかいません」は文の主語にできない。"}, "sentence_index": 0, "correct_answer": "一人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家の庭に猫が一人いる。", "explanation": "ここは〈一匹〉（動物を数える）の意味。一人は人を数えるので、猫には使わない。"}, {"text": "机の上に紙が一人ある。", "explanation": "ここは〈一枚〉（紙など薄いものを数える）の意味。一人は人を数えるので、紙には使わない。"}, {"text": "この店で、おにぎりを一人買った。", "explanation": "ここは〈一個〉（小さい物を数える）の意味。一人は人を数えるので、おにぎりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37142, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一人", "is_correct": true, "explanation": "「小さい子どもを一人で行かせる」の「一人」。子どもが大人なしで行くことを表す。"}, {"text": "一緒", "is_correct": false, "explanation": "「一緒で行かせる」の形では文が成り立たず、「一緒に」なら別の意味になる。"}, {"text": "夜中", "is_correct": false, "explanation": "時間を示す語なので、「夜中で行かせる」は文が成り立たない。"}, {"text": "大人", "is_correct": false, "explanation": "「大人で行かせる」では誰が行くかの説明にならず、文が不自然になる。"}], "explanations": {"一人": "「小さい子どもを一人で行かせる」の「一人」。子どもが大人なしで行くことを表す。", "一緒": "「一緒で行かせる」の形では文が成り立たず、「一緒に」なら別の意味になる。", "夜中": "時間を示す語なので、「夜中で行かせる」は文が成り立たない。", "大人": "「大人で行かせる」では誰が行くかの説明にならず、文が不自然になる。"}, "sentence_index": 6, "correct_answer": "一人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机の上に本が一人ある。", "explanation": "ここは〈一冊〉（本を数える）の意味。一人は人を数えるので、本には使わない。"}, {"text": "駐車場に車が一人止まっている。", "explanation": "ここは〈一台〉（車などを数える）の意味。一人は人を数えるので、車には使わない。"}, {"text": "その店では、ラーメンを一人注文した。", "explanation": "ここは〈一杯〉（器に入った料理を数える）の意味。一人は人を数えるので、料理には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37142, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家に一人にいると、少し寂しい。", "corrected_sentence": "家に一人でいると、少し寂しい。", "error_description": "「一人でいる」は、単独で「いる」様子を表す「で」が正しい。「一人に」は「いる」と続かず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37142, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末は一人を映画を見に行くことが多い。", "corrected_sentence": "週末は一人で映画を見に行くことが多い。", "error_description": "「一人で」は単独で行くことを表す。「一人を」は目的語にならず、「映画を」と目的語が重なって文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
