INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37144, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "function", "definition": "家具や楽器、機械などを数える助数詞。", "primary_collocate": null, "pronunciation": "だい", "ipa": "dai", "syllable_count": 2, "sentences": [{"text": "部屋にベッドが二台あるので、四人で泊まれる。", "target_word": "台", "complexity_tier": "T3", "furigana": "部屋[へや]にベッドが二台[にだい]あるので、四人[よにん]で泊[と]まれる。", "sentence_source": "generated"}, {"text": "学校のパソコンは全部で四十台ある。", "target_word": "台", "complexity_tier": "T3", "furigana": "学校[がっこう]のパソコンは全部[ぜんぶ]で四十台[よんじゅうだい]ある。", "sentence_source": "generated"}, {"text": "店の前に自転車が五台並んでいる。", "target_word": "台", "complexity_tier": "T3", "furigana": "店[みせ]の前[まえ]に自転車[じてんしゃ]が五台[ごだい]並[なら]んでいる。", "sentence_source": "generated"}, {"text": "父は古いカメラを三台持っている。", "target_word": "台", "complexity_tier": "T3", "furigana": "父[ちち]は古[ふる]いカメラを三台[さんだい]持[も]っている。", "sentence_source": "generated"}, {"text": "会議室にはプロジェクターが一台しかないので、順番に使う。", "target_word": "台", "complexity_tier": "T3", "furigana": "会議室[かいぎしつ]にはプロジェクターが一台[いちだい]しかないので、順番[じゅんばん]に使[つか]う。", "sentence_source": "generated"}, {"text": "引っ越しでテレビを一台買い替えた。", "target_word": "台", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しでテレビを一台[いちだい]買[か]い替[か]えた。", "sentence_source": "generated"}, {"text": "音楽室にピアノが二台あり、二人で同時に練習できる。", "target_word": "台", "complexity_tier": "T3", "furigana": "音楽室[おんがくしつ]にピアノが二台[にだい]あり、二人[ふたり]で同時[どうじ]に練習[れんしゅう]できる。", "sentence_source": "generated"}, {"text": "工場に新しい機械を十台入れる予定だ。", "target_word": "台", "complexity_tier": "T3", "furigana": "工場[こうじょう]に新[あたら]しい機械[きかい]を十台[じゅうだい]入[い]れる予定[よてい]だ。", "sentence_source": "generated"}, {"text": "入口にコピー機が一台置いてあるが、紙がなくなった。", "target_word": "台", "complexity_tier": "T3", "furigana": "入口[いりぐち]にコピー機[き]が一台[いちだい]置[お]いてあるが、紙[かみ]がなくなった。", "sentence_source": "generated"}, {"text": "展示会場には最新のロボットが七台並んでいた。", "target_word": "台", "complexity_tier": "T3", "furigana": "展示会場[てんじかいじょう]には最新[さいしん]のロボットが七台[ななだい]並[なら]んでいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ベッドやピアノなど、台を単位に物を数える助数詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f35ae2-3626-49c3-8754-26766e35d357') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37144, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "台", "is_correct": true, "explanation": "ベッドなどの家具や機械を数える〈台〉。二台と数えるのが正しい。"}, {"text": "枚", "is_correct": false, "explanation": "枚は紙や板のような薄く平らな物を数える語で、ベッドには合わない。"}, {"text": "本", "is_correct": false, "explanation": "本は細長い物を数える語で、ベッドを二本とは言わない。"}, {"text": "冊", "is_correct": false, "explanation": "冊は本や雑誌を数える語で、ベッドには使えない。"}], "explanations": {"台": "ベッドなどの家具や機械を数える〈台〉。二台と数えるのが正しい。", "枚": "枚は紙や板のような薄く平らな物を数える語で、ベッドには合わない。", "本": "本は細長い物を数える語で、ベッドを二本とは言わない。", "冊": "冊は本や雑誌を数える語で、ベッドには使えない。"}, "sentence_index": 0, "correct_answer": "台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "港に大きな船が三台停まっている。", "explanation": "ここは〈隻〉の意味。船は隻で数える。台は車や機械の数え方なので、船には合わない。"}, {"text": "テーブルの上にりんごが三台ある。", "explanation": "ここは〈個〉の意味。りんごのような小さい物は個で数える。台は家具や機械を数える語なので、果物には合わない。"}, {"text": "友達が三台来た。", "explanation": "ここは〈人〉の意味。人は人で数える。台は物を数える語なので、人には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37144, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台", "is_correct": true, "explanation": "ピアノなどの楽器や機械を数える〈台〉。二台と数える。"}, {"text": "件", "is_correct": false, "explanation": "件は事柄や用件を数える語で、ピアノには合わない。"}, {"text": "軒", "is_correct": false, "explanation": "軒は家や店を数える語で、ピアノには使えない。"}, {"text": "羽", "is_correct": false, "explanation": "羽は鳥などを数える語で、ピアノには合わない。"}], "explanations": {"台": "ピアノなどの楽器や機械を数える〈台〉。二台と数える。", "件": "件は事柄や用件を数える語で、ピアノには合わない。", "軒": "軒は家や店を数える語で、ピアノには使えない。", "羽": "羽は鳥などを数える語で、ピアノには合わない。"}, "sentence_index": 6, "correct_answer": "台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "滑走路に旅客機が五台並んでいる。", "explanation": "ここは〈機〉の意味。飛行機は機で数える。台は家具や機械を数える語なので、旅客機には合わない。"}, {"text": "駅のホームに電車が五台止まっている。", "explanation": "ここは〈両〉の意味。電車は両で数える。台は電車の数え方としては合わない。"}, {"text": "この山には鉄塔が十台立っている。", "explanation": "ここは〈基〉の意味。鉄塔のような大きな構造物は基で数える。台は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37144, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "娘のために、新しいピアノを一台を買った。", "corrected_sentence": "娘のために、新しいピアノを一台買った。", "error_description": "助詞の重複。数量詞〈一台〉の後に〈を〉を付けているが、〈を〉は目的語〈ピアノ〉の後ですでに示されている。〈一台〉の後には助詞を付けず、〈ピアノを一台買った〉が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37144, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "倉庫に古い扇風機が三台をある。", "corrected_sentence": "倉庫に古い扇風機が三台ある。", "error_description": "助詞の誤り。〈三台〉の後に〈を〉が付いているが、〈ある〉は存在を表し目的語を取らないので〈を〉は要らない。正しくは〈扇風機が三台ある〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
