INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37145, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "function", "definition": "機械や乗り物など、一人で使ったり動かしたりするものを数える語。", "primary_collocate": null, "pronunciation": "だい", "ipa": "dai", "syllable_count": 2, "sentences": [{"text": "駐車場に車が三台止まっている。", "target_word": "台", "complexity_tier": "T3", "furigana": "駐車場[ちゅうしゃじょう]に車[くるま]が三台[さんだい]止[と]まっている。", "sentence_source": "generated"}, {"text": "洗濯機を一台買ったので、もう手洗いはしない。", "target_word": "台", "complexity_tier": "T3", "furigana": "洗濯機[せんたくき]を一台[いちだい]買[か]ったので、もう手洗[てあら]いはしない。", "sentence_source": "generated"}, {"text": "工場の前にトラックが四台並んでいた。", "target_word": "台", "complexity_tier": "T3", "furigana": "工場[こうじょう]の前[まえ]にトラックが四台[よんだい]並[なら]んでいた。", "sentence_source": "generated"}, {"text": "事故でバイクが二台壊れた。", "target_word": "台", "complexity_tier": "T3", "furigana": "事故[じこ]でバイクが二台[にだい]壊[こわ]れた。", "sentence_source": "generated"}, {"text": "家族が増えたので、車をもう一台買うことにした。", "target_word": "台", "complexity_tier": "T3", "furigana": "家族[かぞく]が増[ふ]えたので、車[くるま]をもう一台[いちだい]買[か]うことにした。", "sentence_source": "generated"}, {"text": "空港の入口にタクシーが十台ほど待っていた。", "target_word": "台", "complexity_tier": "T3", "furigana": "空港[くうこう]の入口[いりぐち]にタクシーが十台[じゅうだい]ほど待[ま]っていた。", "sentence_source": "generated"}, {"text": "この店には掃除機が五台置いてある。", "target_word": "台", "complexity_tier": "T3", "furigana": "この店[みせ]には掃除機[そうじき]が五台[ごだい]置[お]いてある。", "sentence_source": "generated"}, {"text": "農家では大きなトラクターを二台使っている。", "target_word": "台", "complexity_tier": "T3", "furigana": "農家[のうか]では大[おお]きなトラクターを二台[にだい]使[つか]っている。", "sentence_source": "generated"}, {"text": "修理工場に故障した車が六台運ばれてきた。", "target_word": "台", "complexity_tier": "T3", "furigana": "修理工場[しゅうりこうじょう]に故障[こしょう]した車[くるま]が六台[ろくだい]運[はこ]ばれてきた。", "sentence_source": "generated"}, {"text": "兄の会社は配達用の車を八台持っている。", "target_word": "台", "complexity_tier": "T3", "furigana": "兄[あに]の会社[かいしゃ]は配達用[はいたつよう]の車[くるま]を八台[はちだい]持[も]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "車や機械など、乗り物・機械を数える助数詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f35ae2-3626-49c3-8754-26766e35d357') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37145, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "台", "is_correct": true, "explanation": "車や機械を数える〈台〉。三台と数える。"}, {"text": "基", "is_correct": false, "explanation": "基は塔や墓など大きな構造物を数える語で、車には使わない。"}, {"text": "件", "is_correct": false, "explanation": "件は事柄や用件を数える語で、車には合わない。"}, {"text": "機", "is_correct": false, "explanation": "機は飛行機やエンジンなどを数える語で、車には使わない。"}], "explanations": {"台": "車や機械を数える〈台〉。三台と数える。", "基": "基は塔や墓など大きな構造物を数える語で、車には使わない。", "件": "件は事柄や用件を数える語で、車には合わない。", "機": "機は飛行機やエンジンなどを数える語で、車には使わない。"}, "sentence_index": 0, "correct_answer": "台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鉛筆を三台削った。", "explanation": "ここは〈本〉の意味。鉛筆のように細長い物は本で数える。台は車や機械を数える語なので、鉛筆には合わない。"}, {"text": "店員が三台働いている。", "explanation": "ここは〈人〉の意味。人は人で数える。台は物を数える語なので、人には使えない。"}, {"text": "本を三台買った。", "explanation": "ここは〈冊〉の意味。本や雑誌は冊で数える。台は車や機械を数える語なので、本には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37145, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台", "is_correct": true, "explanation": "掃除機など家電や機械を数える〈台〉。五台と数える。"}, {"text": "枚", "is_correct": false, "explanation": "枚は薄く平らな物を数える語で、掃除機には使わない。"}, {"text": "羽", "is_correct": false, "explanation": "羽は鳥などを数える語で、掃除機には使えない。"}, {"text": "軒", "is_correct": false, "explanation": "軒は家や店を数える語で、掃除機には合わない。"}], "explanations": {"台": "掃除機など家電や機械を数える〈台〉。五台と数える。", "枚": "枚は薄く平らな物を数える語で、掃除機には使わない。", "羽": "羽は鳥などを数える語で、掃除機には使えない。", "軒": "軒は家や店を数える語で、掃除機には合わない。"}, "sentence_index": 6, "correct_answer": "台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅に列車が五台止まっている。", "explanation": "ここは〈両〉の意味。列車は両で数える。台は列車の数え方としては合わない。"}, {"text": "漁港に漁船が五台停泊している。", "explanation": "ここは〈隻〉の意味。船は隻で数える。台は船には合わない。"}, {"text": "湖にボートが三台浮かんでいる。", "explanation": "ここは〈艇〉の意味。ボートのような小型の船は艇で数える。台は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37145, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟が中古のスクーターを一台に買った。", "corrected_sentence": "弟が中古のスクーターを一台買った。", "error_description": "余分な助詞。〈一台〉の後に〈に〉が付いている。助詞は目的語〈スクーター〉に付けるもので、数量詞の後には付けない。正しくは〈スクーターを一台買った〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37145, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "倉庫に古いバイクが三台をある。", "corrected_sentence": "倉庫に古いバイクが三台ある。", "error_description": "助詞の誤り。〈三台〉の後に〈を〉が付いているが、〈ある〉は存在を表し目的語を取らないので〈を〉は要らない。正しくは〈バイクが三台ある〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37146, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「いちご」を目的語にとる乗せるの対象を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、置かれる対象（目的語）の位置には合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用を示すため、置く対象を表せない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示すため、目的語の位置には合わない。"}], "correct_answer": "を", "explanations": {"を": "「いちご」を目的語にとる乗せるの対象を示す正しい助詞。", "が": "主語を示す助詞で、置かれる対象（目的語）の位置には合わない。", "と": "共同・引用を示すため、置く対象を表せない。", "で": "手段・場所を示すため、目的語の位置には合わない。"}, "error_tags": {"が": "主語の助詞", "と": "共同・引用", "で": "手段・場所"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降ろす", "is_correct": true, "explanation": "乗せるの対義語で、上に載せたものを下へ移す意味を表す。"}, {"text": "押す", "is_correct": false, "explanation": "力を加えて動かす動作で、上下の移動の対義語ではない。"}, {"text": "持つ", "is_correct": false, "explanation": "手で保つ動作で、乗せるの対義語にはならない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "場所を移す動作だが、上に載せる動作の対義語にはならない。"}], "correct_answer": "降ろす", "explanations": {"降ろす": "乗せるの対義語で、上に載せたものを下へ移す意味を表す。", "押す": "力を加えて動かす動作で、上下の移動の対義語ではない。", "持つ": "手で保つ動作で、乗せるの対義語にはならない。", "運ぶ": "場所を移す動作だが、上に載せる動作の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37146, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「膝」の位置を示す「に」で、乗せる場所を表す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示すため、置く場所を表せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すので、置く先（到達点）には合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点を示し、ここでは置く場所を表せない。"}], "correct_answer": "に", "explanations": {"に": "「膝」の位置を示す「に」で、乗せる場所を表す。", "の": "連体修飾を示すため、置く場所を表せない。", "から": "起点を示すので、置く先（到達点）には合わない。", "より": "比較・起点を示し、ここでは置く場所を表せない。"}, "error_tags": {"の": "連体修飾", "から": "起点", "より": "比較・起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降ろす", "is_correct": true, "explanation": "乗せるの対義語で、肩に乗せた人を下ろす意味を表す。"}, {"text": "叩く", "is_correct": false, "explanation": "強く打つ動作で、上下の移動の対義語ではない。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作で、載せる動作との対義関係はない。"}, {"text": "掴む", "is_correct": false, "explanation": "握って取る動作で、乗せるの対義語にはならない。"}], "correct_answer": "降ろす", "explanations": {"降ろす": "乗せるの対義語で、肩に乗せた人を下ろす意味を表す。", "叩く": "強く打つ動作で、上下の移動の対義語ではない。", "眺める": "見る動作で、載せる動作との対義関係はない。", "掴む": "握って取る動作で、乗せるの対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37146, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や物を上にのせる。", "primary_collocate": null, "pronunciation": "のせる", "ipa": "noseɾɯ", "syllable_count": 3, "sentences": [{"text": "母は赤ちゃんをひざに乗せて、絵本を読んであげた。", "target_word": "乗せて", "complexity_tier": "T3", "furigana": "母[はは]は赤[あか]ちゃんをひざに乗[の]せて、絵本[えほん]を読[よ]んであげた。", "sentence_source": "generated"}, {"text": "仕上げに、ケーキの上にいちごを乗せる。", "target_word": "乗せる", "complexity_tier": "T3", "furigana": "仕上[しあ]げに、ケーキの上[うえ]にいちごを乗[の]せる。", "sentence_source": "generated"}, {"text": "パンの上にチーズを乗せて、オーブンで焼く。", "target_word": "乗せて", "complexity_tier": "T3", "furigana": "パンの上[うえ]にチーズを乗[の]せて、オーブンで焼[や]く。", "sentence_source": "generated"}, {"text": "重い荷物を棚に乗せようとして、腰を痛めた。", "target_word": "乗せよう", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を棚[たな]に乗[の]せようとして、腰[こし]を痛[いた]めた。", "sentence_source": "generated"}, {"text": "お盆にコップを乗せて、客のところへ運んだ。", "target_word": "乗せて", "complexity_tier": "T3", "furigana": "お盆[ぼん]にコップを乗[の]せて、客[きゃく]のところへ運[はこ]んだ。", "sentence_source": "generated"}, {"text": "弟は頭に帽子を乗せたまま、食事を始めた。", "target_word": "乗せた", "complexity_tier": "T3", "furigana": "弟[おとうと]は頭[あたま]に帽子[ぼうし]を乗[の]せたまま、食事[しょくじ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "この机は弱いので、重い物を乗せないでほしい。", "target_word": "乗せない", "complexity_tier": "T3", "furigana": "この机[つくえ]は弱[よわ]いので、重[おも]い物[もの]を乗[の]せないでほしい。", "sentence_source": "generated"}, {"text": "祖父は孫を膝に乗せるのが何よりの楽しみだ。", "target_word": "乗せる", "complexity_tier": "T3", "furigana": "祖父[そふ]は孫[まご]を膝[ひざ]に乗[の]せるのが何[なに]よりの楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "肉を網の上に乗せると、いい音がして煙が上がった。", "target_word": "乗せる", "complexity_tier": "T3", "furigana": "肉[にく]を網[あみ]の上[うえ]に乗[の]せると、いい音[おと]がして煙[けむり]が上[あ]がった。", "sentence_source": "generated"}, {"text": "兄は私を肩に乗せて、花火を見せてくれた。", "target_word": "乗せて", "complexity_tier": "T3", "furigana": "兄[あに]は私[わたし]を肩[かた]に乗[の]せて、花火[はなび]を見[み]せてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "乗せる", "label": "辞書形"}, {"form": "乗せます", "label": "ます形"}, {"form": "乗せて", "label": "て形"}, {"form": "乗せた", "label": "過去形"}, {"form": "乗せない", "label": "否定形"}, {"form": "乗せられる", "label": "可能形"}, {"form": "乗せれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "人や物をほかの物の上に置く、または人をひざや肩などの上にのせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451f182-b416-4156-a958-f234e1ab7309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37146, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乗せて", "is_correct": true, "explanation": "ひざの上に載せた状態を表し、その後で絵本を読むという流れに合う。"}, {"text": "焼いて", "is_correct": false, "explanation": "焼くは熱で加熱する動作で、赤ちゃんをひざに置く場面には合わない。"}, {"text": "洗って", "is_correct": false, "explanation": "洗うは水などで汚れを落とす動作で、人をひざに置く文脈には合わない。"}, {"text": "削って", "is_correct": false, "explanation": "削るは表面を薄く取る動作で、人をひざに置くことには使えない。"}], "explanations": {"乗せて": "ひざの上に載せた状態を表し、その後で絵本を読むという流れに合う。", "焼いて": "焼くは熱で加熱する動作で、赤ちゃんをひざに置く場面には合わない。", "洗って": "洗うは水などで汚れを落とす動作で、人をひざに置く文脈には合わない。", "削って": "削るは表面を薄く取る動作で、人をひざに置くことには使えない。"}, "sentence_index": 0, "correct_answer": "乗せて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の壁に絵を乗せて、釘でしっかり固定した。", "explanation": "ここは〈掛ける〉の意味。壁に吊るす場合は掛けるを使い、乗せるは物を上に載せる動作なので合わない。"}, {"text": "コップに水を乗せて、ゆっくり飲んだ。", "explanation": "ここは〈入れる〉の意味。液体を容器に入れる場合は入れるを使うので、乗せるは合わない。"}, {"text": "花びんに花を乗せて、窓辺に飾った。", "explanation": "ここは〈挿す〉の意味。花を花びんに挿す場合は挿すを使い、乗せるは上に置く動作なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37146, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乗せない", "is_correct": true, "explanation": "否定形で「〜ないでほしい」と続き、依頼の文として正しい。"}, {"text": "乗せよう", "is_correct": false, "explanation": "意志形は「〜ようでほしい」と続かず不自然。"}, {"text": "乗せれば", "is_correct": false, "explanation": "仮定形は「〜ればでほしい」と続かず、文が成り立たない。"}, {"text": "乗せます", "is_correct": false, "explanation": "丁寧形は「〜ますでほしい」と続けられず不適切。"}], "explanations": {"乗せない": "否定形で「〜ないでほしい」と続き、依頼の文として正しい。", "乗せよう": "意志形は「〜ようでほしい」と続かず不自然。", "乗せれば": "仮定形は「〜ればでほしい」と続かず、文が成り立たない。", "乗せます": "丁寧形は「〜ますでほしい」と続けられず不適切。"}, "sentence_index": 6, "correct_answer": "乗せない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木の枝にひもを乗せて、ブランコを作った。", "explanation": "ここは〈結びつける〉の意味。ひもを枝に結ぶ場合は結ぶを使い、乗せるは上に置く動作なので合わない。"}, {"text": "封筒に切手を乗せて、ポストに入れた。", "explanation": "ここは〈貼る〉の意味。切手は封筒に貼り付けるもので、貼るを使う。乗せるは上に置くだけなので合わない。"}, {"text": "ねじ穴にねじを乗せて、回した。", "explanation": "ここは〈ねじ込む〉の意味。ねじを穴に回し入れる場合はねじ込むを使い、乗せるは上に置く動作なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37146, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鍋の上に蓋で乗せたが、すぐ外した。", "corrected_sentence": "鍋の上に蓋を乗せたが、すぐ外した。", "error_description": "助詞の誤り。乗せるの対象（蓋）には「を」が必要で、「で」は手段・場所を表すため誤り。「蓋を乗せた」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "乗せる", "is_correct": true, "explanation": "文末で言い切る辞書形。「仕上げに」で始まる手順の文の述語として正しい。"}, {"text": "乗せて", "is_correct": false, "explanation": "て形は文末で言い切れず、続きが必要になるので不適切。"}, {"text": "乗せれば", "is_correct": false, "explanation": "仮定形は文末で言い切れず、「乗せれば」だけでは文が完結しない。"}, {"text": "乗せたら", "is_correct": false, "explanation": "条件形は文末で言い切れず、続きがないと文が成り立たない。"}], "correct_form": "乗せる", "base_form": "乗せる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"乗せる": "文末で言い切る辞書形。「仕上げに」で始まる手順の文の述語として正しい。", "乗せて": "て形は文末で言い切れず、続きが必要になるので不適切。", "乗せれば": "仮定形は文末で言い切れず、「乗せれば」だけでは文が完結しない。", "乗せたら": "条件形は文末で言い切れず、続きがないと文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37146, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この机は弱いので、重い本を乗せなくてほしい。", "corrected_sentence": "この机は弱いので、重い本を乗せないでほしい。", "error_description": "活用の誤り。依頼の否定は「乗せないでほしい」が正しく、「乗せなくてほしい」は接続が不自然で誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "乗せる", "is_correct": true, "explanation": "「のが」の前に来る辞書形で、名詞化して「〜のが」と続く正しい形。"}, {"text": "乗せます", "is_correct": false, "explanation": "丁寧形は名詞の前には続かず不適切。"}, {"text": "乗せよう", "is_correct": false, "explanation": "意志形は「〜のが」の前に置けない。"}, {"text": "乗せれば", "is_correct": false, "explanation": "仮定形は名詞修飾に使えず、文が成り立たない。"}], "correct_form": "乗せる", "base_form": "乗せる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"乗せる": "「のが」の前に来る辞書形で、名詞化して「〜のが」と続く正しい形。", "乗せます": "丁寧形は名詞の前には続かず不適切。", "乗せよう": "意志形は「〜のが」の前に置けない。", "乗せれば": "仮定形は名詞修飾に使えず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37147, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「車いすの人」を目的語にとる乗せるの対象を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、乗せられる対象の位置には合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同・並列を示し、目的語の位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示すため、人の位置には合わない。"}], "correct_answer": "を", "explanations": {"を": "「車いすの人」を目的語にとる乗せるの対象を示す正しい助詞。", "が": "主語を示す助詞で、乗せられる対象の位置には合わない。", "と": "共同・並列を示し、目的語の位置には合わない。", "で": "手段・場所を示すため、人の位置には合わない。"}, "error_tags": {"が": "主語の助詞", "と": "共同・並列", "で": "手段・場所"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降ろす", "is_correct": true, "explanation": "乗せるの対義語で、車から人を降ろす意味を表す。"}, {"text": "押す", "is_correct": false, "explanation": "力を加えて動かす動作で、乗り降りの対義語ではない。"}, {"text": "持つ", "is_correct": false, "explanation": "手で保つ動作で、乗せるの対義語にはならない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "移動させる動作で、乗せるの対義語ではない。"}], "correct_answer": "降ろす", "explanations": {"降ろす": "乗せるの対義語で、車から人を降ろす意味を表す。", "押す": "力を加えて動かす動作で、乗り降りの対義語ではない。", "持つ": "手で保つ動作で、乗せるの対義語にはならない。", "運ぶ": "移動させる動作で、乗せるの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37147, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「車」の場所を示し、乗せる先を表す正しい助詞。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示すため、乗せる先を表せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、乗せる先（到達点）には合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点を示し、ここでは場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "「車」の場所を示し、乗せる先を表す正しい助詞。", "の": "連体修飾を示すため、乗せる先を表せない。", "から": "起点を示すため、乗せる先（到達点）には合わない。", "より": "比較・起点を示し、ここでは場所を示せない。"}, "error_tags": {"の": "連体修飾", "から": "起点", "より": "比較・起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降ろす", "is_correct": true, "explanation": "乗せるの対義語で、乗客を乗り物から下ろす意味を表す。"}, {"text": "叩く", "is_correct": false, "explanation": "強く打つ動作で、乗り降りの対義語ではない。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作で、乗せるとの対義関係はない。"}, {"text": "掴む", "is_correct": false, "explanation": "握って取る動作で、乗せるの対義語にはならない。"}], "correct_answer": "降ろす", "explanations": {"降ろす": "乗せるの対義語で、乗客を乗り物から下ろす意味を表す。", "叩く": "強く打つ動作で、乗り降りの対義語ではない。", "眺める": "見る動作で、乗せるとの対義関係はない。", "掴む": "握って取る動作で、乗せるの対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37147, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や物を車や電車などの上にのせること。", "primary_collocate": null, "pronunciation": "のせる", "ipa": "noseɾɯ", "syllable_count": 3, "sentences": [{"text": "父は友達を車に乗せて、駅まで送った。", "target_word": "乗せて", "complexity_tier": "T3", "furigana": "父[ちち]は友達[ともだち]を車[くるま]に乗[の]せて、駅[えき]まで送[おく]った。", "sentence_source": "generated"}, {"text": "このバスは車いすの人を乗せることができる。", "target_word": "乗せる", "complexity_tier": "T3", "furigana": "このバスは車[くるま]いすの人[ひと]を乗[の]せることができる。", "sentence_source": "generated"}, {"text": "運転手は重い荷物をトランクに乗せてくれた。", "target_word": "乗せて", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]は重[おも]い荷物[にもつ]をトランクに乗[の]せてくれた。", "sentence_source": "generated"}, {"text": "雨が降っていたので、近所の人が私を車に乗せてくれた。", "target_word": "乗せて", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]っていたので、近所[きんじょ]の人[ひと]が私[わたし]を車[くるま]に乗[の]せてくれた。", "sentence_source": "generated"}, {"text": "この船は百人の客を乗せて、島へ向かう。", "target_word": "乗せて", "complexity_tier": "T3", "furigana": "この船[ふね]は百人[ひゃくにん]の客[きゃく]を乗[の]せて、島[しま]へ向[む]かう。", "sentence_source": "generated"}, {"text": "運転手は酔った客を乗せたくなかったので、断った。", "target_word": "乗せたく", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]は酔[よ]った客[きゃく]を乗[の]せたくなかったので、断[ことわ]った。", "sentence_source": "generated"}, {"text": "自転車を電車に乗せるときは、専用の袋に入れなければならない。", "target_word": "乗せる", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]を電車[でんしゃ]に乗[の]せるときは、専用[せんよう]の袋[ふくろ]に入[い]れなければならない。", "sentence_source": "generated"}, {"text": "荷物が多すぎて、これ以上は車に乗せられない。", "target_word": "乗せられない", "complexity_tier": "T3", "furigana": "荷物[にもつ]が多[おお]すぎて、これ以上[いじょう]は車[くるま]に乗[の]せられない。", "sentence_source": "generated"}, {"text": "彼は妹を自転車の後ろに乗せて、学校まで走った。", "target_word": "乗せて", "complexity_tier": "T3", "furigana": "彼[かれ]は妹[いもうと]を自転車[じてんしゃ]の後[うし]ろに乗[の]せて、学校[がっこう]まで走[はし]った。", "sentence_source": "generated"}, {"text": "バスは乗客を乗せると、ゆっくり動き出した。", "target_word": "乗せる", "complexity_tier": "T3", "furigana": "バスは乗客[じょうきゃく]を乗[の]せると、ゆっくり動[うご]き出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "乗せる", "label": "辞書形"}, {"form": "乗せます", "label": "ます形"}, {"form": "乗せて", "label": "て形"}, {"form": "乗せた", "label": "過去形"}, {"form": "乗せない", "label": "否定形"}, {"form": "乗せられる", "label": "可能形"}, {"form": "乗せれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "人や荷物を車・電車・船などの乗り物に入れて運ぶ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451f182-b416-4156-a958-f234e1ab7309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37147, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乗せて", "is_correct": true, "explanation": "車に人を入れた状態を表し、その後に駅まで送る流れに合う。"}, {"text": "磨いて", "is_correct": false, "explanation": "磨くは表面をこする動作で、車に人を入れる文脈には合わない。"}, {"text": "砕いて", "is_correct": false, "explanation": "砕くは細かく割る動作で、人や車には使えず不自然。"}, {"text": "焼いて", "is_correct": false, "explanation": "焼くは加熱する動作で、乗り物に人を入れる意味にはならない。"}], "explanations": {"乗せて": "車に人を入れた状態を表し、その後に駅まで送る流れに合う。", "磨いて": "磨くは表面をこする動作で、車に人を入れる文脈には合わない。", "砕いて": "砕くは細かく割る動作で、人や車には使えず不自然。", "焼いて": "焼くは加熱する動作で、乗り物に人を入れる意味にはならない。"}, "sentence_index": 0, "correct_answer": "乗せて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもを教室に乗せて、ドアを閉めた。", "explanation": "ここは〈入れる〉の意味。部屋の中に人を入れる場合は入れるを使い、乗せるは乗り物に人を入れる意味なので合わない。"}, {"text": "車を玄関に乗せて、鍵をかけた。", "explanation": "ここは〈寄せる〉の意味。車を近くに止める場合は寄せるを使い、乗せるは人や物を車に入れる意味なので合わない。"}, {"text": "私は友達を屋上に乗せて、景色を見せた。", "explanation": "ここは〈連れて行く〉の意味。人を場所へ連れて行く場合は連れて行くを使い、乗せるは乗り物に人を入れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37147, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乗せる", "is_correct": true, "explanation": "辞書形で「ときは」に続き、条件を述べる文として正しい。"}, {"text": "乗せよう", "is_correct": false, "explanation": "意志形は「ときは」に続かず不自然。"}, {"text": "乗せれば", "is_correct": false, "explanation": "仮定形は「ときは」の前に置けず不適切。"}, {"text": "乗せます", "is_correct": false, "explanation": "丁寧形は「とき」に続かず不自然。"}], "explanations": {"乗せる": "辞書形で「ときは」に続き、条件を述べる文として正しい。", "乗せよう": "意志形は「ときは」に続かず不自然。", "乗せれば": "仮定形は「ときは」の前に置けず不適切。", "乗せます": "丁寧形は「とき」に続かず不自然。"}, "sentence_index": 6, "correct_answer": "乗せる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は孫を書斎に乗せて、ドアを閉めた。", "explanation": "ここは〈入れる〉の意味。部屋の中に人を入れる場合は入れるを使い、乗せるは乗り物に人を入れる意味なので合わない。"}, {"text": "先生は子どもを黒板の前に乗せた。", "explanation": "ここは〈立たせる〉の意味。人を場所に立たせる場合は立たせるを使い、乗せるは乗り物に人を入れる意味なので合わない。"}, {"text": "彼は妹を家に乗せて、一人で出かけた。", "explanation": "ここは〈残す〉の意味。人を場所に置いていく場合は残すを使い、乗せるは乗り物に人を入れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37147, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は荷物を車を乗せて、駅まで運んだ。", "corrected_sentence": "父は荷物を車に乗せて、駅まで運んだ。", "error_description": "助詞の誤り。乗せるの場所（乗り物）には「に」が必要で、「車を」は誤り。「車に乗せて」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "乗せる", "is_correct": true, "explanation": "「こと」に続く辞書形で、動詞を名詞句にして「できる」と続く正しい形。"}, {"text": "乗せた", "is_correct": false, "explanation": "過去形は「こと」の前に置くと不自然で、可能の意味が合わない。"}, {"text": "乗せない", "is_correct": false, "explanation": "否定形では「できる」の意味が逆になる。"}, {"text": "乗せたい", "is_correct": false, "explanation": "願望形は「〜ことができる」の能力の意味に合わない。"}], "correct_form": "乗せる", "base_form": "乗せる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"乗せる": "「こと」に続く辞書形で、動詞を名詞句にして「できる」と続く正しい形。", "乗せた": "過去形は「こと」の前に置くと不自然で、可能の意味が合わない。", "乗せない": "否定形では「できる」の意味が逆になる。", "乗せたい": "願望形は「〜ことができる」の能力の意味に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37147, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "箱が多すぎて、これ以上は車に乗せられる。", "corrected_sentence": "箱が多すぎて、これ以上は車に乗せられない。", "error_description": "否定の誤り。「多すぎて」は限界を表すので「乗せられない」が必要。「乗せられる」は肯定で文意が逆になり誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "乗せられない", "is_correct": true, "explanation": "可能形の否定形で、「これ以上は〜できない」の意味に合う。"}, {"text": "乗せられれば", "is_correct": false, "explanation": "条件形は文末で言い切れず、「乗せられれば」だけでは文が完結しない。"}, {"text": "乗せよう", "is_correct": false, "explanation": "意志形は可能の意味に合わない。"}, {"text": "乗せれば", "is_correct": false, "explanation": "仮定形は文が続かず、限界の意味を表せない。"}], "correct_form": "乗せられない", "base_form": "乗せる", "form_label": "可能形の否定形", "sentence_index": 7, "explanations": {"乗せられない": "可能形の否定形で、「これ以上は〜できない」の意味に合う。", "乗せられれば": "条件形は文末で言い切れず、「乗せられれば」だけでは文が完結しない。", "乗せよう": "意志形は可能の意味に合わない。", "乗せれば": "仮定形は文が続かず、限界の意味を表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37148, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示す助詞。ここで〈手段〉は探される対象なので、目的語を示す〈を〉が正しく、〈手段が探した〉では意味が通らない。"}, {"text": "を", "is_correct": true, "explanation": "〈探す〉の目的語〈別の手段〉を示す〈を〉。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は到着点や相手を示す助詞で、〈探す〉の対象には使わない。〈手段に探した〉は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は共同や引用を示す助詞。〈手段と探した〉では探す対象が示せず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"が": "〈が〉は主語を示す助詞。ここで〈手段〉は探される対象なので、目的語を示す〈を〉が正しく、〈手段が探した〉では意味が通らない。", "を": "〈探す〉の目的語〈別の手段〉を示す〈を〉。", "に": "〈に〉は到着点や相手を示す助詞で、〈探す〉の対象には使わない。〈手段に探した〉は成り立たない。", "と": "〈と〉は共同や引用を示す助詞。〈手段と探した〉では探す対象が示せず、文が成り立たない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37148, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "〈手段〉と〈一つ〉をつなぐ〈の〉。「手段の一つ」で〈手段〉のうちの一つという意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す助詞。〈手段へ一つ〉では名詞同士をつなげられず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を示す助詞。〈手段から一つ〉では〈一つ〉との関係を示せず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を示す助詞。〈手段より一つ〉では比べる相手がなく、〈手段の一つ〉の意味にならない。"}], "correct_answer": "の", "explanations": {"の": "〈手段〉と〈一つ〉をつなぐ〈の〉。「手段の一つ」で〈手段〉のうちの一つという意味になる。", "へ": "〈へ〉は方向を示す助詞。〈手段へ一つ〉では名詞同士をつなげられず、文が成り立たない。", "から": "〈から〉は起点を示す助詞。〈手段から一つ〉では〈一つ〉との関係を示せず、意味が通らない。", "より": "〈より〉は比較を示す助詞。〈手段より一つ〉では比べる相手がなく、〈手段の一つ〉の意味にならない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37148, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときに使う方法や道具のことです。", "primary_collocate": null, "pronunciation": "しゅだん", "ipa": "ɕɯdaɴ", "syllable_count": 3, "sentences": [{"text": "目的を達成するために、あらゆる手段を考えた。", "target_word": "手段", "complexity_tier": "T3", "furigana": "目的[もくてき]を達成[たっせい]するために、あらゆる手段[しゅだん]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "電車が止まったので、会社に行く別の手段を探した。", "target_word": "手段", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が止[と]まったので、会社[かいしゃ]に行[い]く別[べつ]の手段[しゅだん]を探[さが]した。", "sentence_source": "generated"}, {"text": "話し合いで解決する手段がなくなり、裁判になった。", "target_word": "手段", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いで解決[かいけつ]する手段[しゅだん]がなくなり、裁判[さいばん]になった。", "sentence_source": "generated"}, {"text": "目的のためなら手段を選ばないという考え方は危険だ。", "target_word": "手段", "complexity_tier": "T3", "furigana": "目的[もくてき]のためなら手段[しゅだん]を選[えら]ばないという考[かんが]え方[かた]は危険[きけん]だ。", "sentence_source": "generated"}, {"text": "山の中では、連絡する手段が電話しかなくて困った。", "target_word": "手段", "complexity_tier": "T3", "furigana": "山[やま]の中[なか]では、連絡[れんらく]する手段[しゅだん]が電話[でんわ]しかなくて困[こま]った。", "sentence_source": "generated"}, {"text": "彼女は最後の手段として、友達にお金を借りた。", "target_word": "手段", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は最後[さいご]の手段[しゅだん]として、友達[ともだち]にお金[かね]を借[か]りた。", "sentence_source": "generated"}, {"text": "雪で道が使えず、ヘリコプターが唯一の移動の手段だった。", "target_word": "手段", "complexity_tier": "T3", "furigana": "雪[ゆき]で道[みち]が使[つか]えず、ヘリコプターが唯一[ゆいいつ]の移動[いどう]の手段[しゅだん]だった。", "sentence_source": "generated"}, {"text": "値上げは企業にとって、利益を増やす手段の一つだ。", "target_word": "手段", "complexity_tier": "T3", "furigana": "値上[ねあ]げは企業[きぎょう]にとって、利益[りえき]を増[ふ]やす手段[しゅだん]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "彼はお金を稼ぐ手段として、ネットで古本を売っている。", "target_word": "手段", "complexity_tier": "T3", "furigana": "彼[かれ]はお金[かね]を稼[かせ]ぐ手段[しゅだん]として、ネットで古本[ふるほん]を売[う]っている。", "sentence_source": "generated"}, {"text": "災害の時は、情報を集める手段を二つ以上持っておくとよい。", "target_word": "手段", "complexity_tier": "T3", "furigana": "災害[さいがい]の時[とき]は、情報[じょうほう]を集[あつ]める手段[しゅだん]を二[ふた]つ以上[いじょう]持[も]っておくとよい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手段", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "目的を果たすために使う方法や道具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f35ae2-3626-49c3-8754-26766e35d357') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37148, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手段", "is_correct": true, "explanation": "目的を果たすための方法や道具を表す〈手段〉。"}, {"text": "予算", "is_correct": false, "explanation": "予算は使える金額の見積もりで、考える対象の方法とは合わない。"}, {"text": "期限", "is_correct": false, "explanation": "期限は締め切りの時期で、方法の代わりにはならない。"}, {"text": "本音", "is_correct": false, "explanation": "本音は本当の気持ちで、方法を考えるという文脈には合わない。"}], "explanations": {"手段": "目的を果たすための方法や道具を表す〈手段〉。", "予算": "予算は使える金額の見積もりで、考える対象の方法とは合わない。", "期限": "期限は締め切りの時期で、方法の代わりにはならない。", "本音": "本音は本当の気持ちで、方法を考えるという文脈には合わない。"}, "sentence_index": 0, "correct_answer": "手段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この事故の手段は居眠り運転だ。", "explanation": "ここは〈原因〉の意味。居眠り運転が事故を起こしたことは原因。手段は目的を果たす方法なので、原因は指せない。"}, {"text": "この料理は作るのに手段がかかる。", "explanation": "ここは〈手間〉の意味。作業にかかる時間や労力は手間。手段は方法を指すので、かかる負担には使えない。"}, {"text": "この旅行の手段は友達に会うことだ。", "explanation": "ここは〈目的〉の意味。友達に会うことは旅行の目指すところなので目的。手段は目的を果たす方法なので、この文の内容とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37148, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手段", "is_correct": true, "explanation": "移動の方法としての〈手段〉。唯一の移動の手段だったと言える。"}, {"text": "期間", "is_correct": false, "explanation": "期間は長さの区切りを表し、移動の方法とは合わない。"}, {"text": "速度", "is_correct": false, "explanation": "速度は速さの程度で、移動の方法の代わりにはならない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は天気の状態で、移動の方法とは合わない。"}], "explanations": {"手段": "移動の方法としての〈手段〉。唯一の移動の手段だったと言える。", "期間": "期間は長さの区切りを表し、移動の方法とは合わない。", "速度": "速度は速さの程度で、移動の方法の代わりにはならない。", "天候": "天候は天気の状態で、移動の方法とは合わない。"}, "sentence_index": 6, "correct_answer": "手段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この工事の手段は百万円だ。", "explanation": "ここは〈費用〉の意味。金額で表されるのは費用。手段は方法を指すので、金額は表せない。"}, {"text": "役所で住民票の手段を済ませた。", "explanation": "ここは〈手続き〉の意味。役所で決まった書類や手順を済ませることは手続き。手段は目的を果たす方法なので、済ませる対象にはならない。"}, {"text": "会議の手段は賛成多数だった。", "explanation": "ここは〈結論〉の意味。議論の末に決まった判断は結論。手段は方法なので、判断の内容は指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37148, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その目的を果たす手段を探してている。", "corrected_sentence": "その目的を果たす手段を探している。", "error_description": "動詞〈探す〉の活用の誤り。〈探している〉が正しく、〈探してている〉では〈て〉が二重になっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37148, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "非常時に連絡をとる手段が二つ用意しておく。", "corrected_sentence": "非常時に連絡をとる手段を二つ用意しておく。", "error_description": "助詞の誤り。〈手段〉に付く助詞が〈が〉になっているが、〈用意しておく〉は他動詞なので目的語は〈を〉で示す。〈手段を二つ用意しておく〉が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37150, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「効果で」は原因を示し、運動を続けた結果として体が軽くなったという文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「効果を」だと効果が動作の対象になり、体が軽くなる原因を述べる文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「効果に」は対象や到達点を示すが、原因を述べる文脈では合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「効果へ」は方向を示すが、体が軽くなった原因を述べる形にならない。"}], "correct_answer": "で", "explanations": {"で": "「効果で」は原因を示し、運動を続けた結果として体が軽くなったという文に合う。", "を": "「効果を」だと効果が動作の対象になり、体が軽くなる原因を述べる文が成り立たない。", "に": "「効果に」は対象や到達点を示すが、原因を述べる文脈では合わない。", "へ": "「効果へ」は方向を示すが、体が軽くなった原因を述べる形にならない。"}, "error_tags": {"を": "目的語", "に": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37150, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「効果が切れる」で、薬の働きが終わるという意味になり、主語を示す「が」が正しい。"}, {"text": "より", "is_correct": false, "explanation": "比べる相手がないので、「効果より切れると」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すが、「切れると」の条件とうまく結びつかず不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、効果そのものが切れるという主語の関係に合わない。"}], "correct_answer": "が", "explanations": {"が": "「効果が切れる」で、薬の働きが終わるという意味になり、主語を示す「が」が正しい。", "より": "比べる相手がないので、「効果より切れると」では文が成り立たない。", "と": "「と」は並列や引用を示すが、「切れると」の条件とうまく結びつかず不自然。", "から": "起点を示す「から」は、効果そのものが切れるという主語の関係に合わない。"}, "error_tags": {"より": "比較", "と": "並列・条件", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37150, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをしたときに、ねらったとおりのよい結果が出ること。", "primary_collocate": null, "pronunciation": "こうか", "ipa": "koːka", "syllable_count": 3, "sentences": [{"text": "この薬は、飲んで三十分ほどで効果が出ます。", "target_word": "効果", "complexity_tier": "T3", "furigana": "この薬(くすり)は、飲(の)んで三十分(さんじゅっぷん)ほどで効果(こうか)が出(で)ます。", "sentence_source": "generated"}, {"text": "運動を続けた効果で、体が軽くなりました。", "target_word": "効果", "complexity_tier": "T3", "furigana": "運動(うんどう)を続(つづ)けた効果(こうか)で、体(からだ)が軽(かる)くなりました。", "sentence_source": "generated"}, {"text": "広告の効果があり、店に客が増えました。", "target_word": "効果", "complexity_tier": "T3", "furigana": "広告(こうこく)の効果(こうか)があり、店(みせ)に客(きゃく)が増(ふ)えました。", "sentence_source": "generated"}, {"text": "勉強のやり方を変えましたが、効果はあまりありませんでした。", "target_word": "効果", "complexity_tier": "T3", "furigana": "勉強(べんきょう)のやり方(かた)を変(か)えましたが、効果(こうか)はあまりありませんでした。", "sentence_source": "generated"}, {"text": "早く寝ると、疲れをとる効果があります。", "target_word": "効果", "complexity_tier": "T3", "furigana": "早(はや)く寝(ね)ると、疲(つか)れをとる効果(こうか)があります。", "sentence_source": "generated"}, {"text": "この対策は、すぐに効果が見えるわけではありません。", "target_word": "効果", "complexity_tier": "T3", "furigana": "この対策(たいさく)は、すぐに効果(こうか)が見(み)えるわけではありません。", "sentence_source": "generated"}, {"text": "先生にほめられた効果で、彼は急に勉強を頑張り始めました。", "target_word": "効果", "complexity_tier": "T3", "furigana": "先生(せんせい)にほめられた効果(こうか)で、彼(かれ)は急(きゅう)に勉強(べんきょう)を頑張(がんば)り始(はじ)めました。", "sentence_source": "generated"}, {"text": "薬の効果が切れると、また痛みが戻ります。", "target_word": "効果", "complexity_tier": "T3", "furigana": "薬(くすり)の効果(こうか)が切(き)れると、また痛(いた)みが戻(もど)ります。", "sentence_source": "generated"}, {"text": "値下げの効果はなく、売り上げは変わりませんでした。", "target_word": "効果", "complexity_tier": "T3", "furigana": "値下(ねさ)げの効果(こうか)はなく、売(う)り上(あ)げは変(か)わりませんでした。", "sentence_source": "generated"}, {"text": "音楽を聞くと、気持ちが落ち着く効果があります。", "target_word": "効果", "complexity_tier": "T3", "furigana": "音楽(おんがく)を聞(き)くと、気持(きも)ちが落(お)ち着(つ)く効果(こうか)があります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "効果", "label": "基本形"}, {"form": "効果の", "label": "連体修飾形"}], "register": "中立（丁寧体）", "sense_fingerprint": "ある働きかけによって得られる、ねらいどおりのよい結果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab72206-6277-420c-88d0-f9c8f74db76f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37150, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "効果", "is_correct": true, "explanation": "「効果が出る」で、薬を飲んだあとに現れるねらった結果を表す。"}, {"text": "薬局", "is_correct": false, "explanation": "薬局は店や場所を指すので、「薬局が出ます」は結果を表さず意味が通らない。"}, {"text": "注射", "is_correct": false, "explanation": "注射は治療の行為や処置で、飲んだあとに出るものではないので合わない。"}, {"text": "診察", "is_correct": false, "explanation": "診察は受ける行為で、「診察が出ます」は薬の働きの結果としては成り立たない。"}], "explanations": {"効果": "「効果が出る」で、薬を飲んだあとに現れるねらった結果を表す。", "薬局": "薬局は店や場所を指すので、「薬局が出ます」は結果を表さず意味が通らない。", "注射": "注射は治療の行為や処置で、飲んだあとに出るものではないので合わない。", "診察": "診察は受ける行為で、「診察が出ます」は薬の働きの結果としては成り立たない。"}, "sentence_index": 0, "correct_answer": "効果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "入試の効果は、来週発表されます。", "explanation": "ここは〈結果〉の意味。効果はねらったとおりのよい結果を指すので、試験の成績そのものには合わない。"}, {"text": "作業の効果で、データが消えてしまいました。", "explanation": "ここは〈結果〉の意味。効果はねらったよい結果を指すので、データが消えるような結果には合わない。"}, {"text": "薬の効果で、熱が出ました。", "explanation": "ここは〈副作用〉の意味。効果はねらったよい結果を指すので、熱のような望まない結果には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37150, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "効果", "is_correct": true, "explanation": "「先生にほめられた効果」で、ほめられたことがきっかけで生じた良い結果を表す。"}, {"text": "時計", "is_correct": false, "explanation": "時計は物で、「先生にほめられた時計で」は原因として成り立たない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は自然現象で、先生にほめられることの結果にはならないので合わない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は建物の一部で、ほめられた結果を表す語としては意味が通らない。"}], "explanations": {"効果": "「先生にほめられた効果」で、ほめられたことがきっかけで生じた良い結果を表す。", "時計": "時計は物で、「先生にほめられた時計で」は原因として成り立たない。", "雨": "雨は自然現象で、先生にほめられることの結果にはならないので合わない。", "天井": "天井は建物の一部で、ほめられた結果を表す語としては意味が通らない。"}, "sentence_index": 6, "correct_answer": "効果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台風の効果で、道路が冠水しました。", "explanation": "ここは〈影響〉の意味。効果はねらったよい結果を指すので、冠水のような悪い結果には合わない。"}, {"text": "けがの効果で、今も足が痛みます。", "explanation": "ここは〈後遺症〉の意味。効果は望んだよい結果を指すので、残る痛みには合わない。"}, {"text": "この工場の効果は、一日に千個です。", "explanation": "ここは〈生産性〉の意味。効果はねらったよい結果を指すので、単位時間あたりの生産量の意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37150, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日の散歩の効果を、体力がつきました。", "corrected_sentence": "毎日の散歩の効果で、体力がつきました。", "error_description": "助詞の誤り。原因を表す「効果で」が正しいが、「効果を」になっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37150, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "薬の効果が表すまで、一時間かかります。", "corrected_sentence": "薬の効果が現れるまで、一時間かかります。", "error_description": "動詞の誤り。主語「効果」に合うのは自動詞の「現れる」だが、他動詞の「表す」が使われている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
