INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37152, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときの、その一部として行うこと。", "primary_collocate": null, "pronunciation": "いっかん", "ipa": "ikkaɴ", "syllable_count": 4, "sentences": [{"text": "会社は環境を守る取り組みの一環として、紙の使用を減らしています。", "target_word": "一環", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は環境[かんきょう]を守[まも]る取[と]り組[く]みの一環[いっかん]として、紙[かみ]の使用[しよう]を減[へ]らしています。", "sentence_source": "generated"}, {"text": "学校では、防災教育の一環として、避難訓練を行いました。", "target_word": "一環", "complexity_tier": "T3", "furigana": "学校[がっこう]では、防災[ぼうさい]教育[きょういく]の一環[いっかん]として、避難[ひなん]訓練[くんれん]を行[おこな]いました。", "sentence_source": "generated"}, {"text": "健康管理の一環で、毎朝三十分歩いています。", "target_word": "一環", "complexity_tier": "T3", "furigana": "健康[けんこう]管理[かんり]の一環[いっかん]で、毎朝[まいあさ]三十分[さんじゅっぷん]歩[ある]いています。", "sentence_source": "generated"}, {"text": "この調査は、町づくりの一環として行われました。", "target_word": "一環", "complexity_tier": "T3", "furigana": "この調査[ちょうさ]は、町[まち]づくりの一環[いっかん]として行[おこな]われました。", "sentence_source": "generated"}, {"text": "英語の勉強の一環として、毎晩映画を見ています。", "target_word": "一環", "complexity_tier": "T3", "furigana": "英語[えいご]の勉強[べんきょう]の一環[いっかん]として、毎晩[まいばん]映画[えいが]を見[み]ています。", "sentence_source": "generated"}, {"text": "新人研修の一環で、私たちは工場を見学しました。", "target_word": "一環", "complexity_tier": "T3", "furigana": "新人[しんじん]研修[けんしゅう]の一環[いっかん]で、私[わたし]たちは工場[こうじょう]を見学[けんがく]しました。", "sentence_source": "generated"}, {"text": "地域の安全を守る活動の一環として、夜の見回りが始まりました。", "target_word": "一環", "complexity_tier": "T3", "furigana": "地域[ちいき]の安全[あんぜん]を守[まも]る活動[かつどう]の一環[いっかん]として、夜[よる]の見回[みまわ]りが始[はじ]まりました。", "sentence_source": "generated"}, {"text": "節約の一環として、今月から外食をやめました。", "target_word": "一環", "complexity_tier": "T3", "furigana": "節約[せつやく]の一環[いっかん]として、今月[こんげつ]から外食[がいしょく]をやめました。", "sentence_source": "generated"}, {"text": "病院は、患者へのサービスの一環で、無料の相談会を開きました。", "target_word": "一環", "complexity_tier": "T3", "furigana": "病院[びょういん]は、患者[かんじゃ]へのサービスの一環[いっかん]で、無料[むりょう]の相談会[そうだんかい]を開[ひら]きました。", "sentence_source": "generated"}, {"text": "彼女は仕事の一環として、海外の展示会に参加しました。", "target_word": "一環", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は仕事[しごと]の一環[いっかん]として、海外[かいがい]の展示会[てんじかい]に参加[さんか]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一環", "label": "基本形"}], "register": "formal", "sense_fingerprint": "an act done as one part of a larger activity (〜の一環として行う)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37152, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一環", "is_correct": true, "explanation": "「取り組みの一環として」は全体の中の一部として行うという意味で、文脈に合う。"}, {"text": "色", "is_correct": false, "explanation": "「取り組みの色として」は意味が通らない。「色」は物の見た目で、取り組みの部分ではない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は空模様なので、取り組みの一部として位置づける語ではない。"}, {"text": "楽器", "is_correct": false, "explanation": "「楽器」は演奏の道具で、取り組みの部分を表す語としては合わない。"}], "explanations": {"一環": "「取り組みの一環として」は全体の中の一部として行うという意味で、文脈に合う。", "色": "「取り組みの色として」は意味が通らない。「色」は物の見た目で、取り組みの部分ではない。", "天気": "「天気」は空模様なので、取り組みの一部として位置づける語ではない。", "楽器": "「楽器」は演奏の道具で、取り組みの部分を表す語としては合わない。"}, "sentence_index": 0, "correct_answer": "一環"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "料理の一環を食べた。", "explanation": "一環は活動の中の取り組みを指す。料理の一部は食べられるが、食べ物に一環は使えない。"}, {"text": "この店の品質は、最初から最後まで一環だった。", "explanation": "ここは〈一貫〉（最初から最後まで変わらないこと）の意味。一環は全体の中の一つの部分を表すので、この文には合わない。"}, {"text": "車の一環を交換した。", "explanation": "一環に〈部品〉の意味はない。車の部品は交換できるが、一環は取り組みの一部を指すので物には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37152, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一環", "is_correct": true, "explanation": "「活動の一環として」は活動の一部として見回りを始めるという意味で、文脈に合う。"}, {"text": "駐車場", "is_correct": false, "explanation": "「活動の駐車場として」は意味が通らない。「駐車場」は車を停める場所で、活動の部分ではない。"}, {"text": "季節", "is_correct": false, "explanation": "「活動の季節として」は不自然。「季節」は時期を指し、活動の部分を表さない。"}, {"text": "財布", "is_correct": false, "explanation": "「活動の財布として」は意味が通らない。「財布」は金入れで、活動の部分ではない。"}], "explanations": {"一環": "「活動の一環として」は活動の一部として見回りを始めるという意味で、文脈に合う。", "駐車場": "「活動の駐車場として」は意味が通らない。「駐車場」は車を停める場所で、活動の部分ではない。", "季節": "「活動の季節として」は不自然。「季節」は時期を指し、活動の部分を表さない。", "財布": "「活動の財布として」は意味が通らない。「財布」は金入れで、活動の部分ではない。"}, "sentence_index": 6, "correct_answer": "一環"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の一環を見て、驚いた。", "explanation": "一環に〈一面〉の意味はない。人の一面は見られるが、一環は活動の取り組みを指すので人には使えない。"}, {"text": "店の一環が改装された。", "explanation": "一環に〈一角〉の意味はない。店の一角は改装できるが、一環は取り組みの一部を指すので場所には使えない。"}, {"text": "私の一環は課長です。", "explanation": "一環に〈役職〉の意味はない。役職は課長だが、一環は活動の取り組みを指すので人の地位には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37152, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の清掃は、地域活動の一環に行われました。", "corrected_sentence": "町の清掃は、地域活動の一環として行われました。", "error_description": "「一環として」の形で、活動の一部として行うことを示す。「一環に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37152, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社の方針の一環の、新しい研修が始まった。", "corrected_sentence": "会社の方針の一環として、新しい研修が始まった。", "error_description": "一環に続けて「として」を使い、取り組みの一部であることを示す。「の」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37153, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一環にすぎない」の「に」。一環だけで全体ではないと限定する形で、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「すぎない」は目的語を取らないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「一環がすぎません」は文の構造が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「一環へすぎません」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「一環にすぎない」の「に」。一環だけで全体ではないと限定する形で、ここに入る。", "を": "「を」は目的語を示すが、「すぎない」は目的語を取らないので合わない。", "が": "「が」は主語を示すので、「一環がすぎません」は文の構造が合わない。", "へ": "「へ」は方向を示すので、「一環へすぎません」は意味が通らない。"}, "error_tags": {"を": "object", "が": "subject", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37153, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37153, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を行うときの、全体の中の一つの部分や段階。", "primary_collocate": null, "pronunciation": "いっかん", "ipa": "ikkaɴ", "syllable_count": 4, "sentences": [{"text": "実験は、研究全体の中の大切な一環です。", "target_word": "一環", "complexity_tier": "T3", "furigana": "実験[じっけん]は、研究[けんきゅう]全体[ぜんたい]の中[なか]の大切[たいせつ]な一環[いっかん]です。", "sentence_source": "generated"}, {"text": "資料集めも、計画づくりの一環にすぎません。", "target_word": "一環", "complexity_tier": "T3", "furigana": "資料[しりょう]集[あつ]めも、計画[けいかく]づくりの一環[いっかん]にすぎません。", "sentence_source": "generated"}, {"text": "面接は、採用の流れの一環で、最後に行われます。", "target_word": "一環", "complexity_tier": "T3", "furigana": "面接[めんせつ]は、採用[さいよう]の流[なが]れの一環[いっかん]で、最後[さいご]に行[おこな]われます。", "sentence_source": "generated"}, {"text": "この作業は、工事の一環であり、次の段階につながります。", "target_word": "一環", "complexity_tier": "T3", "furigana": "この作業[さぎょう]は、工事[こうじ]の一環[いっかん]であり、次[つぎ]の段階[だんかい]につながります。", "sentence_source": "generated"}, {"text": "掃除も料理も、家事の大切な一環です。", "target_word": "一環", "complexity_tier": "T3", "furigana": "掃除[そうじ]も料理[りょうり]も、家事[かじ]の大切[たいせつ]な一環[いっかん]です。", "sentence_source": "generated"}, {"text": "練習は、本番までの準備の一環です。", "target_word": "一環", "complexity_tier": "T3", "furigana": "練習[れんしゅう]は、本番[ほんばん]までの準備[じゅんび]の一環[いっかん]です。", "sentence_source": "generated"}, {"text": "事前の調査は、プロジェクトの一環として欠かせません。", "target_word": "一環", "complexity_tier": "T3", "furigana": "事前[じぜん]の調査[ちょうさ]は、プロジェクトの一環[いっかん]として欠[か]かせません。", "sentence_source": "generated"}, {"text": "この会議も、改革の一環だと考えてください。", "target_word": "一環", "complexity_tier": "T3", "furigana": "この会議[かいぎ]も、改革[かいかく]の一環[いっかん]だと考[かんが]えてください。", "sentence_source": "generated"}, {"text": "検査は治療の一環なので、必ず受けてください。", "target_word": "一環", "complexity_tier": "T3", "furigana": "検査[けんさ]は治療[ちりょう]の一環[いっかん]なので、必[かなら]ず受[う]けてください。", "sentence_source": "generated"}, {"text": "失敗も成長の一環だったと、今は思います。", "target_word": "一環", "complexity_tier": "T3", "furigana": "失敗[しっぱい]も成長[せいちょう]の一環[いっかん]だったと、今[いま]は思[おも]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一環", "label": "基本形"}], "register": "formal", "sense_fingerprint": "one link or stage within a whole process (〜の一環だ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37153, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一環", "is_correct": true, "explanation": "「研究全体の中の大切な一環」は全体の中の一つの段階という意味で、文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「大切な天気です」は意味が通らない。「天気」は空模様で、研究の段階ではない。"}, {"text": "楽器", "is_correct": false, "explanation": "「大切な楽器です」は研究の文脈に合わない。「楽器」は演奏の道具である。"}, {"text": "分量", "is_correct": false, "explanation": "「大切な分量です」は文脈に合わない。「分量」は量の程度で、全体の中の段階を指さない。"}], "explanations": {"一環": "「研究全体の中の大切な一環」は全体の中の一つの段階という意味で、文脈に合う。", "天気": "「大切な天気です」は意味が通らない。「天気」は空模様で、研究の段階ではない。", "楽器": "「大切な楽器です」は研究の文脈に合わない。「楽器」は演奏の道具である。", "分量": "「大切な分量です」は文脈に合わない。「分量」は量の程度で、全体の中の段階を指さない。"}, "sentence_index": 0, "correct_answer": "一環"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "料理の一環を買った。", "explanation": "一環に〈材料〉の意味はない。材料は買えるが、一環は全体の中の段階を指すので買う対象にはならない。"}, {"text": "この店の接客は、最初から最後まで一環だった。", "explanation": "ここは〈一貫〉（最初から最後まで変わらないこと）の意味。一環は全体の中の段階を表すので、この文には合わない。"}, {"text": "舞台の一環を着替えた。", "explanation": "一環に〈衣装〉の意味はない。衣装は着替えられるが、一環は段階や部分を指すので着替えの対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37153, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一環", "is_correct": true, "explanation": "「プロジェクトの一環として欠かせません」は、全体の一部として必要だという意味で合う。"}, {"text": "季節", "is_correct": false, "explanation": "「プロジェクトの季節として欠かせません」は意味が通らない。「季節」は時期を指す語である。"}, {"text": "財布", "is_correct": false, "explanation": "「プロジェクトの財布として欠かせません」は意味が通らない。「財布」は金入れで、プロジェクトの部分ではない。"}, {"text": "駐車場", "is_correct": false, "explanation": "「プロジェクトの駐車場として欠かせません」は意味が通らない。「駐車場」は車を停める場所である。"}], "explanations": {"一環": "「プロジェクトの一環として欠かせません」は、全体の一部として必要だという意味で合う。", "季節": "「プロジェクトの季節として欠かせません」は意味が通らない。「季節」は時期を指す語である。", "財布": "「プロジェクトの財布として欠かせません」は意味が通らない。「財布」は金入れで、プロジェクトの部分ではない。", "駐車場": "「プロジェクトの駐車場として欠かせません」は意味が通らない。「駐車場」は車を停める場所である。"}, "sentence_index": 6, "correct_answer": "一環"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大きな一環を乗り越えた。", "explanation": "一環に〈試練〉の意味はない。試練は乗り越えるものだが、一環は段階を指すので乗り越える対象にはならない。"}, {"text": "会社の一環をつけて働いた。", "explanation": "一環に〈名札〉の意味はない。名札はつけるものだが、一環は段階を指すので身につけるものではない。"}, {"text": "彼女は大きな一環を感じた。", "explanation": "一環に〈喜び〉の意味はない。喜びは感じるものだが、一環は段階を指すので感じる対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37153, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "打ち合わせは、計画づくりの一環をすぎません。", "corrected_sentence": "打ち合わせは、計画づくりの一環にすぎません。", "error_description": "「〜にすぎない」は「に」を使う。「一環をすぎません」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37153, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この打ち合わせは、改革の一環するので、来週も続きます。", "corrected_sentence": "この打ち合わせは、改革の一環なので、来週も続きます。", "error_description": "「一環」は名詞なので「一環する」は誤り。断定は「一環なので」と「な」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37154, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共用", "is_correct": true, "explanation": "専用（一つの用途に限る）の対義語で、複数の人や用途で使うことを指す。"}, {"text": "公共", "is_correct": false, "explanation": "社会全体で使うことを指す語で、専用の対義語ではない。"}, {"text": "延長", "is_correct": false, "explanation": "時間や長さを伸ばすことを指し、用途を限る専用とは関係しない。"}, {"text": "特別", "is_correct": false, "explanation": "普通と違う扱いを指すが、専用の対義語ではない。"}], "correct_answer": "共用", "explanations": {"共用": "専用（一つの用途に限る）の対義語で、複数の人や用途で使うことを指す。", "公共": "社会全体で使うことを指す語で、専用の対義語ではない。", "延長": "時間や長さを伸ばすことを指し、用途を限る専用とは関係しない。", "特別": "普通と違う扱いを指すが、専用の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
