INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37154, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることだけに使うこと。", "primary_collocate": null, "pronunciation": "せんよう", "ipa": "seɴjoː", "syllable_count": 4, "sentences": [{"text": "この駐車場は、お客様専用です。", "target_word": "専用", "complexity_tier": "T3", "furigana": "この駐車場[ちゅうしゃじょう]は、お客様[きゃくさま]専用[せんよう]です。", "sentence_source": "generated"}, {"text": "会社の入口に、社員専用のドアがあります。", "target_word": "専用", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の入口[いりぐち]に、社員[しゃいん]専用[せんよう]のドアがあります。", "sentence_source": "generated"}, {"text": "このケーブルはパソコン専用なので、スマホには使えません。", "target_word": "専用", "complexity_tier": "T3", "furigana": "このケーブルはパソコン専用[せんよう]なので、スマホには使[つか]えません。", "sentence_source": "generated"}, {"text": "子ども専用の席が、電車の前の方にあります。", "target_word": "専用", "complexity_tier": "T3", "furigana": "子[こ]ども専用[せんよう]の席[せき]が、電車[でんしゃ]の前[まえ]の方[ほう]にあります。", "sentence_source": "generated"}, {"text": "犬専用のプールがあるホテルに泊まりました。", "target_word": "専用", "complexity_tier": "T3", "furigana": "犬[いぬ]専用[せんよう]のプールがあるホテルに泊[と]まりました。", "sentence_source": "generated"}, {"text": "この部屋は会議専用で、食事はできません。", "target_word": "専用", "complexity_tier": "T3", "furigana": "この部屋[へや]は会議[かいぎ]専用[せんよう]で、食事[しょくじ]はできません。", "sentence_source": "generated"}, {"text": "女性専用の車両は、朝と夜だけあります。", "target_word": "専用", "complexity_tier": "T3", "furigana": "女性[じょせい]専用[せんよう]の車両[しゃりょう]は、朝[あさ]と夜[よる]だけあります。", "sentence_source": "generated"}, {"text": "このアプリは学生専用なので、登録に学生証が必要です。", "target_word": "専用", "complexity_tier": "T3", "furigana": "このアプリは学生[がくせい]専用[せんよう]なので、登録[とうろく]に学生証[がくせいしょう]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "工場の中には、荷物専用のエレベーターがあります。", "target_word": "専用", "complexity_tier": "T3", "furigana": "工場[こうじょう]の中[なか]には、荷物[にもつ]専用[せんよう]のエレベーターがあります。", "sentence_source": "generated"}, {"text": "この掃除機は車専用に作られているので、家では使いにくいです。", "target_word": "専用", "complexity_tier": "T3", "furigana": "この掃除機[そうじき]は車[くるま]専用[せんよう]に作[つく]られているので、家[いえ]では使[つか]いにくいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "専用", "label": "基本形"}, {"form": "専用の", "label": "連体形"}, {"form": "専用です", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "ある用途だけに限って使うこと。パソコン専用のケーブル、会議専用の部屋など。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f35ae2-3626-49c3-8754-26766e35d357') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37154, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "専用", "is_correct": true, "explanation": "お客様だけに使わせる駐車場の性格を示し、「お客様専用です」の文に合う。"}, {"text": "満車", "is_correct": false, "explanation": "車がいっぱいで止められない状態を指し、「お客様満車です」では文が成り立たない。"}, {"text": "臨時", "is_correct": false, "explanation": "一時的であることを表し、「お客様臨時です」では文が成り立たない。"}, {"text": "深夜", "is_correct": false, "explanation": "夜中の時間帯を指し、「お客様深夜です」では文が成り立たない。"}], "explanations": {"専用": "お客様だけに使わせる駐車場の性格を示し、「お客様専用です」の文に合う。", "満車": "車がいっぱいで止められない状態を指し、「お客様満車です」では文が成り立たない。", "臨時": "一時的であることを表し、「お客様臨時です」では文が成り立たない。", "深夜": "夜中の時間帯を指し、「お客様深夜です」では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "専用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は、社員みんなで専用している。", "explanation": "ここは〈共用〉の意味。複数の人が使う共用とは逆で、用途を一つに限る専用は合わないので合わない。"}, {"text": "彼女は専用主婦として家事をしている。", "explanation": "ここは〈専業〉の意味。家事や仕事を主にする身分を指すので、用途を限る専用とは違うので合わない。"}, {"text": "大学では、専用は歴史だった。", "explanation": "ここは〈専攻〉の意味。深く学ぶ分野を指すので、用途を限る専用とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37154, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "専用", "is_correct": true, "explanation": "女性だけに使わせる車両の性格を示し、「女性専用の車両」の文に合う。"}, {"text": "最新", "is_correct": false, "explanation": "新しいことを表すが、「女性最新の車両」では文が成り立たない。"}, {"text": "故障", "is_correct": false, "explanation": "機械が壊れることで、「女性故障の車両」では文が成り立たない。"}, {"text": "緊急", "is_correct": false, "explanation": "差し迫った事態を表し、「女性緊急の車両」では文が成り立たない。"}], "explanations": {"専用": "女性だけに使わせる車両の性格を示し、「女性専用の車両」の文に合う。", "最新": "新しいことを表すが、「女性最新の車両」では文が成り立たない。", "故障": "機械が壊れることで、「女性故障の車両」では文が成り立たない。", "緊急": "差し迫った事態を表し、「女性緊急の車両」では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "専用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は勉強に専用している。", "explanation": "ここは〈専念〉の意味。一つのことに集中する意味で、用途を限る専用とは違うので合わない。"}, {"text": "大学の専用講師になった。", "explanation": "ここは〈専任〉の意味。常勤で一つの職場に勤める身分を指し、用途に限る専用とは違うので合わない。"}, {"text": "この会社は市場を専用している。", "explanation": "ここは〈独占〉の意味。一社だけが市場を押さえる状態を指すので、用途限定の専用とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37154, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この倉庫は、冷凍食品の保管専用な部屋として使われている。", "corrected_sentence": "この倉庫は、冷凍食品の保管専用の部屋として使われている。", "error_description": "「専用」が後ろの名詞を修飾するときは「の」を使う。「専用な」は誤りで、正しくは「専用の部屋」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37154, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このバスは、障害のある方専用を座席があります。", "corrected_sentence": "このバスは、障害のある方専用の座席があります。", "error_description": "「専用」と「座席」をつなぐのは「の」。「専用を座席」の「を」は誤りで、「座席があります」に続かず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37156, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「レーンを走る」の移動する場所を示し、レーンに直接つく助詞。"}, {"text": "が", "is_correct": false, "explanation": "「レーンが走る」だとレーンが主語になり、バスが走る文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「レーンの走る」は動詞として成り立たず、走る場所を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「レーンと走る」は並べる意味になり、移動の場所として不自然。"}], "correct_answer": "を", "explanations": {"を": "「レーンを走る」の移動する場所を示し、レーンに直接つく助詞。", "が": "「レーンが走る」だとレーンが主語になり、バスが走る文として成り立たない。", "の": "「レーンの走る」は動詞として成り立たず、走る場所を表せない。", "と": "「レーンと走る」は並べる意味になり、移動の場所として不自然。"}, "error_tags": {"が": "主語", "の": "所属", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37156, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「レーンを走る」の走る場所を示し、レーンに直接つく助詞。"}, {"text": "に", "is_correct": false, "explanation": "「レーンに走る」は場所の表し方として不自然で、走る文として成り立ちにくい。"}, {"text": "の", "is_correct": false, "explanation": "「バスのレーンの走ってはいけない」は動詞の目的語が欠け、文の形が崩れる。"}, {"text": "より", "is_correct": false, "explanation": "「レーンより走ってはいけない」は比較の意味になり、走る場所を表せない。"}], "correct_answer": "を", "explanations": {"を": "「レーンを走る」の走る場所を示し、レーンに直接つく助詞。", "に": "「レーンに走る」は場所の表し方として不自然で、走る文として成り立ちにくい。", "の": "「バスのレーンの走ってはいけない」は動詞の目的語が欠け、文の形が崩れる。", "より": "「レーンより走ってはいけない」は比較の意味になり、走る場所を表せない。"}, "error_tags": {"に": "位置", "の": "所属", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37156, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "道の上に、バスだけが走れる特別な場所があります。", "primary_collocate": null, "pronunciation": "れーん", "ipa": "ɾeːɴ", "syllable_count": 3, "sentences": [{"text": "朝のラッシュ時は、バス専用のレーンに一般の車は入れません。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "朝[あさ]のラッシュ時[じ]は、バス専用[せんよう]のレーンに一般[いっぱん]の車[くるま]は入[はい]れません。", "sentence_source": "generated"}, {"text": "バスはレーンを走るので、渋滞でも時間どおりに着く。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "バスはレーンを走[はし]るので、渋滞[じゅうたい]でも時間[じかん]どおりに着[つ]く。", "sentence_source": "generated"}, {"text": "運転手は間違えて、バスのレーンに入ってしまった。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]は間違[まちが]えて、バスのレーンに入[はい]ってしまった。", "sentence_source": "generated"}, {"text": "道の左側にバスのレーンがあり、赤く塗られている。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "道[みち]の左側[ひだりがわ]にバスのレーンがあり、赤[あか]く塗[ぬ]られている。", "sentence_source": "generated"}, {"text": "車が渋滞していても、バスはレーンを使ってすいすい進んだ。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "車[くるま]が渋滞[じゅうたい]していても、バスはレーンを使[つか]ってすいすい進[すす]んだ。", "sentence_source": "generated"}, {"text": "警察官が、バスのレーンに止まっている車に注意した。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "警察官[けいさつかん]が、バスのレーンに止[と]まっている車[くるま]に注意[ちゅうい]した。", "sentence_source": "generated"}, {"text": "この道路は朝七時から九時まで、左のレーンがバスだけになる。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "この道路[どうろ]は朝[あさ]七時[しちじ]から九時[くじ]まで、左[ひだり]のレーンがバスだけになる。", "sentence_source": "generated"}, {"text": "通行規制の時間は、乗用車はバスのレーンを走ってはいけない。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "通行[つうこう]規制[きせい]の時間[じかん]は、乗用車[じょうようしゃ]はバスのレーンを走[はし]ってはいけない。", "sentence_source": "generated"}, {"text": "新しくできたレーンのおかげで、駅までのバスが十分早くなった。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "新[あたら]しくできたレーンのおかげで、駅[えき]までのバスが十分[じゅっぷん]早[はや]くなった。", "sentence_source": "generated"}, {"text": "雨の日は、バスのレーンの色が見えにくいので気をつけたい。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、バスのレーンの色[いろ]が見[み]えにくいので気[き]をつけたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "レーン", "label": "基本形"}, {"form": "レーンの", "label": "連体(の)"}, {"form": "レーンを", "label": "目的格(を)"}], "register": "neutral", "sense_fingerprint": "道路上のバス専用に区切られた走行帯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b6f44e-98bc-47ea-8709-e20223619fec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37156, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "レーン", "is_correct": true, "explanation": "「バス専用の走行帯に一般の車は入れない」という文で、道路の区切りを表す語として合う。"}, {"text": "座席", "is_correct": false, "explanation": "「バス専用の座席に車は入れない」は成り立たず、道路の話と合わない。"}, {"text": "売り場", "is_correct": false, "explanation": "売り場に車を入れるという話は道路の文脈と合わない。"}, {"text": "受付", "is_correct": false, "explanation": "受付に車は入れないという文は場所として合わず、道路の規制と結びつかない。"}], "explanations": {"レーン": "「バス専用の走行帯に一般の車は入れない」という文で、道路の区切りを表す語として合う。", "座席": "「バス専用の座席に車は入れない」は成り立たず、道路の話と合わない。", "売り場": "売り場に車を入れるという話は道路の文脈と合わない。", "受付": "受付に車は入れないという文は場所として合わず、道路の規制と結びつかない。"}, "sentence_index": 0, "correct_answer": "レーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "満員電車のレーンで、乗客が一列に並んで通った。", "explanation": "ここは〈車内の通路〉の意味。レーンは車両が走る帯で、車内の通路の意味では使わない。"}, {"text": "この道はレーンが広くて、子どもが安心して歩ける。", "explanation": "ここは〈歩道〉の意味。レーンは車が走る帯で、人が歩く道の意味では使わない。"}, {"text": "この時間はレーンが満車で、車は入れない。", "explanation": "ここは〈駐車場〉の意味。レーンは走行のための帯で、車を停める場所の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37156, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "レーン", "is_correct": true, "explanation": "「朝七時から九時まで左のレーンがバスだけになる」という文で、道路の区間を表す語として合う。"}, {"text": "窓口", "is_correct": false, "explanation": "左の窓口がバスだけになるという文は成り立たず、道路の話と合わない。"}, {"text": "教室", "is_correct": false, "explanation": "道路の左側が教室になるのは不自然で、交通規制の文と合わない。"}, {"text": "商店", "is_correct": false, "explanation": "道路が商店になるという文脈は合わず、バスだけが通る区間の話にならない。"}], "explanations": {"レーン": "「朝七時から九時まで左のレーンがバスだけになる」という文で、道路の区間を表す語として合う。", "窓口": "左の窓口がバスだけになるという文は成り立たず、道路の話と合わない。", "教室": "道路の左側が教室になるのは不自然で、交通規制の文と合わない。", "商店": "道路が商店になるという文脈は合わず、バスだけが通る区間の話にならない。"}, "sentence_index": 6, "correct_answer": "レーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝は、バスのレーンにごみ袋を並べて出しておく。", "explanation": "ここは〈ごみ置き場〉の意味。レーンは走行のための帯で、ごみを置く場所の意味では使わない。"}, {"text": "雨の日は、バスのレーンで客を待つ人が多いので気をつけたい。", "explanation": "ここは〈停留所〉の意味。レーンは走るための帯で、客が待つ場所ではない。"}, {"text": "雨の日は、バスのレーンに荷物を置いて保管するので気をつけたい。", "explanation": "ここは〈倉庫〉の意味。レーンは走行専用の帯で、荷物を保管する場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37156, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "バスは混んだ道でも、専用のレーンに走れば時間に遅れにくい。", "corrected_sentence": "バスは混んだ道でも、専用のレーンを走れば時間に遅れにくい。", "error_description": "「走る」が通る場所は「を」で示す。「に」は誤りで、レーンに直接つく助詞は「を」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37156, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道では、一般の車はバスのレーンに通れない。", "corrected_sentence": "この道では、一般の車はバスのレーンを通れない。", "error_description": "「通る」が通過する場所は「を」で示す。「に」は誤りで、レーンに直接つく助詞は「を」になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37157, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「レーンを選ぶ」の選ぶ対象を示し、レーンに直接つく助詞。"}, {"text": "が", "is_correct": false, "explanation": "「レーンが選んだ」だとレーンが選ぶ主体になり、文の意味が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「レーンへ選んだ」は方向の意味になり、選ぶ対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「レーンと選んだ」は並べる意味になり、選ぶ対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「レーンを選ぶ」の選ぶ対象を示し、レーンに直接つく助詞。", "が": "「レーンが選んだ」だとレーンが選ぶ主体になり、文の意味が合わない。", "へ": "「レーンへ選んだ」は方向の意味になり、選ぶ対象を表せない。", "と": "「レーンと選んだ」は並べる意味になり、選ぶ対象として成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37157, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「レーンはバイクだけが走れる」と主題を示し、レーンに直接つく助詞。"}, {"text": "を", "is_correct": false, "explanation": "「レーンを、バイクだけが走れる」は走る対象の意味になり、文の形が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "「レーンの、バイクだけが走れる」は助詞の続き方が崩れ、文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「レーンから、バイクだけが走れる」は起点の意味になり、走れる範囲を示せない。"}], "correct_answer": "は", "explanations": {"は": "「レーンはバイクだけが走れる」と主題を示し、レーンに直接つく助詞。", "を": "「レーンを、バイクだけが走れる」は走る対象の意味になり、文の形が崩れる。", "の": "「レーンの、バイクだけが走れる」は助詞の続き方が崩れ、文として成り立たない。", "から": "「レーンから、バイクだけが走れる」は起点の意味になり、走れる範囲を示せない。"}, "error_tags": {"を": "対象", "の": "所属", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37157, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "特定の種類の交通機関だけが通行できるように区切られた道路の部分。", "primary_collocate": null, "pronunciation": "れーん", "ipa": "ɾeːɴ", "syllable_count": 3, "sentences": [{"text": "自転車専用のレーンができて、通学が安全になった。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]専用[せんよう]のレーンができて、通学[つうがく]が安全[あんぜん]になった。", "sentence_source": "generated"}, {"text": "高速道路の料金所で、ETC車専用のレーンを選んだ。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "高速道路[こうそくどうろ]の料金所[りょうきんじょ]で、ETC車[しゃ]専用[せんよう]のレーンを選[えら]んだ。", "sentence_source": "generated"}, {"text": "路面電車が走るレーンに、一般の車は入れない。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "路面電車[ろめんでんしゃ]が走[はし]るレーンに、一般[いっぱん]の車[くるま]は入[はい]れない。", "sentence_source": "generated"}, {"text": "自転車のレーンに車が止まっていて、通れなかった。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]のレーンに車[くるま]が止[と]まっていて、通[とお]れなかった。", "sentence_source": "generated"}, {"text": "この通りには、バスと自転車が通れるレーンがある。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "この通[とお]りには、バスと自転車[じてんしゃ]が通[とお]れるレーンがある。", "sentence_source": "generated"}, {"text": "歩道が狭いので、市は道路の端に自転車のレーンを作った。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "歩道[ほどう]が狭[せま]いので、市[し]は道路[どうろ]の端[はし]に自転車[じてんしゃ]のレーンを作[つく]った。", "sentence_source": "generated"}, {"text": "空港へ向かう道には、タクシー専用のレーンが設けられている。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "空港[くうこう]へ向[む]かう道[みち]には、タクシー専用[せんよう]のレーンが設[もう]けられている。", "sentence_source": "generated"}, {"text": "青い線で区切られたレーンは、バイクだけが走れる。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "青[あお]い線[せん]で区切[くぎ]られたレーンは、バイクだけが走[はし]れる。", "sentence_source": "generated"}, {"text": "この道の右側は、タクシーだけが通れるレーンになっている。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "この道[みち]の右側[みぎがわ]は、タクシーだけが通[とお]れるレーンになっている。", "sentence_source": "generated"}, {"text": "緊急車両のためのレーンを空けて、他の車は道の端に寄った。", "target_word": "レーン", "complexity_tier": "T3", "furigana": "緊急車両[きんきゅうしゃりょう]のためのレーンを空[あ]けて、他[ほか]の車[くるま]は道[みち]の端[はし]に寄[よ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "レーン", "label": "基本形"}, {"form": "レーンの", "label": "連体(の)"}, {"form": "レーンに", "label": "位置(に)"}], "register": "neutral", "sense_fingerprint": "自転車・バス・ETC車など特定の交通向けに区切られた道路の帯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b6f44e-98bc-47ea-8709-e20223619fec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37157, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "レーン", "is_correct": true, "explanation": "「自転車専用のレーンができて、通学が安全になった」という流れに合う道路の区切りを表す語。"}, {"text": "売り場", "is_correct": false, "explanation": "自転車専用の売り場ができても通学の安全には結びつかない。"}, {"text": "窓口", "is_correct": false, "explanation": "自転車専用の窓口は道路の安全と関係せず、文の流れに合わない。"}, {"text": "座席", "is_correct": false, "explanation": "自転車専用の座席は道路の安全を高める話にならず、文と合わない。"}], "explanations": {"レーン": "「自転車専用のレーンができて、通学が安全になった」という流れに合う道路の区切りを表す語。", "売り場": "自転車専用の売り場ができても通学の安全には結びつかない。", "窓口": "自転車専用の窓口は道路の安全と関係せず、文の流れに合わない。", "座席": "自転車専用の座席は道路の安全を高める話にならず、文と合わない。"}, "sentence_index": 0, "correct_answer": "レーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "満員の電車では、乗客がレーンを通路代わりに進んだ。", "explanation": "ここは〈通路〉の意味。レーンは車両が走る帯で、人が進む通路の意味では使わない。"}, {"text": "この通りは自転車のレーンが広く、お年寄りが並んで歩ける。", "explanation": "ここは〈歩道〉の意味。自転車のレーンは自転車の走行帯で、人が並んで歩く場所ではない。"}, {"text": "この時間は自転車のレーンに空きがなく、駐車はできない。", "explanation": "ここは〈駐車場〉の意味。レーンは走行のための帯で、車を停める場所の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37157, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "レーン", "is_correct": true, "explanation": "「空港へ向かう道にタクシー専用の走行帯が設けられている」という文に合う道路の区切り。"}, {"text": "受付", "is_correct": false, "explanation": "タクシー専用の受付が道に設けられているという文は成り立たない。"}, {"text": "売店", "is_correct": false, "explanation": "タクシー専用の売店が道に設けられるという話は不自然。"}, {"text": "食堂", "is_correct": false, "explanation": "タクシー専用の食堂が道に設けられるという文脈は合わない。"}], "explanations": {"レーン": "「空港へ向かう道にタクシー専用の走行帯が設けられている」という文に合う道路の区切り。", "受付": "タクシー専用の受付が道に設けられているという文は成り立たない。", "売店": "タクシー専用の売店が道に設けられるという話は不自然。", "食堂": "タクシー専用の食堂が道に設けられるという文脈は合わない。"}, "sentence_index": 6, "correct_answer": "レーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "緊急車両のためのレーンで、部品を組み立てて工場にした。", "explanation": "ここは〈工場〉の意味。レーンは車両が走るための帯で、作業をする場所の意味では使わない。"}, {"text": "緊急車両のためのレーンに商品を並べて、売り場にした。", "explanation": "ここは〈売り場〉の意味。レーンは車両が走るための帯で、商品を並べる場所の意味では使わない。"}, {"text": "緊急車両のためのレーンで、客が乗降を待つ。", "explanation": "ここは〈停留所〉の意味。レーンは走行のための帯で、客が待つ場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37157, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "料金所では、ETC車専用のレーンに通る車が多い。", "corrected_sentence": "料金所では、ETC車専用のレーンを通る車が多い。", "error_description": "「通る」は通過する場所を「を」で示す。「に」は誤りで、レーンに直接つく助詞は「を」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37157, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救急車が来たので、道の左のレーンが空けた。", "corrected_sentence": "救急車が来たので、道の左のレーンを空けた。", "error_description": "「空ける」は他動詞なので対象を「を」で示す。「が」は誤りで、レーンに直接つく助詞は「を」になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37158, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「鉄道ができる」の主語を示す「が」。「新しい鉄道ができて」の主語として合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「できる」は目的語を取らないので、「鉄道をできて」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「鉄道へできて」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「鉄道からできて」では成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「鉄道ができる」の主語を示す「が」。「新しい鉄道ができて」の主語として合う。", "を": "「を」は目的語を示すが、「できる」は目的語を取らないので、「鉄道をできて」は不自然。", "へ": "「へ」は方向を示すが、「鉄道へできて」では意味が通らない。", "から": "「から」は起点を示すが、「鉄道からできて」では成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37158, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「古い鉄道の跡」の「の」。「鉄道」を「跡」に結びつける連体修飾の印。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「古い鉄道で跡が」では跡の説明にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、比べる相手がなく、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「古い鉄道を跡が」では続く動詞がなく、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「古い鉄道の跡」の「の」。「鉄道」を「跡」に結びつける連体修飾の印。", "で": "「で」は手段や場所を示すが、「古い鉄道で跡が」では跡の説明にならない。", "より": "「より」は比較を示すが、比べる相手がなく、文が成り立たない。", "を": "「を」は目的語を示すが、「古い鉄道を跡が」では続く動詞がなく、文が成り立たない。"}, "error_tags": {"で": "手段・場所", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37158, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電車や列車が走るための道。", "primary_collocate": null, "pronunciation": "てつどう", "ipa": "tetsɯdoː", "syllable_count": 4, "sentences": [{"text": "この町には、山の中を通る鉄道があります。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "この町[まち]には、山[やま]の中[なか]を通[とお]る鉄道[てつどう]があります。", "sentence_source": "generated"}, {"text": "新しい鉄道ができて、海まで一時間で行けます。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "新[あたら]しい鉄道[てつどう]ができて、海[うみ]まで一時間[いちじかん]で行[い]けます。", "sentence_source": "generated"}, {"text": "百年前に作られた鉄道は、今も使われています。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "百年前[ひゃくねんまえ]に作[つく]られた鉄道[てつどう]は、今[いま]も使[つか]われています。", "sentence_source": "generated"}, {"text": "川の上に、鉄道の橋がかかっています。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "川[かわ]の上[うえ]に、鉄道[てつどう]の橋[はし]がかかっています。", "sentence_source": "generated"}, {"text": "大雨で鉄道が水につかり、電車が走れなくなりました。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で鉄道[てつどう]が水[みず]につかり、電車[でんしゃ]が走[はし]れなくなりました。", "sentence_source": "generated"}, {"text": "鉄道のそばに住んでいるので、電車の音がよく聞こえます。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "鉄道[てつどう]のそばに住[す]んでいるので、電車[でんしゃ]の音[おと]がよく聞[き]こえます。", "sentence_source": "generated"}, {"text": "工事のために、鉄道の一部が使えなくなっています。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "工事[こうじ]のために、鉄道[てつどう]の一部[いちぶ]が使[つか]えなくなっています。", "sentence_source": "generated"}, {"text": "古い鉄道の跡が、今は散歩道になっています。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "古[ふる]い鉄道[てつどう]の跡[あと]が、今[いま]は散歩道[さんぽみち]になっています。", "sentence_source": "generated"}, {"text": "鉄道を作る工事には、長い時間とお金がかかります。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "鉄道[てつどう]を作[つく]る工事[こうじ]には、長[なが]い時間[じかん]とお金[かね]がかかります。", "sentence_source": "generated"}, {"text": "山の下を通る鉄道のトンネルは、長さが十キロもあります。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "山[やま]の下[した]を通[とお]る鉄道[てつどう]のトンネルは、長[なが]さが十[じゅっ]キロもあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鉄道", "label": "基本形"}, {"form": "鉄道の", "label": "連体形"}, {"form": "鉄道を", "label": "を格"}], "register": "neutral", "sense_fingerprint": "電車や列車が走るために敷かれたレールの道。鉄道を作る、鉄道の橋など。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 山の下 (Zipf 2.17)']::text[], 'b9f35ae2-3626-49c3-8754-26766e35d357') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37158, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鉄道", "is_correct": true, "explanation": "山の中を通るものとして、電車が走る線路や設備を指す〈鉄道〉が合う。"}, {"text": "空港", "is_correct": false, "explanation": "飛行機が発着する施設で、山の中を通るものではないので合わない。"}, {"text": "駐車場", "is_correct": false, "explanation": "車を止める場所で、山の中を通ることはないので合わない。"}, {"text": "工場", "is_correct": false, "explanation": "物を作る施設で、山の中を通るとは言えないので合わない。"}], "explanations": {"鉄道": "山の中を通るものとして、電車が走る線路や設備を指す〈鉄道〉が合う。", "空港": "飛行機が発着する施設で、山の中を通るものではないので合わない。", "駐車場": "車を止める場所で、山の中を通ることはないので合わない。", "工場": "物を作る施設で、山の中を通るとは言えないので合わない。"}, "sentence_index": 0, "correct_answer": "鉄道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鉄道が駅に止まって、乗客を降ろしました。", "explanation": "ここは〈電車〉の意味。駅に止まって乗客を降ろすのは乗り物の電車で、〈鉄道〉は電車が走るための道なので、止まって人を降ろすことはない。"}, {"text": "この鉄道は、朝は車で混みます。", "explanation": "ここは〈道路〉の意味。車で混むのは道路で、〈鉄道〉は電車が走る線路のことなので、車が混むとは言わない。"}, {"text": "この橋は鉄道で支えられています。", "explanation": "ここは〈鉄骨〉の意味。橋を支える材料は鉄骨で、〈鉄道〉は電車の線路を指すので、材料にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37158, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鉄道", "is_correct": true, "explanation": "工事で一部が使えなくなる設備として、線路や電車の仕組みを指す〈鉄道〉が合う。"}, {"text": "空気", "is_correct": false, "explanation": "「空気の一部が使えなくなる」は意味が通らず、工事の対象にもならない。"}, {"text": "雨", "is_correct": false, "explanation": "「雨の一部が使えなくなっています」は成り立たないので合わない。"}, {"text": "霧", "is_correct": false, "explanation": "霧は使うものではなく、一部が使えなくなる対象にはならない。"}], "explanations": {"鉄道": "工事で一部が使えなくなる設備として、線路や電車の仕組みを指す〈鉄道〉が合う。", "空気": "「空気の一部が使えなくなる」は意味が通らず、工事の対象にもならない。", "雨": "「雨の一部が使えなくなっています」は成り立たないので合わない。", "霧": "霧は使うものではなく、一部が使えなくなる対象にはならない。"}, "sentence_index": 6, "correct_answer": "鉄道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鉄道を改札機に入れて、ホームに出ました。", "explanation": "ここは〈切符〉の意味。改札機に入れるのは切符で、〈鉄道〉は電車が走る仕組みを指すので、改札機に入れられない。"}, {"text": "鉄道が車内を回って、乗客の様子を見ました。", "explanation": "ここは〈車掌〉の意味。車内を回って乗客を見るのは人である車掌で、〈鉄道〉は仕組みを指すので、動作の主体にはならない。"}, {"text": "鉄道は、距離によって決まります。", "explanation": "ここは〈運賃〉の意味。距離によって決まるのは乗る料金の〈運賃〉で、〈鉄道〉は料金ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37158, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい鉄道を、山の向こうまで行けるようになりました。", "corrected_sentence": "新しい鉄道で、山の向こうまで行けるようになりました。", "error_description": "「鉄道で行く」の「で」は手段を表す。「を」は目的語の印なので、「行ける」の前に「鉄道を」と置くのは誤り。正しくは「鉄道で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37158, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨のあと、鉄道な橋が流されました。", "corrected_sentence": "大雨のあと、鉄道の橋が流されました。", "error_description": "「鉄道」は名詞なので、直後は「の」で修飾する。「な」は形容動詞の語尾で、「鉄道」には付かない。正しくは「鉄道の橋」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
