INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37159, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "レールの上を走る乗り物のための交通施設。電車や列車の路線や設備全体を指す。", "primary_collocate": null, "pronunciation": "てつどう", "ipa": "tetsɯdoː", "syllable_count": 4, "sentences": [{"text": "日本の鉄道は、時間に正確なことで有名です。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "日本[にほん]の鉄道[てつどう]は、時間[じかん]に正確[せいかく]なことで有名[ゆうめい]です。", "sentence_source": "generated"}, {"text": "兄は鉄道会社で働いています。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "兄[あに]は鉄道[てつどう]会社[かいしゃ]で働[はたら]いています。", "sentence_source": "generated"}, {"text": "大きな都市では、鉄道が通勤する人の足になっています。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "大[おお]きな都市[とし]では、鉄道[てつどう]が通勤[つうきん]する人[ひと]の足[あし]になっています。", "sentence_source": "generated"}, {"text": "この国の鉄道は、まだ地方まで広がっていません。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "この国[くに]の鉄道[てつどう]は、まだ地方[ちほう]まで広[ひろ]がっていません。", "sentence_source": "generated"}, {"text": "休みには、鉄道で遠くへ出かけます。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "休[やす]みには、鉄道[てつどう]で遠[とお]くへ出[で]かけます。", "sentence_source": "generated"}, {"text": "鉄道とバスをうまく使えば、車がなくても暮らせます。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "鉄道[てつどう]とバスをうまく使[つか]えば、車[くるま]がなくても暮[く]らせます。", "sentence_source": "generated"}, {"text": "鉄道の安全を守るために、毎晩点検が行われます。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "鉄道[てつどう]の安全[あんぜん]を守[まも]るために、毎晩[まいばん]点検[てんけん]が行[おこな]われます。", "sentence_source": "generated"}, {"text": "駅前に、鉄道の歴史を紹介する博物館があります。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "駅前[えきまえ]に、鉄道[てつどう]の歴史[れきし]を紹介[しょうかい]する博物館[はくぶつかん]があります。", "sentence_source": "generated"}, {"text": "鉄道が発達したおかげで、人々の移動が楽になりました。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "鉄道[てつどう]が発達[はったつ]したおかげで、人々[ひとびと]の移動[いどう]が楽[らく]になりました。", "sentence_source": "generated"}, {"text": "地震のとき、鉄道はすべて止まりました。", "target_word": "鉄道", "complexity_tier": "T3", "furigana": "地震[じしん]のとき、鉄道[てつどう]はすべて止[と]まりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鉄道", "label": "基本形"}, {"form": "鉄道の", "label": "連体形"}, {"form": "鉄道で", "label": "で格"}], "register": "neutral", "sense_fingerprint": "路線や駅、車両などを含む交通のしくみ全体。日本の鉄道、鉄道会社、鉄道が発達するなど。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f35ae2-3626-49c3-8754-26766e35d357') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37159, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鉄道", "is_correct": true, "explanation": "時間に正確なことで有名なのは日本の鉄道で、交通の仕組みとして合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は時間に正確であることで有名にはならず、文が成り立たない。"}, {"text": "漢字", "is_correct": false, "explanation": "漢字は時間に正確であることでは有名にならず、意味が通らない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は時間に正確なことで有名にはならず、文の意味が通らない。"}], "explanations": {"鉄道": "時間に正確なことで有名なのは日本の鉄道で、交通の仕組みとして合う。", "天気": "天気は時間に正確であることで有名にはならず、文が成り立たない。", "漢字": "漢字は時間に正確であることでは有名にならず、意味が通らない。", "料理": "料理は時間に正確なことで有名にはならず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "鉄道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鉄道の窓を開けて、風を入れました。", "explanation": "ここは〈車両〉の意味。窓を開けて風を入れるのは電車などの車両で、〈鉄道〉は路線や設備全体を指すので、窓を持つものではない。"}, {"text": "鉄道が港に入ってきました。", "explanation": "ここは〈船舶〉の意味。港に入ってくるのは船で、〈鉄道〉は電車の仕組みを指すので、港には入らない。"}, {"text": "鉄道が下がったので、暖房をつけました。", "explanation": "ここは〈気温〉の意味。下がるのは気温で、〈鉄道〉は温度ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37159, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鉄道", "is_correct": true, "explanation": "安全を守る対象として、電車を走らせる交通の仕組みを指す〈鉄道〉が合う。"}, {"text": "歌", "is_correct": false, "explanation": "歌は安全を守る点検の対象にはならず、「歌の安全」では文が成り立たない。"}, {"text": "言葉", "is_correct": false, "explanation": "言葉は安全を守るための点検の対象にはならないので合わない。"}, {"text": "夢", "is_correct": false, "explanation": "夢は点検の対象にはならず、「夢の安全を守る」では意味が通らない。"}], "explanations": {"鉄道": "安全を守る対象として、電車を走らせる交通の仕組みを指す〈鉄道〉が合う。", "歌": "歌は安全を守る点検の対象にはならず、「歌の安全」では文が成り立たない。", "言葉": "言葉は安全を守るための点検の対象にはならないので合わない。", "夢": "夢は点検の対象にはならず、「夢の安全を守る」では意味が通らない。"}, "sentence_index": 6, "correct_answer": "鉄道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鉄道は、駅から歩いて五分の所にあります。", "explanation": "ここは〈ホテル〉の意味。建物として駅から歩いて行ける場所にあるのはホテルで、〈鉄道〉は建物ではないので合わない。"}, {"text": "鉄道から天気予報が流れてきました。", "explanation": "ここは〈ラジオ〉の意味。天気予報が流れてくるのは放送機器のラジオで、〈鉄道〉は交通の仕組みなので流れてこない。"}, {"text": "鉄道が降ったので、傘を持って出ました。", "explanation": "ここは〈雨〉の意味。降るのは雨で、〈鉄道〉は交通の仕組みなので降ることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37159, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鉄道を通勤する人が増えています。", "corrected_sentence": "鉄道で通勤する人が増えています。", "error_description": "「鉄道で通勤する」の「で」は手段を表す。「を」は目的語の印なので、「通勤する」の前には合わない。正しくは「鉄道で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37159, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地震のあと、鉄道な運転が再開しました。", "corrected_sentence": "地震のあと、鉄道の運転が再開しました。", "error_description": "「鉄道の運転」は「の」で結ぶ。「な」は形容動詞の語尾で、「鉄道」には付かない。正しくは「鉄道の運転」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37160, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「整備を終える」の「を」で、終える対象の整備を示す。"}, {"text": "が", "is_correct": false, "explanation": "「終える」は他動詞なので主語に「が」は付かず、「整備が終えた車」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「整備に終えた」では対象が示せず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や引用を示すので、「整備と終えた」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「整備を終える」の「を」で、終える対象の整備を示す。", "が": "「終える」は他動詞なので主語に「が」は付かず、「整備が終えた車」は成り立たない。", "に": "「整備に終えた」では対象が示せず、文が成り立たない。", "と": "「と」は相手や引用を示すので、「整備と終えた」は意味が通らない。"}, "error_tags": {"が": "主語の誤用", "に": "方向・相手", "と": "相手・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37160, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37160, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを使いやすくするために、準備をしたり、直したりすること。", "primary_collocate": null, "pronunciation": "せいび", "ipa": "seːbi", "syllable_count": 3, "sentences": [{"text": "出発の前に、自転車をきちんと整備しておく。", "target_word": "整備", "complexity_tier": "T3", "furigana": "出発[しゅっぱつ]の前[まえ]に、自転車[じてんしゃ]をきちんと整備[せいび]しておく。", "sentence_source": "generated"}, {"text": "整備を終えた車は、とても静かに走った。", "target_word": "整備", "complexity_tier": "T3", "furigana": "整備[せいび]を終[お]えた車[くるま]は、とても静[しず]かに走[はし]った。", "sentence_source": "generated"}, {"text": "毎年春になると、スキー場のリフトを整備する。", "target_word": "整備", "complexity_tier": "T3", "furigana": "毎年[まいとし]春[はる]になると、スキー場[じょう]のリフトを整備[せいび]する。", "sentence_source": "generated"}, {"text": "整備が足りなかったので、その飛行機は飛べなかった。", "target_word": "整備", "complexity_tier": "T3", "furigana": "整備[せいび]が足[た]りなかったので、その飛行機[ひこうき]は飛[と]べなかった。", "sentence_source": "generated"}, {"text": "父は工場で、バスの整備をしている。", "target_word": "整備", "complexity_tier": "T3", "furigana": "父[ちち]は工場[こうじょう]で、バスの整備[せいび]をしている。", "sentence_source": "generated"}, {"text": "雨で道が悪くなったため、山の道を整備した。", "target_word": "整備", "complexity_tier": "T3", "furigana": "雨[あめ]で道[みち]が悪[わる]くなったため、山[やま]の道[みち]を整備[せいび]した。", "sentence_source": "generated"}, {"text": "船の整備をする人は、小さな音も聞きのがさない。", "target_word": "整備", "complexity_tier": "T3", "furigana": "船[ふね]の整備[せいび]をする人[ひと]は、小[ちい]さな音[おと]も聞[き]きのがさない。", "sentence_source": "generated"}, {"text": "よく整備されたグラウンドでは、安心してサッカーができる。", "target_word": "整備", "complexity_tier": "T3", "furigana": "よく整備[せいび]されたグラウンドでは、安心[あんしん]してサッカーができる。", "sentence_source": "generated"}, {"text": "古い道具を整備して、子どもたちが使えるようにした。", "target_word": "整備", "complexity_tier": "T3", "furigana": "古[ふる]い道具[どうぐ]を整備[せいび]して、子[こ]どもたちが使[つか]えるようにした。", "sentence_source": "generated"}, {"text": "試合の前に、みんなでコートを整備した。", "target_word": "整備", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]に、みんなでコートを整備[せいび]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "整備する", "label": "動詞形"}, {"form": "整備した", "label": "た形"}, {"form": "整備される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "機械・乗り物・道具・場所を点検し、直して、すぐ使える状態にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1174785-6c89-4c94-b05d-420bafe00172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37160, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整備", "is_correct": true, "explanation": "「使えるように点検・修理しておく」の意味で、自転車を主語にしたこの文に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を別の言語に置き換えることなので、自転車には使えない。"}, {"text": "放送", "is_correct": false, "explanation": "電波で番組などを流すことで、自転車を対象にできない。"}, {"text": "上演", "is_correct": false, "explanation": "舞台で劇などを演じることで、「自転車を上演しておく」は成り立たない。"}], "explanations": {"整備": "「使えるように点検・修理しておく」の意味で、自転車を主語にしたこの文に合う。", "翻訳": "言葉を別の言語に置き換えることなので、自転車には使えない。", "放送": "電波で番組などを流すことで、自転車を対象にできない。", "上演": "舞台で劇などを演じることで、「自転車を上演しておく」は成り立たない。"}, "sentence_index": 0, "correct_answer": "整備"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の遠足に向けて、お弁当を整備する。", "explanation": "ここは〈用意〉の意味。整備は機械や設備を使える状態に整えることで、お弁当の用意には使わない。"}, {"text": "友達と会う約束を整備した。", "explanation": "ここは〈調整〉の意味。整備は機械や場所の状態を保つことで、約束の日時を決める場合は調整を使う。"}, {"text": "毎朝、体調を整備する。", "explanation": "ここは〈整える〉の意味。整備は機械や設備を対象にする語で、人の体調には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37160, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整備", "is_correct": true, "explanation": "「船の整備をする人」の意味で、船の機械や設備を保つ仕事を指し、この文に合う。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつけることなので、船の作業には当てはまらない。"}, {"text": "作曲", "is_correct": false, "explanation": "曲を作ることで、船の作業を指さないので文が成り立たない。"}, {"text": "出勤", "is_correct": false, "explanation": "職場に出て仕事を始めることで、「船の出勤」は意味が通らない。"}], "explanations": {"整備": "「船の整備をする人」の意味で、船の機械や設備を保つ仕事を指し、この文に合う。", "採点": "答案などに点数をつけることなので、船の作業には当てはまらない。", "作曲": "曲を作ることで、船の作業を指さないので文が成り立たない。", "出勤": "職場に出て仕事を始めることで、「船の出勤」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "整備"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空港で手荷物を整備された。", "explanation": "ここは〈点検〉の意味。整備は機械や設備を使える状態に保つことで、手荷物を調べる場合は点検を使う。"}, {"text": "朝礼で生徒を一列に整備した。", "explanation": "ここは〈整列〉の意味。整備は人を並べる意味では使わず、機械や場所を対象にする。"}, {"text": "髪を整備してから出かけた。", "explanation": "ここは〈整える〉の意味。整備は髪の身だしなみには使わず、機械や場所の状態を保つことに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37160, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は毎週末、バイクの整備に手伝っている。", "corrected_sentence": "彼は毎週末、バイクの整備を手伝っている。", "error_description": "「手伝う」の対象は「を」で示す。正しくは「整備を手伝う」で、「整備に手伝う」は誤り（「を」を「に」にした助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37160, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い機械が整備して、故障が減った。", "corrected_sentence": "古い機械が整備されて、故障が減った。", "error_description": "「整備」は他動詞で、「機械が」のように物を主語にするときは受身形「整備される」にする。「整備して」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
