INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37161, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ルールを整備する」の「を」で、整備の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「ルールが整備する」では他動詞の対象が主語の形になり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ルールに整備する」は対象を示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「ルールへ整備する」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「ルールを整備する」の「を」で、整備の対象を示す。", "が": "「ルールが整備する」では他動詞の対象が主語の形になり、文が成り立たない。", "に": "「ルールに整備する」は対象を示せず、文が成り立たない。", "へ": "「へ」は方向を示すので、「ルールへ整備する」は意味が通らない。"}, "error_tags": {"が": "主語・目的語の取り違え", "に": "方向・位置", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37161, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事がうまく動くように、必要なものをそろえたり、状態をよくしたりすること。", "primary_collocate": null, "pronunciation": "せいび", "ipa": "seːbi", "syllable_count": 3, "sentences": [{"text": "町は、高齢者が暮らしやすいように環境を整備している。", "target_word": "整備", "complexity_tier": "T3", "furigana": "町[まち]は、高齢者[こうれいしゃ]が暮[く]らしやすいように環境[かんきょう]を整備[せいび]している。", "sentence_source": "generated"}, {"text": "新しい制度が整備され、働く人の権利が守られるようになった。", "target_word": "整備", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]が整備[せいび]され、働[はたら]く人[ひと]の権利[けんり]が守[まも]られるようになった。", "sentence_source": "generated"}, {"text": "災害に備えて、避難所の整備を急ぐ必要がある。", "target_word": "整備", "complexity_tier": "T3", "furigana": "災害[さいがい]に備[そな]えて、避難所[ひなんじょ]の整備[せいび]を急[いそ]ぐ必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "会社はインターネットで会議ができる体制を整備した。", "target_word": "整備", "complexity_tier": "T3", "furigana": "会社[かいしゃ]はインターネットで会議[かいぎ]ができる体制[たいせい]を整備[せいび]した。", "sentence_source": "generated"}, {"text": "駅の周りの整備が進み、歩きやすくなった。", "target_word": "整備", "complexity_tier": "T3", "furigana": "駅[えき]の周[まわ]りの整備[せいび]が進[すす]み、歩[ある]きやすくなった。", "sentence_source": "generated"}, {"text": "制度の整備が遅れているため、多くの人が困っている。", "target_word": "整備", "complexity_tier": "T3", "furigana": "制度[せいど]の整備[せいび]が遅[おく]れているため、多[おお]くの人[ひと]が困[こま]っている。", "sentence_source": "generated"}, {"text": "学校は図書室の整備に力を入れている。", "target_word": "整備", "complexity_tier": "T3", "furigana": "学校[がっこう]は図書室[としょしつ]の整備[せいび]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "外国人が働きやすいように、ルールを整備する。", "target_word": "整備", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]が働[はたら]きやすいように、ルールを整備[せいび]する。", "sentence_source": "generated"}, {"text": "道路が整備されて、荷物を運ぶ時間が短くなった。", "target_word": "整備", "complexity_tier": "T3", "furigana": "道路[どうろ]が整備[せいび]されて、荷物[にもつ]を運[はこ]ぶ時間[じかん]が短[みじか]くなった。", "sentence_source": "generated"}, {"text": "市は公園の整備に、来年度の予算を使うことにした。", "target_word": "整備", "complexity_tier": "T3", "furigana": "市[し]は公園[こうえん]の整備[せいび]に、来年度[らいねんど]の予算[よさん]を使[つか]うことにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "整備する", "label": "動詞形"}, {"form": "整備した", "label": "た形"}, {"form": "整備される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "制度・環境・設備などを必要なだけそろえ、うまく機能する状態に整えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1174785-6c89-4c94-b05d-420bafe00172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37161, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整備", "is_correct": true, "explanation": "「環境を必要なだけそろえて、うまく機能させる」の意味で、この文に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を別の言語に置き換えることなので、環境を対象にできない。"}, {"text": "上演", "is_correct": false, "explanation": "舞台作品を演じることで、環境を上演するという文は成り立たない。"}, {"text": "放送", "is_correct": false, "explanation": "電波で番組などを流すことで、環境を放送するという文は成り立たない。"}], "explanations": {"整備": "「環境を必要なだけそろえて、うまく機能させる」の意味で、この文に合う。", "翻訳": "言葉を別の言語に置き換えることなので、環境を対象にできない。", "上演": "舞台作品を演じることで、環境を上演するという文は成り立たない。", "放送": "電波で番組などを流すことで、環境を放送するという文は成り立たない。"}, "sentence_index": 0, "correct_answer": "整備"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週のパーティーのために、料理を整備した。", "explanation": "ここは〈準備〉の意味。整備は制度や設備を機能する状態に整えることに使うので、料理には使わない。"}, {"text": "来月の会議の日程を整備した。", "explanation": "ここは〈調整〉の意味。整備は仕組みや設備を機能させることで、日程を合わせる場合は調整を使う。"}, {"text": "散らかった書類を整備した。", "explanation": "ここは〈整理〉の意味。書類は分類して片付けるもので、制度や設備を機能させる意味の整備は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37161, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整備", "is_correct": true, "explanation": "「図書室の整備に力を入れる」の意味で、設備を機能させる整備が正解。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつけることで、図書室の設備には当てはまらない。"}, {"text": "作曲", "is_correct": false, "explanation": "曲を作ることで、図書室を対象にできない。"}, {"text": "乗車", "is_correct": false, "explanation": "乗り物に乗ることで、「図書室の乗車」は意味が通らない。"}], "explanations": {"整備": "「図書室の整備に力を入れる」の意味で、設備を機能させる整備が正解。", "採点": "答案などに点数をつけることで、図書室の設備には当てはまらない。", "作曲": "曲を作ることで、図書室を対象にできない。", "乗車": "乗り物に乗ることで、「図書室の乗車」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "整備"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "髪を整備してから出かけた。", "explanation": "ここは〈整える〉の意味。整備は制度や設備を機能させる意味で、髪の身だしなみには使わない。"}, {"text": "朝礼で子どもたちを一列に整備させた。", "explanation": "ここは〈整列〉の意味。整備は人を並べる意味では使わず、制度や設備を機能させることに使う。"}, {"text": "空港でスーツケースを整備された。", "explanation": "ここは〈点検〉の意味。整備は仕組みや設備を機能させることで、荷物を調べる場合は点検を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37161, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい制度の整備を進み、働く人が守られた。", "corrected_sentence": "新しい制度の整備が進み、働く人が守られた。", "error_description": "「進む」は自動詞なので主語に「が」を付けて「整備が進む」とする。「整備を進み」は誤り（「が」を「を」にした助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37161, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい法律に合わせて、制度が整備した。", "corrected_sentence": "新しい法律に合わせて、制度が整備された。", "error_description": "「整備」は他動詞で、「制度が」を主語にするには受身形「整備される」が必要。「整備した」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37162, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不便", "is_correct": true, "explanation": "便利の対義語で、役に立たず使いにくい状態を表す。"}, {"text": "有名", "is_correct": false, "explanation": "知られていることを表し、便利の反対の関係にはならない。"}, {"text": "静か", "is_correct": false, "explanation": "静けさを表し、便利さの反対とはならない。"}, {"text": "新鮮", "is_correct": false, "explanation": "新しさを表し、対義語の関係ではない。"}], "correct_answer": "不便", "explanations": {"不便": "便利の対義語で、役に立たず使いにくい状態を表す。", "有名": "知られていることを表し、便利の反対の関係にはならない。", "静か": "静けさを表し、便利さの反対とはならない。", "新鮮": "新しさを表し、対義語の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37162, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不便", "is_correct": true, "explanation": "便利の対義語で、役立たず都合の悪い状態を表す。"}, {"text": "豊か", "is_correct": false, "explanation": "物が十分にある様子を表し、便利さの反対とはならない。"}, {"text": "穏やか", "is_correct": false, "explanation": "落ち着いた様子を表し、便利の対義語ではない。"}, {"text": "簡単", "is_correct": false, "explanation": "やさしいことを表すが、便利の対義語ではない。"}], "correct_answer": "不便", "explanations": {"不便": "便利の対義語で、役立たず都合の悪い状態を表す。", "豊か": "物が十分にある様子を表し、便利さの反対とはならない。", "穏やか": "落ち着いた様子を表し、便利の対義語ではない。", "簡単": "やさしいことを表すが、便利の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37162, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "何かをするときに、とても役に立つこと。", "primary_collocate": null, "pronunciation": "べんり", "ipa": "beɴɾi", "syllable_count": 3, "sentences": [{"text": "辞書アプリは、わからない言葉をすぐ調べられるので便利だ。", "target_word": "便利", "complexity_tier": "T3", "furigana": "辞書[じしょ]アプリは、わからない言葉[ことば]をすぐ調[しら]べられるので便利[べんり]だ。", "sentence_source": "generated"}, {"text": "この道具は料理の準備に便利なので、毎日使っている。", "target_word": "便利", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は料理[りょうり]の準備[じゅんび]に便利[べんり]なので、毎日[まいにち]使[つか]っている。", "sentence_source": "generated"}, {"text": "冷凍食品は忙しい朝にとても便利だ。", "target_word": "便利", "complexity_tier": "T3", "furigana": "冷凍[れいとう]食品[しょくひん]は忙[いそが]しい朝[あさ]にとても便利[べんり]だ。", "sentence_source": "generated"}, {"text": "地図アプリは、知らない町を歩くときに便利な道具だ。", "target_word": "便利", "complexity_tier": "T3", "furigana": "地図[ちず]アプリは、知[し]らない町[まち]を歩[ある]くときに便利[べんり]な道具[どうぐ]だ。", "sentence_source": "generated"}, {"text": "旅行にはキャスターつきのかばんが便利だと思う。", "target_word": "便利", "complexity_tier": "T3", "furigana": "旅行[りょこう]にはキャスターつきのかばんが便利[べんり]だと思[おも]う。", "sentence_source": "generated"}, {"text": "付箋があれば、本の大事なところに印をつけるのに便利だ。", "target_word": "便利", "complexity_tier": "T3", "furigana": "付箋[ふせん]があれば、本[ほん]の大事[だいじ]なところに印[しるし]をつけるのに便利[べんり]だ。", "sentence_source": "generated"}, {"text": "このはさみは小さいが、袋を開けるときに便利だ。", "target_word": "便利", "complexity_tier": "T3", "furigana": "このはさみは小[ちい]さいが、袋[ふくろ]を開[あ]けるときに便利[べんり]だ。", "sentence_source": "generated"}, {"text": "翻訳機能のおかげで、外国の記事も読めて便利になった。", "target_word": "便利", "complexity_tier": "T3", "furigana": "翻訳[ほんやく]機能[きのう]のおかげで、外国[がいこく]の記事[きじ]も読[よ]めて便利[べんり]になった。", "sentence_source": "generated"}, {"text": "一台で電話も写真もできる便利な機械を、今では誰でも持っている。", "target_word": "便利", "complexity_tier": "T3", "furigana": "一台[いちだい]で電話[でんわ]も写真[しゃしん]もできる便利[べんり]な機械[きかい]を、今[いま]では誰[だれ]でも持[も]っている。", "sentence_source": "generated"}, {"text": "雨の日は折りたたみ傘があると便利だから、かばんに入れておく。", "target_word": "便利", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は折[お]りたたみ傘[がさ]があると便利[べんり]だから、かばんに入[い]れておく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "便利だ", "label": "終止形"}, {"form": "便利な", "label": "連体形"}, {"form": "便利で", "label": "連用形（で）"}, {"form": "便利に", "label": "連用形（に）"}, {"form": "便利です", "label": "丁寧形"}, {"form": "便利だった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "道具や機能が、ある作業をするときにとても役に立つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451f182-b416-4156-a958-f234e1ab7309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37162, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便利", "is_correct": true, "explanation": "「すぐ調べられる」という理由と合い、役立つという意味に一致する。"}, {"text": "危険", "is_correct": false, "explanation": "危険さは調べられることの理由にならず、文の意味が成り立たない。"}, {"text": "静か", "is_correct": false, "explanation": "静かさは辞書アプリの機能と関係せず、理由節に合わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "新鮮さは機能の利点と結びつかず、理由節に合わない。"}], "explanations": {"便利": "「すぐ調べられる」という理由と合い、役立つという意味に一致する。", "危険": "危険さは調べられることの理由にならず、文の意味が成り立たない。", "静か": "静かさは辞書アプリの機能と関係せず、理由節に合わない。", "新鮮": "新鮮さは機能の利点と結びつかず、理由節に合わない。"}, "sentence_index": 0, "correct_answer": "便利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は体の状態によって便利だ。", "explanation": "ここは〈必要だ〉の意味。便利は役に立つ道具の性質を言い、必要かどうかの条件には使わない。"}, {"text": "彼は便利な性格で、誰とでも仲良くなれる。", "explanation": "ここは〈親切だ〉の意味。便利は物や道具が役に立つ様子で、人の性格には使わない。"}, {"text": "彼は会議で便利な発言をして、皆を笑わせた。", "explanation": "ここは〈機転がきく〉の意味。便利は物事が役立つ・使いやすいことで、発言の巧みさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37162, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便利", "is_correct": true, "explanation": "袋を開ける場面で役立つという意味に合う。"}, {"text": "誠実", "is_correct": false, "explanation": "人の態度を表す語で、はさみの働きには合わない。"}, {"text": "寡黙", "is_correct": false, "explanation": "口数が少ない人の様子で、道具には使えない。"}, {"text": "奇妙", "is_correct": false, "explanation": "風変わりな様子を表し、袋を開ける場面と結びつかない。"}], "explanations": {"便利": "袋を開ける場面で役立つという意味に合う。", "誠実": "人の態度を表す語で、はさみの働きには合わない。", "寡黙": "口数が少ない人の様子で、道具には使えない。", "奇妙": "風変わりな様子を表し、袋を開ける場面と結びつかない。"}, "sentence_index": 6, "correct_answer": "便利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "引っ越しは便利だった。", "explanation": "ここは〈大変だ〉の意味。便利は役に立つ様子を表し、苦労の意味では使わない。"}, {"text": "試合に負けて便利だった。", "explanation": "ここは〈残念だ〉の意味。便利は役立ちを表すので、気持ちを言う文には合わない。"}, {"text": "この春の雨は便利で、寒さがすっかり消えた。", "explanation": "ここは〈ありがたい〉の意味。便利は道具や方法が役に立つことで、天候の恩恵には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37162, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この包丁は野菜の準備に便利だので、毎日使っている。", "corrected_sentence": "この包丁は野菜の準備に便利なので、毎日使っている。", "error_description": "活用の誤り。名詞を修飾し「ので」に続く形は「便利な」。「便利だ」の後に「ので」は続かないため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "便利", "is_correct": true, "explanation": "語幹「便利」。後ろに「な」が続く形で、ここでは語幹に当たる。"}, {"text": "便利だ", "is_correct": false, "explanation": "終止形で、「なので」の前には置けない。"}, {"text": "便利に", "is_correct": false, "explanation": "連用形の「に」で、「なので」とは続かない。"}, {"text": "便利で", "is_correct": false, "explanation": "連用形の「で」は「なので」の前には続かない。"}], "correct_form": "便利", "base_form": "便利だ", "form_label": "形状詞（語幹）", "sentence_index": 1, "explanations": {"便利": "語幹「便利」。後ろに「な」が続く形で、ここでは語幹に当たる。", "便利だ": "終止形で、「なので」の前には置けない。", "便利に": "連用形の「に」で、「なので」とは続かない。", "便利で": "連用形の「で」は「なので」の前には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37162, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日はレインコートがあると便利くて、玄関に置いておく。", "corrected_sentence": "雨の日はレインコートがあると便利だから、玄関に置いておく。", "error_description": "活用の誤り。「便利だ」は形状詞なので「くて」ではなく「だから」と続ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "便利", "is_correct": true, "explanation": "語幹「便利」。「に」が続く形で、ここでは語幹に当たる。"}, {"text": "便利です", "is_correct": false, "explanation": "丁寧形で、「になった」の前には続かない。"}, {"text": "便利だった", "is_correct": false, "explanation": "過去形で、「になった」と続けると不自然。"}, {"text": "便利な", "is_correct": false, "explanation": "連体形で、「になった」の前には使えない。"}], "correct_form": "便利", "base_form": "便利だ", "form_label": "形状詞（語幹）", "sentence_index": 7, "explanations": {"便利": "語幹「便利」。「に」が続く形で、ここでは語幹に当たる。", "便利です": "丁寧形で、「になった」の前には続かない。", "便利だった": "過去形で、「になった」と続けると不自然。", "便利な": "連体形で、「になった」の前には使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37163, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不便", "is_correct": true, "explanation": "便利の対義語で、都合が悪く使いにくい様子を表す。"}, {"text": "高価", "is_correct": false, "explanation": "値段が高いことを表し、便利さの反対の関係ではない。"}, {"text": "上品", "is_correct": false, "explanation": "品の良さを表し、対義語ではない。"}, {"text": "丈夫", "is_correct": false, "explanation": "壊れにくい様子を表し、便利の対義語にはならない。"}], "correct_answer": "不便", "explanations": {"不便": "便利の対義語で、都合が悪く使いにくい様子を表す。", "高価": "値段が高いことを表し、便利さの反対の関係ではない。", "上品": "品の良さを表し、対義語ではない。", "丈夫": "壊れにくい様子を表し、便利の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37163, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不便", "is_correct": true, "explanation": "便利の対義語で、都合が悪く使いにくいことを表す。"}, {"text": "豊か", "is_correct": false, "explanation": "豊かさを表し、便利さの反対とはならない。"}, {"text": "地味", "is_correct": false, "explanation": "目立たない様子を表し、対義語ではない。"}, {"text": "賢明", "is_correct": false, "explanation": "判断が適切なことを表し、対義語にはならない。"}], "correct_answer": "不便", "explanations": {"不便": "便利の対義語で、都合が悪く使いにくいことを表す。", "豊か": "豊かさを表し、便利さの反対とはならない。", "地味": "目立たない様子を表し、対義語ではない。", "賢明": "判断が適切なことを表し、対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37163, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "目的を達成するのに都合がよく、使いやすいこと。", "primary_collocate": null, "pronunciation": "べんり", "ipa": "beɴɾi", "syllable_count": 3, "sentences": [{"text": "この部屋は駅から歩いて二分で、とても便利だ。", "target_word": "便利", "complexity_tier": "T3", "furigana": "この部屋[へや]は駅[えき]から歩[ある]いて二分[にふん]で、とても便利[べんり]だ。", "sentence_source": "generated"}, {"text": "引っ越してから会社が近くなって、毎朝の通勤がずっと便利になった。", "target_word": "便利", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]してから会社[かいしゃ]が近[ちか]くなって、毎朝[まいあさ]の通勤[つうきん]がずっと便利[べんり]になった。", "sentence_source": "generated"}, {"text": "私の町はバスが多く、どこへ行くにも便利だ。", "target_word": "便利", "complexity_tier": "T3", "furigana": "私[わたし]の町[まち]はバスが多[おお]く、どこへ行[い]くにも便利[べんり]だ。", "sentence_source": "generated"}, {"text": "引っ越すなら、買い物に便利な場所がいい。", "target_word": "便利", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]すなら、買[か]い物[もの]に便利[べんり]な場所[ばしょ]がいい。", "sentence_source": "generated"}, {"text": "新しい財布はカードがたくさん入って、使うのに便利だ。", "target_word": "便利", "complexity_tier": "T3", "furigana": "新[あたら]しい財布[さいふ]はカードがたくさん入[はい]って、使[つか]うのに便利[べんり]だ。", "sentence_source": "generated"}, {"text": "店が多くて便利な町だが、家賃が高い。", "target_word": "便利", "complexity_tier": "T3", "furigana": "店[みせ]が多[おお]くて便利[べんり]な町[まち]だが、家賃[やちん]が高[たか]い。", "sentence_source": "generated"}, {"text": "ホテルは空港の近くなので、朝早い飛行機にも便利だった。", "target_word": "便利", "complexity_tier": "T3", "furigana": "ホテルは空港[くうこう]の近[ちか]くなので、朝[あさ]早[はや]い飛行機[ひこうき]にも便利[べんり]だった。", "sentence_source": "generated"}, {"text": "操作が簡単なので、お年寄りにも便利なスマホだ。", "target_word": "便利", "complexity_tier": "T3", "furigana": "操作[そうさ]が簡単[かんたん]なので、お年寄[としよ]りにも便利[べんり]なスマホだ。", "sentence_source": "generated"}, {"text": "この図書館は駅の中にあって、帰りに寄れて便利だ。", "target_word": "便利", "complexity_tier": "T3", "furigana": "この図書館[としょかん]は駅[えき]の中[なか]にあって、帰[かえ]りに寄[よ]れて便利[べんり]だ。", "sentence_source": "generated"}, {"text": "荷物が多い日は、改札の近くにコインロッカーがあって便利だ。", "target_word": "便利", "complexity_tier": "T3", "furigana": "荷物[にもつ]が多[おお]い日[ひ]は、改札[かいさつ]の近[ちか]くにコインロッカーがあって便利[べんり]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "便利だ", "label": "終止形"}, {"form": "便利な", "label": "連体形"}, {"form": "便利で", "label": "連用形（で）"}, {"form": "便利に", "label": "連用形（に）"}, {"form": "便利です", "label": "丁寧形"}, {"form": "便利だった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "場所や物が目的に合って都合がよく、使いやすい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451f182-b416-4156-a958-f234e1ab7309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37163, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便利", "is_correct": true, "explanation": "駅から近いことを表し、場所の都合のよさを示す文の述語として正しい。"}, {"text": "不便", "is_correct": false, "explanation": "駅に近い利点と反対の意味になり、文の説明に合わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "新しさを表し、立地の近さと結びつかない。"}, {"text": "不快", "is_correct": false, "explanation": "不快さは駅に近い利点の説明にならず、文の意味が合わない。"}], "explanations": {"便利": "駅から近いことを表し、場所の都合のよさを示す文の述語として正しい。", "不便": "駅に近い利点と反対の意味になり、文の説明に合わない。", "新鮮": "新しさを表し、立地の近さと結びつかない。", "不快": "不快さは駅に近い利点の説明にならず、文の意味が合わない。"}, "sentence_index": 0, "correct_answer": "便利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は値段が便利で、学生にぴったりだ。", "explanation": "ここは〈手頃だ〉の意味。便利は使いやすさや都合を表し、値段の安さには使わない。"}, {"text": "この店は便利で、テレビにもよく出ている。", "explanation": "ここは〈有名だ〉の意味。便利は都合のよさを表し、知名度には使わないので合わない。"}, {"text": "この犬は便利で、とても賢い。", "explanation": "ここは〈賢い〉の意味。便利は都合のよさや使いやすさを表し、動物の賢さは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37163, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便利", "is_correct": true, "explanation": "空港の近さを理由に、朝早い便にも都合がよいという意味に合う。"}, {"text": "丁寧", "is_correct": false, "explanation": "態度の丁寧さを表し、ホテルの立地の説明には合わない。"}, {"text": "派手", "is_correct": false, "explanation": "目立つ様子を表し、立地の利点を説明する文には合わない。"}, {"text": "地味", "is_correct": false, "explanation": "目立たない様子を表し、飛行機の利用に都合がよいことを表さない。"}], "explanations": {"便利": "空港の近さを理由に、朝早い便にも都合がよいという意味に合う。", "丁寧": "態度の丁寧さを表し、ホテルの立地の説明には合わない。", "派手": "目立つ様子を表し、立地の利点を説明する文には合わない。", "地味": "目立たない様子を表し、飛行機の利用に都合がよいことを表さない。"}, "sentence_index": 6, "correct_answer": "便利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋は便利で、家族全員が住める。", "explanation": "ここは〈広い〉の意味。便利は都合のよさを表し、広さは表さないので合わない。"}, {"text": "週末は便利で、休む時間がない。", "explanation": "ここは〈忙しい〉の意味。便利は都合のよさを表し、忙しさの状態は表せない。"}, {"text": "夏の飲み物は便利なほうがおいしい。", "explanation": "ここは〈冷たい〉の意味。便利は使いやすさを表し、温度の状態は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37163, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部屋は駅から近くて、通勤に便利の場所だ。", "corrected_sentence": "この部屋は駅から近くて、通勤に便利な場所だ。", "error_description": "連体修飾の誤り。名詞「場所」を修飾するには「便利な」が必要で、「便利の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "便利", "is_correct": true, "explanation": "語幹「便利」。「に」が続く形で、ここでは語幹に当たる。"}, {"text": "便利だ", "is_correct": false, "explanation": "終止形で、「になった」とは続かない。"}, {"text": "便利で", "is_correct": false, "explanation": "連用形の「で」は「になった」と続けると不自然。"}, {"text": "便利です", "is_correct": false, "explanation": "丁寧形で、「になった」の前には使えない。"}], "correct_form": "便利", "base_form": "便利だ", "form_label": "形状詞（語幹）", "sentence_index": 1, "explanations": {"便利": "語幹「便利」。「に」が続く形で、ここでは語幹に当たる。", "便利だ": "終止形で、「になった」とは続かない。", "便利で": "連用形の「で」は「になった」と続けると不自然。", "便利です": "丁寧形で、「になった」の前には使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37163, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町は駅が近く、どこへ行くにも便利ので、家賃が高い。", "corrected_sentence": "この町は駅が近く、どこへ行くにも便利で、家賃が高い。", "error_description": "接続の誤り。「便利だ」は中止形「便利で」で続けるので、「便利ので」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "便利", "is_correct": true, "explanation": "語幹「便利」。「な」が続く形で、ここでは語幹に当たる。"}, {"text": "便利に", "is_correct": false, "explanation": "連用形の「に」で、名詞を修飾する位置には合わない。"}, {"text": "便利だった", "is_correct": false, "explanation": "過去形で、名詞修飾の位置には使えない。"}, {"text": "便利なら", "is_correct": false, "explanation": "仮定形で、「スマホだ」の名詞修飾の形には合わない。"}], "correct_form": "便利", "base_form": "便利だ", "form_label": "形状詞（語幹）", "sentence_index": 7, "explanations": {"便利": "語幹「便利」。「な」が続く形で、ここでは語幹に当たる。", "便利に": "連用形の「に」で、名詞を修飾する位置には合わない。", "便利だった": "過去形で、名詞修飾の位置には使えない。", "便利なら": "仮定形で、「スマホだ」の名詞修飾の形には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37166, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「遊園地が混雑する」で、遊園地が主語になり、混雑する主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「混雑する」は自動詞なので目的語を取らない。「遊園地を混雑する」は成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や対象を示すが、「遊園地に混雑する」は不自然で文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す。「遊園地へ混雑する」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「遊園地が混雑する」で、遊園地が主語になり、混雑する主体を示す。", "を": "「混雑する」は自動詞なので目的語を取らない。「遊園地を混雑する」は成立しない。", "に": "「に」は方向や対象を示すが、「遊園地に混雑する」は不自然で文が成立しない。", "へ": "「へ」は移動の方向を示す。「遊園地へ混雑する」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "方向・対象", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閑散", "is_correct": true, "explanation": "人や車が少なくてひっそりした様子を表し、人が集まって動きにくい「混雑」の反対の状態。"}, {"text": "静粛", "is_correct": false, "explanation": "静かさを表すが、人の集まりの多さを表さないので対義語ではない。"}, {"text": "活発", "is_correct": false, "explanation": "人出や動きが盛んな様子で、混雑と近い方向を向くので対義語ではない。"}, {"text": "安定", "is_correct": false, "explanation": "変化がなく落ち着いた状態を表し、人の数の多少とは関係しない。"}], "correct_answer": "閑散", "explanations": {"閑散": "人や車が少なくてひっそりした様子を表し、人が集まって動きにくい「混雑」の反対の状態。", "静粛": "静かさを表すが、人の集まりの多さを表さないので対義語ではない。", "活発": "人出や動きが盛んな様子で、混雑と近い方向を向くので対義語ではない。", "安定": "変化がなく落ち着いた状態を表し、人の数の多少とは関係しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37166, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閑散", "is_correct": true, "explanation": "人が少なくてひっそりした様子を表し、混雑の反対の状態。"}, {"text": "友好", "is_correct": false, "explanation": "仲が良い関係を表し、人の集まりの多少とは関係しないので対義語ではない。"}, {"text": "豊富", "is_correct": false, "explanation": "十分に多くある様子を表すが、混雑の反対の意味にはならない。"}, {"text": "寛容", "is_correct": false, "explanation": "心が広く許す態度を表し、混雑とは対になる関係にない。"}], "correct_answer": "閑散", "explanations": {"閑散": "人が少なくてひっそりした様子を表し、混雑の反対の状態。", "友好": "仲が良い関係を表し、人の集まりの多少とは関係しないので対義語ではない。", "豊富": "十分に多くある様子を表すが、混雑の反対の意味にはならない。", "寛容": "心が広く許す態度を表し、混雑とは対になる関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37166, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人がたくさんいて、せまくて動きにくいこと。", "primary_collocate": null, "pronunciation": "こんざつ", "ipa": "koɴzat͡sɯ", "syllable_count": 4, "sentences": [{"text": "朝のラッシュ時は、駅の混雑がひどい。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "朝[あさ]のラッシュ時[じ]は、駅[えき]の混雑[こんざつ]がひどい。", "sentence_source": "generated"}, {"text": "連休は遊園地が混雑するので、平日に行きます。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "連休[れんきゅう]は遊園地[ゆうえんち]が混雑[こんざつ]するので、平日[へいじつ]に行[い]きます。", "sentence_source": "generated"}, {"text": "混雑を避けるために、早い時間に店へ行った。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "混雑[こんざつ]を避[さ]けるために、早[はや]い時間[じかん]に店[みせ]へ行[い]った。", "sentence_source": "generated"}, {"text": "花火大会の会場は、人で混雑していた。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "花火大会[はなびたいかい]の会場[かいじょう]は、人[ひと]で混雑[こんざつ]していた。", "sentence_source": "generated"}, {"text": "昼休みの食堂は混雑していて、座る場所がなかった。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "昼休[ひるやす]みの食堂[しょくどう]は混雑[こんざつ]していて、座[すわ]る場所[ばしょ]がなかった。", "sentence_source": "generated"}, {"text": "この電車は混雑しているので、ベビーカーは乗りにくい。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "この電車[でんしゃ]は混雑[こんざつ]しているので、ベビーカーは乗[の]りにくい。", "sentence_source": "generated"}, {"text": "年末のデパートは混雑がひどく、まっすぐ歩けなかった。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "年末[ねんまつ]のデパートは混雑[こんざつ]がひどく、まっすぐ歩[ある]けなかった。", "sentence_source": "generated"}, {"text": "混雑した車内で、足を踏まれてしまった。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "混雑[こんざつ]した車内[しゃない]で、足[あし]を踏[ふ]まれてしまった。", "sentence_source": "generated"}, {"text": "日曜日の動物園は家族連れで混雑する。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "日曜日[にちようび]の動物園[どうぶつえん]は家族連[かぞくづ]れで混雑[こんざつ]する。", "sentence_source": "generated"}, {"text": "混雑する時間をさけて、空いている午後に病院へ行った。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "混雑[こんざつ]する時間[じかん]をさけて、空[す]いている午後[ごご]に病院[びょういん]へ行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "混雑", "label": "基本形"}, {"form": "混雑する", "label": "する形"}, {"form": "混雑した", "label": "過去形"}, {"form": "混雑している", "label": "ている形"}, {"form": "混雑しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "場所に人が多すぎて、窮屈で動きにくい状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aebd181-359a-45dc-80f8-127f2fbef7ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37166, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "混雑", "is_correct": true, "explanation": "「駅の混雑」の形で名詞として「の」に続き、「ひどい」の主語になる。"}, {"text": "混雑する", "is_correct": false, "explanation": "動詞の形なので、「駅の」の後に続く名詞の位置に入らない。"}, {"text": "混雑して", "is_correct": false, "explanation": "て形は文を続ける形で、名詞の位置には入らない。「駅の混雑してがひどい」は成立しない。"}, {"text": "混雑した", "is_correct": false, "explanation": "連体形なので後ろに名詞が必要。「駅の混雑したがひどい」は「がひどい」につながらない。"}], "explanations": {"混雑": "「駅の混雑」の形で名詞として「の」に続き、「ひどい」の主語になる。", "混雑する": "動詞の形なので、「駅の」の後に続く名詞の位置に入らない。", "混雑して": "て形は文を続ける形で、名詞の位置には入らない。「駅の混雑してがひどい」は成立しない。", "混雑した": "連体形なので後ろに名詞が必要。「駅の混雑したがひどい」は「がひどい」につながらない。"}, "sentence_index": 0, "correct_answer": "混雑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "停電のせいで、電車の運行が混雑した。", "explanation": "ここは〈混乱〉の意味。運行が乱れる様子は人が集まって動きにくい状態ではないので、〈混雑〉は合わない。"}, {"text": "二種類の粉を、ボウルの中で混雑させる。", "explanation": "ここは〈混合〉の意味。粉を混ぜる動作には〈混雑〉を使わない。"}, {"text": "会議は意見が混雑して、結論が出なかった。", "explanation": "ここは〈紛糾〉の意味。意見が激しく対立して収拾がつかない様子には〈混雑〉を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37166, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "混雑", "is_correct": true, "explanation": "「デパートは混雑がひどく」で、混雑が主語となり「ひどく」につながる名詞。"}, {"text": "混雑させる", "is_correct": false, "explanation": "使役の動詞で、「は…がひどく」の位置の名詞にならない。"}, {"text": "混雑している", "is_correct": false, "explanation": "ている形で名詞の位置に入らず、「がひどく」とつながらない。"}, {"text": "混雑しない", "is_correct": false, "explanation": "否定形で名詞の位置に入らない。「は混雑しないがひどく」は成立しない。"}], "explanations": {"混雑": "「デパートは混雑がひどく」で、混雑が主語となり「ひどく」につながる名詞。", "混雑させる": "使役の動詞で、「は…がひどく」の位置の名詞にならない。", "混雑している": "ている形で名詞の位置に入らず、「がひどく」とつながらない。", "混雑しない": "否定形で名詞の位置に入らない。「は混雑しないがひどく」は成立しない。"}, "sentence_index": 6, "correct_answer": "混雑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "交渉が混雑して、話し合いがまったく進まない。", "explanation": "ここは〈停滞〉の意味。交渉の進みが止まる状態には〈混雑〉を使わない。〈混雑〉は人や物が一か所に集まる状態を指す。"}, {"text": "食品に異物が混雑していたため、回収された。", "explanation": "ここは〈混入〉の意味。異物が紛れ込む様子には〈混雑〉を使わない。"}, {"text": "試合が序盤から混雑して、どちらも点を取れなかった。", "explanation": "ここは〈混戦〉の意味。点の取り合いが続く激しい争いには〈混雑〉を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37166, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の駅は、混雑を少ない。", "corrected_sentence": "夜の駅は、混雑が少ない。", "error_description": "正しくは「混雑が少ない」。「少ない」の主語にあたる「混雑」には「が」を付ける。「を」は目的語を示すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37166, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末の書店は、夕方になると混雑に増える。", "corrected_sentence": "週末の書店は、夕方になると混雑が増える。", "error_description": "正しくは「混雑が増える」。「増える」の主語になる「混雑」には「が」を付ける。「に」は場所や相手を示すので、ここでは不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37167, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「入口が混雑して」で、入口が主語となり、混雑する主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「混雑」は自動詞なので目的語を取らない。「入口を混雑して」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「入口へ混雑して」は場所への移動を表さず不自然。"}, {"text": "の", "is_correct": false, "explanation": "名詞同士をつなぐ「の」は、「入口の混雑して」では動詞に続かず不自然。"}], "correct_answer": "が", "explanations": {"が": "「入口が混雑して」で、入口が主語となり、混雑する主体を示す。", "を": "「混雑」は自動詞なので目的語を取らない。「入口を混雑して」は不自然。", "へ": "方向を示すが、「入口へ混雑して」は場所への移動を表さず不自然。", "の": "名詞同士をつなぐ「の」は、「入口の混雑して」では動詞に続かず不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閑散", "is_correct": true, "explanation": "人が少なくて通路や店がすいている様子を表し、混雑の対義語。"}, {"text": "清潔", "is_correct": false, "explanation": "衛生的な様子を表し、人の多さとは関係がないので対義語ではない。"}, {"text": "容易", "is_correct": false, "explanation": "やさしい様子を表し、混雑の反対の意味にはならない。"}, {"text": "不安", "is_correct": false, "explanation": "心配な気持ちを表し、人の集まりとは関係しない。"}], "correct_answer": "閑散", "explanations": {"閑散": "人が少なくて通路や店がすいている様子を表し、混雑の対義語。", "清潔": "衛生的な様子を表し、人の多さとは関係がないので対義語ではない。", "容易": "やさしい様子を表し、混雑の反対の意味にはならない。", "不安": "心配な気持ちを表し、人の集まりとは関係しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37167, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閑散", "is_correct": true, "explanation": "人が少なくてひっそりした様子を表し、混雑の反対の状態。"}, {"text": "安価", "is_correct": false, "explanation": "値段が安い様子を表し、人の集まりとは関係がないので対義語ではない。"}, {"text": "寛大", "is_correct": false, "explanation": "心が広く許す態度を表し、混雑とは対になる関係にない。"}, {"text": "誠実", "is_correct": false, "explanation": "真面目な態度を表し、混雑の反対の意味にはならない。"}], "correct_answer": "閑散", "explanations": {"閑散": "人が少なくてひっそりした様子を表し、混雑の反対の状態。", "安価": "値段が安い様子を表し、人の集まりとは関係がないので対義語ではない。", "寛大": "心が広く許す態度を表し、混雑とは対になる関係にない。", "誠実": "真面目な態度を表し、混雑の反対の意味にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37167, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "多くの人や物が一か所に集まって、動きにくい状態。", "primary_collocate": null, "pronunciation": "こんざつ", "ipa": "koɴzat͡sɯ", "syllable_count": 4, "sentences": [{"text": "夕方の高速道路は車で混雑する。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]の高速道路[こうそくどうろ]は車[くるま]で混雑[こんざつ]する。", "sentence_source": "generated"}, {"text": "発表の直前、会場の入口が混雑して、なかなか中に入れなかった。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の直前[ちょくぜん]、会場[かいじょう]の入口[いりぐち]が混雑[こんざつ]して、なかなか中[なか]に入[はい]れなかった。", "sentence_source": "generated"}, {"text": "週末の空港は、旅行客と荷物で混雑する。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]の空港[くうこう]は、旅行客[りょこうきゃく]と荷物[にもつ]で混雑[こんざつ]する。", "sentence_source": "generated"}, {"text": "夕方のスーパーのレジは混雑して、長い列ができていた。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]のスーパーのレジは混雑[こんざつ]して、長[なが]い列[れつ]ができていた。", "sentence_source": "generated"}, {"text": "雨の日は、バス停の付近が傘を持った人で混雑する。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、バス停[てい]の付近[ふきん]が傘[かさ]を持[も]った人[ひと]で混雑[こんざつ]する。", "sentence_source": "generated"}, {"text": "事故のせいで、国道は車で混雑している。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "事故[じこ]のせいで、国道[こくどう]は車[くるま]で混雑[こんざつ]している。", "sentence_source": "generated"}, {"text": "港は大きな船と人で混雑していた。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "港[みなと]は大[おお]きな船[ふね]と人[ひと]で混雑[こんざつ]していた。", "sentence_source": "generated"}, {"text": "混雑したエレベーターの中では、みんな静かだった。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "混雑[こんざつ]したエレベーターの中[なか]では、みんな静[しず]かだった。", "sentence_source": "generated"}, {"text": "入学式の日は、校門の前が混雑した。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "入学式[にゅうがくしき]の日[ひ]は、校門[こうもん]の前[まえ]が混雑[こんざつ]した。", "sentence_source": "generated"}, {"text": "混雑のため、入場まで三十分待たされた。", "target_word": "混雑", "complexity_tier": "T3", "furigana": "混雑[こんざつ]のため、入場[にゅうじょう]まで三十分[さんじゅっぷん]待[ま]たされた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "混雑", "label": "基本形"}, {"form": "混雑する", "label": "する形"}, {"form": "混雑した", "label": "過去形"}, {"form": "混雑している", "label": "ている形"}, {"form": "混雑しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "人や車などが一か所に集まり、身動きや流れが悪くなる状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aebd181-359a-45dc-80f8-127f2fbef7ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37167, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "混雑", "is_correct": true, "explanation": "「車で混雑する」で、車が原因や手段となって場所が混み合う状態を表す。"}, {"text": "工事", "is_correct": false, "explanation": "「車で工事する」は意味が通らず、高速道路の状況を表さない。"}, {"text": "誕生", "is_correct": false, "explanation": "「車で誕生する」は意味をなさず、道路の状況を表せない。"}, {"text": "繁殖", "is_correct": false, "explanation": "生物が増える意味で、車が原因になる状況では文が成立しない。"}], "explanations": {"混雑": "「車で混雑する」で、車が原因や手段となって場所が混み合う状態を表す。", "工事": "「車で工事する」は意味が通らず、高速道路の状況を表さない。", "誕生": "「車で誕生する」は意味をなさず、道路の状況を表せない。", "繁殖": "生物が増える意味で、車が原因になる状況では文が成立しない。"}, "sentence_index": 0, "correct_answer": "混雑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "絵の具を混雑させて、新しい色を作った。", "explanation": "ここは〈混合〉の意味。色を混ぜる動作には〈混雑〉を使わない。"}, {"text": "条件が混雑していて、契約がなかなかまとまらない。", "explanation": "ここは〈錯綜〉の意味。条件や筋道が入り組む様子には〈混雑〉を使わない。"}, {"text": "ガラスの破片が床で混雑していて、歩くと危ない。", "explanation": "ここは〈散乱〉の意味。破片が四方に飛び散った様子には〈混雑〉を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37167, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "混雑", "is_correct": true, "explanation": "「船と人で混雑していた」で、人や船が一か所に集まった状態を表す名詞。"}, {"text": "解体", "is_correct": false, "explanation": "「人で解体していた」は意味が通らず、解体は船や建物を分ける作業を指す。"}, {"text": "作成", "is_correct": false, "explanation": "物を新しくつくる行為で、「船と人で作成していた」は港の様子を表せない。"}, {"text": "遮断", "is_correct": false, "explanation": "流れを止める意味で、人と船を主語にすると港の状況に合わない。"}], "explanations": {"混雑": "「船と人で混雑していた」で、人や船が一か所に集まった状態を表す名詞。", "解体": "「人で解体していた」は意味が通らず、解体は船や建物を分ける作業を指す。", "作成": "物を新しくつくる行為で、「船と人で作成していた」は港の様子を表せない。", "遮断": "流れを止める意味で、人と船を主語にすると港の状況に合わない。"}, "sentence_index": 6, "correct_answer": "混雑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工事が混雑して、完成が大幅に遅れた。", "explanation": "ここは〈停滞〉の意味。作業の進みが止まる状態には〈混雑〉を使わない。"}, {"text": "生地に異物が混雑していて、使えなかった。", "explanation": "ここは〈混入〉の意味。異物が紛れ込む様子には〈混雑〉を使わない。"}, {"text": "似た二つの単語を混雑して覚えてしまい、テストで間違えた。", "explanation": "ここは〈混同〉の意味。別々のものを取り違える場合には〈混雑〉を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37167, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市場の入口は、客を混雑している。", "corrected_sentence": "市場の入口は、客で混雑している。", "error_description": "正しくは「客で混雑している」。混雑の原因や状態を示す「で」を使う。「を」は目的語を示すため、「混雑する」（自動詞）と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37167, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りの日の神社は、人に混雑する。", "corrected_sentence": "祭りの日の神社は、人で混雑する。", "error_description": "正しくは「人で混雑する」。混雑の原因を示す「で」を使う。「に」は方向や対象を示すので、混雑には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37168, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「駐車が少なくて」で、駐車の量が少ないことを示す主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「少ない」は形容詞で目的語を取らず、「駐車を少なくて」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "場所や対象を示すが、「駐車に少なくて」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「駐車で少なくて」は文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「駐車が少なくて」で、駐車の量が少ないことを示す主語になる。", "を": "「少ない」は形容詞で目的語を取らず、「駐車を少なくて」は不自然。", "に": "場所や対象を示すが、「駐車に少なくて」は意味が通らない。", "で": "手段や場所を示すが、「駐車で少なくて」は文が成立しない。"}, "error_tags": {"を": "目的語", "に": "方向・対象", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37168, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「駐車のための場所」で、場所の用途を示す連体修飾の「の」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「駐車がための場所」と続かず不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「駐車をための場所」では名詞の修飾が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「駐車でための場所」は文が成立しない。"}], "correct_answer": "の", "explanations": {"の": "「駐車のための場所」で、場所の用途を示す連体修飾の「の」。", "が": "主語を示すが、「駐車がための場所」と続かず不自然。", "を": "目的語を示すが、「駐車をための場所」では名詞の修飾が成立しない。", "で": "手段や場所を示すが、「駐車でための場所」は文が成立しない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37168, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "くるまをとめるためのばしょのこと。", "primary_collocate": null, "pronunciation": "ちゅうしゃ", "ipa": "t͡ɕɯːɕa", "syllable_count": 3, "sentences": [{"text": "この店には、お客さん用の駐車が三台分あります。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "この店[みせ]には、お客[きゃく]さん用[よう]の駐車[ちゅうしゃ]が三台分[さんだいぶん]あります。", "sentence_source": "generated"}, {"text": "この辺りは駐車が少なくて、車を止める場所に困る。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "この辺[あた]りは駐車[ちゅうしゃ]が少[すく]なくて、車[くるま]を止[と]める場所[ばしょ]に困[こま]る。", "sentence_source": "generated"}, {"text": "駅の近くで、駐車が二十台分ある所を探しています。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くで、駐車[ちゅうしゃ]が二十台分[にじゅうだいぶん]ある所[ところ]を探[さが]しています。", "sentence_source": "generated"}, {"text": "店の裏の空き地を、お客さん用の駐車として借りた。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "店[みせ]の裏[うら]の空[あ]き地[ち]を、お客[きゃく]さん用[よう]の駐車[ちゅうしゃ]として借[か]りた。", "sentence_source": "generated"}, {"text": "この建物は、地下に駐車が六台分あります。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "この建物[たてもの]は、地下[ちか]に駐車[ちゅうしゃ]が六台分[ろくだいぶん]あります。", "sentence_source": "generated"}, {"text": "祭りの日は、公園の横の駐車がすぐいっぱいになる。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]は、公園[こうえん]の横[よこ]の駐車[ちゅうしゃ]がすぐいっぱいになる。", "sentence_source": "generated"}, {"text": "病院の裏の駐車を、一台だけ使わせてもらった。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "病院[びょういん]の裏[うら]の駐車[ちゅうしゃ]を、一台[いちだい]だけ使[つか]わせてもらった。", "sentence_source": "generated"}, {"text": "駐車のための場所が足りなくて、近所の人が困っている。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "駐車[ちゅうしゃ]のための場所[ばしょ]が足[た]りなくて、近所[きんじょ]の人[ひと]が困[こま]っている。", "sentence_source": "generated"}, {"text": "雪の日は、屋根のある駐車を選んだほうがいい。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、屋根[やね]のある駐車[ちゅうしゃ]を選[えら]んだほうがいい。", "sentence_source": "generated"}, {"text": "兄は白い線の中の駐車に、車をゆっくり後ろに下げて入れた。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "兄[あに]は白[しろ]い線[せん]の中[なか]の駐車[ちゅうしゃ]に、車[くるま]をゆっくり後[うし]ろに下[さ]げて入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "駐車", "label": "基本形"}, {"form": "駐車する", "label": "する形"}, {"form": "駐車した", "label": "過去形"}, {"form": "駐車できる", "label": "可能形"}, {"form": "駐車しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "車をとめて置くこと、またそのための場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aebd181-359a-45dc-80f8-127f2fbef7ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37168, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "駐車", "is_correct": true, "explanation": "「お客さん用の駐車」で、車を止めておく場所を表す名詞。台数で数えられる。"}, {"text": "試着", "is_correct": false, "explanation": "服を試す行為で、台数で数えられる場所を表さない。"}, {"text": "読書", "is_correct": false, "explanation": "本を読む行為で、台数で数えられる場所を表せない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて出かける行為で、車を止める台数分の場所にはならない。"}], "explanations": {"駐車": "「お客さん用の駐車」で、車を止めておく場所を表す名詞。台数で数えられる。", "試着": "服を試す行為で、台数で数えられる場所を表さない。", "読書": "本を読む行為で、台数で数えられる場所を表せない。", "散歩": "歩いて出かける行為で、車を止める台数分の場所にはならない。"}, "sentence_index": 0, "correct_answer": "駐車"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車が駅に五分間駐車した。", "explanation": "ここは〈停車〉の意味。電車やバスが一時的に止まることは〈駐車〉ではなく〈停車〉と言う。"}, {"text": "部隊が国外に駐車している。", "explanation": "ここは〈駐留〉の意味。軍隊が一定の地域にとどまる場合には〈駐車〉は使わない。"}, {"text": "船が港に駐車した。", "explanation": "ここは〈停泊〉の意味。船が港に止まることは〈駐車〉ではなく〈停泊〉と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37168, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "駐車", "is_correct": true, "explanation": "「病院の裏の駐車」で、車を止める場所を指す名詞。"}, {"text": "受付", "is_correct": false, "explanation": "事務の窓口を表し、車を一台使う対象にならない。"}, {"text": "手術", "is_correct": false, "explanation": "医療行為を表し、台数で使うものにはならない。"}, {"text": "献血", "is_correct": false, "explanation": "血液を提供する行為で、病院の裏の場所を表せない。"}], "explanations": {"駐車": "「病院の裏の駐車」で、車を止める場所を指す名詞。", "受付": "事務の窓口を表し、車を一台使う対象にならない。", "手術": "医療行為を表し、台数で使うものにはならない。", "献血": "血液を提供する行為で、病院の裏の場所を表せない。"}, "sentence_index": 6, "correct_answer": "駐車"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は海外に駐車している。", "explanation": "ここは〈駐在〉の意味。会社員が任地に勤務することには〈駐車〉を使わない。"}, {"text": "旅館に一週間、駐車した。", "explanation": "ここは〈宿泊〉の意味。人が泊まることには〈駐車〉を使わない。"}, {"text": "容疑者は留置場に駐車された。", "explanation": "ここは〈留置〉の意味。人を一定の場所にとどめて拘束する場合は〈駐車〉と言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37168, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜間は駐車を無料になります。", "corrected_sentence": "夜間は駐車が無料になります。", "error_description": "正しくは「駐車が無料になる」。「無料になる」の主語は「駐車」なので「が」を使う。「を」は目的語を示すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37168, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駐車られる場所を探した。", "corrected_sentence": "駐車できる場所を探した。", "error_description": "正しくは「駐車できる」。「駐車」はサ変名詞なので、可能の意味は「できる」で表す。「られる」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
