INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37169, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「所に駐車した」で、車を止めた場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「所が駐車した」は場所が駐車する文になり意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」だが、「所の駐車した」は名詞に続かず文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、「所と駐車した」は成立しない。"}], "correct_answer": "に", "explanations": {"に": "「所に駐車した」で、車を止めた場所を示す。", "が": "主語を示すが、「所が駐車した」は場所が駐車する文になり意味が通らない。", "の": "連体修飾の「の」だが、「所の駐車した」は名詞に続かず文が成立しない。", "と": "並列や相手を示すが、「所と駐車した」は成立しない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37169, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "車を止めておく場所や、車を止めるという動作。", "primary_collocate": null, "pronunciation": "ちゅうしゃ", "ipa": "t͡ɕɯːɕa", "syllable_count": 3, "sentences": [{"text": "駐車が下手なので、広い所に止めたい。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "駐車[ちゅうしゃ]が下手[へた]なので、広[ひろ]い所[ところ]に止[と]めたい。", "sentence_source": "generated"}, {"text": "駐車は三十分までと決まっている。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "駐車[ちゅうしゃ]は三十分[さんじゅっぷん]までと決[き]まっている。", "sentence_source": "generated"}, {"text": "ここに駐車してもいいですか。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "ここに駐車[ちゅうしゃ]してもいいですか。", "sentence_source": "generated"}, {"text": "駐車に時間がかかって、約束に遅れた。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "駐車[ちゅうしゃ]に時間[じかん]がかかって、約束[やくそく]に遅[おく]れた。", "sentence_source": "generated"}, {"text": "父は駐車が得意で、細い所にもすぐ入れる。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "父[ちち]は駐車[ちゅうしゃ]が得意[とくい]で、細[ほそ]い所[ところ]にもすぐ入[い]れる。", "sentence_source": "generated"}, {"text": "路上に駐車すると、警察に注意されることがある。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "路上[ろじょう]に駐車[ちゅうしゃ]すると、警察[けいさつ]に注意[ちゅうい]されることがある。", "sentence_source": "generated"}, {"text": "駐車の仕方を、教習所で習った。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "駐車[ちゅうしゃ]の仕方[しかた]を、教習所[きょうしゅうじょ]で習[なら]った。", "sentence_source": "generated"}, {"text": "満車だったので、少し離れた所に駐車した。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "満車[まんしゃ]だったので、少[すこ]し離[はな]れた所[ところ]に駐車[ちゅうしゃ]した。", "sentence_source": "generated"}, {"text": "駐車する場所がなく、同じ道を何度も回った。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "駐車[ちゅうしゃ]する場所[ばしょ]がなく、同[おな]じ道[みち]を何度[なんど]も回[まわ]った。", "sentence_source": "generated"}, {"text": "店の人に頼んで、一時間だけ駐車させてもらった。", "target_word": "駐車", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]に頼[たの]んで、一時間[いちじかん]だけ駐車[ちゅうしゃ]させてもらった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "駐車", "label": "基本形"}, {"form": "駐車する", "label": "する形"}, {"form": "駐車した", "label": "過去形"}, {"form": "駐車させる", "label": "使役形"}, {"form": "駐車しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "車を一定の場所に止めておく動作、またその場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 満車 (Zipf 2.29)']::text[], '4aebd181-359a-45dc-80f8-127f2fbef7ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37169, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "駐車", "is_correct": true, "explanation": "「駐車が下手」で、車を止める動作を表し、後の「広い所に止めたい」という理由につながる。"}, {"text": "試験", "is_correct": false, "explanation": "車の操作と関係がなく、「広い所に止めたい」と理由がつながらない。"}, {"text": "読書", "is_correct": false, "explanation": "車を止める理由にならず、文が成立しない。"}, {"text": "発表", "is_correct": false, "explanation": "車の動作と関係がなく、後の文の理由にならない。"}], "explanations": {"駐車": "「駐車が下手」で、車を止める動作を表し、後の「広い所に止めたい」という理由につながる。", "試験": "車の操作と関係がなく、「広い所に止めたい」と理由がつながらない。", "読書": "車を止める理由にならず、文が成立しない。", "発表": "車の動作と関係がなく、後の文の理由にならない。"}, "sentence_index": 0, "correct_answer": "駐車"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場の機械が急に駐車した。", "explanation": "ここは〈停止〉の意味。機械が動きを止めることには〈駐車〉を使わない。"}, {"text": "次の電車に駐車した。", "explanation": "ここは〈乗車〉の意味。人が車両に乗り込むことは〈駐車〉と言わない。"}, {"text": "選手がベンチで駐車して、出番を待った。", "explanation": "ここは〈待機〉の意味。人がその場で順番を待つことには〈駐車〉を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37169, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "駐車", "is_correct": true, "explanation": "「駐車の仕方」で、車を止める動作の方法を表す。"}, {"text": "天井", "is_correct": false, "explanation": "建物の上部を表し、習う方法の対象にならない。"}, {"text": "椅子", "is_correct": false, "explanation": "座る家具を表し、「仕方」と組み合わない。"}, {"text": "地震", "is_correct": false, "explanation": "自然現象を表し、教習所で習う方法にはならない。"}], "explanations": {"駐車": "「駐車の仕方」で、車を止める動作の方法を表す。", "天井": "建物の上部を表し、習う方法の対象にならない。", "椅子": "座る家具を表し、「仕方」と組み合わない。", "地震": "自然現象を表し、教習所で習う方法にはならない。"}, "sentence_index": 6, "correct_answer": "駐車"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乗客は次々とフェリーに駐車した。", "explanation": "ここは〈乗船〉の意味。人が船に乗り込むことには〈駐車〉を使わない。"}, {"text": "ボールが芝生の上でしばらく駐車した。", "explanation": "ここは〈静止〉の意味。物が動かずに止まる状態には〈駐車〉を使わない。"}, {"text": "景気が長く駐車して、賃金が上がらない。", "explanation": "ここは〈停滞〉の意味。経済の動きが止まることには〈駐車〉を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37169, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路上に駐車を車が多い。", "corrected_sentence": "路上に駐車する車が多い。", "error_description": "正しくは「駐車する車」。「駐車」は名詞なので、後ろの車を修飾するには「駐車する」と動詞の形にする必要がある。「を」は目的語を示すため、ここでは余分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37169, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駐車を場所を探すのに、十分もかかった。", "corrected_sentence": "駐車の場所を探すのに、十分もかかった。", "error_description": "正しくは「駐車の場所」。「駐車」と「場所」をつなぐのは「の」。「を」は動詞の目的語を示すため、名詞同士の間では誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37170, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安心", "is_correct": true, "explanation": "対義語。心配（悪いことを不安に思う）の反対で、不安が消えて落ち着いた状態を指す。"}, {"text": "期待", "is_correct": false, "explanation": "対義語ではない。良い結果を望んで楽しみに待つ気持ちで、心配の反対語とはされない。"}, {"text": "熱中", "is_correct": false, "explanation": "対義語ではない。ある物事に夢中になることで、心配の反対語とはされない。"}, {"text": "感謝", "is_correct": false, "explanation": "対義語ではない。相手の厚意にありがたく思う気持ちで、心配の反対語とはされない。"}], "correct_answer": "安心", "explanations": {"安心": "対義語。心配（悪いことを不安に思う）の反対で、不安が消えて落ち着いた状態を指す。", "期待": "対義語ではない。良い結果を望んで楽しみに待つ気持ちで、心配の反対語とはされない。", "熱中": "対義語ではない。ある物事に夢中になることで、心配の反対語とはされない。", "感謝": "対義語ではない。相手の厚意にありがたく思う気持ちで、心配の反対語とはされない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37170, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安心", "is_correct": true, "explanation": "対義語。心配（悪いことを不安に思う）の反対で、不安が消えて落ち着いた状態を指す。"}, {"text": "注目", "is_correct": false, "explanation": "対義語ではない。特定の物事に関心を向けることで、心配の反対語とはされない。"}, {"text": "満足", "is_correct": false, "explanation": "対義語ではない。十分に良いと感じることで、心配の反対語とはされない。"}, {"text": "集中", "is_correct": false, "explanation": "対義語ではない。一つの物事に意識を向けることで、心配の反対語とはされない。"}], "correct_answer": "安心", "explanations": {"安心": "対義語。心配（悪いことを不安に思う）の反対で、不安が消えて落ち着いた状態を指す。", "注目": "対義語ではない。特定の物事に関心を向けることで、心配の反対語とはされない。", "満足": "対義語ではない。十分に良いと感じることで、心配の反対語とはされない。", "集中": "対義語ではない。一つの物事に意識を向けることで、心配の反対語とはされない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37170, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「心配」は、何か悪いことが起きるかもしれないと考えて、不安に思うことです。", "primary_collocate": null, "pronunciation": "しんぱい", "ipa": "ɕiɴpai", "syllable_count": 4, "sentences": [{"text": "娘が夜になっても帰らないので、母はとても心配した。", "target_word": "心配", "complexity_tier": "T3", "furigana": "娘[むすめ]が夜[よる]になっても帰[かえ]らないので、母[はは]はとても心配[しんぱい]した。", "sentence_source": "generated"}, {"text": "明日の試験のことが心配で、よく眠れなかった。", "target_word": "心配", "complexity_tier": "T3", "furigana": "明日[あした]の試験[しけん]のことが心配[しんぱい]で、よく眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "「大丈夫だよ。心配しないで」と友達が言ってくれた。", "target_word": "心配", "complexity_tier": "T3", "furigana": "「大丈夫[だいじょうぶ]だよ。心配[しんぱい]しないで」と友達[ともだち]が言[い]ってくれた。", "sentence_source": "generated"}, {"text": "祖母が一人で暮らしているので、みんな心配している。", "target_word": "心配", "complexity_tier": "T3", "furigana": "祖母[そぼ]が一人[ひとり]で暮[く]らしているので、みんな心配[しんぱい]している。", "sentence_source": "generated"}, {"text": "熱が下がらない弟のことを、母は心配している。", "target_word": "心配", "complexity_tier": "T3", "furigana": "熱[ねつ]が下[さ]がらない弟[おとうと]のことを、母[はは]は心配[しんぱい]している。", "sentence_source": "generated"}, {"text": "天気が悪くなると、山に登った兄が心配になる。", "target_word": "心配", "complexity_tier": "T3", "furigana": "天気[てんき]が悪[わる]くなると、山[やま]に登[のぼ]った兄[あに]が心配[しんぱい]になる。", "sentence_source": "generated"}, {"text": "心配をかけてごめん。もう元気になったよ。", "target_word": "心配", "complexity_tier": "T3", "furigana": "心配[しんぱい]をかけてごめん。もう元気[げんき]になったよ。", "sentence_source": "generated"}, {"text": "森さんは道が暗いのを心配して、駅まで迎えに来てくれた。", "target_word": "心配", "complexity_tier": "T3", "furigana": "森[もり]さんは道[みち]が暗[くら]いのを心配[しんぱい]して、駅[えき]まで迎[むか]えに来[き]てくれた。", "sentence_source": "generated"}, {"text": "財布をなくしたかもしれないと思うと、心配で仕事に集中できない。", "target_word": "心配", "complexity_tier": "T3", "furigana": "財布[さいふ]をなくしたかもしれないと思[おも]うと、心配[しんぱい]で仕事[しごと]に集中[しゅうちゅう]できない。", "sentence_source": "generated"}, {"text": "初めての一人旅に出る娘を、両親は心配していた。", "target_word": "心配", "complexity_tier": "T3", "furigana": "初[はじ]めての一人旅[ひとりたび]に出[で]る娘[むすめ]を、両親[りょうしん]は心配[しんぱい]していた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "心配する", "label": "辞書形"}, {"form": "心配して", "label": "て形"}, {"form": "心配した", "label": "過去形"}, {"form": "心配しない", "label": "否定形"}, {"form": "心配です", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "家族や友達など身近な人や自分のことで、悪いことが起きないかと不安に思う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451f182-b416-4156-a958-f234e1ab7309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37170, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心配", "is_correct": true, "explanation": "「娘が夜になっても帰らず、悪いことを不安に思った」という文脈に合う。「母はとても心配した」の形。"}, {"text": "天気", "is_correct": false, "explanation": "「母はとても天気した」は成り立たない。「天気」は「する」と結びつかない名詞。"}, {"text": "料理", "is_correct": false, "explanation": "「母はとても料理した」は意味が通らない。「料理」は作る・食べるものを表す名詞。"}, {"text": "手紙", "is_correct": false, "explanation": "「母はとても手紙した」は不自然。「手紙」は書く・出すものを表す名詞。"}], "explanations": {"心配": "「娘が夜になっても帰らず、悪いことを不安に思った」という文脈に合う。「母はとても心配した」の形。", "天気": "「母はとても天気した」は成り立たない。「天気」は「する」と結びつかない名詞。", "料理": "「母はとても料理した」は意味が通らない。「料理」は作る・食べるものを表す名詞。", "手紙": "「母はとても手紙した」は不自然。「手紙」は書く・出すものを表す名詞。"}, "sentence_index": 0, "correct_answer": "心配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生の説明の分かりやすさに、みんなが心配した。", "explanation": "「心配」は不安の意味で、説明のすぐれた点に感心する意味は持たない。"}, {"text": "その選手は大会で心配を獲得した。", "explanation": "「心配」は不安の意味で、賞を得ることは表さない。"}, {"text": "その説明には、どうしても心配がいかない。", "explanation": "「心配」は不安の意味で、話に納得する意味は持たない。「合点がいかない」の代わりにもならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37170, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心配", "is_correct": true, "explanation": "「心配をかける」は、相手に気を遣わせることを表す定型の表現。"}, {"text": "興味", "is_correct": false, "explanation": "「興味をかける」とは言わない。「興味を持つ」「興味を示す」と使う名詞。"}, {"text": "残念", "is_correct": false, "explanation": "「残念をかける」は成り立たない。「残念だ」「残念に思う」と使う。"}, {"text": "感謝", "is_correct": false, "explanation": "「感謝をかける」とは言わない。「感謝を伝える」「感謝する」と使う。"}], "explanations": {"心配": "「心配をかける」は、相手に気を遣わせることを表す定型の表現。", "興味": "「興味をかける」とは言わない。「興味を持つ」「興味を示す」と使う名詞。", "残念": "「残念をかける」は成り立たない。「残念だ」「残念に思う」と使う。", "感謝": "「感謝をかける」とは言わない。「感謝を伝える」「感謝する」と使う。"}, "sentence_index": 6, "correct_answer": "心配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "帰り道で昔の友人に心配に会った。", "explanation": "「心配」は不安の意味で、思いがけない出会いを表さない。"}, {"text": "店員は客の質問に心配に答えた。", "explanation": "「心配」は不安の意味で、答え方の丁寧さは表さない。"}, {"text": "大切に育てた花が心配に咲いた。", "explanation": "「心配」は不安の意味で、花の咲き方を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37170, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟が熱を出したので、母は弟が心配した。", "corrected_sentence": "弟が熱を出したので、母は弟を心配した。", "error_description": "「心配する」は対象を「〜を心配する」の形で取る。対象の「弟」に「が」を付けたのが誤りで、正しくは「弟を心配した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37170, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風邪で寝込んだ友達が心配、見舞いに行った。", "corrected_sentence": "風邪で寝込んだ友達が心配で、見舞いに行った。", "error_description": "「心配」を理由として続けるには「で」が必要。「で」が抜けていて、「心配」と「見舞いに行った」が正しくつながらない。正しくは「心配で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37171, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安心", "is_correct": true, "explanation": "対義語。心配（悪い結果を不安に思う）の反対で、不安がない落ち着いた状態を指す。"}, {"text": "熱中", "is_correct": false, "explanation": "対義語ではない。ある物事に夢中になることで、心配の反対語とはされない。"}, {"text": "遠慮", "is_correct": false, "explanation": "対義語ではない。相手に気を遣って控えることで、心配の反対語とはされない。"}, {"text": "感謝", "is_correct": false, "explanation": "対義語ではない。ありがたく思う気持ちで、心配の反対語とはされない。"}], "correct_answer": "安心", "explanations": {"安心": "対義語。心配（悪い結果を不安に思う）の反対で、不安がない落ち着いた状態を指す。", "熱中": "対義語ではない。ある物事に夢中になることで、心配の反対語とはされない。", "遠慮": "対義語ではない。相手に気を遣って控えることで、心配の反対語とはされない。", "感謝": "対義語ではない。ありがたく思う気持ちで、心配の反対語とはされない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37171, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安心", "is_correct": true, "explanation": "対義語。心配（悪い結果を不安に思う）の反対で、不安がない落ち着いた状態を指す。"}, {"text": "注目", "is_correct": false, "explanation": "対義語ではない。特定の物事に関心を向けることで、心配の反対語とはされない。"}, {"text": "満足", "is_correct": false, "explanation": "対義語ではない。十分に良いと感じることで、心配の反対語とはされない。"}, {"text": "集中", "is_correct": false, "explanation": "対義語ではない。一つの物事に意識を向けることで、心配の反対語とはされない。"}], "correct_answer": "安心", "explanations": {"安心": "対義語。心配（悪い結果を不安に思う）の反対で、不安がない落ち着いた状態を指す。", "注目": "対義語ではない。特定の物事に関心を向けることで、心配の反対語とはされない。", "満足": "対義語ではない。十分に良いと感じることで、心配の反対語とはされない。", "集中": "対義語ではない。一つの物事に意識を向けることで、心配の反対語とはされない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37171, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「心配」は、将来の出来事や現在の状況に対して、悪い結果を予想して不安を感じること、またはその気持ちを指します。", "primary_collocate": null, "pronunciation": "しんぱい", "ipa": "ɕiɴpai", "syllable_count": 4, "sentences": [{"text": "来週は台風が来るそうなので、農家の人は作物の被害を心配している。", "target_word": "心配", "complexity_tier": "T3", "furigana": "来週[らいしゅう]は台風[たいふう]が来[く]るそうなので、農家[のうか]の人[ひと]は作物[さくもつ]の被害[ひがい]を心配[しんぱい]している。", "sentence_source": "generated"}, {"text": "このままでは地球の気温が上がり続けるのではないかと心配だ。", "target_word": "心配", "complexity_tier": "T3", "furigana": "このままでは地球[ちきゅう]の気温[きおん]が上[あ]がり続[つづ]けるのではないかと心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "景気が悪くなって、会社がつぶれないか心配する人が増えた。", "target_word": "心配", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなって、会社[かいしゃ]がつぶれないか心配[しんぱい]する人[ひと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "雨が続くと、川があふれる心配がある。", "target_word": "心配", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]くと、川[かわ]があふれる心配[しんぱい]がある。", "sentence_source": "generated"}, {"text": "彼は新しい仕事がうまくいくか心配で、毎晩遅くまで資料を読んだ。", "target_word": "心配", "complexity_tier": "T3", "furigana": "彼[かれ]は新[あたら]しい仕事[しごと]がうまくいくか心配[しんぱい]で、毎晩[まいばん]遅[おそ]くまで資料[しりょう]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "食べ物の値段が上がり続けて、生活費が心配だ。", "target_word": "心配", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]の値段[ねだん]が上[あ]がり続[つづ]けて、生活費[せいかつひ]が心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "最近は、子どもがスマホを使いすぎる心配がある。", "target_word": "心配", "complexity_tier": "T3", "furigana": "最近[さいきん]は、子[こ]どもがスマホを使[つか]いすぎる心配[しんぱい]がある。", "sentence_source": "generated"}, {"text": "医者は「手術は成功したので、もう心配はいりません」と言った。", "target_word": "心配", "complexity_tier": "T3", "furigana": "医者[いしゃ]は「手術[しゅじゅつ]は成功[せいこう]したので、もう心配[しんぱい]はいりません」と言[い]った。", "sentence_source": "generated"}, {"text": "この地域では、大きな地震が起きる心配が強まっている。", "target_word": "心配", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、大[おお]きな地震[じしん]が起[お]きる心配[しんぱい]が強[つよ]まっている。", "sentence_source": "generated"}, {"text": "雪が降ると電車が止まるかもしれないので、明日の出勤が心配だ。", "target_word": "心配", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]ると電車[でんしゃ]が止[と]まるかもしれないので、明日[あした]の出勤[しゅっきん]が心配[しんぱい]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "心配する", "label": "辞書形"}, {"form": "心配して", "label": "て形"}, {"form": "心配した", "label": "過去形"}, {"form": "心配しない", "label": "否定形"}, {"form": "心配です", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "将来の出来事や今の状況について、悪い結果になるのではと予想して不安を感じる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451f182-b416-4156-a958-f234e1ab7309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37171, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心配", "is_correct": true, "explanation": "「作物の被害を心配している」の形。台風による悪い結果を不安に思う文脈に合う。"}, {"text": "安心", "is_correct": false, "explanation": "「被害を安心している」は成り立たない。「安心」は対象を「を」で取れない。"}, {"text": "準備", "is_correct": false, "explanation": "「被害を準備している」は意味が通らない。「準備」は作るものや整えるものに使う。"}, {"text": "掃除", "is_correct": false, "explanation": "「被害を掃除している」は意味が通らない。「掃除」は場所やものを対象にする。"}], "explanations": {"心配": "「作物の被害を心配している」の形。台風による悪い結果を不安に思う文脈に合う。", "安心": "「被害を安心している」は成り立たない。「安心」は対象を「を」で取れない。", "準備": "「被害を準備している」は意味が通らない。「準備」は作るものや整えるものに使う。", "掃除": "「被害を掃除している」は意味が通らない。「掃除」は場所やものを対象にする。"}, "sentence_index": 0, "correct_answer": "心配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試験の結果を先生に心配した。", "explanation": "「心配」は不安の意味で、試験の結果を報告する行為には使えない。"}, {"text": "彼は大会で心配を獲得した。", "explanation": "「心配」は不安の意味で、賞や名誉を得ることは表さない。"}, {"text": "遅れてすみません。心配します。", "explanation": "「心配」は不安の意味で、詫びの言葉としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37171, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心配", "is_correct": true, "explanation": "「心配がある」の形で、悪いことが起きる不安を表す。文脈の「使いすぎる」に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "「スマホを使いすぎる翻訳がある」は意味が通らない。文脈に合わない。"}, {"text": "料理", "is_correct": false, "explanation": "「スマホを使いすぎる料理がある」は意味が通らない。文脈に合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「スマホを使いすぎる散歩がある」は意味が通らない。文脈に合わない。"}], "explanations": {"心配": "「心配がある」の形で、悪いことが起きる不安を表す。文脈の「使いすぎる」に合う。", "翻訳": "「スマホを使いすぎる翻訳がある」は意味が通らない。文脈に合わない。", "料理": "「スマホを使いすぎる料理がある」は意味が通らない。文脈に合わない。", "散歩": "「スマホを使いすぎる散歩がある」は意味が通らない。文脈に合わない。"}, "sentence_index": 6, "correct_answer": "心配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会うたびに、先生に心配の一礼をした。", "explanation": "「心配」は不安の意味で、お辞儀の動作は表さない。"}, {"text": "友達の冗談を聞いて、心配に笑った。", "explanation": "「心配」は不安の意味で、楽しく笑う様子は表さない。"}, {"text": "店で料理の代わりに心配を注文した。", "explanation": "「心配」は不安の意味で、料理などを頼む場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37171, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このまま値上がりが続けば、家計が苦しくなる心配をある。", "corrected_sentence": "このまま値上がりが続けば、家計が苦しくなる心配がある。", "error_description": "「心配がある」の「が」が「を」になっている。「ある」は存在を表す文で、主語に「が」を取るため、正しくは「心配がある」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37171, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもの帰りが遅く、親は心配ている。", "corrected_sentence": "子どもの帰りが遅く、親は心配している。", "error_description": "動詞の活用が誤っている。「心配ている」の「し」が抜けており、正しくは「心配している」（続いている状態）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
