INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37172, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "共に住む相手を示す。「友達と暮らすと」の「と」として自然。"}, {"text": "の", "is_correct": false, "explanation": "所属。「友達の暮らす」は不自然で、一緒に住む意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向。「友達へ暮らす」は一緒に住む相手を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較。「友達より暮らす」は文の意味を成さない。"}], "correct_answer": "と", "explanations": {"と": "共に住む相手を示す。「友達と暮らすと」の「と」として自然。", "の": "所属。「友達の暮らす」は不自然で、一緒に住む意味にならない。", "へ": "方向。「友達へ暮らす」は一緒に住む相手を表せない。", "より": "比較。「友達より暮らす」は文の意味を成さない。"}, "error_tags": {"の": "所属。「友達の暮らす」は不自然で、一緒に住む意味にならない。", "へ": "方向。「友達へ暮らす」は一緒に住む相手を表せない。", "より": "比較。「友達より暮らす」は文の意味を成さない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37172, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人が生活すること。", "primary_collocate": null, "pronunciation": "くらす", "ipa": "kɯɾasɯ", "syllable_count": 3, "sentences": [{"text": "この小さな島の人々は、魚をとって暮らしている。", "target_word": "暮らしている", "complexity_tier": "T3", "furigana": "この小[ちい]さな島[しま]の人々[ひとびと]は、魚[さかな]をとって暮[く]らしている。", "sentence_source": "generated"}, {"text": "私は両親と一緒に暮らしている。", "target_word": "暮らしている", "complexity_tier": "T2", "furigana": "私[わたし]は両親[りょうしん]と一緒[いっしょ]に暮[く]らしている。", "sentence_source": "generated"}, {"text": "祖母は昔、広い農家で大勢の家族と暮らしていた。", "target_word": "暮らしていた", "complexity_tier": "T3", "furigana": "祖母[そぼ]は昔[むかし]、広[ひろ]い農家[のうか]で大勢[おおぜい]の家族[かぞく]と暮[く]らしていた。", "sentence_source": "generated"}, {"text": "年を取ったら、海の見える町で暮らしたい。", "target_word": "暮らしたい", "complexity_tier": "T3", "furigana": "年[とし]を取[と]ったら、海[うみ]の見[み]える町[まち]で暮[く]らしたい。", "sentence_source": "generated"}, {"text": "留学生のリサさんは、日本の家庭で暮らして、言葉を覚えた。", "target_word": "暮らして", "complexity_tier": "T4", "furigana": "留学生[りゅうがくせい]のリサさんは、日本[にほん]の家庭[かてい]で暮[く]らして、言葉[ことば]を覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "毎月の給料だけで暮らすのは、思ったより難しい。", "target_word": "暮らす", "complexity_tier": "T3", "furigana": "毎月[まいつき]の給料[きゅうりょう]だけで暮[く]らすのは、思[おも]ったより難[むずか]しい。", "sentence_source": "generated"}, {"text": "彼らは電気のない山の中で暮らしていた。", "target_word": "暮らしていた", "complexity_tier": "T3", "furigana": "彼[かれ]らは電気[でんき]のない山[やま]の中[なか]で暮[く]らしていた。", "sentence_source": "generated"}, {"text": "友達と暮らすと、家事を分けられるので助かる。", "target_word": "暮らす", "complexity_tier": "T3", "furigana": "友達[ともだち]と暮[く]らすと、家事[かじ]を分[わ]けられるので助[たす]かる。", "sentence_source": "generated"}, {"text": "一人で暮らしていると、病気のときにとても心細い。", "target_word": "暮らしている", "complexity_tier": "T3", "furigana": "一人[ひとり]で暮[く]らしていると、病気[びょうき]のときにとても心細[こころぼそ]い。", "sentence_source": "generated"}, {"text": "彼は定年後、犬と静かに暮らした。", "target_word": "暮らした", "complexity_tier": "T3", "furigana": "彼[かれ]は定年後[ていねんご]、犬[いぬ]と静[しず]かに暮[く]らした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "暮らす", "label": "終止形・連体形"}, {"form": "暮らし", "label": "連用形"}, {"form": "暮らさ", "label": "未然形"}, {"form": "暮らせ", "label": "命令形・仮定形・可能形語幹"}, {"form": "暮らそう", "label": "意志形"}, {"form": "暮らして", "label": "て形"}, {"form": "暮らした", "label": "た形"}], "register": "標準（中立）", "sense_fingerprint": "人が日々の生活を営む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37172, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暮らしている", "is_correct": true, "explanation": "魚をとる暮らしが現在も続いている状態を表し、文に合う。"}, {"text": "暮らし", "is_correct": false, "explanation": "連用形で終えることができず、文が成り立たない。"}, {"text": "暮らさ", "is_correct": false, "explanation": "未然形のみで、文を終える形にならない。"}, {"text": "暮らして", "is_correct": false, "explanation": "て形で終わると文が途切れ、述語として機能しない。"}], "explanations": {"暮らしている": "魚をとる暮らしが現在も続いている状態を表し、文に合う。", "暮らし": "連用形で終えることができず、文が成り立たない。", "暮らさ": "未然形のみで、文を終える形にならない。", "暮らして": "て形で終わると文が途切れ、述語として機能しない。"}, "sentence_index": 0, "correct_answer": "暮らしている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三日間の出張で、市内の旅館で暮らした。", "explanation": "ここは〈滞在する〉の意味。暮らすは生活を続けることで、短い出張の宿泊には使わない。"}, {"text": "毎朝一時間かけて学校で暮らしている。", "explanation": "ここは〈通学する〉の意味。暮らすは住んで生活することで、学校へ通う行為には合わない。"}, {"text": "帰りに市場で暮らした。", "explanation": "ここは〈立ち寄る〉の意味。暮らすは生活の営みで、市場に寄るだけの行動には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37172, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暮らしていた", "is_correct": true, "explanation": "電気のない山での過去の生活を表す形で、文に合う。"}, {"text": "暮らさず", "is_correct": false, "explanation": "否定の連用形で、文を終えられない。"}, {"text": "暮らしつつ", "is_correct": false, "explanation": "〜つつの形で、文の述語にならない。"}, {"text": "暮らしながら", "is_correct": false, "explanation": "〜ながらの形で、文を終える述語にならない。"}], "explanations": {"暮らしていた": "電気のない山での過去の生活を表す形で、文に合う。", "暮らさず": "否定の連用形で、文を終えられない。", "暮らしつつ": "〜つつの形で、文の述語にならない。", "暮らしながら": "〜ながらの形で、文を終える述語にならない。"}, "sentence_index": 6, "correct_answer": "暮らしていた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜は友人の家で暮らした。", "explanation": "ここは〈泊まる〉の意味。暮らすは生活を続けることで、一晩の宿泊には合わない。"}, {"text": "駅前の喫茶店で暮らした。", "explanation": "ここは〈休憩する〉の意味。暮らすは日々の生活を送ることで、一時の休みには使わない。"}, {"text": "週末に城で暮らした。", "explanation": "ここは〈見物する〉の意味。暮らすは住んで生活することで、城を見て回る行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37172, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父と母は三年前から、この町を暮らしている。", "corrected_sentence": "父と母は三年前から、この町で暮らしている。", "error_description": "場所を示す助詞は「で」。「を」は暮らすの目的語にならないので、「この町で暮らしている」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "暮らしている", "is_correct": true, "explanation": "両親と今も一緒に住んでいる状態を表し、文の内容と合う。"}, {"text": "暮らし", "is_correct": false, "explanation": "連用形のままでは文を終えられず、「私は両親と一緒に暮らし。」は成り立たない。"}, {"text": "暮らさない", "is_correct": false, "explanation": "否定形で、一緒に住んでいる事実と逆になる。"}, {"text": "暮らしたい", "is_correct": false, "explanation": "願望の形なので、現在の事実を述べる文に合わない。"}], "correct_form": "暮らしている", "base_form": "暮らす", "form_label": "ている形（継続）", "sentence_index": 1, "explanations": {"暮らしている": "両親と今も一緒に住んでいる状態を表し、文の内容と合う。", "暮らし": "連用形のままでは文を終えられず、「私は両親と一緒に暮らし。」は成り立たない。", "暮らさない": "否定形で、一緒に住んでいる事実と逆になる。", "暮らしたい": "願望の形なので、現在の事実を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37172, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は若いころ、外国で暮らしている。", "corrected_sentence": "母は若いころ、外国で暮らしていた。", "error_description": "「若いころ」は過去の話なので過去形「暮らしていた」にする。「暮らしている」は現在の状態で、時制が合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "暮らす", "is_correct": true, "explanation": "「〜と」の条件節を作る基本形で、文の流れに合う。"}, {"text": "暮らして", "is_correct": false, "explanation": "て形では「〜と」の条件節を作れず、文が成り立たない。"}, {"text": "暮らさ", "is_correct": false, "explanation": "未然形のみで、「友達と暮らさと」と続けると条件節として成り立たない。"}, {"text": "暮らせ", "is_correct": false, "explanation": "命令の形で、条件節を作れない。"}], "correct_form": "暮らす", "base_form": "暮らす", "form_label": "基本形（〜と）", "sentence_index": 7, "explanations": {"暮らす": "「〜と」の条件節を作る基本形で、文の流れに合う。", "暮らして": "て形では「〜と」の条件節を作れず、文が成り立たない。", "暮らさ": "未然形のみで、「友達と暮らさと」と続けると条件節として成り立たない。", "暮らせ": "命令の形で、条件節を作れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37173, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す。「東京で暮らしている」の住む場所として自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語。東京は暮らすの対象ではないので「東京を暮らす」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語。「東京が暮らす」とは言えず、住む人が主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す。暮らすは場所で生活することなので「へ」は合わない。"}], "correct_answer": "で", "explanations": {"で": "場所を示す。「東京で暮らしている」の住む場所として自然。", "を": "目的語。東京は暮らすの対象ではないので「東京を暮らす」は成り立たない。", "が": "主語。「東京が暮らす」とは言えず、住む人が主語になる。", "へ": "方向を表す。暮らすは場所で生活することなので「へ」は合わない。"}, "error_tags": {"を": "目的語。東京は暮らすの対象ではないので「東京を暮らす」は成り立たない。", "が": "主語。「東京が暮らす」とは言えず、住む人が主語になる。", "へ": "方向を表す。暮らすは場所で生活することなので「へ」は合わない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37173, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "状況・場を示す。「少ない中で暮らしていた」の状況として自然。"}, {"text": "から", "is_correct": false, "explanation": "起点。「少ない中から暮らす」は場所を示す意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "相手。中は人ではないので「中と暮らす」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較。「中より暮らす」は文の意味を成さない。"}], "correct_answer": "で", "explanations": {"で": "状況・場を示す。「少ない中で暮らしていた」の状況として自然。", "から": "起点。「少ない中から暮らす」は場所を示す意味にならない。", "と": "相手。中は人ではないので「中と暮らす」は成り立たない。", "より": "比較。「中より暮らす」は文の意味を成さない。"}, "error_tags": {"から": "起点。「少ない中から暮らす」は場所を示す意味にならない。", "と": "相手。中は人ではないので「中と暮らす」は成り立たない。", "より": "比較。「中より暮らす」は文の意味を成さない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37173, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "生活するために、ある場所に住んで、日常を過ごすこと。", "primary_collocate": null, "pronunciation": "くらす", "ipa": "kɯɾasɯ", "syllable_count": 3, "sentences": [{"text": "森の奥深くに佇む、その赤いドアの小さな家は、かつて祖母が一人で暮らしていた場所だ。", "target_word": "暮らしていた", "complexity_tier": "T4", "furigana": "森[もり]の奥深[おくふか]くに佇[たたず]む、その赤[あか]いドアの小[ちい]さな家[いえ]は、かつて祖母[そぼ]が一人[ひとり]で暮[く]らしていた場所[ばしょ]だ。", "sentence_source": "mined"}, {"text": "私は大学を出てから、ずっと東京で暮らしている。", "target_word": "暮らしている", "complexity_tier": "T3", "furigana": "私[わたし]は大学[だいがく]を出[で]てから、ずっと東京[とうきょう]で暮[く]らしている。", "sentence_source": "generated"}, {"text": "祖父は海の近くの町で、静かに暮らしたいと言っている。", "target_word": "暮らしたい", "complexity_tier": "T3", "furigana": "祖父[そふ]は海[うみ]の近[ちか]くの町[まち]で、静[しず]かに暮[く]らしたいと言[い]っている。", "sentence_source": "generated"}, {"text": "彼は三年間、外国で暮らした経験がある。", "target_word": "暮らした", "complexity_tier": "T3", "furigana": "彼[かれ]は三年間[さんねんかん]、外国[がいこく]で暮[く]らした経験[けいけん]がある。", "sentence_source": "generated"}, {"text": "お金が少なくても、家族と楽しく暮らせれば幸せだ。", "target_word": "暮らせれば", "complexity_tier": "T3", "furigana": "お金[かね]が少[すく]なくても、家族[かぞく]と楽[たの]しく暮[く]らせれば幸[しあわ]せだ。", "sentence_source": "generated"}, {"text": "兄は猫と二人で、小さなアパートに暮らしている。", "target_word": "暮らしている", "complexity_tier": "T3", "furigana": "兄[あに]は猫[ねこ]と二人[ふたり]で、小[ちい]さなアパートに暮[く]らしている。", "sentence_source": "generated"}, {"text": "田舎で暮らすと、星がきれいに見えるのがうれしい。", "target_word": "暮らす", "complexity_tier": "T3", "furigana": "田舎[いなか]で暮[く]らすと、星[ほし]がきれいに見[み]えるのがうれしい。", "sentence_source": "generated"}, {"text": "戦争のころ、人々は食べ物が少ない中で暮らしていた。", "target_word": "暮らしていた", "complexity_tier": "T3", "furigana": "戦争[せんそう]のころ、人々[ひとびと]は食[た]べ物[もの]が少[すく]ない中[なか]で暮[く]らしていた。", "sentence_source": "generated"}, {"text": "卒業したら、親から離れて一人で暮らすつもりだ。", "target_word": "暮らす", "complexity_tier": "T3", "furigana": "卒業[そつぎょう]したら、親[おや]から離[はな]れて一人[ひとり]で暮[く]らすつもりだ。", "sentence_source": "generated"}, {"text": "この町で暮らして十年になるが、まだ道に迷うことがある。", "target_word": "暮らして", "complexity_tier": "T4", "furigana": "この町[まち]で暮[く]らして十年[じゅうねん]になるが、まだ道[みち]に迷[まよ]うことがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "暮らす", "label": "終止形・連体形"}, {"form": "暮らし", "label": "連用形"}, {"form": "暮らさ", "label": "未然形"}, {"form": "暮らせ", "label": "命令形・仮定形・可能形語幹"}, {"form": "暮らそう", "label": "意志形"}, {"form": "暮らして", "label": "て形"}, {"form": "暮らした", "label": "た形"}], "register": "標準（中立）", "sense_fingerprint": "ある場所に住んで日々の生活を送る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37173, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暮らしていた", "is_correct": true, "explanation": "「かつて」と合う過去の連体形で、名詞「場所」を修飾できる。"}, {"text": "暮らして", "is_correct": false, "explanation": "て形のままでは名詞「場所」を修飾できず、文が成り立たない。"}, {"text": "暮らさ", "is_correct": false, "explanation": "未然形のみで、名詞を修飾する形にならない。"}, {"text": "暮らそう", "is_correct": false, "explanation": "意志形なので、「場所」を修飾する形にならない。"}], "explanations": {"暮らしていた": "「かつて」と合う過去の連体形で、名詞「場所」を修飾できる。", "暮らして": "て形のままでは名詞「場所」を修飾できず、文が成り立たない。", "暮らさ": "未然形のみで、名詞を修飾する形にならない。", "暮らそう": "意志形なので、「場所」を修飾する形にならない。"}, "sentence_index": 0, "correct_answer": "暮らしていた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨夜は駅前のホテルで暮らした。", "explanation": "ここは〈泊まる〉の意味。暮らすは日々の生活を続けることで、一晩の宿泊には合わない。"}, {"text": "帰りに駅前の本屋で暮らした。", "explanation": "ここは〈立ち寄る〉の意味。暮らすは生活を営むことで、店に寄るだけの短い行動には使わない。"}, {"text": "毎日二時間かけて会社で暮らしている。", "explanation": "ここは〈通勤する〉の意味。暮らすは住んで生活することで、職場へ通う行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37173, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暮らす", "is_correct": true, "explanation": "「田舎で暮らすと」と条件節を作れる基本形で、文の流れに合う。"}, {"text": "暮らし", "is_correct": false, "explanation": "連用形のままでは「田舎で〜と」と続かず、文が成り立たない。"}, {"text": "暮らさず", "is_correct": false, "explanation": "否定の連用形で、条件節を作れない。"}, {"text": "暮らさせ", "is_correct": false, "explanation": "使役の形で、誰かに住まわせる意味になり、この文の内容と合わない。"}], "explanations": {"暮らす": "「田舎で暮らすと」と条件節を作れる基本形で、文の流れに合う。", "暮らし": "連用形のままでは「田舎で〜と」と続かず、文が成り立たない。", "暮らさず": "否定の連用形で、条件節を作れない。", "暮らさせ": "使役の形で、誰かに住まわせる意味になり、この文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "暮らす"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末は京都で暮らした。", "explanation": "ここは〈観光する〉の意味。暮らすは生活を続けることで、週末の数日の観光には使わない。"}, {"text": "昼休みに会議室で暮らした。", "explanation": "ここは〈仮眠する〉の意味。暮らすは日々の生活を送ることで、短い休憩には合わない。"}, {"text": "午後は工場で暮らした。", "explanation": "ここは〈見学する〉の意味。暮らすは住んで生活することで、工場を見て回る行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37173, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は結婚してから、ずっと札幌を暮らしている。", "corrected_sentence": "姉は結婚してから、ずっと札幌で暮らしている。", "error_description": "場所を示す助詞は「で」。「を」は暮らすの目的語にならないので、「札幌で暮らしている」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "暮らしている", "is_correct": true, "explanation": "現在も東京に住み続けている状態を表し、文の内容と合う。"}, {"text": "暮らし", "is_correct": false, "explanation": "連用形のままでは文を終えられず、「ずっと東京で暮らし。」は成り立たない。"}, {"text": "暮らしていない", "is_correct": false, "explanation": "否定形なので、東京で暮らしているという内容と逆になる。"}, {"text": "暮らしたい", "is_correct": false, "explanation": "願望の形なので、現在の事実を述べる文に合わない。"}], "correct_form": "暮らしている", "base_form": "暮らす", "form_label": "ている形（継続）", "sentence_index": 1, "explanations": {"暮らしている": "現在も東京に住み続けている状態を表し、文の内容と合う。", "暮らし": "連用形のままでは文を終えられず、「ずっと東京で暮らし。」は成り立たない。", "暮らしていない": "否定形なので、東京で暮らしているという内容と逆になる。", "暮らしたい": "願望の形なので、現在の事実を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37173, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は三年前から、大阪で暮らさている。", "corrected_sentence": "彼女は三年前から、大阪で暮らしている。", "error_description": "「ている」は連用形の「暮らし」に続く。「暮らさ」は未然形なので誤りで、「暮らしている」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "暮らしていた", "is_correct": true, "explanation": "戦争のころという過去の状況に合う、過去の継続の形。"}, {"text": "暮らさせていた", "is_correct": false, "explanation": "使役の形で、人々が誰かに住まわされた意味になり、文の内容と合わない。"}, {"text": "暮らさなかった", "is_correct": false, "explanation": "否定の過去形で、人々が生活しなかったことになり、文の内容と逆になる。"}, {"text": "暮らしておいた", "is_correct": false, "explanation": "準備や保存の意味になり、人々の生活の状況を説明する文に合わない。"}], "correct_form": "暮らしていた", "base_form": "暮らす", "form_label": "ていた形（過去の継続）", "sentence_index": 7, "explanations": {"暮らしていた": "戦争のころという過去の状況に合う、過去の継続の形。", "暮らさせていた": "使役の形で、人々が誰かに住まわされた意味になり、文の内容と合わない。", "暮らさなかった": "否定の過去形で、人々が生活しなかったことになり、文の内容と逆になる。", "暮らしておいた": "準備や保存の意味になり、人々の生活の状況を説明する文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37174, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「声がする」で、聞こえる音を表します。"}, {"text": "の", "is_correct": false, "explanation": "「声のします」は文として成り立ちません。"}, {"text": "を", "is_correct": false, "explanation": "「声をします」は「する」と合わず文法的に誤りです。"}, {"text": "へ", "is_correct": false, "explanation": "「声へします」は文法的に誤りです。"}], "correct_answer": "が", "explanations": {"が": "「声がする」で、聞こえる音を表します。", "の": "「声のします」は文として成り立ちません。", "を": "「声をします」は「する」と合わず文法的に誤りです。", "へ": "「声へします」は文法的に誤りです。"}, "error_tags": {"の": "genitive", "を": "object_marker", "へ": "direction"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37174, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "声を手段にして歌うので「で」です。"}, {"text": "が", "is_correct": false, "explanation": "「声がうたって」は主語が合わず誤りです。"}, {"text": "へ", "is_correct": false, "explanation": "「声へうたって」は文法的に誤りです。"}, {"text": "まで", "is_correct": false, "explanation": "「声までうたって」は意味が通りません。"}], "correct_answer": "で", "explanations": {"で": "声を手段にして歌うので「で」です。", "が": "「声がうたって」は主語が合わず誤りです。", "へ": "「声へうたって」は文法的に誤りです。", "まで": "「声までうたって」は意味が通りません。"}, "error_tags": {"が": "subject", "へ": "direction", "まで": "limit"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
