INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37175, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が口に出して言うことばや、意見、考えを表したもの。また、動物や物が出す音。", "primary_collocate": null, "pronunciation": "こえ", "ipa": "koe", "syllable_count": 2, "sentences": [{"text": "彼は汗を拭いながら、通行人に丁寧に声をかけていた。", "target_word": "声", "complexity_tier": "T5", "furigana": "彼[かれ]は汗[あせ]を拭[ふ]いながら、通行人[つうこうにん]に丁寧[ていねい]に声[こえ]をかけていた。", "sentence_source": "mined"}, {"text": "彼女の声は小さいです。", "target_word": "声", "complexity_tier": "T2", "furigana": "彼女[かのじょ]の声[こえ]は小[ちい]さいです。", "sentence_source": "generated"}, {"text": "大きな声で話してください。", "target_word": "声", "complexity_tier": "T3", "furigana": "大[おお]きな声[こえ]で話[はな]してください。", "sentence_source": "generated"}, {"text": "外から子どもの声が聞こえる。", "target_word": "声", "complexity_tier": "T3", "furigana": "外[そと]から子[こ]どもの声[こえ]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "鳥の声で、朝早く目が覚めた。", "target_word": "声", "complexity_tier": "T3", "furigana": "鳥[とり]の声[こえ]で、朝早[あさはや]く目[め]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "電話の声がよく聞こえなかった。", "target_word": "声", "complexity_tier": "T3", "furigana": "電話[でんわ]の声[こえ]がよく聞[き]こえなかった。", "sentence_source": "generated"}, {"text": "市民の声を聞いて、町の計画を変えた。", "target_word": "声", "complexity_tier": "T3", "furigana": "市民[しみん]の声[こえ]を聞[き]いて、町[まち]の計画[けいかく]を変[か]えた。", "sentence_source": "generated"}, {"text": "先生に名前を呼ばれて、思わず声が出た。", "target_word": "声", "complexity_tier": "T4", "furigana": "先生[せんせい]に名前[なまえ]を呼[よ]ばれて、思[おも]わず声[こえ]が出[で]た。", "sentence_source": "generated"}, {"text": "声を出さずに、静かに本を読んだ。", "target_word": "声", "complexity_tier": "T3", "furigana": "声[こえ]を出[だ]さずに、静[しず]かに本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "病気で声が出なくなってしまった。", "target_word": "声", "complexity_tier": "T3", "furigana": "病気[びょうき]で声[こえ]が出[で]なくなってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大声", "label": "派生"}, {"form": "歌声", "label": "派生"}, {"form": "声援", "label": "派生"}, {"form": "声優", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人や動物が出す音や人々の意見", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e809459e-112d-418e-b65d-24a3fcd1f3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37175, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "声", "is_correct": true, "explanation": "「こえ」で、聞こえた語と一致する。"}, {"text": "米", "is_correct": false, "explanation": "「こめ」で、最後の音が「え」ではなく「め」。"}, {"text": "恋", "is_correct": false, "explanation": "「こい」で、最後の音が「え」ではなく「い」。"}, {"text": "苔", "is_correct": false, "explanation": "「こけ」で、最後の音が「え」ではなく「け」。"}, {"text": "腰", "is_correct": false, "explanation": "「こし」で、最後の音が「え」ではなく「し」。"}], "explanations": {"声": "「こえ」で、聞こえた語と一致する。", "米": "「こめ」で、最後の音が「え」ではなく「め」。", "恋": "「こい」で、最後の音が「え」ではなく「い」。", "苔": "「こけ」で、最後の音が「え」ではなく「け」。", "腰": "「こし」で、最後の音が「え」ではなく「し」。"}, "sentence_index": null, "correct_answer": "声"}, "level_3": {"options": [{"text": "声", "is_correct": true, "explanation": "「声をかける」で、話しかける意味になる。"}, {"text": "眼鏡", "is_correct": false, "explanation": "「眼鏡をかける」は成り立つが、通行人に丁寧にするという意味が合わない。"}, {"text": "鍵", "is_correct": false, "explanation": "「鍵をかける」は成り立つが、通行人に丁寧にするという意味が合わない。"}, {"text": "保険", "is_correct": false, "explanation": "「保険をかける」は成り立つが、通行人に丁寧にするという意味が合わない。"}], "explanations": {"声": "「声をかける」で、話しかける意味になる。", "眼鏡": "「眼鏡をかける」は成り立つが、通行人に丁寧にするという意味が合わない。", "鍵": "「鍵をかける」は成り立つが、通行人に丁寧にするという意味が合わない。", "保険": "「保険をかける」は成り立つが、通行人に丁寧にするという意味が合わない。"}, "sentence_index": 0, "correct_answer": "声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんに声を食べた。", "explanation": "声は音であって食べ物ではないので、「食べる」の目的語にならない。"}, {"text": "彼女の声は赤くて四角い形をしている。", "explanation": "声は音なので、色や形で表すことはできない。"}, {"text": "かばんの中に声を入れて持ってきた。", "explanation": "声は物ではないので、かばんに入れることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37175, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "声", "is_correct": true, "explanation": "「こえ」で、聞こえた語と一致する。"}, {"text": "琴", "is_correct": false, "explanation": "「こと」で、最後の音が「え」ではなく「と」。"}, {"text": "独楽", "is_correct": false, "explanation": "「こま」で、最後の音が「え」ではなく「ま」。"}, {"text": "鏝", "is_correct": false, "explanation": "「こて」で、最後の音が「え」ではなく「て」。"}, {"text": "冷え", "is_correct": false, "explanation": "「ひえ」で、最初の音が「こ」ではなく「ひ」。"}], "explanations": {"声": "「こえ」で、聞こえた語と一致する。", "琴": "「こと」で、最後の音が「え」ではなく「と」。", "独楽": "「こま」で、最後の音が「え」ではなく「ま」。", "鏝": "「こて」で、最後の音が「え」ではなく「て」。", "冷え": "「ひえ」で、最初の音が「こ」ではなく「ひ」。"}, "sentence_index": null, "correct_answer": "声"}, "level_3": {"options": [{"text": "声", "is_correct": true, "explanation": "市民の意見を聞いて計画を変えたので意味が合う。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、靴は「聞く」ものではないので意味が合わない。"}, {"text": "体重", "is_correct": false, "explanation": "形は合うが、体重を聞いて町の計画を変えるのは意味が合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが、帽子は「聞く」ものではないので意味が合わない。"}], "explanations": {"声": "市民の意見を聞いて計画を変えたので意味が合う。", "靴": "形は合うが、靴は「聞く」ものではないので意味が合わない。", "体重": "形は合うが、体重を聞いて町の計画を変えるのは意味が合わない。", "帽子": "形は合うが、帽子は「聞く」ものではないので意味が合わない。"}, "sentence_index": 6, "correct_answer": "声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "病気で声が走らなくなってしまった。", "explanation": "声は「走る」ものではないので、動詞との組み合わせが合わない。"}, {"text": "病気で声が重くて、持ち上げられなくなった。", "explanation": "声は音なので、重さを持ち上げることはできない。"}, {"text": "病気で声が冷蔵庫に入らなくなってしまった。", "explanation": "声は物ではないので、冷蔵庫に入れることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37175, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "授業中に大きな声に話してはいけない。", "corrected_sentence": "授業中に大きな声で話してはいけない。", "error_description": "話し方の手段を表すので、「声に」ではなく「声で」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37175, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達の声を見て、すぐ誰か分かった。", "corrected_sentence": "友達の声を聞いて、すぐ誰か分かった。", "error_description": "声は「見る」ものではなく「聞く」ものなので、動詞が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37176, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「一人一人が」の「が」。動作の主語を示す格助詞で、文の流れに合う。"}, {"text": "を", "is_correct": false, "explanation": "「一人一人を好きな動物を紙に書いた」は目的語が重なり、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「一人一人へ、好きな動物を紙に書いた」は方向を示す形になり、書く主体を示す文に合わない。"}, {"text": "より", "is_correct": false, "explanation": "「一人一人より、好きな動物を紙に書いた」は比較の形になり、書く主体を示す文として不自然。"}], "correct_answer": "が", "explanations": {"が": "「一人一人が」の「が」。動作の主語を示す格助詞で、文の流れに合う。", "を": "「一人一人を好きな動物を紙に書いた」は目的語が重なり、文として成り立たない。", "へ": "「一人一人へ、好きな動物を紙に書いた」は方向を示す形になり、書く主体を示す文に合わない。", "より": "「一人一人より、好きな動物を紙に書いた」は比較の形になり、書く主体を示す文として不自然。"}, "error_tags": {"を": "object", "へ": "direction", "より": "comparison"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
