INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37176, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "一人一人は、たくさんの人の中の、ひとりひとりのことです。", "primary_collocate": null, "pronunciation": "ひとりひとり", "ipa": "çitoɾiçitoɾi", "syllable_count": 6, "sentences": [{"text": "大きな会場にいる一人一人に、係の人が地図を配った。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "大[おお]きな会場[かいじょう]にいる一人一人[ひとりひとり]に、係[かかり]の人[ひと]が地図[ちず]を配[くば]った。", "sentence_source": "generated"}, {"text": "クラスの一人一人が、好きな動物を紙に書いた。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "クラスの一人一人[ひとりひとり]が、好[す]きな動物[どうぶつ]を紙[かみ]に書[か]いた。", "sentence_source": "generated"}, {"text": "一人一人の顔は違うが、みんな同じ町に住んでいる。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "一人一人[ひとりひとり]の顔[かお]は違[ちが]うが、みんな同[おな]じ町[まち]に住[す]んでいる。", "sentence_source": "generated"}, {"text": "先生は三十人の子ども一人一人と握手をした。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "先生[せんせい]は三十人[さんじゅうにん]の子[こ]ども一人一人[ひとりひとり]と握手[あくしゅ]をした。", "sentence_source": "generated"}, {"text": "選手一人一人にコーチが声をかけた。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "選手[せんしゅ]一人一人[ひとりひとり]にコーチが声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "一人一人の意見を聞いてから、会議を終えた。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "一人一人[ひとりひとり]の意見[いけん]を聞[き]いてから、会議[かいぎ]を終[お]えた。", "sentence_source": "generated"}, {"text": "町の人一人一人に、市長が手紙を書いた。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]一人一人[ひとりひとり]に、市長[しちょう]が手紙[てがみ]を書[か]いた。", "sentence_source": "generated"}, {"text": "参加者一人一人の席に、水が置いてある。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]一人一人[ひとりひとり]の席[せき]に、水[みず]が置[お]いてある。", "sentence_source": "generated"}, {"text": "一人一人が名前を呼ばれて、前に出た。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "一人一人[ひとりひとり]が名前[なまえ]を呼[よ]ばれて、前[まえ]に出[で]た。", "sentence_source": "generated"}, {"text": "駅前を歩く人の一人一人に、それぞれの生活がある。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "駅前[えきまえ]を歩[ある]く人[ひと]の一人一人[ひとりひとり]に、それぞれの生活[せいかつ]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一人一人", "label": "基本形"}], "register": "中立", "sense_fingerprint": "大勢の中から、一人ずつ順に数え上げた個々の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37176, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一人一人", "is_correct": true, "explanation": "「会場にいる一人一人に」の一人一人。会場の中の個々の人を指し、文に合う。"}, {"text": "会場", "is_correct": false, "explanation": "「会場にいる会場に」は言葉が重なり、配る相手を示せない。"}, {"text": "地図", "is_correct": false, "explanation": "「会場にいる地図に」は意味が通らず、配る相手を示す語として合わない。"}, {"text": "配布", "is_correct": false, "explanation": "「会場にいる配布に」は意味が通らず、人を表す語として合わない。"}], "explanations": {"一人一人": "「会場にいる一人一人に」の一人一人。会場の中の個々の人を指し、文に合う。", "会場": "「会場にいる会場に」は言葉が重なり、配る相手を示せない。", "地図": "「会場にいる地図に」は意味が通らず、配る相手を示す語として合わない。", "配布": "「会場にいる配布に」は意味が通らず、人を表す語として合わない。"}, "sentence_index": 0, "correct_answer": "一人一人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は三十冊のノート一人一人に、赤ペンで書き込みをした。", "explanation": "ここは人を指す語。ノートのような物には個々を表す〈一つ一つ〉を使うので、一人一人は合わない。"}, {"text": "先生は一人一人で三十人の子どもを教室へ送った。", "explanation": "ここは〈一人で〉の意味。複数の人を一人ずつ数える一人一人は、単独の行動には使わない。"}, {"text": "先生は三十人の子ども一人一人を、全員まとめて呼び出した。", "explanation": "ここは〈全員〉の意味。個々を数える一人一人と、まとめて呼ぶ全員は意味が矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37176, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一人一人", "is_correct": true, "explanation": "「町の人一人一人に」の一人一人。町の人それぞれを指し、文に合う。"}, {"text": "町", "is_correct": false, "explanation": "「町の人町に」は言葉が重なり、手紙を渡す相手を示せない。"}, {"text": "手紙", "is_correct": false, "explanation": "「町の人手紙に」は意味が通らず、手紙を受け取る相手を示す語として合わない。"}, {"text": "市長", "is_correct": false, "explanation": "「町の人市長に」は意味が通らず、手紙を送る主体と重なって不自然。"}], "explanations": {"一人一人": "「町の人一人一人に」の一人一人。町の人それぞれを指し、文に合う。", "町": "「町の人町に」は言葉が重なり、手紙を渡す相手を示せない。", "手紙": "「町の人手紙に」は意味が通らず、手紙を受け取る相手を示す語として合わない。", "市長": "「町の人市長に」は意味が通らず、手紙を送る主体と重なって不自然。"}, "sentence_index": 6, "correct_answer": "一人一人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅前で一人一人で大きな声を出した。", "explanation": "ここは〈一人で〉の意味。複数の人を一人ずつ数える一人一人は、単独の行動には使わない。"}, {"text": "駅前の一人一人が、一緒に輪になった。", "explanation": "ここは〈一緒に〉の意味。個々を数える一人一人は、まとまって行う動作には使わない。"}, {"text": "駅前の一人一人の店が、夜になっても開いていた。", "explanation": "ここは人を指す語。店のような物には〈一軒一軒〉などを使い、一人一人は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37176, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一人一人を、自分の意見を書いた。", "corrected_sentence": "一人一人が、自分の意見を書いた。", "error_description": "主語を表す「が」が「を」になっている。「一人一人を」は目的語の形になり、「自分の意見を書いた」と続く主語が成り立たなくなる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37176, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一人一人で気持ちを大切にして、話し合った。", "corrected_sentence": "一人一人の気持ちを大切にして、話し合った。", "error_description": "「一人一人の気持ち」が「一人一人で気持ち」になっている。「で」は手段や場所を示すため、個々の人の気持ちを修飾する形として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
