INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37177, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "それぞれの人。すべての人。", "primary_collocate": null, "pronunciation": "ひとりひとり", "ipa": "çitoɾiçitoɾi", "syllable_count": 6, "sentences": [{"text": "今は一人一人の体に合う薬です。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "今[いま]は一人一人[ひとりひとり]の体[からだ]に合[あ]う薬[くすり]です。", "sentence_source": "mined"}, {"text": "先生は生徒一人一人の名前を覚えています。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]一人一人[ひとりひとり]の名前[なまえ]を覚[おぼ]えています。", "sentence_source": "generated"}, {"text": "一人一人が自分の考えを発表した。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "一人一人[ひとりひとり]が自分[じぶん]の考[かんが]えを発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "客の一人一人に、店長が笑顔で挨拶した。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "客[きゃく]の一人一人[ひとりひとり]に、店長[てんちょう]が笑顔[えがお]で挨拶[あいさつ]した。", "sentence_source": "generated"}, {"text": "社員一人一人の努力が会社を支えている。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "社員[しゃいん]一人一人[ひとりひとり]の努力[どりょく]が会社[かいしゃ]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "一人一人の顔を見ながら、先生は話しました。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "一人一人[ひとりひとり]の顔[かお]を見[み]ながら、先生[せんせい]は話[はな]しました。", "sentence_source": "generated"}, {"text": "受付で、来た人一人一人に名札を渡した。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "受付[うけつけ]で、来[き]た人[ひと]一人一人[ひとりひとり]に名札[なふだ]を渡[わた]した。", "sentence_source": "generated"}, {"text": "人の好みは一人一人違うので、全員に同じ料理は出せない。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "人[ひと]の好[この]みは一人一人[ひとりひとり]違[ちが]うので、全員[ぜんいん]に同[おな]じ料理[りょうり]は出[だ]せない。", "sentence_source": "generated"}, {"text": "医者は患者一人一人の話をていねいに聞く。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]一人一人[ひとりひとり]の話[はなし]をていねいに聞[き]く。", "sentence_source": "generated"}, {"text": "一人一人が少しずつ片づければ、教室はすぐきれいになる。", "target_word": "一人一人", "complexity_tier": "T3", "furigana": "一人一人[ひとりひとり]が少[すこ]しずつ片[かた]づければ、教室[きょうしつ]はすぐきれいになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一人一人", "label": "基本形"}], "register": "中立", "sense_fingerprint": "集団の中の各人を一人ずつ取り上げて言う（それぞれの人・全員）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37177, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一人一人", "is_correct": true, "explanation": "「今は一人一人の体に合う薬です」の一人一人。それぞれの人を指し、文の流れに合う。"}, {"text": "名前", "is_correct": false, "explanation": "「名前の体に合う薬」は意味が通らず、体の持ち主を表せない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の体に合う薬」は意味が通らず、人を表す語として合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節の体に合う薬」は意味が通らず、人を表す語として合わない。"}], "explanations": {"一人一人": "「今は一人一人の体に合う薬です」の一人一人。それぞれの人を指し、文の流れに合う。", "名前": "「名前の体に合う薬」は意味が通らず、体の持ち主を表せない。", "天気": "「天気の体に合う薬」は意味が通らず、人を表す語として合わない。", "季節": "「季節の体に合う薬」は意味が通らず、人を表す語として合わない。"}, "sentence_index": 0, "correct_answer": "一人一人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店の一人一人に、値札がついている。", "explanation": "ここは人を指す語。商品には個々を表す〈一つ一つ〉を使うので、一人一人は合わない。"}, {"text": "ベンチを一人一人、ペンキで塗った。", "explanation": "ここは人を指す語。ベンチのような物には〈一つずつ〉を使うので、一人一人は合わない。"}, {"text": "一人一人で店に入り、買い物をした。", "explanation": "ここは〈一人で〉の意味。複数の人を一人ずつ数える一人一人は、単独の行動には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37177, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一人一人", "is_correct": true, "explanation": "「来た人一人一人に名札を渡した」の一人一人。来た人それぞれを指し、文の流れに合う。"}, {"text": "受付", "is_correct": false, "explanation": "「来た人受付に名札を渡した」は意味が通らず、人を表す語として合わない。"}, {"text": "名札", "is_correct": false, "explanation": "「来た人名札に名札を渡した」は意味が通らず、同じ語が重なって不自然。"}, {"text": "来客", "is_correct": false, "explanation": "「来た人来客に名札を渡した」は言葉が重なり、個々の人を表す文として不自然。"}], "explanations": {"一人一人": "「来た人一人一人に名札を渡した」の一人一人。来た人それぞれを指し、文の流れに合う。", "受付": "「来た人受付に名札を渡した」は意味が通らず、人を表す語として合わない。", "名札": "「来た人名札に名札を渡した」は意味が通らず、同じ語が重なって不自然。", "来客": "「来た人来客に名札を渡した」は言葉が重なり、個々の人を表す文として不自然。"}, "sentence_index": 6, "correct_answer": "一人一人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末は一人一人で映画を見た。", "explanation": "ここは〈一人で〉の意味。複数の人を一人ずつ数える一人一人は、単独の行動には使わない。"}, {"text": "駅前の一人一人の柱を、白く塗った。", "explanation": "ここは人を指す語。柱のような物には〈一本一本〉を使い、一人一人は合わない。"}, {"text": "昨日の嵐で、町の一人一人の屋根が飛んだ。", "explanation": "ここは人を指す語。屋根のような建物には〈一軒一軒〉を使い、一人一人は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
