INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37177, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一人一人で子どもが、自分の絵を見せた。", "corrected_sentence": "一人一人の子どもが、自分の絵を見せた。", "error_description": "「一人一人の」が「一人一人で」になっている。「で」は手段や場所を示し、個々の子どもを修飾する形として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37179, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「作りが丈夫だ」の主語を示す「が」。「作りが丈夫で」の形で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「作りを丈夫で」とは言えず、「丈夫だ」の主語は「が」で示すので「を」は不可。"}, {"text": "に", "is_correct": false, "explanation": "「作りに丈夫だ」とは言わず、状態の主語には「に」を使わない。"}, {"text": "で", "is_correct": false, "explanation": "「作りで丈夫だ」は手段の「で」が状態の主語にならず、不自然。"}], "correct_answer": "が", "explanations": {"が": "「作りが丈夫だ」の主語を示す「が」。「作りが丈夫で」の形で正しい。", "を": "「作りを丈夫で」とは言えず、「丈夫だ」の主語は「が」で示すので「を」は不可。", "に": "「作りに丈夫だ」とは言わず、状態の主語には「に」を使わない。", "で": "「作りで丈夫だ」は手段の「で」が状態の主語にならず、不自然。"}, "error_tags": {"が": "主語（正解）", "を": "対象（丁寧だに合わない）", "に": "場所・帰着（不適）", "で": "手段（不適）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37179, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「作りの粗い机」の「の」で、「作り」を机を修飾する連体修飾として結ぶ。"}, {"text": "と", "is_correct": false, "explanation": "「作りと粗い机」のように並べる働きになり、修飾関係が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「作りへ」は方向を表し、机の性質を言う文脈には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「作りから粗い机」は起点を表し、「作り」が机を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "「作りの粗い机」の「の」で、「作り」を机を修飾する連体修飾として結ぶ。", "と": "「作りと粗い机」のように並べる働きになり、修飾関係が崩れる。", "へ": "「作りへ」は方向を表し、机の性質を言う文脈には合わない。", "から": "「作りから粗い机」は起点を表し、「作り」が机を修飾する形にならない。"}, "error_tags": {"の": "連体修飾（正解）", "と": "並列（不適）", "へ": "方向（不適）", "から": "起点（不適）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37179, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物や事柄を新しくつくること。また、その結果できたもの。", "primary_collocate": null, "pronunciation": "つくり", "ipa": "tsɯkɯɾi", "syllable_count": 3, "sentences": [{"text": "この人形は作りが丁寧で、本物の人のように見える。", "target_word": "作り", "complexity_tier": "T3", "furigana": "この人形[にんぎょう]は作[つく]りが丁寧[ていねい]で、本物[ほんもの]の人[ひと]のように見[み]える。", "sentence_source": "generated"}, {"text": "この傘は作りが丈夫で、強い風が吹いても骨が折れない。", "target_word": "作り", "complexity_tier": "T3", "furigana": "このかさはつくりがじょうぶで、つよいかぜがふいてもほねがおれない。", "sentence_source": "generated"}, {"text": "安いおもちゃだが、作りは意外としっかりしている。", "target_word": "作り", "complexity_tier": "T3", "furigana": "安[やす]いおもちゃだが、作[つく]りは意外[いがい]としっかりしている。", "sentence_source": "generated"}, {"text": "木で作った棚だが、作りが素人っぽくて少し傾いている。", "target_word": "作り", "complexity_tier": "T3", "furigana": "木[き]で作[つく]った棚[たな]だが、作[つく]りが素人[しろうと]っぽくて少[すこ]し傾[かたむ]いている。", "sentence_source": "generated"}, {"text": "この料理は作りが丁寧で、味にむらがない。", "target_word": "作り", "complexity_tier": "T3", "furigana": "このりょうりはつくりがていねいで、あじにむらがない。", "sentence_source": "generated"}, {"text": "外国の携帯電話は、日本のものと作りが違う。", "target_word": "作り", "complexity_tier": "T3", "furigana": "外国[がいこく]の携帯電話[けいたいでんわ]は、日本[にほん]のものと作[つく]りが違[ちが]う。", "sentence_source": "generated"}, {"text": "職人の作りは細部まで正確で、誰が見ても感心する。", "target_word": "作り", "complexity_tier": "T3", "furigana": "職人[しょくにん]の作[つく]りは細部[さいぶ]まで正確[せいかく]で、誰[だれ]が見[み]ても感心[かんしん]する。", "sentence_source": "generated"}, {"text": "作りの粗い机なので、引き出しが開けにくい。", "target_word": "作り", "complexity_tier": "T3", "furigana": "作[つく]りの粗[あら]い机[つくえ]なので、引[ひ]き出[だ]しが開[あ]けにくい。", "sentence_source": "generated"}, {"text": "この服は作りが軽く、夏でも涼しく着られる。", "target_word": "作り", "complexity_tier": "T3", "furigana": "この服[ふく]は作[つく]りが軽[かる]く、夏[なつ]でも涼[すず]しく着[き]られる。", "sentence_source": "generated"}, {"text": "新しい橋は作りが頑丈で、大きな台風でも壊れなかった。", "target_word": "作り", "complexity_tier": "T3", "furigana": "新[あたら]しい橋[はし]は作[つく]りが頑丈[がんじょう]で、大[おお]きな台風[たいふう]でも壊[こわ]れなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作り", "label": "基本形"}], "register": "一般", "sense_fingerprint": "新しく作った物の出来や仕上がり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f48066bd-2190-4cb8-bbf1-f08443cd7da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37179, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作り", "is_correct": true, "explanation": "「丁寧で」と合う、出来や仕上がりの様子を表す語。"}, {"text": "大きさ", "is_correct": false, "explanation": "「大きさが丁寧」とは言えず、仕上がりの評価に合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは量の性質で、丁寧さの評価とは結びつかない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは匂いの種類で、人形の仕上がりを述べる文脈では使えない。"}], "explanations": {"作り": "「丁寧で」と合う、出来や仕上がりの様子を表す語。", "大きさ": "「大きさが丁寧」とは言えず、仕上がりの評価に合わない。", "重さ": "重さは量の性質で、丁寧さの評価とは結びつかない。", "香り": "香りは匂いの種類で、人形の仕上がりを述べる文脈では使えない。"}, "sentence_index": 0, "correct_answer": "作り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱は作りが嬉しくて、思わず笑ってしまう。", "explanation": "ここは〈感情〉の意味。物の仕上がりは喜べず、「作り」では表せない。"}, {"text": "このシャツは作りが鮮やかで、洗っても色落ちしない。", "explanation": "ここは〈色〉の意味。「作り」は仕上がりの出来で、色の鮮やかさは言えない。"}, {"text": "この石鹸は作りが爽やかで、洗うと気分がすっきりする。", "explanation": "ここは〈香り〉の意味。「作り」は出来の話で、香りの爽やかさは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37179, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作り", "is_correct": true, "explanation": "「細部まで正確」と合う、仕上がりや造りの様子を表す語。"}, {"text": "値段", "is_correct": false, "explanation": "「細部まで正確」と結びつかず、職人の仕事の質を表さない。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目の要素で、細部の正確さを述べる文脈には合わない。"}, {"text": "音", "is_correct": false, "explanation": "音は聞こえ方の性質で、職人の仕事の正確さとは関係しない。"}], "explanations": {"作り": "「細部まで正確」と合う、仕上がりや造りの様子を表す語。", "値段": "「細部まで正確」と結びつかず、職人の仕事の質を表さない。", "色": "色は見た目の要素で、細部の正確さを述べる文脈には合わない。", "音": "音は聞こえ方の性質で、職人の仕事の正確さとは関係しない。"}, "sentence_index": 6, "correct_answer": "作り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は作りが澄んでいて、歌うと聞き入ってしまう。", "explanation": "ここは〈声〉の意味。「作り」は物の仕上がりを指し、人の声の澄み具合には使えない。"}, {"text": "このギターは作りが眠たそうで、弾いていると眠くなる。", "explanation": "ここは〈人の様子〉の意味。物の仕上がりは眠たそうに見えず、「作り」では表せない。"}, {"text": "このお香は作りが穏やかで、寝る前に焚くのにぴったりだ。", "explanation": "ここは〈香り〉の意味。「作り」は物の造りで、香りの穏やかさは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37179, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この時計は作りを丁寧で、細かい部品までしっかり組まれている。", "corrected_sentence": "この時計は作りが丁寧で、細かい部品までしっかり組まれている。", "error_description": "「作り」の後は「が」。「丁寧だ」の主語を示す助詞が必要で、「を」は対象を表すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37179, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この橋は作りに頑丈で、大雨の日でも渡れた。", "corrected_sentence": "この橋は作りが頑丈で、大雨の日でも渡れた。", "error_description": "「作り」の後は「が」。「頑丈だ」の主語を示すので「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37180, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ネガティブ", "is_correct": true, "explanation": "物事の悪い面や後ろ向きな気持ちを表し、〈いいこと、よい気持ち〉の対義語として類語辞典に載る。"}, {"text": "丁寧", "is_correct": false, "explanation": "礼儀正しく心を配るさまを表し、ポジティブの対義語ではない。"}, {"text": "確実", "is_correct": false, "explanation": "間違いがないさまを表し、前向きさの反対の意味ではない。"}, {"text": "平和", "is_correct": false, "explanation": "争いのない状態を表し、ポジティブとは対義関係にない。"}], "correct_answer": "ネガティブ", "explanations": {"ネガティブ": "物事の悪い面や後ろ向きな気持ちを表し、〈いいこと、よい気持ち〉の対義語として類語辞典に載る。", "丁寧": "礼儀正しく心を配るさまを表し、ポジティブの対義語ではない。", "確実": "間違いがないさまを表し、前向きさの反対の意味ではない。", "平和": "争いのない状態を表し、ポジティブとは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37180, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ネガティブ", "is_correct": true, "explanation": "物事の悪い面や後ろ向きな気持ちを表し、〈いいこと、よい気持ち〉の対義語として類語辞典に載る。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深く行動するさまを表し、ポジティブの対義語ではない。"}, {"text": "簡単", "is_correct": false, "explanation": "容易なさまを表し、ポジティブとは対義関係にない。"}, {"text": "豊富", "is_correct": false, "explanation": "たくさんあるさまを表し、ポジティブの対義語ではない。"}], "correct_answer": "ネガティブ", "explanations": {"ネガティブ": "物事の悪い面や後ろ向きな気持ちを表し、〈いいこと、よい気持ち〉の対義語として類語辞典に載る。", "慎重": "注意深く行動するさまを表し、ポジティブの対義語ではない。", "簡単": "容易なさまを表し、ポジティブとは対義関係にない。", "豊富": "たくさんあるさまを表し、ポジティブの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37180, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "いいこと、よい気持ちのようす。", "primary_collocate": null, "pronunciation": "ぽじてぃぶ", "ipa": "podʑitibɯ", "syllable_count": 4, "sentences": [{"text": "彼女はいつもポジティブで、まわりの人を元気にする。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はいつもポジティブで、まわりの人[ひと]を元気[げんき]にする。", "sentence_source": "generated"}, {"text": "失敗しても、ポジティブに考えればまた挑戦できる。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "失敗[しっぱい]しても、ポジティブに考[かんが]えればまた挑戦[ちょうせん]できる。", "sentence_source": "generated"}, {"text": "テストの結果が悪くて落ちこんだが、友だちのポジティブな言葉で元気が出た。", "target_word": "ポジティブ", "complexity_tier": "T4", "furigana": "テストの結果[けっか]が悪[わる]くて落[お]ちこんだが、友[とも]だちのポジティブな言葉[ことば]で元気[げんき]が出[で]た。", "sentence_source": "generated"}, {"text": "朝から気持ちをポジティブに切りかえて、一日を始めた。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "朝[あさ]から気持[きも]ちをポジティブに切[き]りかえて、一日[いちにち]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "兄はポジティブな性格なので、何があっても笑っている。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "兄[あに]はポジティブな性格[せいかく]なので、何[なに]があっても笑[わら]っている。", "sentence_source": "generated"}, {"text": "雨の日でも、ポジティブな人は「本が読める」と喜ぶ。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]でも、ポジティブな人[ひと]は「本[ほん]が読[よ]める」と喜[よろこ]ぶ。", "sentence_source": "generated"}, {"text": "先生は、ポジティブな気持ちで試験にのぞむようにと言った。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ポジティブな気持[きも]ちで試験[しけん]にのぞむようにと言[い]った。", "sentence_source": "generated"}, {"text": "ネガティブな話ばかりでなく、ポジティブな話もしようよ。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "ネガティブな話[はなし]ばかりでなく、ポジティブな話[はなし]もしようよ。", "sentence_source": "generated"}, {"text": "笑顔で話すと、ポジティブな気分になりやすい。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "笑顔[えがお]で話[はな]すと、ポジティブな気分[きぶん]になりやすい。", "sentence_source": "generated"}, {"text": "弟はとてもポジティブで、負けた試合のあとでも「次は勝つよ」と言った。", "target_word": "ポジティブ", "complexity_tier": "T4", "furigana": "弟[おとうと]はとてもポジティブで、負[ま]けた試合[しあい]のあとでも「次[つぎ]は勝[か]つよ」と言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポジティブだ", "label": "断定形"}, {"form": "ポジティブな", "label": "連体形"}, {"form": "ポジティブに", "label": "連用形"}], "register": "casual", "sense_fingerprint": "物事を明るく前向きに受け止める気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: 落ちこん (Zipf 1.69)','sentence 3 above tier T3: contains vocabulary far above tier T3: 切りかえ (Zipf 1.88)']::text[], 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37180, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポジティブ", "is_correct": true, "explanation": "前向きな人柄を表し、まわりの人を元気にする文脈に合う。"}, {"text": "過激", "is_correct": false, "explanation": "激しく極端なさまを表す語で、人を元気にする人柄の描写には合わない。"}, {"text": "静粛", "is_correct": false, "explanation": "静かで慎み深いさまを表す語で、人を元気にするという後半と噛み合わない。"}, {"text": "安全", "is_correct": false, "explanation": "危険がないさまを表す語で、人柄を描く空欄には意味が合わない。"}], "explanations": {"ポジティブ": "前向きな人柄を表し、まわりの人を元気にする文脈に合う。", "過激": "激しく極端なさまを表す語で、人を元気にする人柄の描写には合わない。", "静粛": "静かで慎み深いさまを表す語で、人を元気にするという後半と噛み合わない。", "安全": "危険がないさまを表す語で、人柄を描く空欄には意味が合わない。"}, "sentence_index": 0, "correct_answer": "ポジティブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の終盤、ポジティブを一点取って逆転した。", "explanation": "ここは〈ポイント（得点）〉の意味。ポジティブは前向きな態度を表す語で、試合の得点の意味は持たないので、この文とは合わない。"}, {"text": "乾電池のポジティブ極に、赤いコードをつないだ。", "explanation": "ここは電気の〈プラス極（正極）〉の意味。ポジティブは前向きな気持ちを表す語で、電極の名前としては使わないので、この文とは合わない。"}, {"text": "教室の壁に、ポジティブを貼った。", "explanation": "ここは〈ポスター（掲示物）〉の意味。ポジティブは前向きな態度を表す語で、紙の掲示物の意味は持たないので、この文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37180, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポジティブ", "is_correct": true, "explanation": "前向きな気持ちで試験に臨むという文脈に合う形容。「な気持ち」の前に入る。"}, {"text": "正確", "is_correct": false, "explanation": "正しく誤りがないさまで、気持ちの様子を表す文脈には合わない。"}, {"text": "極端", "is_correct": false, "explanation": "行きすぎたさまを表し、試験に臨む気持ちの描写とは合わない。"}, {"text": "無謀", "is_correct": false, "explanation": "考えなしで無茶なさまを表し、落ち着いて試験に臨む文脈と噛み合わない。"}], "explanations": {"ポジティブ": "前向きな気持ちで試験に臨むという文脈に合う形容。「な気持ち」の前に入る。", "正確": "正しく誤りがないさまで、気持ちの様子を表す文脈には合わない。", "極端": "行きすぎたさまを表し、試験に臨む気持ちの描写とは合わない。", "無謀": "考えなしで無茶なさまを表し、落ち着いて試験に臨む文脈と噛み合わない。"}, "sentence_index": 6, "correct_answer": "ポジティブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝の空がポジティブで、気持ちがいい。", "explanation": "ここは〈明るい〉の意味。ポジティブは人の気持ちや物事の受け止め方を指すので、空の明るさには使わない。"}, {"text": "この選手はセンターのポジティブを守っている。", "explanation": "ここは〈ポジション（守備位置）〉の意味。ポジティブは前向きな態度を表し、場所や役割の意味は持たない。"}, {"text": "夕方の海はポジティブだった。", "explanation": "ここは〈穏やか〉の意味。ポジティブは海の静けさを表す語ではなく、物事の前向きな受け止め方を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37180, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ミスをしても、ポジティブを考えてみよう。", "corrected_sentence": "ミスをしても、ポジティブに考えてみよう。", "error_description": "誤りは「ポジティブを」の「を」。「考える」を修飾するには様子を表す連用形「ポジティブに」が必要で、格助詞「を」は使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ポジティブ", "is_correct": true, "explanation": "基本形そのもので、語の見出しとして正解。"}, {"text": "ポジティブだ", "is_correct": false, "explanation": "断定の「だ」が付いた形で、文末で言い切るときの形。ここでは合わない。"}, {"text": "ポジティブな", "is_correct": false, "explanation": "連体形で、名詞の前に付く形。この位置には名詞が続かないので合わない。"}, {"text": "ポジティブさ", "is_correct": false, "explanation": "名詞化した形で、様子を表す形容としてはこの位置に続かない。"}], "correct_form": "ポジティブ", "base_form": "ポジティブ", "form_label": "連用形", "sentence_index": 1, "explanations": {"ポジティブ": "基本形そのもので、語の見出しとして正解。", "ポジティブだ": "断定の「だ」が付いた形で、文末で言い切るときの形。ここでは合わない。", "ポジティブな": "連体形で、名詞の前に付く形。この位置には名詞が続かないので合わない。", "ポジティブさ": "名詞化した形で、様子を表す形容としてはこの位置に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37180, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちのポジティブの言葉で、少し元気が出た。", "corrected_sentence": "友だちのポジティブな言葉で、少し元気が出た。", "error_description": "誤りは「ポジティブの」の「の」。形状詞は名詞の前で連体形「な」になるので「ポジティブな言葉」が正しく、格助詞「の」は使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ポジティブ", "is_correct": true, "explanation": "基本形そのもので、語の見出しとして正解。"}, {"text": "ポジティブだった", "is_correct": false, "explanation": "過去の断定の形で、「な」の前に続くこの位置には合わない。"}, {"text": "ポジティブで", "is_correct": false, "explanation": "て形の「で」で、名詞の前に直接続けられない。"}, {"text": "ポジティブに", "is_correct": false, "explanation": "連用形で、動詞を修飾する形。名詞の前には続かない。"}], "correct_form": "ポジティブ", "base_form": "ポジティブ", "form_label": "連体形", "sentence_index": 7, "explanations": {"ポジティブ": "基本形そのもので、語の見出しとして正解。", "ポジティブだった": "過去の断定の形で、「な」の前に続くこの位置には合わない。", "ポジティブで": "て形の「で」で、名詞の前に直接続けられない。", "ポジティブに": "連用形で、動詞を修飾する形。名詞の前には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37181, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ネガティブ", "is_correct": true, "explanation": "物事の悪い面や後ろ向きな結果を表し、〈よい面・前向きな結果〉の対義語として類語辞典に載る。"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫で壊れにくいさまを表し、ポジティブの対義語ではない。"}, {"text": "便利", "is_correct": false, "explanation": "使いやすく役立つさまを表し、ポジティブとは対義関係にない。"}, {"text": "清潔", "is_correct": false, "explanation": "汚れがないさまを表し、ポジティブの対義語ではない。"}], "correct_answer": "ネガティブ", "explanations": {"ネガティブ": "物事の悪い面や後ろ向きな結果を表し、〈よい面・前向きな結果〉の対義語として類語辞典に載る。", "頑丈": "丈夫で壊れにくいさまを表し、ポジティブの対義語ではない。", "便利": "使いやすく役立つさまを表し、ポジティブとは対義関係にない。", "清潔": "汚れがないさまを表し、ポジティブの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
