INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37181, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事のよい面や、前向きな結果を表すこと。", "primary_collocate": null, "pronunciation": "ぽじてぃぶ", "ipa": "podʑitibɯ", "syllable_count": 4, "sentences": [{"text": "新しい制度には、ポジティブな面もたくさんある。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]には、ポジティブな面[めん]もたくさんある。", "sentence_source": "generated"}, {"text": "新商品はポジティブな反応が多く、売り上げも伸びた。", "target_word": "ポジティブ", "complexity_tier": "T4", "furigana": "新商品[しんしょうひん]はポジティブな反応[はんのう]が多[おお]く、売[う]り上[あ]げも伸[の]びた。", "sentence_source": "generated"}, {"text": "在宅勤務は、時間を有効に使えるというポジティブな影響がある。", "target_word": "ポジティブ", "complexity_tier": "T4", "furigana": "在宅勤務[ざいたくきんむ]は、時間[じかん]を有効[ゆうこう]に使[つか]えるというポジティブな影響[えいきょう]がある。", "sentence_source": "generated"}, {"text": "アンケートでは、ポジティブな意見のほうが多かった。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "アンケートでは、ポジティブな意見[いけん]のほうが多[おお]かった。", "sentence_source": "generated"}, {"text": "運動を続けた結果、体にポジティブな変化が表れた。", "target_word": "ポジティブ", "complexity_tier": "T4", "furigana": "運動[うんどう]を続[つづ]けた結果[けっか]、体[からだ]にポジティブな変化[へんか]が表[あらわ]れた。", "sentence_source": "generated"}, {"text": "記事は、町の未来をポジティブにとらえて書かれている。", "target_word": "ポジティブ", "complexity_tier": "T4", "furigana": "記事[きじ]は、町[まち]の未来[みらい]をポジティブにとらえて書[か]かれている。", "sentence_source": "generated"}, {"text": "社長の発表は、会社の成長を示すポジティブな内容だった。", "target_word": "ポジティブ", "complexity_tier": "T4", "furigana": "社長[しゃちょう]の発表[はっぴょう]は、会社[かいしゃ]の成長[せいちょう]を示[しめ]すポジティブな内容[ないよう]だった。", "sentence_source": "generated"}, {"text": "失敗を学びに変えるのは、ポジティブな受け止め方だ。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を学[まな]びに変[か]えるのは、ポジティブな受[う]け止[と]め方[かた]だ。", "sentence_source": "generated"}, {"text": "評価はポジティブなものばかりで、先生も満足していた。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "評価[ひょうか]はポジティブなものばかりで、先生[せんせい]も満足[まんぞく]していた。", "sentence_source": "generated"}, {"text": "景気がよくなり、ポジティブなニュースが続いている。", "target_word": "ポジティブ", "complexity_tier": "T3", "furigana": "景気[けいき]がよくなり、ポジティブなニュースが続[つづ]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポジティブだ", "label": "断定形"}, {"form": "ポジティブな", "label": "連体形"}, {"form": "ポジティブに", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "物事のよい面や前向きな結果を表すさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37181, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポジティブ", "is_correct": true, "explanation": "物事のよい面を表し、「な面もたくさんある」という文脈に合う。"}, {"text": "透明", "is_correct": false, "explanation": "すきとおるさまを表し、制度の面を評価する文脈には合わない。"}, {"text": "神聖", "is_correct": false, "explanation": "尊く冒しがたいさまを表し、制度の利点を述べる文と噛み合わない。"}, {"text": "無敵", "is_correct": false, "explanation": "敵がいないほど強いさまを表し、制度の面の説明としては意味が合わない。"}], "explanations": {"ポジティブ": "物事のよい面を表し、「な面もたくさんある」という文脈に合う。", "透明": "すきとおるさまを表し、制度の面を評価する文脈には合わない。", "神聖": "尊く冒しがたいさまを表し、制度の利点を述べる文と噛み合わない。", "無敵": "敵がいないほど強いさまを表し、制度の面の説明としては意味が合わない。"}, "sentence_index": 0, "correct_answer": "ポジティブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の後半、ポジティブを二点入れて逆転勝ちした。", "explanation": "ここは〈ポイント（得点）〉の意味。ポジティブは前向きな結果やよい面を表す語で、得点の意味は持たないので、この文とは合わない。"}, {"text": "電池のポジティブ側に、赤いコードをつないだ。", "explanation": "ここは電気の〈プラス極（正極）〉の意味。ポジティブは物事のよい面を表す語で、電極の名前としては使わないので、この文とは合わない。"}, {"text": "廊下の掲示板に、ポジティブを三枚貼った。", "explanation": "ここは〈ポスター（掲示物）〉の意味。ポジティブは物事のよい面を表す語で、紙の掲示物の意味は持たないので、この文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37181, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポジティブ", "is_correct": true, "explanation": "会社の成長を示す好ましい内容を表し、「な内容だった」の前に合う。"}, {"text": "神秘的", "is_correct": false, "explanation": "不思議で神秘的なさまを表し、会社の成長を示す発表の内容とは合わない。"}, {"text": "無謀", "is_correct": false, "explanation": "考えなしで無茶なさまを表し、成長を示す発表の内容と噛み合わない。"}, {"text": "陰気", "is_correct": false, "explanation": "暗く沈んださまを表し、成長を示す発表の内容とは合わない。"}], "explanations": {"ポジティブ": "会社の成長を示す好ましい内容を表し、「な内容だった」の前に合う。", "神秘的": "不思議で神秘的なさまを表し、会社の成長を示す発表の内容とは合わない。", "無謀": "考えなしで無茶なさまを表し、成長を示す発表の内容と噛み合わない。", "陰気": "暗く沈んださまを表し、成長を示す発表の内容とは合わない。"}, "sentence_index": 6, "correct_answer": "ポジティブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この選手はセンターのポジティブを守っている。", "explanation": "ここは〈ポジション（守備位置）〉の意味。ポジティブは前向きさを表し、場所や役割の意味は持たない。"}, {"text": "夕方の海はポジティブだった。", "explanation": "ここは〈穏やか〉の意味。ポジティブは海の静けさを表す語ではなく、物事の前向きな受け止め方を指す。"}, {"text": "今日の空はポジティブで、気持ちよく晴れている。", "explanation": "ここは〈明るい〉の意味。ポジティブは人の気持ちや物事の前向きさを指すので、空の明るさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37181, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社員は、その変化をポジティブをとらえた。", "corrected_sentence": "社員は、その変化をポジティブにとらえた。", "error_description": "誤りは「ポジティブを」の「を」。「とらえる」を修飾する様態は連用形「ポジティブに」で表すので、格助詞「を」は使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ポジティブ", "is_correct": true, "explanation": "連体形「ポジティブな」の語幹で、「な反応」の「な」の前に入る形。ここでは名詞「反応」を修飾する形の語幹にあたる。"}, {"text": "ポジティブだ", "is_correct": false, "explanation": "断定形で文を言い切る形。名詞「反応」を直接修飾できないので、この位置には入らない。"}, {"text": "ポジティブで", "is_correct": false, "explanation": "中止や接続の形で、後ろに続けて文をつなぐ。名詞「反応」の前には置けない。"}, {"text": "ポジティブなら", "is_correct": false, "explanation": "条件を表す形で「もし〜ならば」の意味になる。反応の性質を述べる文脈には合わない。"}], "correct_form": "ポジティブ", "base_form": "ポジティブ", "form_label": "連体形", "sentence_index": 1, "explanations": {"ポジティブ": "連体形「ポジティブな」の語幹で、「な反応」の「な」の前に入る形。ここでは名詞「反応」を修飾する形の語幹にあたる。", "ポジティブだ": "断定形で文を言い切る形。名詞「反応」を直接修飾できないので、この位置には入らない。", "ポジティブで": "中止や接続の形で、後ろに続けて文をつなぐ。名詞「反応」の前には置けない。", "ポジティブなら": "条件を表す形で「もし〜ならば」の意味になる。反応の性質を述べる文脈には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37181, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "売り上げが伸び、ポジティブへニュースが続いている。", "corrected_sentence": "売り上げが伸び、ポジティブなニュースが続いている。", "error_description": "誤りは「ポジティブへ」の「へ」。方向の格助詞「へ」は形状詞には付かず、連体形「な」でニュースを修飾するのが正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ポジティブ", "is_correct": true, "explanation": "連体形「ポジティブな」の語幹で、「な受け止め方」の「な」の前に入る形。名詞「受け止め方」を修飾する形の語幹にあたる。"}, {"text": "ポジティブだった", "is_correct": false, "explanation": "過去の断定形で、過去の状態を表す。ここは現在の受け止め方を修飾する位置なので合わない。"}, {"text": "ポジティブだろう", "is_correct": false, "explanation": "推量の形で「〜だろう」と推し量る意味になる。名詞「受け止め方」を修飾する位置には入らない。"}, {"text": "ポジティブそう", "is_correct": false, "explanation": "様態の形で「〜に見える」「〜らしい」の意味になり、受け止め方の性質を断定する文と合わない。"}], "correct_form": "ポジティブ", "base_form": "ポジティブ", "form_label": "連体形", "sentence_index": 7, "explanations": {"ポジティブ": "連体形「ポジティブな」の語幹で、「な受け止め方」の「な」の前に入る形。名詞「受け止め方」を修飾する形の語幹にあたる。", "ポジティブだった": "過去の断定形で、過去の状態を表す。ここは現在の受け止め方を修飾する位置なので合わない。", "ポジティブだろう": "推量の形で「〜だろう」と推し量る意味になる。名詞「受け止め方」を修飾する位置には入らない。", "ポジティブそう": "様態の形で「〜に見える」「〜らしい」の意味になり、受け止め方の性質を断定する文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
