INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37182, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "だんだんと、もっとそうなること。", "primary_collocate": null, "pronunciation": "ますます", "ipa": "masɯmasɯ", "syllable_count": 4, "sentences": [{"text": "秋が深まり、朝晩は益々寒くなってきた。", "target_word": "益々", "complexity_tier": "T3", "furigana": "秋[あき]が深[ふか]まり、朝晩[あさばん]は益々[ますます]寒[さむ]くなってきた。", "sentence_source": "generated"}, {"text": "練習を続けるうちに、ピアノが益々好きになった。", "target_word": "益々", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を続[つづ]けるうちに、ピアノが益々[ますます]好[す]きになった。", "sentence_source": "generated"}, {"text": "雨は弱まるどころか、益々強くなってきた。", "target_word": "益々", "complexity_tier": "T3", "furigana": "雨[あめ]は弱[よわ]まるどころか、益々[ますます]強[つよ]くなってきた。", "sentence_source": "generated"}, {"text": "彼の店は評判がよく、客が益々多くなっている。", "target_word": "益々", "complexity_tier": "T3", "furigana": "彼[かれ]の店[みせ]は評判[ひょうばん]がよく、客[きゃく]が益々[ますます]多[おお]くなっている。", "sentence_source": "generated"}, {"text": "日本語は勉強すればするほど、益々おもしろくなる。", "target_word": "益々", "complexity_tier": "T3", "furigana": "日本語[にほんご]は勉強[べんきょう]すればするほど、益々[ますます]おもしろくなる。", "sentence_source": "generated"}, {"text": "日が暮れて、山道は益々暗くなった。", "target_word": "益々", "complexity_tier": "T3", "furigana": "日[ひ]が暮[く]れて、山道[やまみち]は益々[ますます]暗[くら]くなった。", "sentence_source": "generated"}, {"text": "薬を飲んだのに、頭の痛みは益々ひどくなった。", "target_word": "益々", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだのに、頭[あたま]の痛[いた]みは益々[ますます]ひどくなった。", "sentence_source": "generated"}, {"text": "春が近づくにつれて、公園の人が益々増えてきた。", "target_word": "益々", "complexity_tier": "T3", "furigana": "春[はる]が近[ちか]づくにつれて、公園[こうえん]の人[ひと]が益々[ますます]増[ふ]えてきた。", "sentence_source": "generated"}, {"text": "説明を聞くほど、問題が益々わからなくなった。", "target_word": "益々", "complexity_tier": "T3", "furigana": "説明[せつめい]を聞[き]くほど、問題[もんだい]が益々[ますます]わからなくなった。", "sentence_source": "generated"}, {"text": "姉は仕事が忙しくて、最近は益々やせてきた。", "target_word": "益々", "complexity_tier": "T3", "furigana": "姉[あね]は仕事[しごと]が忙[いそが]しくて、最近[さいきん]は益々[ますます]やせてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "益々", "label": "基本形（活用しない）"}], "register": "neutral", "sense_fingerprint": "状態や気持ちが、前よりもだんだん強く、大きくなっていくさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451f182-b416-4156-a958-f234e1ab7309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37182, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "益々", "is_correct": true, "explanation": "「朝晩は益々寒くなってきた」の形。だんだん寒さが強まる様子を表す。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "「寒くなってきた」とは続かない。「ぐっすり」は眠りの深さを表す副詞。"}, {"text": "きちんと", "is_correct": false, "explanation": "「寒くなってきた」とは続かない。「きちんと」は整っている様子を表す副詞。"}, {"text": "大声で", "is_correct": false, "explanation": "「大声で寒くなってきた」は意味が通らない。「大声で」は声の大きさを表す。"}], "explanations": {"益々": "「朝晩は益々寒くなってきた」の形。だんだん寒さが強まる様子を表す。", "ぐっすり": "「寒くなってきた」とは続かない。「ぐっすり」は眠りの深さを表す副詞。", "きちんと": "「寒くなってきた」とは続かない。「きちんと」は整っている様子を表す副詞。", "大声で": "「大声で寒くなってきた」は意味が通らない。「大声で」は声の大きさを表す。"}, "sentence_index": 0, "correct_answer": "益々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その店は昨日、益々開店した。", "explanation": "「益々」は少しずつ程度が進む意味で、一度きりの開店には合わない。"}, {"text": "山道を登り続けて、益々頂上に着いた。", "explanation": "「益々」は程度が一層進む意味で、到達した瞬間の動作には合わない。"}, {"text": "電話を益々一度だけかけた。", "explanation": "「益々」は程度が進む意味で、一度きりの動作とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37182, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "益々", "is_correct": true, "explanation": "「頭の痛みは益々ひどくなった」の形。程度が一層進んだことを表す。"}, {"text": "一人で", "is_correct": false, "explanation": "「頭の痛みは一人でひどくなった」は意味が通らない。「一人で」は行動の主体を表す。"}, {"text": "丁寧に", "is_correct": false, "explanation": "「丁寧にひどくなった」は意味が通らない。「丁寧に」は行動のしかたを表す。"}, {"text": "こっそり", "is_correct": false, "explanation": "「こっそりひどくなった」は意味が通らない。「こっそり」は人目を避けた行動を表す。"}], "explanations": {"益々": "「頭の痛みは益々ひどくなった」の形。程度が一層進んだことを表す。", "一人で": "「頭の痛みは一人でひどくなった」は意味が通らない。「一人で」は行動の主体を表す。", "丁寧に": "「丁寧にひどくなった」は意味が通らない。「丁寧に」は行動のしかたを表す。", "こっそり": "「こっそりひどくなった」は意味が通らない。「こっそり」は人目を避けた行動を表す。"}, "sentence_index": 6, "correct_answer": "益々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "帰り道で、昔の友人に益々一度だけ会った。", "explanation": "「益々」は程度が進む意味で、一度きりの出会いとは合わない。"}, {"text": "店員は客の質問に益々答えた。", "explanation": "「益々」は程度が進む意味で、答え方の丁寧さは表さない。"}, {"text": "寄り道もせず、益々家に帰った。", "explanation": "「益々」は程度が進む意味で、一直線に進む様子は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37182, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の緊張は益々の高まった。", "corrected_sentence": "彼女の緊張は益々高まった。", "error_description": "「益々」の直後に「の」を入れたのが誤り。「益々の」は名詞を修飾する形（益々の発展）で、ここでは動詞「高まった」を続けられない。正しくは「益々高まった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37182, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客が益々増えてきない。", "corrected_sentence": "客が益々増えてきた。", "error_description": "動詞の活用が誤っている。「増えてきない」は活用形として成り立たず、過去形の「増えてきた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
