INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37183, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "物事の程度が一層進むさま。時間が経つにつれて、いっそう強くなること。", "primary_collocate": null, "pronunciation": "ますます", "ipa": "masɯmasɯ", "syllable_count": 4, "sentences": [{"text": "技術の進歩によって、機械の性能は益々高まっている。", "target_word": "益々", "complexity_tier": "T3", "furigana": "技術[ぎじゅつ]の進歩[しんぽ]によって、機械[きかい]の性能[せいのう]は益々[ますます]高[たか]まっている。", "sentence_source": "generated"}, {"text": "時代が変わり、人々の健康への関心は益々強くなっている。", "target_word": "益々", "complexity_tier": "T3", "furigana": "時代[じだい]が変[か]わり、人々[ひとびと]の健康[けんこう]への関心[かんしん]は益々[ますます]強[つよ]くなっている。", "sentence_source": "generated"}, {"text": "少子化が進み、この町の学校は益々少なくなるだろう。", "target_word": "益々", "complexity_tier": "T3", "furigana": "少子化[しょうしか]が進[すす]み、この町[まち]の学校[がっこう]は益々[ますます]少[すく]なくなるだろう。", "sentence_source": "generated"}, {"text": "外国との交流が増え、英語の力が益々必要になってきた。", "target_word": "益々", "complexity_tier": "T3", "furigana": "外国[がいこく]との交流[こうりゅう]が増[ふ]え、英語[えいご]の力[ちから]が益々[ますます]必要[ひつよう]になってきた。", "sentence_source": "generated"}, {"text": "年を重ねるごとに、祖父の話は益々味わい深くなる。", "target_word": "益々", "complexity_tier": "T3", "furigana": "年[とし]を重[かさ]ねるごとに、祖父[そふ]の話[はなし]は益々[ますます]味[あじ]わい深[ぶか]くなる。", "sentence_source": "generated"}, {"text": "物価が上がり、家計の苦しさは益々増している。", "target_word": "益々", "complexity_tier": "T3", "furigana": "物価[ぶっか]が上[あ]がり、家計[かけい]の苦[くる]しさは益々[ますます]増[ま]している。", "sentence_source": "generated"}, {"text": "彼の努力が認められ、チームでの信頼は益々厚くなった。", "target_word": "益々", "complexity_tier": "T3", "furigana": "彼[かれ]の努力[どりょく]が認[みと]められ、チームでの信頼[しんらい]は益々[ますます]厚[あつ]くなった。", "sentence_source": "generated"}, {"text": "運動を続けた結果、体力が益々ついてきた。", "target_word": "益々", "complexity_tier": "T3", "furigana": "運動[うんどう]を続[つづ]けた結果[けっか]、体力[たいりょく]が益々[ますます]ついてきた。", "sentence_source": "generated"}, {"text": "国際的な競争が激しくなり、企業の負担は益々大きくなっている。", "target_word": "益々", "complexity_tier": "T3", "furigana": "国際[こくさい]的[てき]な競争[きょうそう]が激[はげ]しくなり、企業[きぎょう]の負担[ふたん]は益々[ますます]大[おお]きくなっている。", "sentence_source": "generated"}, {"text": "環境問題への注目は、これからも益々高まるだろう。", "target_word": "益々", "complexity_tier": "T3", "furigana": "環境[かんきょう]問題[もんだい]への注目[ちゅうもく]は、これからも益々[ますます]高[たか]まるだろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "益々", "label": "基本形（活用しない）"}], "register": "neutral", "sense_fingerprint": "社会の動きや物事の程度が、時間とともに一層進んで強まっていくさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451f182-b416-4156-a958-f234e1ab7309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37183, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "益々", "is_correct": true, "explanation": "「機械の性能は益々高まっている」の形。技術の進歩により程度が一層進むことを表す。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "「性能はぐっすり高まっている」は意味が通らない。「ぐっすり」は眠りの深さを表す。"}, {"text": "きちんと", "is_correct": false, "explanation": "「きちんと高まっている」は文脈に合わない。「きちんと」は整っている様子を表す。"}, {"text": "大声で", "is_correct": false, "explanation": "「大声で高まっている」は意味が通らない。「大声で」は声の大きさを表す。"}], "explanations": {"益々": "「機械の性能は益々高まっている」の形。技術の進歩により程度が一層進むことを表す。", "ぐっすり": "「性能はぐっすり高まっている」は意味が通らない。「ぐっすり」は眠りの深さを表す。", "きちんと": "「きちんと高まっている」は文脈に合わない。「きちんと」は整っている様子を表す。", "大声で": "「大声で高まっている」は意味が通らない。「大声で」は声の大きさを表す。"}, "sentence_index": 0, "correct_answer": "益々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警報が鳴ったので、人々は益々一度に避難した。", "explanation": "「益々」は程度が進む意味で、一斉に行う様子とは合わない。"}, {"text": "会議の最初に、益々自己紹介をした。", "explanation": "「益々」は程度が進む意味で、順序の最初を表す語ではない。"}, {"text": "彼は許可を取らず、益々帰った。", "explanation": "「益々」は程度が進む意味で、無断で行動する様子は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37183, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "益々", "is_correct": true, "explanation": "「チームでの信頼は益々厚くなった」の形。努力の積み重ねで程度が一層進んだことを表す。"}, {"text": "一人で", "is_correct": false, "explanation": "「信頼は一人で厚くなった」は意味が通らない。「一人で」は行動の主体を表す。"}, {"text": "丁寧に", "is_correct": false, "explanation": "「信頼は丁寧に厚くなった」は意味が通らない。「丁寧に」は行動のしかたを表す。"}, {"text": "こっそり", "is_correct": false, "explanation": "「信頼はこっそり厚くなった」は意味が通らない。「こっそり」は人目を避けた行動を表す。"}], "explanations": {"益々": "「チームでの信頼は益々厚くなった」の形。努力の積み重ねで程度が一層進んだことを表す。", "一人で": "「信頼は一人で厚くなった」は意味が通らない。「一人で」は行動の主体を表す。", "丁寧に": "「信頼は丁寧に厚くなった」は意味が通らない。「丁寧に」は行動のしかたを表す。", "こっそり": "「信頼はこっそり厚くなった」は意味が通らない。「こっそり」は人目を避けた行動を表す。"}, "sentence_index": 6, "correct_answer": "益々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全員が益々無事に帰宅した。", "explanation": "「益々」は程度が進む意味で、安全に終わったことは表さない。"}, {"text": "大量の荷物を益々一度に運んだ。", "explanation": "「益々」は程度が進む意味で、一度に全部行う様子は表さない。"}, {"text": "帰り道で、益々偶然友人に会った。", "explanation": "「益々」は程度が進む意味で、思いがけない出会いは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37183, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人々の関心は益々の深まっていく。", "corrected_sentence": "人々の関心は益々深まっていく。", "error_description": "「益々」の直後に「の」を入れたのが誤り。「益々の」は名詞を修飾する形（益々の発展）で、ここでは動詞「深まっていく」を続けられない。正しくは「益々深まっていく」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37183, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "景気は益々悪くなっているた。", "corrected_sentence": "景気は益々悪くなっている。", "error_description": "動詞の活用が誤っている。「なっているた」は成り立たず、「なっている」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37184, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "テーマを主題として述べる「は」。「〜は、…と思う」の形に合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、「テーマへ、…と思う」は文として続かない。"}, {"text": "に", "is_correct": false, "explanation": "位置や対象を示す「に」で、テーマを主題として述べる文には合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」で、この主題文には合わない。"}], "correct_answer": "は", "explanations": {"は": "テーマを主題として述べる「は」。「〜は、…と思う」の形に合う。", "へ": "方向を示す「へ」で、「テーマへ、…と思う」は文として続かない。", "に": "位置や対象を示す「に」で、テーマを主題として述べる文には合わない。", "で": "手段や場所を示す「で」で、この主題文には合わない。"}, "error_tags": {"に": "位置・対象", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37184, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "テーマを主語として「がはっきりしている」と続ける「が」。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」で、「テーマから、はっきりしていて」は文として続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、「テーマへ、はっきりしていて」は文意が合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、後ろに名詞が続かないと「テーマの、はっきりしていて」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "テーマを主語として「がはっきりしている」と続ける「が」。", "から": "起点を示す「から」で、「テーマから、はっきりしていて」は文として続かない。", "へ": "方向を示す「へ」で、「テーマへ、はっきりしていて」は文意が合わない。", "の": "連体修飾の「の」で、後ろに名詞が続かないと「テーマの、はっきりしていて」は成り立たない。"}, "error_tags": {"から": "起点", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37184, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お話の中心になること", "primary_collocate": null, "pronunciation": "てーま", "ipa": "teːma", "syllable_count": 3, "sentences": [{"text": "今日の作文のテーマは「夏休み」だ。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "今日[きょう]の作文[さくぶん]のテーマは「夏休[なつやす]み」だ。", "sentence_source": "generated"}, {"text": "この映画のテーマは、家族の大切さだと思う。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "この映画[えいが]のテーマは、家族[かぞく]の大切[たいせつ]さだと思[おも]う。", "sentence_source": "generated"}, {"text": "発表のテーマを決めるのに、三日もかかった。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "発表[はっぴょう]のテーマを決[き]めるのに、三日[みっか]もかかった。", "sentence_source": "generated"}, {"text": "先生は、話のテーマからずれないように注意した。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、話[はなし]のテーマからずれないように注意[ちゅうい]した。", "sentence_source": "generated"}, {"text": "この小説のテーマは、戦争の中で人が何を選ぶかだと思う。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]のテーマ[てーま]は、戦争[せんそう]の中[なか]で人[ひと]が何[なに]を選[えら]ぶかだと思[おも]う。", "sentence_source": "generated"}, {"text": "その歌のテーマは、別れの悲しさだ。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "その歌[うた]のテーマは、別[わか]れの悲[かな]しさだ。", "sentence_source": "generated"}, {"text": "絵のテーマが決まらなくて、まだ描き始められない。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "絵[え]のテーマが決[き]まらなくて、まだ描[か]き始[はじ]められない。", "sentence_source": "generated"}, {"text": "彼の話はテーマがはっきりしていて、わかりやすい。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]はテーマがはっきりしていて、わかりやすい。", "sentence_source": "generated"}, {"text": "今週のクラスのテーマは「食べ物」です。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "今週[こんしゅう]のクラスのテーマは「食[た]べ物[もの]」です。", "sentence_source": "generated"}, {"text": "この物語のテーマは、友情だと先生が教えてくれた。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "この物語[ものがたり]のテーマは、友情[ゆうじょう]だと先生[せんせい]が教[おし]えてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テーマ", "label": "基本形"}, {"form": "テーマは", "label": "は形"}, {"form": "テーマが", "label": "が形"}], "register": "neutral", "sense_fingerprint": "作文・映画・歌・パーティーなどで、中心になる題材や考え", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aebd181-359a-45dc-80f8-127f2fbef7ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37184, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テーマ", "is_correct": true, "explanation": "作文の中心の題材を表す「テーマ」。「今日の作文の〜は『夏休み』だ」に合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "筆記具の名前で、作文の題材を表さないので「〜は『夏休み』だ」と続かない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "文房具で、作文の題材を指さないため文意が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天候の意味で、作文の題材の意味にならないので合わない。"}], "explanations": {"テーマ": "作文の中心の題材を表す「テーマ」。「今日の作文の〜は『夏休み』だ」に合う。", "鉛筆": "筆記具の名前で、作文の題材を表さないので「〜は『夏休み』だ」と続かない。", "消しゴム": "文房具で、作文の題材を指さないため文意が成り立たない。", "天気": "天候の意味で、作文の題材の意味にならないので合わない。"}, "sentence_index": 0, "correct_answer": "テーマ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この荷物は、テーマが五キロもある。", "explanation": "ここは〈重さ〉の意味。テーマは作品や研究の主題を指す語で、物の重さを表さないので合わない。"}, {"text": "絵の右下に、テーマを入れた。", "explanation": "ここは〈サイン〉の意味。テーマは考えや題材で、絵の隅に書き入れるものではないので合わない。"}, {"text": "会議に遅れた理由を、テーマで先生に説明した。", "explanation": "ここは〈手段〉の意味。テーマは主題を指す語で、説明の手段として使う言葉ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37184, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テーマ", "is_correct": true, "explanation": "絵で描く中心の題材を表す「テーマ」。「絵の〜が決まらない」に合う。"}, {"text": "雨", "is_correct": false, "explanation": "天候の名前で、絵の題材の決定を表す文には合わないので不自然。"}, {"text": "時刻", "is_correct": false, "explanation": "時の位置を表す語で、絵の題材が決まらない文には合わない。"}, {"text": "音", "is_correct": false, "explanation": "聞こえるものを指す語で、絵の題材の決定という文意に合わない。"}], "explanations": {"テーマ": "絵で描く中心の題材を表す「テーマ」。「絵の〜が決まらない」に合う。", "雨": "天候の名前で、絵の題材の決定を表す文には合わないので不自然。", "時刻": "時の位置を表す語で、絵の題材が決まらない文には合わない。", "音": "聞こえるものを指す語で、絵の題材の決定という文意に合わない。"}, "sentence_index": 6, "correct_answer": "テーマ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しいテーマを買うために、店へ行った。", "explanation": "ここは〈買う対象〉の意味。テーマは主題を表す語で、買い物の対象にはならないので合わない。"}, {"text": "その本は、テーマが千円だった。", "explanation": "ここは〈値段〉の意味。テーマは主題を表す語で、金額を示す語ではないので合わない。"}, {"text": "彼の話を聞いて、テーマが悔しくなった。", "explanation": "ここは〈気持ち〉の意味。テーマは感情を抱く主体ではないので、『悔しくなる』とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37184, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日の授業のテーマを「海」だ。", "corrected_sentence": "今日の授業のテーマは「海」だ。", "error_description": "テーマに続くのは主題を示す「は」が正しい。「を」は目的語を示すので、「〜だ」の文には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37184, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私の絵のテーマを決まらなくて、困っている。", "corrected_sentence": "私の絵のテーマが決まらなくて、困っている。", "error_description": "「決まる」は自動詞なので、テーマには主語を示す「が」が正しい。「を」は他動詞の目的語に付くため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37185, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "テーマを主題として「は、…についてだ」と述べる「は」。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」で、「テーマを、…についてだ」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置や対象の「に」で、「テーマに、…についてだ」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」で、この主題文には合わない。"}], "correct_answer": "は", "explanations": {"は": "テーマを主題として「は、…についてだ」と述べる「は」。", "を": "目的語の「を」で、「テーマを、…についてだ」では文が成り立たない。", "に": "位置や対象の「に」で、「テーマに、…についてだ」は不自然。", "で": "手段や場所の「で」で、この主題文には合わない。"}, "error_tags": {"を": "目的語", "に": "位置・対象", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37185, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "テーマを主語として「が広すぎて」と続ける「が」。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」で、「テーマから広すぎて」は文意が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、「テーマへ広すぎて」は文として続かない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、後ろに名詞がないと「テーマの広すぎて」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "テーマを主語として「が広すぎて」と続ける「が」。", "から": "起点を示す「から」で、「テーマから広すぎて」は文意が合わない。", "へ": "方向を示す「へ」で、「テーマへ広すぎて」は文として続かない。", "の": "連体修飾の「の」で、後ろに名詞がないと「テーマの広すぎて」は成り立たない。"}, "error_tags": {"から": "起点", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37185, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "議論や研究の中心となる主題。話題。", "primary_collocate": null, "pronunciation": "てーま", "ipa": "teːma", "syllable_count": 3, "sentences": [{"text": "卒業論文のテーマに、都市の交通問題を選んだ。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "卒業[そつぎょう]論文[ろんぶん]のテーマに、都市[とし]の交通[こうつう]問題[もんだい]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "今日の会議のテーマは、来年の予算についてだ。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "今日[きょう]の会議[かいぎ]のテーマは、来年[らいねん]の予算[よさん]についてだ。", "sentence_source": "generated"}, {"text": "研究のテーマを絞らないと、時間が足りなくなる。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "研究[けんきゅう]のテーマを絞[しぼ]らないと、時間[じかん]が足[た]りなくなる。", "sentence_source": "generated"}, {"text": "討論会では、環境問題がメインのテーマになった。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "討論会[とうろんかい]では、環境[かんきょう]問題[もんだい]がメインのテーマになった。", "sentence_source": "generated"}, {"text": "学会で、彼女は新しいテーマの研究を発表した。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "学会[がっかい]で、彼女[かのじょ]は新[あたら]しいテーマの研究[けんきゅう]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "教授は、学生に自由にテーマを選ばせた。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "教授[きょうじゅ]は、学生[がくせい]に自由[じゆう]にテーマを選[えら]ばせた。", "sentence_source": "generated"}, {"text": "高齢化は、この講演会の中心的なテーマだ。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "高齢化[こうれいか]は、この講演会[こうえんかい]の中心的[ちゅうしんてき]なテーマだ。", "sentence_source": "generated"}, {"text": "議論のテーマが広すぎて、結論が出なかった。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "議論[ぎろん]のテーマが広[ひろ]すぎて、結論[けつろん]が出[で]なかった。", "sentence_source": "generated"}, {"text": "同じテーマで研究している人と、意見を交換した。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "同[おな]じテーマで研究[けんきゅう]している人[ひと]と、意見[いけん]を交換[こうかん]した。", "sentence_source": "generated"}, {"text": "来月のセミナーのテーマは、人工知能の利用だ。", "target_word": "テーマ", "complexity_tier": "T3", "furigana": "来月[らいげつ]のセミナーのテーマは、人工[じんこう]知能[ちのう]の利用[りよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テーマ", "label": "基本形"}, {"form": "テーマを", "label": "を形"}, {"form": "テーマに", "label": "に形"}], "register": "neutral", "sense_fingerprint": "会議・討論・論文・研究などで取り上げる中心の主題", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aebd181-359a-45dc-80f8-127f2fbef7ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37185, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テーマ", "is_correct": true, "explanation": "論文の中心の主題を表す「テーマ」。「卒業論文の〜に選んだ」に合う。"}, {"text": "表紙", "is_correct": false, "explanation": "論文の表面を指す語で、主題を選ぶという文には合わない。"}, {"text": "図書館", "is_correct": false, "explanation": "施設の名前で、論文の主題を選ぶ文の対象にならない。"}, {"text": "締切", "is_correct": false, "explanation": "期限を表す語で、主題を選ぶ文には合わない。"}], "explanations": {"テーマ": "論文の中心の主題を表す「テーマ」。「卒業論文の〜に選んだ」に合う。", "表紙": "論文の表面を指す語で、主題を選ぶという文には合わない。", "図書館": "施設の名前で、論文の主題を選ぶ文の対象にならない。", "締切": "期限を表す語で、主題を選ぶ文には合わない。"}, "sentence_index": 0, "correct_answer": "テーマ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "論文の最後に、テーマを押印した。", "explanation": "ここは〈印鑑〉の意味。テーマは主題のことで、印を押すものではないので合わない。"}, {"text": "この研究機器は、テーマが三十万円だった。", "explanation": "ここは〈値段〉の意味。テーマは金額を表さないので、『三十万円』とは結びつかない。"}, {"text": "事務所のドアを、テーマで開けた。", "explanation": "ここは〈鍵〉の意味。ドアを開ける道具は鍵で、テーマは主題を指す語なので道具にはならず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37185, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テーマ", "is_correct": true, "explanation": "講演会の中心の主題を表す「テーマ」。「中心的な〜だ」に合う。"}, {"text": "会場", "is_correct": false, "explanation": "催しを行う場所で、中心の主題を表す語ではないので「中心的な会場だ」は不自然。"}, {"text": "受付", "is_correct": false, "explanation": "手続きの場所で、講演の中心となるものを表さないので合わない。"}, {"text": "時間", "is_correct": false, "explanation": "時の長さを表す語で、講演の中心の内容を示さないので合わない。"}], "explanations": {"テーマ": "講演会の中心の主題を表す「テーマ」。「中心的な〜だ」に合う。", "会場": "催しを行う場所で、中心の主題を表す語ではないので「中心的な会場だ」は不自然。", "受付": "手続きの場所で、講演の中心となるものを表さないので合わない。", "時間": "時の長さを表す語で、講演の中心の内容を示さないので合わない。"}, "sentence_index": 6, "correct_answer": "テーマ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この研究のテーマは、リーダーの田中先生だ。", "explanation": "ここは〈責任者〉の意味。テーマは研究の主題で、人を指す語ではないので合わない。"}, {"text": "その発表を聞いて、テーマがうれしくなった。", "explanation": "ここは〈気持ち〉の意味。テーマは感情を感じる主体ではないので、『うれしくなる』とは合わない。"}, {"text": "この箱は、テーマが三キロもある。", "explanation": "ここは〈重さ〉の意味。テーマは研究や作品の主題を指す語で、物の重さを表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
