INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37186, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "手動", "is_correct": true, "explanation": "人の手で操作する意味で、自動の対義語として辞書に載る。"}, {"text": "読書", "is_correct": false, "explanation": "読書は行為の種類で、自動との対義関係はない。"}, {"text": "機械", "is_correct": false, "explanation": "動かす道具の名称で、自動の反対の意味は持たない。"}, {"text": "電動", "is_correct": false, "explanation": "電気の力で動くことで、自動の対義語ではない。"}], "correct_answer": "手動", "explanations": {"手動": "人の手で操作する意味で、自動の対義語として辞書に載る。", "読書": "読書は行為の種類で、自動との対義関係はない。", "機械": "動かす道具の名称で、自動の反対の意味は持たない。", "電動": "電気の力で動くことで、自動の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
