INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37186, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "自分の力でうごくこと", "primary_collocate": null, "pronunciation": "じどう", "ipa": "dʑidoː", "syllable_count": 3, "sentences": [{"text": "このドアは自動で開くので、荷物を持っていても安心だ。", "target_word": "自動", "complexity_tier": "T3", "furigana": "このドアは自動[じどう]で開[あ]くので、荷物[にもつ]を持[も]っていても安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "洗濯機が自動で止まったので、水があふれずにすんだ。", "target_word": "自動", "complexity_tier": "T3", "furigana": "洗濯機[せんたくき]が自動[じどう]で止[と]まったので、水[みず]があふれずにすんだ。", "sentence_source": "generated"}, {"text": "電気は暗くなると自動で点く。", "target_word": "自動", "complexity_tier": "T3", "furigana": "電気[でんき]は暗[くら]くなると自動[じどう]で点[つ]く。", "sentence_source": "generated"}, {"text": "手で回さなくても、自動でふたが閉まる。", "target_word": "自動", "complexity_tier": "T3", "furigana": "手[て]で回[まわ]さなくても、自動[じどう]でふたが閉[し]まる。", "sentence_source": "generated"}, {"text": "この機械は自動なので、人が見ていなくても動く。", "target_word": "自動", "complexity_tier": "T3", "furigana": "この機械[きかい]は自動[じどう]なので、人[ひと]が見[み]ていなくても動[うご]く。", "sentence_source": "generated"}, {"text": "私の車は自動でブレーキがかかるので、安全だ。", "target_word": "自動", "complexity_tier": "T3", "furigana": "私[わたし]の車[くるま]は自動[じどう]でブレーキがかかるので、安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "窓が自動で閉まらず、雨が部屋に入ってきた。", "target_word": "自動", "complexity_tier": "T3", "furigana": "窓[まど]が自動[じどう]で閉[し]まらず、雨[あめ]が部屋[へや]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "時間になると、エアコンが自動で切れる。", "target_word": "自動", "complexity_tier": "T3", "furigana": "時間[じかん]になると、エアコンが自動[じどう]で切[き]れる。", "sentence_source": "generated"}, {"text": "古い時計は手で巻くが、これは自動で動き続ける。", "target_word": "自動", "complexity_tier": "T3", "furigana": "古[ふる]い時計[とけい]は手[て]で巻[ま]くが、これは自動[じどう]で動[うご]き続[つづ]ける。", "sentence_source": "generated"}, {"text": "この掃除機は部屋の中を自動で回って、ごみを集めてくれる。", "target_word": "自動", "complexity_tier": "T3", "furigana": "このそうじきはへやのなかをじどうでまわって、ごみをあつめてくれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自動", "label": "基本形"}], "register": "一般", "sense_fingerprint": "人の手を使わず、機械などが自分で動くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 点く (Zipf 2.43)']::text[], 'f48066bd-2190-4cb8-bbf1-f08443cd7da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37186, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自動", "is_correct": true, "explanation": "「自動で開く」は人の操作なしにドアが動く意味で、文脈に合う。"}, {"text": "夜間", "is_correct": false, "explanation": "夜間は時間帯で、「夜間で開く」という手段の関係にならない。"}, {"text": "大きさ", "is_correct": false, "explanation": "大きさは寸法で、ドアを開く方法を表さない。"}, {"text": "厚み", "is_correct": false, "explanation": "厚みは物の厚さで、ドアの開き方を示す語にはならない。"}], "explanations": {"自動": "「自動で開く」は人の操作なしにドアが動く意味で、文脈に合う。", "夜間": "夜間は時間帯で、「夜間で開く」という手段の関係にならない。", "大きさ": "大きさは寸法で、ドアを開く方法を表さない。", "厚み": "厚みは物の厚さで、ドアの開き方を示す語にはならない。"}, "sentence_index": 0, "correct_answer": "自動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このロボットは自動して判断し、人の指示を待たずに動く。", "explanation": "ここは〈自律〉の意味。自分で判断して動く様子は自律で、「自動して判断する」とは言わない。"}, {"text": "彼女は大学を出て、親から自動して暮らし始めた。", "explanation": "ここは〈独立〉の意味。人が親元を離れて暮らすことは独立で、機械の動きを表す自動は合わない。"}, {"text": "雨が自動で止んで、空が明るくなった。", "explanation": "ここは〈自然〉の意味。雨がやむ様子は自然に言い、機械的に動く意味の自動は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37186, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自動", "is_correct": true, "explanation": "「窓が自動で閉まる」は機械が自ら閉まる意味で、文脈に合う。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期を表し、「季節で閉まる」という手段の関係にならない。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目の性質で、窓の動き方を示す語ではない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは量の性質で、窓が閉まる方法を表さない。"}], "explanations": {"自動": "「窓が自動で閉まる」は機械が自ら閉まる意味で、文脈に合う。", "季節": "季節は時期を表し、「季節で閉まる」という手段の関係にならない。", "色": "色は見た目の性質で、窓の動き方を示す語ではない。", "重さ": "重さは量の性質で、窓が閉まる方法を表さない。"}, "sentence_index": 6, "correct_answer": "自動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の笑顔は自動で、見る人を安心させる。", "explanation": "ここは〈自然〉の意味。人の笑顔の自然さは自然で、機械の動きを表す自動は合わない。"}, {"text": "彼は親の言葉を聞いて、自動で反省した。", "explanation": "ここは〈自省〉の意味。人が自分を振り返る行為は自省で、自動は機械的な動作に使う。"}, {"text": "彼の料理は自動で、誰にも真似できない味がする。", "explanation": "ここは〈独自〉の意味。料理の個性は独自で、動く機械の意味の自動は言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37186, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この扉は自動に閉まるので、子どもが手を挟む心配がない。", "corrected_sentence": "この扉は自動で閉まるので、子どもが手を挟む心配がない。", "error_description": "「自動で」の「で」（手段）を「に」にしたのが誤り。「自動で閉まる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37186, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このポンプは自動に止まるので、水があふれる心配がない。", "corrected_sentence": "このポンプは自動で止まるので、水があふれる心配がない。", "error_description": "「自動で」の「で」（手段）を「に」にしたのが誤り。「自動で止まる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37188, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「夜だけの営業にシフトした」と、移る先を示す「に」。"}, {"text": "の", "is_correct": false, "explanation": "「営業のシフトした」と続かず、移る先を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「営業でシフトした」では手段・場所の「で」になり、移る先を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「営業とシフトした」では並列や相手の「と」になり、移る先を示す形にならない。"}], "correct_answer": "に", "explanations": {"に": "「夜だけの営業にシフトした」と、移る先を示す「に」。", "の": "「営業のシフトした」と続かず、移る先を表せない。", "で": "「営業でシフトした」では手段・場所の「で」になり、移る先を示せない。", "と": "「営業とシフトした」では並列や相手の「と」になり、移る先を示す形にならない。"}, "error_tags": {"の": "連体修飾", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37188, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「考えにシフトするのは簡単ではない」と、移る先を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「考えをシフトするのは」と目的語を示す形になり、移る先を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「考えからシフトする」は起点を示し、移る先を表せない。"}, {"text": "まで", "is_correct": false, "explanation": "「考えまでシフトする」は到達の範囲を示し、移る先を表す形にならない。"}], "correct_answer": "に", "explanations": {"に": "「考えにシフトするのは簡単ではない」と、移る先を示す「に」。", "を": "「考えをシフトするのは」と目的語を示す形になり、移る先を表せない。", "から": "「考えからシフトする」は起点を示し、移る先を表せない。", "まで": "「考えまでシフトする」は到達の範囲を示し、移る先を表す形にならない。"}, "error_tags": {"を": "目的語", "から": "起点", "まで": "到達範囲"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37188, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「シフト」は、何かを別のものに変えることです。", "primary_collocate": null, "pronunciation": "しふと", "ipa": "ɕiɸɯto", "syllable_count": 3, "sentences": [{"text": "彼女は研究の対象を、植物から昆虫へシフトした。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は研究[けんきゅう]の対象[たいしょう]を、植物[しょくぶつ]から昆虫[こんちゅう]へシフトした。", "sentence_source": "generated"}, {"text": "店は昼の営業をやめ、夜だけの営業にシフトした。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "店[みせ]は昼[ひる]の営業[えいぎょう]をやめ、夜[よる]だけの営業[えいぎょう]にシフトした。", "sentence_source": "generated"}, {"text": "会議の中心は、問題の説明から解決の方法へとシフトした。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "会議[かいぎ]の中心[ちゅうしん]は、問題[もんだい]の説明[せつめい]から解決[かいけつ]の方法[ほうほう]へとシフトした。", "sentence_source": "generated"}, {"text": "試合の流れが、相手チームの攻めから私たちの攻めにシフトした。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "試合[しあい]の流[なが]れが、相手[あいて]チームの攻[せ]めから私[わたし]たちの攻[せ]めにシフトした。", "sentence_source": "generated"}, {"text": "母は肉中心の料理から、野菜中心の料理にシフトした。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "母[はは]は肉[にく]中心[ちゅうしん]の料理[りょうり]から、野菜[やさい]中心[ちゅうしん]の料理[りょうり]にシフトした。", "sentence_source": "generated"}, {"text": "彼は転職を機に、仕事の目標を収入から成長へシフトさせた。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "彼[かれ]は転職[てんしょく]を機[き]に、仕事[しごと]の目標[もくひょう]を収入[しゅうにゅう]から成長[せいちょう]へシフトさせた。", "sentence_source": "generated"}, {"text": "国の政策が、工業から農業へ大きくシフトしている。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "国[くに]の政策[せいさく]が、工業[こうぎょう]から農業[のうぎょう]へ大[おお]きくシフトしている。", "sentence_source": "generated"}, {"text": "気持ちを悲しみから前向きな考えにシフトするのは簡単ではない。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "気持[きも]ちを悲[かな]しみから前向[まえむ]きな考[かんが]えにシフトするのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "工場は古い機械から新しい機械へ、少しずつシフトしている。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "工場[こうじょう]は古[ふる]い機械[きかい]から新[あたら]しい機械[きかい]へ、少[すこ]しずつシフトしている。", "sentence_source": "generated"}, {"text": "先生は授業の進め方を、説明中心から話し合い中心にシフトさせた。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "先生[せんせい]は授業[じゅぎょう]の進[すす]め方[かた]を、説明[せつめい]中心[ちゅうしん]から話[はな]し合[あ]い中心[ちゅうしん]にシフトさせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シフトする", "label": "辞書形"}, {"form": "シフトした", "label": "過去形"}, {"form": "シフトさせる", "label": "使役形"}, {"form": "シフトしている", "label": "継続形"}], "register": "neutral", "sense_fingerprint": "シフト:あるものを別のものに切り替えて変えること(対象・方針・中心などの転換)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a842f311-b815-4a39-bf38-8799be70a7cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37188, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掃除", "is_correct": false, "explanation": "「昆虫へ掃除した」は意味をなさず、対象の転換の文脈に合わない。"}, {"text": "雑談", "is_correct": false, "explanation": "「昆虫へ雑談した」は意味をなさず、対象の転換の文脈に合わない。"}, {"text": "シフト", "is_correct": true, "explanation": "「昆虫へシフトした」は研究の対象を移す意味で、文脈に合う。"}, {"text": "寝坊", "is_correct": false, "explanation": "「昆虫へ寝坊した」は意味をなさず、対象の転換の文脈に合わない。"}], "explanations": {"掃除": "「昆虫へ掃除した」は意味をなさず、対象の転換の文脈に合わない。", "雑談": "「昆虫へ雑談した」は意味をなさず、対象の転換の文脈に合わない。", "シフト": "「昆虫へシフトした」は研究の対象を移す意味で、文脈に合う。", "寝坊": "「昆虫へ寝坊した」は意味をなさず、対象の転換の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "シフト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は足の長さをシフトした。", "explanation": "ここは〈伸ばす〉（長さを増す）の意味。シフトは別のものに変える意味で、長さを伸ばすとは言わないので合わない。"}, {"text": "母は、ケーキの甘さをシフトした。", "explanation": "ここは〈加減する〉（程度を調整する）の意味。シフトは別のものへ変わる意味で、甘さの程度を調整する言い方にはならないので合わない。"}, {"text": "父は部屋の湿度をシフトした。", "explanation": "ここは〈調節する〉（設備の値を合わせる）の意味。シフトは別のものに変える意味で、湿度を調節する言い方にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37188, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遠慮", "is_correct": false, "explanation": "「大きく遠慮している」は意味をなさず、転換の文脈に合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「大きく散歩している」は意味をなさず、転換の文脈に合わない。"}, {"text": "シフト", "is_correct": true, "explanation": "「大きくシフトしている」は政策の重点が移る意味で、文脈に合う。"}, {"text": "旅行", "is_correct": false, "explanation": "「大きく旅行している」は意味をなさず、転換の文脈に合わない。"}], "explanations": {"遠慮": "「大きく遠慮している」は意味をなさず、転換の文脈に合わない。", "散歩": "「大きく散歩している」は意味をなさず、転換の文脈に合わない。", "シフト": "「大きくシフトしている」は政策の重点が移る意味で、文脈に合う。", "旅行": "「大きく旅行している」は意味をなさず、転換の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "シフト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は黒板の文字をシフトした。", "explanation": "ここは〈書き換える〉の意味。シフトは移り変わる意味で、文字の内容を書き換えるとは言わない。"}, {"text": "姉は財布の中身をシフトした。", "explanation": "ここは〈整理する〉の意味。シフトは対象の転換を表し、中身を整えるとは言わない。"}, {"text": "彼は部屋の照明を明るくシフトした。", "explanation": "ここは〈明るくする〉（光を強める）の意味。移行の意味のシフトは、明るさを増す言い方にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37188, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店は客層を学生から会社員をシフトさせた。", "corrected_sentence": "店は客層を学生から会社員へシフトさせた。", "error_description": "「シフトさせる」は移る先を「へ」で示す。「会社員を」は目的語の格で移り先を表せないので誤りで、「会社員へ」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37188, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店長は客層を若者から家族連れへシフトされた。", "corrected_sentence": "店長は客層を若者から家族連れへシフトさせた。", "error_description": "店長が主語で転換を行わせる行為なので使役形「させた」が正しい。受身「された」は主語と合わず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37189, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「電車にシフトする」と、移る先を示す「に」。シフトの移り先に付く正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「電車をシフトする」では対象を取る形になり、移る先を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「電車でシフトする」では手段・場所の「で」になり、移る先を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「電車のシフト」と名詞を修飾する形になり、動詞「シフトする」に続く移り先の助詞にならない。"}], "correct_answer": "に", "explanations": {"に": "「電車にシフトする」と、移る先を示す「に」。シフトの移り先に付く正しい助詞。", "を": "「電車をシフトする」では対象を取る形になり、移る先を示せない。", "で": "「電車でシフトする」では手段・場所の「で」になり、移る先を表せない。", "の": "「電車のシフト」と名詞を修飾する形になり、動詞「シフトする」に続く移り先の助詞にならない。"}, "error_tags": {"を": "対象", "で": "手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37189, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「動画サイトへシフトしている」と、移る先を示す「へ」。"}, {"text": "と", "is_correct": false, "explanation": "「動画サイトとシフトしている」では並列や共同の「と」になり、移る先を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「動画サイトからシフトしている」では起点の「から」になり、移る先ではなく出発点を示すので意味が逆になる。"}, {"text": "が", "is_correct": false, "explanation": "「動画サイトがシフトしている」では主格になり、シフトの移る先を示せない。"}], "correct_answer": "へ", "explanations": {"へ": "「動画サイトへシフトしている」と、移る先を示す「へ」。", "と": "「動画サイトとシフトしている」では並列や共同の「と」になり、移る先を示せない。", "から": "「動画サイトからシフトしている」では起点の「から」になり、移る先ではなく出発点を示すので意味が逆になる。", "が": "「動画サイトがシフトしている」では主格になり、シフトの移る先を示せない。"}, "error_tags": {"と": "並列", "から": "起点", "が": "主格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37189, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「シフト」は、ある状態や位置から別の状態や位置へと移行することを意味します。特に、交通手段や考え方などを切り替える際に使われます。", "primary_collocate": null, "pronunciation": "しふと", "ipa": "ɕiɸɯto", "syllable_count": 3, "sentences": [{"text": "企業は、単純な作業だけでなく、創造性や対人スキルを求められる役割へ従業員をシフトさせなければならない。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "企業[きぎょう]は、単純[たんじゅん]な作業[さぎょう]だけでなく、創造性[そうぞうせい]や対人[たいじん]スキルを求[もと]められる役割[やくわり]へ従業員[じゅうぎょういん]をシフトさせなければならない。", "sentence_source": "mined"}, {"text": "環境のことを考えて、通勤を車から電車にシフトする人が増えている。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "環境[かんきょう]のことを考[かんが]えて、通勤[つうきん]を車[くるま]から電車[でんしゃ]にシフトする人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "会社は紙の広告からインターネット広告へ、宣伝の中心をシフトした。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は紙[かみ]の広告[こうこく]からインターネット広告[こうこく]へ、宣伝[せんでん]の中心[ちゅうしん]をシフトした。", "sentence_source": "generated"}, {"text": "彼は学生のころから、考え方を少しずつシフトさせてきた。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "彼[かれ]は学生[がくせい]のころから、考[かんが]え方[かた]を少[すこ]しずつシフトさせてきた。", "sentence_source": "generated"}, {"text": "値上がりのため、多くの家庭が買う食品を、高いものから安いものにシフトしている。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "値[ね]上[あ]がりのため、多[おお]くの家庭[かてい]が買[か]う食品[しょくひん]を、高[たか]いものから安[やす]いものにシフトしている。", "sentence_source": "generated"}, {"text": "重心を右足にシフトしてから、ボールを強く蹴った。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "重心[じゅうしん]を右足[みぎあし]にシフトしてから、ボールを強[つよ]く蹴[け]った。", "sentence_source": "generated"}, {"text": "新しい社長は、売り上げ重視から社員の育成へ方針をシフトした。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "新[あたら]しい社長[しゃちょう]は、売[う]り上[あ]げ重視[じゅうし]から社員[しゃいん]の育成[いくせい]へ方針[ほうしん]をシフトした。", "sentence_source": "generated"}, {"text": "若い世代は、情報を集める場所をテレビから動画サイトへシフトしている。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "若[わか]い世代[せだい]は、情報[じょうほう]を集[あつ]める場所[ばしょ]をテレビから動画[どうが]サイトへシフトしている。", "sentence_source": "generated"}, {"text": "工事中の道路を避けるために、バスの路線を一本北へシフトさせた。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "工事中[こうじちゅう]の道路[どうろ]を避[さ]けるために、バスの路線[ろせん]を一本[いっぽん]北[きた]へシフトさせた。", "sentence_source": "generated"}, {"text": "年を取ると、仕事中心の生活から家族中心の生活にシフトする人が多い。", "target_word": "シフト", "complexity_tier": "T3", "furigana": "年[とし]を取[と]ると、仕事[しごと]中心[ちゅうしん]の生活[せいかつ]から家族[かぞく]中心[ちゅうしん]の生活[せいかつ]にシフトする人[ひと]が多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シフトする", "label": "辞書形"}, {"form": "シフトした", "label": "過去形"}, {"form": "シフトさせる", "label": "使役形"}, {"form": "シフトしている", "label": "継続形"}], "register": "neutral", "sense_fingerprint": "シフト:ある状態・位置から別の状態・位置へ移ること(交通手段や考え方の切り替えなど)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a842f311-b815-4a39-bf38-8799be70a7cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37189, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旅行", "is_correct": false, "explanation": "「従業員を旅行させる」は文脈の役割の移行と無関係で、意味が通らない。"}, {"text": "シフト", "is_correct": true, "explanation": "「従業員をシフトさせる」は役割を移す意味で、文脈に合う。"}, {"text": "雑談", "is_correct": false, "explanation": "「従業員を雑談させる」は役割の移行と無関係で、文脈に合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "「従業員を清掃させる」は役割の移行と無関係で、文脈に合わない。"}], "explanations": {"旅行": "「従業員を旅行させる」は文脈の役割の移行と無関係で、意味が通らない。", "シフト": "「従業員をシフトさせる」は役割を移す意味で、文脈に合う。", "雑談": "「従業員を雑談させる」は役割の移行と無関係で、文脈に合わない。", "清掃": "「従業員を清掃させる」は役割の移行と無関係で、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "シフト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一か月で体重を三キロシフトした。", "explanation": "ここは〈増減させる〉（数量を増やしたり減らしたりする）の意味。シフトは移り変わる意味で、体重の増減には使わないので合わない。"}, {"text": "母は、お風呂の水温をシフトした。", "explanation": "ここは〈調整する〉（数値を合わせる）の意味。シフトは移行の意味で、水温の数値を合わせる言い方にはならないので合わない。"}, {"text": "彼は壁の色をシフトした。", "explanation": "ここは〈塗り替える〉（色を変える）の意味。シフトは移行の意味で、色を塗り替えるときには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37189, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遠慮", "is_correct": false, "explanation": "「方針を遠慮した」は意味をなさず、移行の文脈に合わない。"}, {"text": "寝坊", "is_correct": false, "explanation": "「方針を寝坊した」は意味をなさず、移行の文脈に合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「方針を散歩した」は意味をなさず、移行の文脈に合わない。"}, {"text": "シフト", "is_correct": true, "explanation": "「方針をシフトした」は重点を別のものに移す意味で、文脈に合う。"}], "explanations": {"遠慮": "「方針を遠慮した」は意味をなさず、移行の文脈に合わない。", "寝坊": "「方針を寝坊した」は意味をなさず、移行の文脈に合わない。", "散歩": "「方針を散歩した」は意味をなさず、移行の文脈に合わない。", "シフト": "「方針をシフトした」は重点を別のものに移す意味で、文脈に合う。"}, "sentence_index": 6, "correct_answer": "シフト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は髪型を短くシフトした。", "explanation": "ここは〈変更〉（形を変える）の意味。移行の意味のシフトは、髪型の形を変えるのには使わない。"}, {"text": "母は、生地を薄くシフトした。", "explanation": "ここは〈伸ばす〉（厚みを変える）の意味。移行のシフトは、生地を薄く延ばす言い方にはならないので合わない。"}, {"text": "今日は夕食のメニューをシフトした。", "explanation": "ここは〈変える〉（内容を替える）の意味。移行の意味のシフトは、献立の内容を替えるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37189, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は通勤手段を車から自転車をシフトした。", "corrected_sentence": "私は通勤手段を車から自転車にシフトした。", "error_description": "「シフトする」は移る先を「に」で示す。「自転車を」は目的語の格なので誤りで、「自転車に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37189, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は仕事の中心を、会議から現場の対応にシフトされた。", "corrected_sentence": "彼は仕事の中心を、会議から現場の対応にシフトさせた。", "error_description": "彼が主語で移行させる行為なので使役形「させた」が正しい。受身「された」にすると主語と合わなくなり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37190, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37190, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「夜の大気は静かだ」と大気を主題として述べる形。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すため、「大気を静かで」は文として成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は状態や方向を示すが、「大気に静かで」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示し、「大気で静かで」は述語とつながらない。"}], "correct_answer": "は", "explanations": {"は": "「夜の大気は静かだ」と大気を主題として述べる形。", "を": "「を」は目的語を示すため、「大気を静かで」は文として成立しない。", "に": "「に」は状態や方向を示すが、「大気に静かで」は不自然。", "で": "「で」は場所や手段を示し、「大気で静かで」は述語とつながらない。"}, "error_tags": {"を": "目的語", "に": "状態・方向", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37190, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気のこと。", "primary_collocate": null, "pronunciation": "たいき", "ipa": "[taiki]", "syllable_count": 3, "sentences": [{"text": "朝の大気は冷たく、深く吸うと頭がすっきりした。", "target_word": "大気", "complexity_tier": "T3", "furigana": "朝[あさ]の大気[たいき]は冷[つめ]たく、深[ふか]く吸[す]うと頭[あたま]がすっきりした。", "sentence_source": "generated"}, {"text": "森の大気には、木の香りがほのかに混じっている。", "target_word": "大気", "complexity_tier": "T3", "furigana": "森[もり]の大気[たいき]には、木[き]の香[かお]りがほのかに混[ま]じっている。", "sentence_source": "generated"}, {"text": "雨上がりの大気は湿っていて、土のにおいがした。", "target_word": "大気", "complexity_tier": "T3", "furigana": "雨上[あめあ]がりの大気[たいき]は湿[しめ]っていて、土[つち]のにおいがした。", "sentence_source": "generated"}, {"text": "窓を開けると、春の大気が部屋に流れ込んできた。", "target_word": "大気", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、春[はる]の大気[たいき]が部屋[へや]に流[なが]れ込[こ]んできた。", "sentence_source": "generated"}, {"text": "山頂の大気は澄んでいて、一息ごとに体が軽くなる気がした。", "target_word": "大気", "complexity_tier": "T3", "furigana": "山頂[さんちょう]の大気[たいき]は澄[す]んでいて、一息[ひといき]ごとに体[からだ]が軽[かる]くなる気[き]がした。", "sentence_source": "generated"}, {"text": "工場の近くは大気が重く、息をするのもつらかった。", "target_word": "大気", "complexity_tier": "T3", "furigana": "工場[こうじょう]の近[ちか]くは大気[たいき]が重[おも]く、息[いき]をするのもつらかった。", "sentence_source": "generated"}, {"text": "大気の動きが変わったのか、急に風が強くなった。", "target_word": "大気", "complexity_tier": "T3", "furigana": "大気[たいき]の動[うご]きが変[か]わったのか、急[きゅう]に風[かぜ]が強[つよ]くなった。", "sentence_source": "generated"}, {"text": "夜の大気は静かで、遠くの電車の音まで聞こえた。", "target_word": "大気", "complexity_tier": "T3", "furigana": "夜[よる]の大気[たいき]は静[しず]かで、遠[とお]くの電車[でんしゃ]の音[おと]まで聞[き]こえた。", "sentence_source": "generated"}, {"text": "彼は目を閉じて、海辺の大気をゆっくり吸いこんだ。", "target_word": "大気", "complexity_tier": "T3", "furigana": "彼[かれ]は目[め]を閉[と]じて、海辺[うみべ]の大気[たいき]をゆっくり吸[す]いこんだ。", "sentence_source": "generated"}, {"text": "乾いた大気のせいで、のどが痛くなってきた。", "target_word": "大気", "complexity_tier": "T3", "furigana": "乾[かわ]いた大気[たいき]のせいで、のどが痛[いた]くなってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大気", "label": "基本形"}], "register": "書き言葉（普通体）", "sense_fingerprint": "身のまわりの空気（やや文学的な言い方）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: 吸いこん (Zipf 1.37)']::text[], 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37190, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大気", "is_correct": true, "explanation": "空気のことで、「朝の大気は冷たく」と続く。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちを表す語で、「朝の食欲は冷たく」は成立しない。"}, {"text": "人口", "is_correct": false, "explanation": "人の数を表す語で、冷たいという性質を持たないため合わない。"}, {"text": "足音", "is_correct": false, "explanation": "歩く音を表す語で、「朝の足音は冷たく」は意味をなさない。"}], "explanations": {"大気": "空気のことで、「朝の大気は冷たく」と続く。", "食欲": "食べたい気持ちを表す語で、「朝の食欲は冷たく」は成立しない。", "人口": "人の数を表す語で、冷たいという性質を持たないため合わない。", "足音": "歩く音を表す語で、「朝の足音は冷たく」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "大気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝の大気が、目覚まし時計のように鳴り響いた。", "explanation": "ここは〈音〉の意味。鳴り響くのは音で、大気は鳴ったり響いたりしない。"}, {"text": "窓の外が明るくなって、大気が差し込んできた。", "explanation": "ここは〈光〉の意味。差し込むのは光で、大気は差し込むものではない。"}, {"text": "このスープは大気が濃くて、飲みにくかった。", "explanation": "ここは〈味〉の意味。濃いのは味で、大気の濃さを味のように表すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37190, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大気", "is_correct": true, "explanation": "空気のことで、「大気の動きが変わった」と続く。"}, {"text": "陶器", "is_correct": false, "explanation": "焼き物の器を指し、動きを持たないため「陶器の動きが変わった」は不自然。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に使う紙片で、「切手の動きが変わった」は意味をなさない。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の出入口で、「玄関の動きが変わった」は成立しない。"}], "explanations": {"大気": "空気のことで、「大気の動きが変わった」と続く。", "陶器": "焼き物の器を指し、動きを持たないため「陶器の動きが変わった」は不自然。", "切手": "郵便に使う紙片で、「切手の動きが変わった」は意味をなさない。", "玄関": "建物の出入口で、「玄関の動きが変わった」は成立しない。"}, "sentence_index": 6, "correct_answer": "大気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕飯の大気を皿に盛って、食べた。", "explanation": "ここは〈料理〉の意味。皿に盛って食べられるのは食べ物で、大気は食べ物ではない。"}, {"text": "故障した大気を、専門の技術者が修理した。", "explanation": "ここは〈機械〉の意味。修理されるのは機械や装置で、大気は修理の対象にならない。"}, {"text": "重い大気を両手で運んで、部屋まで届けた。", "explanation": "ここは〈荷物〉の意味。運んで届けるのは物品で、大気は運んで届けるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37190, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早朝の大気を冷たくて、身が引き締まった。", "corrected_sentence": "早朝の大気は冷たくて、身が引き締まった。", "error_description": "主語の「大気」には「は」を使う。「を」は目的語を示すため、「冷たくて」の主語にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37190, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の大気に静かで、遠くの踏切の音が聞こえた。", "corrected_sentence": "夜の大気は静かで、遠くの踏切の音が聞こえた。", "error_description": "「大気」を主題にするには「は」が正しい。「に」では「静かだ」の主語にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37191, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「大気」は「汚れる」の主語で、「大気が汚れる」と結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「汚れる」は目的語を取らない自動詞なので、「大気を汚れると」は成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、「大気に汚れる」では変化の主体を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「大気へ汚れる」は主語の位置を示せない。"}], "correct_answer": "が", "explanations": {"が": "「大気」は「汚れる」の主語で、「大気が汚れる」と結ぶ。", "を": "「汚れる」は目的語を取らない自動詞なので、「大気を汚れると」は成立しない。", "に": "「に」は場所や相手を示すが、「大気に汚れる」では変化の主体を表せない。", "へ": "「へ」は方向を示すので、「大気へ汚れる」は主語の位置を示せない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37191, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「火星の大気は薄い」と大気を主題として述べる形。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「大気と薄く」は「薄い」の主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、「大気で薄く」は状態の主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「大気から薄く」は状態の説明として不自然。"}], "correct_answer": "は", "explanations": {"は": "「火星の大気は薄い」と大気を主題として述べる形。", "と": "「と」は並列や相手を示すため、「大気と薄く」は「薄い」の主語にならない。", "で": "「で」は場所や手段を示すため、「大気で薄く」は状態の主語にならない。", "から": "「から」は起点を示すが、「大気から薄く」は状態の説明として不自然。"}, "error_tags": {"と": "並列・相手", "で": "場所・手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37191, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地球のまわりにある、私達が呼吸する気体。", "primary_collocate": null, "pronunciation": "たいき", "ipa": "[taiki]", "syllable_count": 3, "sentences": [{"text": "人為的な要因によって大気中に放出された過剰な温室効果ガスは、放射強制力を変化させ、全球規模での気候変動を加速させている。", "target_word": "大気", "complexity_tier": "T5", "furigana": "人為的[じんいてき]な要因[よういん]によって大気中[たいきちゅう]に放出[ほうしゅつ]された過剰[かじょう]な温室効果[おんしつこうか]ガスは、放射強制力[ほうしゃきょうせいりょく]を変化[へんか]させ、全球規模[ぜんきゅうきぼ]での気候変動[きこうへんどう]を加速[かそく]させている。", "sentence_source": "mined"}, {"text": "大気が汚れると、空が白くかすんで見える。", "target_word": "大気", "complexity_tier": "T3", "furigana": "大気[たいき]が汚[よご]れると、空[そら]が白[しろ]くかすんで見[み]える。", "sentence_source": "generated"}, {"text": "山の上は大気が薄いので、息が苦しくなる。", "target_word": "大気", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]は大気[たいき]が薄[うす]いので、息[いき]が苦[くる]しくなる。", "sentence_source": "generated"}, {"text": "地球は厚い大気に包まれている。", "target_word": "大気", "complexity_tier": "T3", "furigana": "地球[ちきゅう]は厚[あつ]い大気[たいき]に包[つつ]まれている。", "sentence_source": "generated"}, {"text": "工場から出た煙が大気に広がり、街全体に臭いが残った。", "target_word": "大気", "complexity_tier": "T3", "furigana": "工場[こうじょう]から出[で]た煙[けむり]が大気[たいき]に広[ひろ]がり、街[まち]全体[ぜんたい]に臭[にお]いが残[のこ]った。", "sentence_source": "generated"}, {"text": "大気の層があるおかげで、地表の温度は急に下がらない。", "target_word": "大気", "complexity_tier": "T3", "furigana": "大気[たいき]の層[そう]があるおかげで、地表[ちひょう]の温度[おんど]は急[きゅう]に下[さ]がらない。", "sentence_source": "generated"}, {"text": "雨がふったあとは、大気が澄んで遠くの山までよく見える。", "target_word": "大気", "complexity_tier": "T3", "furigana": "雨[あめ]がふったあとは、大気[たいき]が澄[す]んで遠[とお]くの山[やま]までよく見[み]える。", "sentence_source": "generated"}, {"text": "火星の大気は薄く、人間はそのままでは呼吸できない。", "target_word": "大気", "complexity_tier": "T3", "furigana": "火星[かせい]の大気[たいき]は薄[うす]く、人間[にんげん]はそのままでは呼吸[こきゅう]できない。", "sentence_source": "generated"}, {"text": "飛行機は大気の上層を飛ぶため、窓の外の空が濃い青に見える。", "target_word": "大気", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は大気[たいき]の上層[じょうそう]を飛[と]ぶため、窓[まど]の外[そと]の空[そら]が濃[こ]い青[あお]に見[み]える。", "sentence_source": "generated"}, {"text": "大気に含まれる酸素は、私たちが生きるために欠かせない。", "target_word": "大気", "complexity_tier": "T3", "furigana": "大気[たいき]に含[ふく]まれる酸素[さんそ]は、私[わたし]たちが生[い]きるために欠[か]かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大気", "label": "基本形"}], "register": "書き言葉（普通体）", "sense_fingerprint": "地球を包む気体の層としての大気（科学的な意味）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37191, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大気", "is_correct": true, "explanation": "地球を取り巻く気体の層を指し、「大気中に放出された」と文意が通る。"}, {"text": "人口", "is_correct": false, "explanation": "人の数を表す語で、「人口中に放出された」は文として成立しない。"}, {"text": "温度", "is_correct": false, "explanation": "数値で表す性質の語で、「温度中に放出された」とは言えない。"}, {"text": "運動", "is_correct": false, "explanation": "動きを表す語で、「運動中に放出された」は意味をなさない。"}], "explanations": {"大気": "地球を取り巻く気体の層を指し、「大気中に放出された」と文意が通る。", "人口": "人の数を表す語で、「人口中に放出された」は文として成立しない。", "温度": "数値で表す性質の語で、「温度中に放出された」とは言えない。", "運動": "動きを表す語で、「運動中に放出された」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "大気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓の大気に顔が映って、びっくりした。", "explanation": "ここは〈ガラス〉の意味。顔が映るのは窓ガラスで、大気は物を映す面にはならない。"}, {"text": "明日の大気は晴れるので、洗濯日和になるでしょう。", "explanation": "ここは〈天気〉の意味。晴れるかどうかは天気の話で、大気そのものが晴れるとは言わない。"}, {"text": "空に大気がふわりと浮かんでいる。", "explanation": "ここは〈雲〉の意味。浮かんで形の見えるものは雲で、大気は目に見える物体ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37191, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大気", "is_correct": true, "explanation": "空気の層を指し、「大気が澄んで遠くの山までよく見える」と続く。"}, {"text": "体温", "is_correct": false, "explanation": "体の温かさを表す語で、「体温が澄んで」は成立しない。"}, {"text": "予算", "is_correct": false, "explanation": "使えるお金の額を表す語で、「予算が澄んで」は意味をなさない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちを表す語で、「食欲が澄んで」は不自然。"}], "explanations": {"大気": "空気の層を指し、「大気が澄んで遠くの山までよく見える」と続く。", "体温": "体の温かさを表す語で、「体温が澄んで」は成立しない。", "予算": "使えるお金の額を表す語で、「予算が澄んで」は意味をなさない。", "食欲": "食べたい気持ちを表す語で、「食欲が澄んで」は不自然。"}, "sentence_index": 6, "correct_answer": "大気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "のどが渇いたので、コップに大気を注いで飲んだ。", "explanation": "ここは〈水〉の意味。注いで飲めるのは液体の水で、大気は気体なのでコップに注げない。"}, {"text": "庭の大気に花が咲いて、春が来たことを知らせた。", "explanation": "ここは〈大地〉の意味。花が咲くのは大地（地面）で、大気（空気）は花を咲かせる場所ではない。"}, {"text": "地震で大気が崩れ、家が倒れた。", "explanation": "ここは〈地盤〉の意味。崩れるのは土地や地盤で、大気は崩れる物体ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37191, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方の大気を澄んでいて、遠くの山が見えた。", "corrected_sentence": "夕方の大気は澄んでいて、遠くの山が見えた。", "error_description": "「大気は〜ている」と主題で述べるには「は」が正しい。「を」は他動詞の目的語に使うため、「澄んでいる」の主語にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37191, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨上がりの大気を澄んで、遠くの山がよく見えた。", "corrected_sentence": "雨上がりの大気が澄んで、遠くの山がよく見えた。", "error_description": "主語の「大気」には「が」を使う。「を」は目的語を示すため、「澄んで」の主語にはならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37194, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「要因が〜とは限らない」と要因を主語にして述べる形。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すため、「要因を寝坊だけとは限らない」は成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や結果を示すが、「要因に寝坊だけ」は主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「要因へ〜とは限らない」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「要因が〜とは限らない」と要因を主語にして述べる形。", "を": "「を」は目的語を示すため、「要因を寝坊だけとは限らない」は成立しない。", "に": "「に」は位置や結果を示すが、「要因に寝坊だけ」は主語にならない。", "へ": "「へ」は方向を示すため、「要因へ〜とは限らない」は不自然。"}, "error_tags": {"を": "目的語", "に": "位置・結果", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37194, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37194, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起きる理由や原因になること。", "primary_collocate": null, "pronunciation": "よういん", "ipa": "[joːiɴ]", "syllable_count": 4, "sentences": [{"text": "火事の要因は、古い配線のショートだったと考えられる。", "target_word": "要因", "complexity_tier": "T3", "furigana": "火事[かじ]の要因[よういん]は、古[ふる]い配線[はいせん]のショートだったと考[かんが]えられる。", "sentence_source": "generated"}, {"text": "遅刻の要因が寝坊だけとは限らない。", "target_word": "要因", "complexity_tier": "T3", "furigana": "遅刻[ちこく]の要因[よういん]が寝坊[ねぼう]だけとは限[かぎ]らない。", "sentence_source": "generated"}, {"text": "この病気の要因には、生活習慣が深く関わっている。", "target_word": "要因", "complexity_tier": "T3", "furigana": "この病気[びょうき]の要因[よういん]には、生活[せいかつ]習慣[しゅうかん]が深[ふか]く関[かか]わっている。", "sentence_source": "generated"}, {"text": "試合に負けた要因は、守りの乱れにあった。", "target_word": "要因", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けた要因[よういん]は、守[まも]りの乱[みだ]れにあった。", "sentence_source": "generated"}, {"text": "渋滞が起きる要因を、専門家が分析した。", "target_word": "要因", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]が起[お]きる要因[よういん]を、専門家[せんもんか]が分析[ぶんせき]した。", "sentence_source": "generated"}, {"text": "ストレスは、頭痛を引き起こす要因になりうる。", "target_word": "要因", "complexity_tier": "T3", "furigana": "ストレスは、頭痛[ずつう]を引[ひ]き起[お]こす要因[よういん]になりうる。", "sentence_source": "generated"}, {"text": "事故の要因は一つではなく、いくつもの小さなミスが重なっていた。", "target_word": "要因", "complexity_tier": "T3", "furigana": "事故[じこ]の要因[よういん]は一[ひと]つではなく、いくつもの小[ちい]さなミスが重[かさ]なっていた。", "sentence_source": "generated"}, {"text": "円安が物価上昇の要因だと言われている。", "target_word": "要因", "complexity_tier": "T3", "furigana": "円安[えんやす]が物価[ぶっか]上昇[じょうしょう]の要因[よういん]だと言[い]われている。", "sentence_source": "generated"}, {"text": "失敗の要因を人のせいにしても、何も変わらない。", "target_word": "要因", "complexity_tier": "T3", "furigana": "失敗[しっぱい]の要因[よういん]を人[ひと]のせいにしても、何[なに]も変[か]わらない。", "sentence_source": "generated"}, {"text": "客が減った要因は、近くに新しい店ができたことだ。", "target_word": "要因", "complexity_tier": "T3", "furigana": "客[きゃく]が減[へ]った要因[よういん]は、近[ちか]くに新[あたら]しい店[みせ]ができたことだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "要因", "label": "基本形"}], "register": "書き言葉（普通体）", "sense_fingerprint": "出来事が起きる理由・原因となるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37194, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要因", "is_correct": true, "explanation": "「火事の要因は〜だったと考えられる」と原因を示す形になる。"}, {"text": "教師", "is_correct": false, "explanation": "人を指す語で、「火事の教師は」とは原因として続かない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車券を指し、「火事の切符は」は成立しない。"}, {"text": "花瓶", "is_correct": false, "explanation": "器の名で、「火事の花瓶は」は不自然。"}], "explanations": {"要因": "「火事の要因は〜だったと考えられる」と原因を示す形になる。", "教師": "人を指す語で、「火事の教師は」とは原因として続かない。", "切符": "乗車券を指し、「火事の切符は」は成立しない。", "花瓶": "器の名で、「火事の花瓶は」は不自然。"}, "sentence_index": 0, "correct_answer": "要因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合に負けた要因は、紙の上で踊った。", "explanation": "ここは〈動作〉の意味。踊るのは人や生き物で、要因は踊れない。"}, {"text": "試合に負けた要因は、深い海の底で歌った。", "explanation": "ここは〈動作〉の意味。歌うのは人や生き物で、要因は歌えない。"}, {"text": "試合に負けた要因は、きれいに咲いた花だった。", "explanation": "ここは〈植物〉の意味。咲くのは植物で、要因は咲くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37194, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要因", "is_correct": true, "explanation": "「事故の要因は一つではなく」と原因の数を述べる形になる。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の出入口で、「事故の玄関は」は意味をなさない。"}, {"text": "陶器", "is_correct": false, "explanation": "焼き物を指し、「事故の陶器は」は成立しない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちを表し、「事故の食欲は」は不自然。"}], "explanations": {"要因": "「事故の要因は一つではなく」と原因の数を述べる形になる。", "玄関": "建物の出入口で、「事故の玄関は」は意味をなさない。", "陶器": "焼き物を指し、「事故の陶器は」は成立しない。", "食欲": "食べたい気持ちを表し、「事故の食欲は」は不自然。"}, "sentence_index": 6, "correct_answer": "要因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客が減った要因の車が、店の前に止まっていた。", "explanation": "ここは〈乗り物〉の意味。店の前に止まるのは乗り物で、要因は止まったりできない。"}, {"text": "客が減った要因は、ゆっくり歌っていた。", "explanation": "ここは〈動作〉の意味。歌うのは人や生き物で、要因は歌えない。"}, {"text": "空港で要因が到着し、警備が厳しくなった。", "explanation": "ここは〈要人〉の意味。到着して警備が厳しくなるのは重要な人物で、要因は人ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37194, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渋滞の要因を、工事のせいだ。", "corrected_sentence": "渋滞の要因は、工事のせいだ。", "error_description": "「要因は〜のせいだ」と主題で示す。「を」では「工事のせいだ」とつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37194, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作物の不作の要因を、雨の多さが挙げられる。", "corrected_sentence": "作物の不作の要因として、雨の多さが挙げられる。", "error_description": "「〜の要因として挙げられる」の形が正しい。「を」では「挙げられる」と結べない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37195, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「要因は〜ことだ」と主題を示す形で、断定文になる。"}, {"text": "を", "is_correct": false, "explanation": "「要因を、〜ことだ」では主題が立たず、文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すため、「要因と〜ことだ」では断定にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「要因へ〜ことだ」は主題にならない。"}], "correct_answer": "は", "explanations": {"は": "「要因は〜ことだ」と主題を示す形で、断定文になる。", "を": "「要因を、〜ことだ」では主題が立たず、文が成立しない。", "と": "「と」は並列や引用を示すため、「要因と〜ことだ」では断定にならない。", "へ": "「へ」は方向を示すが、「要因へ〜ことだ」は主題にならない。"}, "error_tags": {"を": "目的語", "と": "並列・引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37195, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「要因が複数ある」と要因を主語にして述べる形。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すため、「要因に複数ある」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示し、「要因で複数あるため」は主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「要因から複数あるため」は成立しない。"}], "correct_answer": "が", "explanations": {"が": "「要因が複数ある」と要因を主語にして述べる形。", "に": "「に」は場所や相手を示すため、「要因に複数ある」は不自然。", "で": "「で」は場所や手段を示し、「要因で複数あるため」は主語にならない。", "から": "「から」は起点を示すが、「要因から複数あるため」は成立しない。"}, "error_tags": {"に": "場所・相手", "で": "場所・手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37195, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある結果を生み出すもとになった要素。", "primary_collocate": null, "pronunciation": "よういん", "ipa": "[joːiɴ]", "syllable_count": 4, "sentences": [{"text": "人為的な要因によって大気中に放出された過剰な温室効果ガスは、放射強制力を変化させ、全球規模での気候変動を加速させている。", "target_word": "要因", "complexity_tier": "T5", "furigana": "人為的[じんいてき]な要因[よういん]によって大気中[たいきちゅう]に放出[ほうしゅつ]された過剰[かじょう]な温室効果[おんしつこうか]ガスは、放射強制力[ほうしゃきょうせいりょく]を変化[へんか]させ、全球規模[ぜんきゅうきぼ]での気候変動[きこうへんどう]を加速[かそく]させている。", "sentence_source": "mined"}, {"text": "売り上げが落ちた要因は、新商品の発売が遅れたことだ。", "target_word": "要因", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが落[お]ちた要因[よういん]は、新商品[しんしょうひん]の発売[はつばい]が遅[おく]れたことだ。", "sentence_source": "generated"}, {"text": "事故の要因を調べて、同じ失敗を防ぐ対策を立てた。", "target_word": "要因", "complexity_tier": "T3", "furigana": "事故[じこ]の要因[よういん]を調[しら]べて、同[おな]じ失敗[しっぱい]を防[ふせ]ぐ対策[たいさく]を立[た]てた。", "sentence_source": "generated"}, {"text": "天候不順が、野菜の値上がりの大きな要因になった。", "target_word": "要因", "complexity_tier": "T3", "furigana": "天候[てんこう]不順[ふじゅん]が、野菜[やさい]の値上[ねあ]がりの大[おお]きな要因[よういん]になった。", "sentence_source": "generated"}, {"text": "成功の要因は、チーム全員が目標を共有していたことだ。", "target_word": "要因", "complexity_tier": "T3", "furigana": "成功[せいこう]の要因[よういん]は、チーム全員[ぜんいん]が目標[もくひょう]を共有[きょうゆう]していたことだ。", "sentence_source": "generated"}, {"text": "若者の投票率が低い要因について、調査が行われた。", "target_word": "要因", "complexity_tier": "T3", "furigana": "若者[わかもの]の投票率[とうひょうりつ]が低[ひく]い要因[よういん]について、調査[ちょうさ]が行[おこな]われた。", "sentence_source": "generated"}, {"text": "睡眠不足は、体調をくずす要因の一つだ。", "target_word": "要因", "complexity_tier": "T3", "furigana": "睡眠[すいみん]不足[ぶそく]は、体調[たいちょう]をくずす要因[よういん]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "要因が複数あるため、原因を一つにしぼるのは難しい。", "target_word": "要因", "complexity_tier": "T3", "furigana": "要因[よういん]が複数[ふくすう]あるため、原因[げんいん]を一[ひと]つにしぼるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "彼の転職には、給料以外にも要因があったらしい。", "target_word": "要因", "complexity_tier": "T3", "furigana": "彼[かれ]の転職[てんしょく]には、給料[きゅうりょう]以外[いがい]にも要因[よういん]があったらしい。", "sentence_source": "generated"}, {"text": "人口が減った要因として、若い世代の流出が挙げられる。", "target_word": "要因", "complexity_tier": "T3", "furigana": "人口[じんこう]が減[へ]った要因[よういん]として、若[わか]い世代[せだい]の流出[りゅうしゅつ]が挙[あ]げられる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "要因", "label": "基本形"}], "register": "書き言葉（普通体）", "sense_fingerprint": "結果を生んだ構成要素・条件の一つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: くずす (Zipf 1.53)']::text[], 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37195, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要因", "is_correct": true, "explanation": "結果を生んだもとの要素を指し、「人為的な要因によって」と続く。"}, {"text": "指輪", "is_correct": false, "explanation": "指にはめる装飾品で、「人為的な指輪によって」は意味をなさない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車券などの紙片で、「人為的な切符によって」は成立しない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花を生ける器で、「人為的な花瓶によって」は不自然。"}], "explanations": {"要因": "結果を生んだもとの要素を指し、「人為的な要因によって」と続く。", "指輪": "指にはめる装飾品で、「人為的な指輪によって」は意味をなさない。", "切符": "乗車券などの紙片で、「人為的な切符によって」は成立しない。", "花瓶": "花を生ける器で、「人為的な花瓶によって」は不自然。"}, "sentence_index": 0, "correct_answer": "要因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その要因は、昨日警察に逮捕された。", "explanation": "ここは〈犯人〉の意味。逮捕されるのは人で、要因は人ではないので合わない。"}, {"text": "昨日買った要因を、庭に植えた。", "explanation": "ここは〈植物〉の意味。植えるのは苗や種で、要因は植えられない。"}, {"text": "この町の要因は、大きな鍋で煮込まれた。", "explanation": "ここは〈料理〉の意味。煮込まれるのは食べ物で、要因は煮込めない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37195, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要因", "is_correct": true, "explanation": "結果の原因となる要素で、「体調をくずす要因の一つだ」と続く。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の出入口で、「体調をくずす玄関の一つだ」は不自然。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に使う紙で、「体調をくずす切手」は成立しない。"}, {"text": "陶器", "is_correct": false, "explanation": "焼き物の器で、「体調をくずす陶器」は意味をなさない。"}], "explanations": {"要因": "結果の原因となる要素で、「体調をくずす要因の一つだ」と続く。", "玄関": "建物の出入口で、「体調をくずす玄関の一つだ」は不自然。", "切手": "郵便に使う紙で、「体調をくずす切手」は成立しない。", "陶器": "焼き物の器で、「体調をくずす陶器」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "要因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しく来た要因は、熱が高くて苦しそうだ。", "explanation": "ここは〈患者〉の意味。熱が高く苦しそうなのは人で、要因は体調を示せない。"}, {"text": "この店の要因は、昨日ぐっすり眠った。", "explanation": "ここは〈生き物〉の意味。眠るのは人や動物で、要因は眠れない。"}, {"text": "駐車場の要因は、一台だけ空いている。", "explanation": "ここは〈駐車スペース〉の意味。空いているのは駐車できる区画で、要因は空いたり埋まったりする場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37195, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "計画が遅れた要因を人手不足だ。", "corrected_sentence": "計画が遅れた要因は人手不足だ。", "error_description": "「要因は〜だ」と主題で示すのが自然。「を」では断定の文として成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37195, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試合中止の要因を、グラウンドの泥だった。", "corrected_sentence": "試合中止の要因は、グラウンドの泥だった。", "error_description": "「要因は〜だ」と主題で示す。「を」では「泥だった」と結べない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
