INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37196, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「低減を目標に」の「を」で、目標にする対象（低減）を示す。"}, {"text": "に", "is_correct": false, "explanation": "「低減に目標に」は「に」が重なって不自然で、対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「低減で目標に」は手段を示すが、目標にする対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「低減へ目標に」は方向を示すが、目標にする対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「低減を目標に」の「を」で、目標にする対象（低減）を示す。", "に": "「低減に目標に」は「に」が重なって不自然で、対象を示せない。", "で": "「低減で目標に」は手段を示すが、目標にする対象にはならない。", "へ": "「低減へ目標に」は方向を示すが、目標にする対象にはならない。"}, "error_tags": {"に": "目的語を示さない", "で": "手段・場所を示す", "へ": "方向を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37196, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを少なくすること。", "primary_collocate": null, "pronunciation": "ていげん", "ipa": "teːɡeɴ", "syllable_count": 4, "sentences": [{"text": "会社は、仕事の無駄をなくしてコストの低減を目指している。", "target_word": "低減", "complexity_tier": "T3", "furigana": "会社(かいしゃ)は、仕事(しごと)の無駄(むだ)をなくしてコストの低減(ていげん)を目指(めざ)している。", "sentence_source": "generated"}, {"text": "新しい機械を入れてから、製品の不良品が低減した。", "target_word": "低減", "complexity_tier": "T3", "furigana": "あたらしいきかいをいれてから、せいひんのふりょうひんがていげんした。", "sentence_source": "generated"}, {"text": "薬を使って、体の痛みを低減する方法がある。", "target_word": "低減", "complexity_tier": "T3", "furigana": "薬(くすり)を使(つか)って、体(からだ)の痛(いた)みを低減(ていげん)する方法(ほうほう)がある。", "sentence_source": "generated"}, {"text": "市は、住民の負担を低減するために、ごみ袋の値段を下げた。", "target_word": "低減", "complexity_tier": "T3", "furigana": "市(し)は、住民(じゅうみん)の負担(ふたん)を低減(ていげん)するために、ごみ袋(ぶくろ)の値段(ねだん)を下(さ)げた。", "sentence_source": "generated"}, {"text": "道を広くしたことで、事故の危険が低減した。", "target_word": "低減", "complexity_tier": "T3", "furigana": "道(みち)を広(ひろ)くしたことで、事故(じこ)の危険(きけん)が低減(ていげん)した。", "sentence_source": "generated"}, {"text": "新しい制度のおかげで、書類の作成にかかる費用が低減された。", "target_word": "低減", "complexity_tier": "T3", "furigana": "あたらしいせいどのおかげで、しょるいのさくせいにかかるひようがていげんされた。", "sentence_source": "generated"}, {"text": "作業を分けると、一人あたりの残業が低減される。", "target_word": "低減", "complexity_tier": "T3", "furigana": "作業(さぎょう)を分(わ)けると、一人(ひとり)あたりの残業(ざんぎょう)が低減(ていげん)される。", "sentence_source": "generated"}, {"text": "店は、売れ残りの低減を考えて、夕方に値引きを始める。", "target_word": "低減", "complexity_tier": "T3", "furigana": "店(みせ)は、売(う)れ残(のこ)りの低減(ていげん)を考(かんが)えて、夕方(ゆうがた)に値引(ねび)きを始(はじ)める。", "sentence_source": "generated"}, {"text": "先生は、テストへの不安を低減させるため、練習問題を配った。", "target_word": "低減", "complexity_tier": "T3", "furigana": "先生(せんせい)は、テストへの不安(ふあん)を低減(ていげん)させるため、練習問題(れんしゅうもんだい)を配(くば)った。", "sentence_source": "generated"}, {"text": "工場では、機械の故障を低減するために、毎週点検をしている。", "target_word": "低減", "complexity_tier": "T3", "furigana": "工場(こうじょう)では、機械(きかい)の故障(こしょう)を低減(ていげん)するために、毎週(まいしゅう)点検(てんけん)をしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "低減する", "label": "終止形"}, {"form": "低減した", "label": "た形"}, {"form": "低減して", "label": "て形"}, {"form": "低減しない", "label": "否定形"}, {"form": "低減される", "label": "受身形"}, {"form": "低減できる", "label": "可能形"}], "register": "中立（普通体）", "sense_fingerprint": "費用・負担・危険など、ある物事を少なくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93788fa0-f2a6-402a-8dac-82f8c6817f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37196, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低減", "is_correct": true, "explanation": "正解。「コストを減らすこと」の意味で、目指す対象として文意に合う。"}, {"text": "完成", "is_correct": false, "explanation": "「コストの完成」は意味が通らない。完成は物事が仕上がることで、費用の増減には使わない。"}, {"text": "上昇", "is_correct": false, "explanation": "「コストの上昇を目指す」は費用を増やす方向になり、無駄をなくす文脈と逆になる。"}, {"text": "遮断", "is_correct": false, "explanation": "「遮断」は流れを断つことで、コストを減らす意味にはならず文脈に合わない。"}], "explanations": {"低減": "正解。「コストを減らすこと」の意味で、目指す対象として文意に合う。", "完成": "「コストの完成」は意味が通らない。完成は物事が仕上がることで、費用の増減には使わない。", "上昇": "「コストの上昇を目指す」は費用を増やす方向になり、無駄をなくす文脈と逆になる。", "遮断": "「遮断」は流れを断つことで、コストを減らす意味にはならず文脈に合わない。"}, "sentence_index": 0, "correct_answer": "低減"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "専門家は、市の交通政策について改善案を低減した。", "explanation": "ここは〈提言〉（意見を申し出る）の意味。読みは同じ「ていげん」だが、低減は量や負担を減らす語なので改善案には使えない。"}, {"text": "寝不足で、約束の時刻を低減した。", "explanation": "時刻は数量や程度ではないので、低減の対象にならない。"}, {"text": "急な雨で、遠足を途中で低減した。", "explanation": "遠足は数量や程度ではないので、低減の対象にならず、途中で打ち切る意味も低減にはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37196, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低減", "is_correct": true, "explanation": "正解。「残業を減らす」の意味で、作業を分けた結果として文意に合う。"}, {"text": "漂白", "is_correct": false, "explanation": "「残業が漂白される」は意味が通らない。漂白は色を抜く作業のことで、残業には使わない。"}, {"text": "解散", "is_correct": false, "explanation": "「残業が解散される」は意味が通らない。解散は集まりを解くことで、残業の量には合わない。"}, {"text": "点灯", "is_correct": false, "explanation": "「残業が点灯される」は明かりをつける意味で、残業の量を表す文脈に合わない。"}], "explanations": {"低減": "正解。「残業を減らす」の意味で、作業を分けた結果として文意に合う。", "漂白": "「残業が漂白される」は意味が通らない。漂白は色を抜く作業のことで、残業には使わない。", "解散": "「残業が解散される」は意味が通らない。解散は集まりを解くことで、残業の量には合わない。", "点灯": "「残業が点灯される」は明かりをつける意味で、残業の量を表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "低減"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校は、来週の体育祭を低減した。", "explanation": "体育祭は数量や程度ではないので、低減の対象にならない。延期の意味も低減にはない。"}, {"text": "市は、住民の声を低減した。", "explanation": "声は数量や程度ではないので、低減の対象にならない。軽視の意味も低減にはない。"}, {"text": "彼は練習で、サッカーの腕前を低減した。", "explanation": "腕前は数量や程度ではないので、低減の対象にならない。上達の意味も低減にはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37196, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、ごみの量に低減するため、袋を有料にした。", "corrected_sentence": "市は、ごみの量を低減するため、袋を有料にした。", "error_description": "低減の対象（量）には「を」を付ける。「量に」は誤りで、正しくは「ごみの量を低減する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37196, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いエアコンを替えて、電気の使用量を低減てた。", "corrected_sentence": "古いエアコンを替えて、電気の使用量を低減した。", "error_description": "「低減」は「低減した」（した形）と活用する。「低減てた」は活用の誤りで、正しくは「低減した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37197, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「低減を進める」の「を」で、進める対象（低減）を示す。"}, {"text": "が", "is_correct": false, "explanation": "「低減が進める」は主語と動詞の組み合わせが不自然で、進める対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「低減と進める」は並列の形になり、動詞の対象にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「低減に進める」は進める対象を示せず、ここでは不自然。"}], "correct_answer": "を", "explanations": {"を": "正解。「低減を進める」の「を」で、進める対象（低減）を示す。", "が": "「低減が進める」は主語と動詞の組み合わせが不自然で、進める対象を示せない。", "と": "「低減と進める」は並列の形になり、動詞の対象にはならない。", "に": "「低減に進める」は進める対象を示せず、ここでは不自然。"}, "error_tags": {"が": "主語を示す", "と": "並列・共同を示す", "に": "対象を示せない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37197, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「低減を目標に」の「を」で、目標にする対象（低減）を示す。"}, {"text": "に", "is_correct": false, "explanation": "「低減に目標に」は「に」が重なって不自然で、対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「低減で目標に」は手段を示すが、目標にする対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「低減へ目標に」は方向を示すが、目標にする対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「低減を目標に」の「を」で、目標にする対象（低減）を示す。", "に": "「低減に目標に」は「に」が重なって不自然で、対象を示せない。", "で": "「低減で目標に」は手段を示すが、目標にする対象にはならない。", "へ": "「低減へ目標に」は方向を示すが、目標にする対象にはならない。"}, "error_tags": {"に": "目的語を示さない", "で": "手段・場所を示す", "へ": "方向を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37197, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数量や程度を減らすこと。特に、環境問題などで使われることが多い。", "primary_collocate": null, "pronunciation": "ていげん", "ipa": "teːɡeɴ", "syllable_count": 4, "sentences": [{"text": "工場は、排出するガスの量を低減する工夫を続けている。", "target_word": "低減", "complexity_tier": "T3", "furigana": "工場(こうじょう)は、排出(はいしゅつ)するガスの量(りょう)を低減(ていげん)する工夫(くふう)を続(つづ)けている。", "sentence_source": "generated"}, {"text": "市は、ごみの低減を進めるため、分別の決まりを厳しくした。", "target_word": "低減", "complexity_tier": "T3", "furigana": "市(し)は、ごみの低減(ていげん)を進(すす)めるため、分別(ぶんべつ)の決(き)まりを厳(きび)しくした。", "sentence_source": "generated"}, {"text": "車を電気自動車に変えると、二酸化炭素の排出が低減される。", "target_word": "低減", "complexity_tier": "T3", "furigana": "車(くるま)を電気自動車(でんきじどうしゃ)に変(か)えると、二酸化炭素(にさんかたんそ)の排出(はいしゅつ)が低減(ていげん)される。", "sentence_source": "generated"}, {"text": "省エネの家電は、電気の使用量を低減し、環境にもやさしい。", "target_word": "低減", "complexity_tier": "T3", "furigana": "省(しょう)エネの家電(かでん)は、電気(でんき)の使用量(しようりょう)を低減(ていげん)し、環境(かんきょう)にもやさしい。", "sentence_source": "generated"}, {"text": "川の水がよごれる原因を調べ、有害な物質の低減に取り組んでいる。", "target_word": "低減", "complexity_tier": "T4", "furigana": "川(かわ)の水(みず)がよごれる原因(げんいん)を調(しら)べ、有害(ゆうがい)な物質(ぶっしつ)の低減(ていげん)に取(と)り組(く)んでいる。", "sentence_source": "generated"}, {"text": "空港の近くでは、飛行機の騒音を低減する工事が行われた。", "target_word": "低減", "complexity_tier": "T3", "furigana": "空港(くうこう)の近(ちか)くでは、飛行機(ひこうき)の騒音(そうおん)を低減(ていげん)する工事(こうじ)が行(おこな)われた。", "sentence_source": "generated"}, {"text": "プラスチックの低減は、海の環境を守るために欠かせない。", "target_word": "低減", "complexity_tier": "T3", "furigana": "プラスチックの低減(ていげん)は、海(うみ)の環境(かんきょう)を守(まも)るために欠(か)かせない。", "sentence_source": "generated"}, {"text": "町は、自動車の排気ガスの低減を目標に、バスの本数を増やした。", "target_word": "低減", "complexity_tier": "T3", "furigana": "町(まち)は、自動車(じどうしゃ)の排気(はいき)ガスの低減(ていげん)を目標(もくひょう)に、バスの本数(ほんすう)を増(ふ)やした。", "sentence_source": "generated"}, {"text": "農家は、農薬の使用を低減して、土と水を守ろうとしている。", "target_word": "低減", "complexity_tier": "T3", "furigana": "農家(のうか)は、農薬(のうやく)の使用(しよう)を低減(ていげん)して、土(つち)と水(みず)を守(まも)ろうとしている。", "sentence_source": "generated"}, {"text": "会議では、温室効果ガスを低減する具体的な計画が話し合われた。", "target_word": "低減", "complexity_tier": "T4", "furigana": "会議(かいぎ)では、温室効果(おんしつこうか)ガスを低減(ていげん)する具体的(ぐたいてき)な計画(けいかく)が話(はな)し合(あ)われた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "低減する", "label": "終止形"}, {"form": "低減した", "label": "た形"}, {"form": "低減して", "label": "て形"}, {"form": "低減しない", "label": "否定形"}, {"form": "低減される", "label": "受身形"}, {"form": "低減できる", "label": "可能形"}], "register": "中立（普通体）", "sense_fingerprint": "排出量・騒音・使用量など、環境にかかわる数量や程度を減らす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T4: contains vocabulary far above tier T4: よごれる (Zipf 1.26)']::text[], '93788fa0-f2a6-402a-8dac-82f8c6817f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37197, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低減", "is_correct": true, "explanation": "正解。「排出するガスの量を減らす工夫」の意味で、文に合う。"}, {"text": "完成", "is_correct": false, "explanation": "「量を完成する工夫」は意味が通らない。完成は仕上げることで、排出量の増減には使わない。"}, {"text": "倍増", "is_correct": false, "explanation": "「量を倍増する工夫」は増やす方向になり、排出を抑える文脈と逆になる。"}, {"text": "開発", "is_correct": false, "explanation": "「量を開発する工夫」は数量に対して新しく作る意味にならず、不自然である。"}], "explanations": {"低減": "正解。「排出するガスの量を減らす工夫」の意味で、文に合う。", "完成": "「量を完成する工夫」は意味が通らない。完成は仕上げることで、排出量の増減には使わない。", "倍増": "「量を倍増する工夫」は増やす方向になり、排出を抑える文脈と逆になる。", "開発": "「量を開発する工夫」は数量に対して新しく作る意味にならず、不自然である。"}, "sentence_index": 0, "correct_answer": "低減"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市民団体は、町に環境政策の改善を低減した。", "explanation": "ここは〈提言〉（意見を申し出る）の意味。読みは同じ「ていげん」だが、低減は量や負担を減らす語なので政策の改善には使えない。"}, {"text": "寝不足で、空の色を低減した。", "explanation": "色は数量や程度ではないので、低減の対象にならない。"}, {"text": "強い風で、花火大会を途中で低減した。", "explanation": "花火大会は数量や程度ではないので、低減の対象にならない。途中で打ち切る意味も低減にはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37197, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低減", "is_correct": true, "explanation": "正解。「プラスチックを減らすこと」の意味で、海を守る文脈に合う。"}, {"text": "漂白", "is_correct": false, "explanation": "「プラスチックの漂白」は意味が通らない。漂白は色を抜く作業で、環境保護には関係しない。"}, {"text": "解散", "is_correct": false, "explanation": "「プラスチックの解散」は意味が通らない。解散は集まりを解くことで、ここでは使えない。"}, {"text": "点灯", "is_correct": false, "explanation": "「プラスチックの点灯」は明かりをつける意味で、文に合わない。"}], "explanations": {"低減": "正解。「プラスチックを減らすこと」の意味で、海を守る文脈に合う。", "漂白": "「プラスチックの漂白」は意味が通らない。漂白は色を抜く作業で、環境保護には関係しない。", "解散": "「プラスチックの解散」は意味が通らない。解散は集まりを解くことで、ここでは使えない。", "点灯": "「プラスチックの点灯」は明かりをつける意味で、文に合わない。"}, "sentence_index": 6, "correct_answer": "低減"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市は、来月の総選挙を低減した。", "explanation": "選挙は数量や程度ではないので、低減の対象にならない。延期の意味も低減にはない。"}, {"text": "父は、家族の意見を低減した。", "explanation": "意見は数量や程度ではないので、低減の対象にならない。軽視の意味も低減にはない。"}, {"text": "彼は練習で、ピアノの腕前を低減した。", "explanation": "腕前は数量や程度ではないので、低減の対象にならない。上達の意味も低減にはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37197, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工場は、排水の汚れに低減するため、設備を入れ替えた。", "corrected_sentence": "工場は、排水の汚れを低減するため、設備を入れ替えた。", "error_description": "減らす対象（汚れ）には「を」を付ける。「汚れに」は誤りで、正しくは「排水の汚れを低減する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37197, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い設備を新しくして、排出ガスの量を低減てた。", "corrected_sentence": "古い設備を新しくして、排出ガスの量を低減した。", "error_description": "「低減」は「低減した」（した形）と活用する。「低減てた」は活用の誤りで、正しくは「低減した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37198, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「乗用として使える」の「として」の「と」で、乗用に直接付いている。"}, {"text": "が", "is_correct": false, "explanation": "「乗用が使える車」は主語の「が」が文の意味に合わない。"}, {"text": "を", "is_correct": false, "explanation": "「乗用を使える車」は目的語の「を」が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「乗用へ使える車」は方向の「へ」が合わない。"}], "correct_answer": "と", "explanations": {"と": "「乗用として使える」の「として」の「と」で、乗用に直接付いている。", "が": "「乗用が使える車」は主語の「が」が文の意味に合わない。", "を": "「乗用を使える車」は目的語の「を」が合わない。", "へ": "「乗用へ使える車」は方向の「へ」が合わない。"}, "error_tags": {"が": "主語の格", "を": "目的語の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37198, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「乗用の方が多く」の「の」で、乗用に直接付いている。"}, {"text": "に", "is_correct": false, "explanation": "「乗用に方が多く」は相手を表す「に」が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「乗用で方が多く」は手段を表す「で」が合わない。"}, {"text": "から", "is_correct": false, "explanation": "「乗用から方が多く」は起点の「から」が合わない。"}], "correct_answer": "の", "explanations": {"の": "「乗用の方が多く」の「の」で、乗用に直接付いている。", "に": "「乗用に方が多く」は相手を表す「に」が合わない。", "で": "「乗用で方が多く」は手段を表す「で」が合わない。", "から": "「乗用から方が多く」は起点の「から」が合わない。"}, "error_tags": {"に": "対象の格", "で": "手段の格", "から": "起点の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37198, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が乗るための車のこと。", "primary_collocate": null, "pronunciation": "じょうよう", "ipa": "dʑoːjoː", "syllable_count": 4, "sentences": [{"text": "この車は乗用で、重い荷物は運べない。", "target_word": "乗用", "complexity_tier": "T3", "furigana": "この車[くるま]は乗用[じょうよう]で、重[おも]い荷物[にもつ]は運[はこ]べない。", "sentence_source": "generated"}, {"text": "父は仕事用ではなく、乗用として使える車を一台買った。", "target_word": "乗用", "complexity_tier": "T3", "furigana": "父(ちち)は仕事用(しごとよう)ではなく、乗用(じょうよう)として使(つか)える車(くるま)を一台(いちだい)買(か)った。", "sentence_source": "generated"}, {"text": "乗用と貨物用では、税金の額が違う。", "target_word": "乗用", "complexity_tier": "T3", "furigana": "乗用[じょうよう]と貨物用[かもつよう]では、税金[ぜいきん]の額[がく]が違[ちが]う。", "sentence_source": "generated"}, {"text": "会社の車は、社員を送るための乗用として使っている。", "target_word": "乗用", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の車[くるま]は、社員[しゃいん]を送[おく]るための乗用[じょうよう]として使[つか]っている。", "sentence_source": "generated"}, {"text": "このバンは乗用にも貨物用にも使える。", "target_word": "乗用", "complexity_tier": "T3", "furigana": "このバンは乗用[じょうよう]にも貨物用[かもつよう]にも使[つか]える。", "sentence_source": "generated"}, {"text": "この車は乗用として、人が楽に座れるように作られている。", "target_word": "乗用", "complexity_tier": "T3", "furigana": "この車(くるま)は乗用(じょうよう)として、人(ひと)が楽(らく)に座(すわ)れるように作(つく)られている。", "sentence_source": "generated"}, {"text": "あれはトラックで乗用ではないから、人は荷台に乗れない。", "target_word": "乗用", "complexity_tier": "T3", "furigana": "あれはトラックで乗用[じょうよう]ではないから、人[ひと]は荷台[にだい]に乗[の]れない。", "sentence_source": "generated"}, {"text": "町では、荷物を運ぶ車より乗用の方が多く走っている。", "target_word": "乗用", "complexity_tier": "T3", "furigana": "町[まち]では、荷物[にもつ]を運[はこ]ぶ車[くるま]より乗用[じょうよう]の方[ほう]が多[おお]く走[はし]っている。", "sentence_source": "generated"}, {"text": "家族が増えたので、乗用として使う広めの車に買い替えた。", "target_word": "乗用", "complexity_tier": "T3", "furigana": "家族(かぞく)が増(ふ)えたので、乗用(じょうよう)として使(つか)う広(ひろ)めの車(くるま)に買(か)い替(か)えた。", "sentence_source": "generated"}, {"text": "乗用として登録した車は、積める荷物の量に制限がある。", "target_word": "乗用", "complexity_tier": "T3", "furigana": "乗用[じょうよう]として登録[とうろく]した車[くるま]は、積[つ]める荷物[にもつ]の量[りょう]に制限[せいげん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "乗用", "label": "基本形"}, {"form": "乗用の", "label": "連体形(の)"}, {"form": "乗用として", "label": "として形"}], "register": "neutral", "sense_fingerprint": "荷物ではなく人が乗ることを目的とした車(用途の区分)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aebd181-359a-45dc-80f8-127f2fbef7ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37198, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乗用", "is_correct": true, "explanation": "「人が乗るための車」の意味で、「この車は乗用で」と合う。"}, {"text": "運転", "is_correct": false, "explanation": "「運転」は車を動かす行為で、「この車は運転で」とは言えない。"}, {"text": "駐車", "is_correct": false, "explanation": "「駐車」は止める行為で、車の種類には使わない。"}, {"text": "整備", "is_correct": false, "explanation": "「整備」は手入れの行為で、車の種類には使わない。"}], "explanations": {"乗用": "「人が乗るための車」の意味で、「この車は乗用で」と合う。", "運転": "「運転」は車を動かす行為で、「この車は運転で」とは言えない。", "駐車": "「駐車」は止める行為で、車の種類には使わない。", "整備": "「整備」は手入れの行為で、車の種類には使わない。"}, "sentence_index": 0, "correct_answer": "乗用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社の車は、荷物を運ぶための乗用として使っている。", "explanation": "ここは〈貨物〉の意味。乗用は人を運ぶ車を指し、荷物を運ぶ車には貨物を使う。"}, {"text": "会社の車は、社員を送るための乗車として使っている。", "explanation": "ここは〈乗車〉の意味。乗ることは乗車で、車の区分を表す乗用とは合わない。"}, {"text": "会社の船は、社員を送るための乗用として使っている。", "explanation": "ここは〈船舶〉の意味。乗用は自動車の区分を表す語で、船舶には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37198, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乗用", "is_correct": true, "explanation": "「人が乗るための車」の意味で、トラックとの対比に合う。"}, {"text": "燃料", "is_correct": false, "explanation": "「燃料」は動力の材料で、車の種類ではない。"}, {"text": "検査", "is_correct": false, "explanation": "「検査」は調べる行為で、車の種類ではない。"}, {"text": "休業", "is_correct": false, "explanation": "「休業」は仕事を止める意味で、車の種類ではない。"}], "explanations": {"乗用": "「人が乗るための車」の意味で、トラックとの対比に合う。", "燃料": "「燃料」は動力の材料で、車の種類ではない。", "検査": "「検査」は調べる行為で、車の種類ではない。", "休業": "「休業」は仕事を止める意味で、車の種類ではない。"}, "sentence_index": 6, "correct_answer": "乗用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この救急車は乗用として、患者を病院へ運んでいる。", "explanation": "ここは〈特殊車両〉の意味。患者搬送のような特定用途の車には乗用を使わず、乗用は一般の人を運ぶ自動車の区分を表す。"}, {"text": "この電車は乗用なので、ドアが多い。", "explanation": "ここは〈鉄道車両〉の意味。鉄道の車両には乗用を使わず、乗用は自動車の区分を表す語。"}, {"text": "この飛行機は乗用として登録したので、座席を増やせる。", "explanation": "ここは〈航空機〉の意味。飛行機は航空機で、乗用は自動車の区分に使う語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37198, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この車は乗用を、家族で出かけるのに便利だ。", "corrected_sentence": "この車は乗用で、家族で出かけるのに便利だ。", "error_description": "誤りは「乗用を」の「を」。「乗用」は車の種類を表す名詞で、ここでは目的語になれず「で」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37198, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "乗用だ車は、四人まで乗れる。", "corrected_sentence": "乗用の車は、四人まで乗れる。", "error_description": "誤りは「乗用だ車」の「だ」。名詞を車の前に置いて修飾するには「乗用の車」にする。「だ」は連体修飾に使えず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37200, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37200, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈心配する〉の対象である〈酸化〉を〈を〉で示す。〈酸化を心配して〉が自然な形。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉を使うと〈酸化に心配して〉となり、心配の対象の示し方として不自然で文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は相手や引用を示す助詞なので、心配の対象である〈酸化〉には続かない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す助詞なので、心配する対象を表す位置には使えない。"}], "correct_answer": "を", "explanations": {"を": "〈心配する〉の対象である〈酸化〉を〈を〉で示す。〈酸化を心配して〉が自然な形。", "に": "〈に〉を使うと〈酸化に心配して〉となり、心配の対象の示し方として不自然で文が成り立たない。", "と": "〈と〉は相手や引用を示す助詞なので、心配の対象である〈酸化〉には続かない。", "へ": "〈へ〉は方向を示す助詞なので、心配する対象を表す位置には使えない。"}, "error_tags": {"に": "帰着・位置", "と": "共同・引用", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37200, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物が酸素と結びつくこと。", "primary_collocate": null, "pronunciation": "さんか", "ipa": "saŋka", "syllable_count": 3, "sentences": [{"text": "切ったりんごは酸化して、すぐ茶色くなる。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "切[き]ったりんごは酸化[さんか]して、すぐ茶色[ちゃいろ]くなる。", "sentence_source": "generated"}, {"text": "油が酸化すると、嫌なにおいが出る。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "油[あぶら]が酸化[さんか]すると、嫌[いや]なにおいが出[で]る。", "sentence_source": "generated"}, {"text": "酸化を防ぐために、お茶の葉は袋に入れて空気を抜く。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "酸化[さんか]を防[ふせ]ぐために、お茶[ちゃ]の葉[は]は袋[ふくろ]に入[い]れて空気[くうき]を抜[ぬ]く。", "sentence_source": "generated"}, {"text": "開けたワインを放っておくと、酸化が進んで味が落ちる。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "開[あ]けたワインを放[ほう]っておくと、酸化[さんか]が進[すす]んで味[あじ]が落[お]ちる。", "sentence_source": "generated"}, {"text": "銅の十円玉が古くなって茶色いのは、酸化したからだ。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "銅[どう]の十円玉[じゅうえんだま]が古[ふる]くなって茶色[ちゃいろ]いのは、酸化[さんか]したからだ。", "sentence_source": "generated"}, {"text": "空気に触れる時間が長いほど、果物の酸化は早く進む。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "空気[くうき]に触[ふ]れる時間[じかん]が長[なが]いほど、果物[くだもの]の酸化[さんか]は早[はや]く進[すす]む。", "sentence_source": "generated"}, {"text": "バナナの皮が黒くなるのは、酸化が起きているからだ。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "バナナの皮[かわ]が黒[くろ]くなるのは、酸化[さんか]が起[お]きているからだ。", "sentence_source": "generated"}, {"text": "母は油の酸化を心配して、小さい瓶のものを買う。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "母[はは]は油[あぶら]の酸化[さんか]を心配[しんぱい]して、小[ちい]さい瓶[びん]のものを買[か]う。", "sentence_source": "generated"}, {"text": "缶詰は中に空気がないので、酸化しにくい。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "缶詰[かんづめ]は中[なか]に空気[くうき]がないので、酸化[さんか]しにくい。", "sentence_source": "generated"}, {"text": "切ったアボカドにレモン汁をかけると、酸化が遅くなる。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "切[き]ったアボカドにレモン汁[じる]をかけると、酸化[さんか]が遅[おそ]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "酸化", "label": "基本形"}, {"form": "酸化する", "label": "辞書形"}, {"form": "酸化した", "label": "過去形"}, {"form": "酸化して", "label": "て形"}, {"form": "酸化しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "食べ物や油などが空気中の酸素と結びついて変質すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f35ae2-3626-49c3-8754-26766e35d357') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37200, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酸化", "is_correct": true, "explanation": "物が酸素と結びついて変化する〈酸化〉。切ったりんごが茶色くなる変化を表す。"}, {"text": "冷凍", "is_correct": false, "explanation": "冷凍は凍らせることで、すぐ茶色くなる変化の説明にはならない。"}, {"text": "包装", "is_correct": false, "explanation": "包装は包むことで、茶色くなる変化の原因にはならない。"}, {"text": "洗浄", "is_correct": false, "explanation": "洗浄は洗うことで、茶色くなる変化の説明には合わない。"}], "explanations": {"酸化": "物が酸素と結びついて変化する〈酸化〉。切ったりんごが茶色くなる変化を表す。", "冷凍": "冷凍は凍らせることで、すぐ茶色くなる変化の説明にはならない。", "包装": "包装は包むことで、茶色くなる変化の原因にはならない。", "洗浄": "洗浄は洗うことで、茶色くなる変化の説明には合わない。"}, "sentence_index": 0, "correct_answer": "酸化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ヨーグルトは乳酸菌の働きで酸化する。", "explanation": "ここは〈発酵〉の意味。乳酸菌の働きで糖などが変化するのは発酵。酸化は物が酸素と結びつく変化なので合わない。"}, {"text": "レモン汁は酸化だ。", "explanation": "ここは〈酸性〉の意味。レモン汁の性質を表すのは酸性。酸化は酸素と結びつく変化の名前で、性質を表す言葉としては使わない。"}, {"text": "胃で食べ物を酸化する。", "explanation": "ここは〈消化〉の意味。胃で食べ物を分解するのは消化。酸化は酸素と結びつく変化なので、胃の働きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37200, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酸化", "is_correct": true, "explanation": "物が酸素と結びつく変化を表す〈酸化〉。皮が黒くなる原因はこれ。"}, {"text": "発光", "is_correct": false, "explanation": "光を出すことで、皮が黒くなる原因にはならない。"}, {"text": "結晶化", "is_correct": false, "explanation": "結晶化は固まって結晶になることで、皮の変化とは合わない。"}, {"text": "発芽", "is_correct": false, "explanation": "発芽は種が芽を出すことで、バナナの皮の変化には合わない。"}], "explanations": {"酸化": "物が酸素と結びつく変化を表す〈酸化〉。皮が黒くなる原因はこれ。", "発光": "光を出すことで、皮が黒くなる原因にはならない。", "結晶化": "結晶化は固まって結晶になることで、皮の変化とは合わない。", "発芽": "発芽は種が芽を出すことで、バナナの皮の変化には合わない。"}, "sentence_index": 6, "correct_answer": "酸化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水が酸化すると湯気が出る。", "explanation": "ここは〈蒸発〉の意味。液体が気体になる現象は蒸発。酸化は酸素との結合なので、湯気を出す現象には合わない。"}, {"text": "寒さで道路が酸化した。", "explanation": "ここは〈凍結〉の意味。寒さで水分が固まり道路が凍るのは凍結。酸化は酸素と結びつく変化なので、寒さによる変化には使わない。"}, {"text": "部屋の酸化が薄くなった。", "explanation": "ここは〈酸素〉の意味。空気中で薄くなるのは酸素。酸化は変化の名前なので、濃さや薄さの対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37200, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この鉄くぎは湿気で酸化に赤くなった。", "corrected_sentence": "この鉄くぎは湿気で酸化して赤くなった。", "error_description": "形の誤り。〈酸化して〉が正しい。〈酸化に〉では後ろの〈赤くなった〉に続かず、動詞〈酸化する〉の連用形〈酸化して〉が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37200, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ふたをして空気を遮り、酸化に防ぐ。", "corrected_sentence": "ふたをして空気を遮り、酸化を防ぐ。", "error_description": "助詞の誤り。〈防ぐ〉は対象を〈を〉で示すので、〈酸化を防ぐ〉が正しい。〈酸化に〉では〈防ぐ〉の目的語にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37201, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「燃える酸化」と「実験」をつなぎ、酸化を扱う実験という連体修飾になる。"}, {"text": "が", "is_correct": false, "explanation": "「酸化が実験を見た」となり、酸化が見る主語になって文が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「酸化を実験を見た」と目的語が二つ並んで、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「酸化に実験」では名詞同士をつなぐ働きが合わず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「燃える酸化」と「実験」をつなぎ、酸化を扱う実験という連体修飾になる。", "が": "「酸化が実験を見た」となり、酸化が見る主語になって文が通らない。", "を": "「酸化を実験を見た」と目的語が二つ並んで、文が成り立たない。", "に": "「酸化に実験」では名詞同士をつなぐ働きが合わず、文が成り立たない。"}, "error_tags": {"の": "連体修飾", "が": "主語", "を": "目的語", "に": "着点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "還元", "is_correct": true, "explanation": "酸化の対義語で、酸素を失う、または水素を得る反応を指し、酸化と逆の変化。"}, {"text": "発酵", "is_correct": false, "explanation": "微生物の働きで物質が変わる現象で、酸化の対義語ではない。"}, {"text": "分解", "is_correct": false, "explanation": "物質が成分に分かれる変化で、酸化と対になる語ではない。"}, {"text": "結晶", "is_correct": false, "explanation": "物質が規則正しく固まる現象で、酸化の対義語ではない。"}], "correct_answer": "還元", "explanations": {"還元": "酸化の対義語で、酸素を失う、または水素を得る反応を指し、酸化と逆の変化。", "発酵": "微生物の働きで物質が変わる現象で、酸化の対義語ではない。", "分解": "物質が成分に分かれる変化で、酸化と対になる語ではない。", "結晶": "物質が規則正しく固まる現象で、酸化の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37201, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "還元", "is_correct": true, "explanation": "酸化の対義語で、酸素を失う、または水素を得る反応を指し、酸化と逆の変化。"}, {"text": "蒸発", "is_correct": false, "explanation": "液体が気体になる現象で、酸化の対義語ではない。"}, {"text": "合成", "is_correct": false, "explanation": "複数の物質を結びつけて新しい物質を作ることで、酸化の対義語ではない。"}, {"text": "凝集", "is_correct": false, "explanation": "粒子が寄り集まる現象で、酸化の対義語ではない。"}], "correct_answer": "還元", "explanations": {"還元": "酸化の対義語で、酸素を失う、または水素を得る反応を指し、酸化と逆の変化。", "蒸発": "液体が気体になる現象で、酸化の対義語ではない。", "合成": "複数の物質を結びつけて新しい物質を作ることで、酸化の対義語ではない。", "凝集": "粒子が寄り集まる現象で、酸化の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37201, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物質が酸素と結合する化学反応。さびたり燃えたりする変化。", "primary_collocate": null, "pronunciation": "さんか", "ipa": "saŋka", "syllable_count": 3, "sentences": [{"text": "鉄が空気中の酸素と結びつく酸化で、さびができる。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "鉄[てつ]が空気中[くうきちゅう]の酸素[さんそ]と結[むす]びつく酸化[さんか]で、さびができる。", "sentence_source": "generated"}, {"text": "授業で、マグネシウムが燃える酸化の実験を見た。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で、マグネシウムが燃[も]える酸化[さんか]の実験[じっけん]を見[み]た。", "sentence_source": "generated"}, {"text": "酸化が起きると、金属の表面の色が変わる。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "酸化[さんか]が起[お]きると、金属[きんぞく]の表面[ひょうめん]の色[いろ]が変[か]わる。", "sentence_source": "generated"}, {"text": "自転車を雨の中に置いたら、酸化が進んでフレームがさびた。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]を雨[あめ]の中[なか]に置[お]いたら、酸化[さんか]が進[すす]んでフレームがさびた。", "sentence_source": "generated"}, {"text": "火が燃えるのも、急激な酸化の一つだ。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "火[ひ]が燃[も]えるのも、急激[きゅうげき]な酸化[さんか]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "銀の食器は、時間がたつと酸化して黒くなる。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "銀[ぎん]の食器[しょっき]は、時間[じかん]がたつと酸化[さんか]して黒[くろ]くなる。", "sentence_source": "generated"}, {"text": "化学の試験で、酸化の反応式を書く問題が出た。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "化学[かがく]の試験[しけん]で、酸化[さんか]の反応式[はんのうしき]を書[か]く問題[もんだい]が出[で]た。", "sentence_source": "generated"}, {"text": "水に濡れた釘が酸化して、赤茶色になった。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "水[みず]に濡[ぬ]れた釘[くぎ]が酸化[さんか]して、赤茶色[あかちゃいろ]になった。", "sentence_source": "generated"}, {"text": "鉄の橋は酸化を防ぐために、定期的に塗装される。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "鉄[てつ]の橋[はし]は酸化[さんか]を防[ふせ]ぐために、定期的[ていきてき]に塗装[とそう]される。", "sentence_source": "generated"}, {"text": "アルミニウムの表面は酸化すると薄い膜ができ、中を守る。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "アルミニウムの表面[ひょうめん]は酸化[さんか]すると薄[うす]い膜[まく]ができ、中[なか]を守[まも]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "酸化", "label": "基本形"}, {"form": "酸化する", "label": "辞書形"}, {"form": "酸化した", "label": "過去形"}, {"form": "酸化して", "label": "て形"}, {"form": "酸化しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "金属がさびる、物が燃えるなど、物質が酸素と結合する化学反応", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f35ae2-3626-49c3-8754-26766e35d357') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37201, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酸化", "is_correct": true, "explanation": "酸素と結びつく化学反応を表し、鉄がさびる文の説明に合う。"}, {"text": "溶解", "is_correct": false, "explanation": "物質が液体に溶ける現象で、酸素との結合を表さないため、さびの文には合わない。"}, {"text": "膨張", "is_correct": false, "explanation": "体積が大きくなる現象で、酸素と結びつく反応を表さないため、さびの文には合わない。"}, {"text": "凝固", "is_correct": false, "explanation": "液体が固まる現象で、酸素と結びつく反応ではないため、さびの文には合わない。"}], "explanations": {"酸化": "酸素と結びつく化学反応を表し、鉄がさびる文の説明に合う。", "溶解": "物質が液体に溶ける現象で、酸素との結合を表さないため、さびの文には合わない。", "膨張": "体積が大きくなる現象で、酸素と結びつく反応を表さないため、さびの文には合わない。", "凝固": "液体が固まる現象で、酸素と結びつく反応ではないため、さびの文には合わない。"}, "sentence_index": 0, "correct_answer": "酸化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空気中の酸化が多いと、呼吸が楽になる。", "explanation": "ここは〈酸素〉の意味。酸化は物質が酸素と結合する化学反応で、空気の成分そのものは指さないので合わない。"}, {"text": "妹は酸化の病棟で働いている。", "explanation": "ここは同音異義語〈産科〉の意味。酸化は化学反応を表し、診療科は指さないので合わない。"}, {"text": "このレモンは酸化が強すぎて、そのまま食べられない。", "explanation": "ここは〈酸味〉の意味。レモンのすっぱさを表すのは酸味で、酸素と結合する化学反応の酸化とは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37201, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酸化", "is_correct": true, "explanation": "酸素との結合を表す化学反応の語で、反応式の対象として文に合う。"}, {"text": "沸騰", "is_correct": false, "explanation": "液体が沸いて気体になる物理変化で、反応式の対象としては合わない。"}, {"text": "振動", "is_correct": false, "explanation": "物体が揺れる運動で、化学反応ではないため反応式の対象にならない。"}, {"text": "摩擦", "is_correct": false, "explanation": "こすれ合って熱や摩耗が生じる現象で、化学反応の式の対象としては合わない。"}], "explanations": {"酸化": "酸素との結合を表す化学反応の語で、反応式の対象として文に合う。", "沸騰": "液体が沸いて気体になる物理変化で、反応式の対象としては合わない。", "振動": "物体が揺れる運動で、化学反応ではないため反応式の対象にならない。", "摩擦": "こすれ合って熱や摩耗が生じる現象で、化学反応の式の対象としては合わない。"}, "sentence_index": 6, "correct_answer": "酸化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗濯物は、風が強いと早く酸化する。", "explanation": "ここは〈乾燥〉の意味。水分が抜けて乾く現象で、酸素と結びつく酸化とは別なので合わない。"}, {"text": "扇風機を回して、部屋を酸化した。", "explanation": "ここは〈冷却〉の意味。部屋の温度を下げる働きを表すので、酸素と結びつく酸化は合わない。"}, {"text": "氷は室温に置くと、酸化して水になる。", "explanation": "ここは〈融解〉の意味。固体が熱で液体になる現象なので、酸素との結合を表す酸化は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37201, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鍋の底は、火にかけすぎると酸化を焦げ色になる。", "corrected_sentence": "鍋の底は、火にかけすぎると酸化して焦げ色になる。", "error_description": "酸化はサ変名詞なので、後ろは「して」で続ける。「酸化を」の「を」は誤りで、「酸化を焦げ色になる」は文として成り立たない。正しくは「酸化して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37201, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋外の鉄製品は、湿気で酸化するて赤くなる。", "corrected_sentence": "屋外の鉄製品は、湿気で酸化して赤くなる。", "error_description": "酸化はサ変名詞なので、て形は「酸化して」になる。「酸化するて」は活用の誤りで、正しくは「酸化して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
