INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37202, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても小さいこと。", "primary_collocate": null, "pronunciation": "びしょう", "ipa": "biɕoː", "syllable_count": 3, "sentences": [{"text": "この昆虫は微小で、肉眼ではほとんど見えない。", "target_word": "微小", "complexity_tier": "T3", "furigana": "この昆虫(こんちゅう)は微小(びしょう)で、肉眼(にくがん)ではほとんど見(み)えない。", "sentence_source": "generated"}, {"text": "地震計は、地面の微小な揺れも記録する。", "target_word": "微小", "complexity_tier": "T3", "furigana": "地震計(じしんけい)は、地面(じめん)の微小(びしょう)な揺(ゆ)れも記録(きろく)する。", "sentence_source": "generated"}, {"text": "微小な生き物の世界を、写真で紹介する本を買った。", "target_word": "微小", "complexity_tier": "T3", "furigana": "微小(びしょう)な生(い)き物(もの)の世界(せかい)を、写真(しゃしん)で紹介(しょうかい)する本(ほん)を買(か)った。", "sentence_source": "generated"}, {"text": "微小な差だったので、審判も判断に迷った。", "target_word": "微小", "complexity_tier": "T3", "furigana": "微小(びしょう)な差(さ)だったので、審判(しんぱん)も判断(はんだん)に迷(まよ)った。", "sentence_source": "generated"}, {"text": "薬の量は微小なので、体にはほとんど影響がない。", "target_word": "微小", "complexity_tier": "T3", "furigana": "薬(くすり)の量(りょう)は微小(びしょう)なので、体(からだ)にはほとんど影響(えいきょう)がない。", "sentence_source": "generated"}, {"text": "微小な粒子を取り除くために、特別なフィルターを使う。", "target_word": "微小", "complexity_tier": "T3", "furigana": "微小(びしょう)な粒子(りゅうし)を取(と)り除(のぞ)くために、特別(とくべつ)なフィルターを使(つか)う。", "sentence_source": "generated"}, {"text": "画面の微小な傷が、光の下でだけ見えた。", "target_word": "微小", "complexity_tier": "T3", "furigana": "画面(がめん)の微小(びしょう)な傷(きず)が、光(ひかり)の下(した)でだけ見(み)えた。", "sentence_source": "generated"}, {"text": "収入の増え方は微小で、生活はあまり楽にならなかった。", "target_word": "微小", "complexity_tier": "T3", "furigana": "収入(しゅうにゅう)の増(ふ)え方(かた)は微小(びしょう)で、生活(せいかつ)はあまり楽(らく)にならなかった。", "sentence_source": "generated"}, {"text": "その星の光は微小だが、望遠鏡なら確認できる。", "target_word": "微小", "complexity_tier": "T3", "furigana": "その星(ほし)の光(ひかり)は微小(びしょう)だが、望遠鏡(ぼうえんきょう)なら確認(かくにん)できる。", "sentence_source": "generated"}, {"text": "微小な電流を測る機械を、研究室で使っている。", "target_word": "微小", "complexity_tier": "T3", "furigana": "微小(びしょう)な電流(でんりゅう)を測(はか)る機械(きかい)を、研究室(けんきゅうしつ)で使(つか)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "微小だ", "label": "終止形"}, {"form": "微小な", "label": "連体形"}, {"form": "微小に", "label": "連用形"}, {"form": "微小で", "label": "連用形（て形）"}], "register": "formal", "sense_fingerprint": "微小: very small in size or amount (minute)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229fb64a-60c4-458a-8173-9276c7aa12bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37202, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微小", "is_correct": true, "explanation": "「微小で」の形で、極めて小さい様子を表す。文脈に合う唯一の語。"}, {"text": "高価", "is_correct": false, "explanation": "高価は値段が高いことで、大きさを表さない。"}, {"text": "豪快", "is_correct": false, "explanation": "豪快は勢いの大きさを表し、昆虫の大きさには合わない。"}, {"text": "悲惨", "is_correct": false, "explanation": "悲惨は痛ましい様子で、大きさの話とは合わない。"}], "explanations": {"微小": "「微小で」の形で、極めて小さい様子を表す。文脈に合う唯一の語。", "高価": "高価は値段が高いことで、大きさを表さない。", "豪快": "豪快は勢いの大きさを表し、昆虫の大きさには合わない。", "悲惨": "悲惨は痛ましい様子で、大きさの話とは合わない。"}, "sentence_index": 0, "correct_answer": "微小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "収入は微小ずつ増えていった。", "explanation": "〈徐々に〉の意味。微小は大きさの極小を表し、少しずつ増える様子を言う語としては使わない。"}, {"text": "この部屋は微小で、家族四人が住める。", "explanation": "〈広い〉の意味。微小な空間では家族四人は住めず、話が矛盾する。"}, {"text": "あの建物は微小で、街のどこからも見える。", "explanation": "〈巨大〉の意味。微小な建物は街から見えないはずで、話の筋が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37202, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微小", "is_correct": true, "explanation": "「微小な傷」で、極めて小さく目立たない様子を表す。文脈に合う唯一の語。"}, {"text": "豪華", "is_correct": false, "explanation": "豪華は華やかで贅沢な様子で、傷の小ささには合わない。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈は丈夫さを表し、傷の大きさを述べられない。"}, {"text": "活発", "is_correct": false, "explanation": "活発は動きの盛んさを表し、傷の話には合わない。"}], "explanations": {"微小": "「微小な傷」で、極めて小さく目立たない様子を表す。文脈に合う唯一の語。", "豪華": "豪華は華やかで贅沢な様子で、傷の小ささには合わない。", "頑丈": "頑丈は丈夫さを表し、傷の大きさを述べられない。", "活発": "活発は動きの盛んさを表し、傷の話には合わない。"}, "sentence_index": 6, "correct_answer": "微小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大量の注文が来て、微小な忙しさになった。", "explanation": "〈わずか〉の意味。微小は極めて小さいことで、注文が大量に来た後の忙しさを表すには合わない。"}, {"text": "微小な声援が球場に響き渡った。", "explanation": "〈大声〉の意味。微小は極めて小さいことなので、球場に響くほどの声の大きさとは合わない。"}, {"text": "その村の人口は微小で、大きな町よりにぎやかだ。", "explanation": "〈多い〉の意味。人口が微小なら大きな町よりにぎやかとは言えず、矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37202, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この実験では微小に量の薬品を使う。", "corrected_sentence": "この実験では微小な量の薬品を使う。", "error_description": "名詞「量」を修飾するので連体形「微小な」が必要。連用形「微小に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "微小", "is_correct": true, "explanation": "「微小な」の語幹。連体形の形の元になる部分。"}, {"text": "微小だ", "is_correct": false, "explanation": "終止形で、名詞を直接修飾しない。"}, {"text": "微小に", "is_correct": false, "explanation": "連用形で、動詞や形容詞を修飾する形。"}, {"text": "微小で", "is_correct": false, "explanation": "て形で、文を続ける接続に使う形。"}], "correct_form": "微小", "base_form": "微小だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"微小": "「微小な」の語幹。連体形の形の元になる部分。", "微小だ": "終止形で、名詞を直接修飾しない。", "微小に": "連用形で、動詞や形容詞を修飾する形。", "微小で": "て形で、文を続ける接続に使う形。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37202, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "微小の量の電解液を、実験に使った。", "corrected_sentence": "微小な量の電解液を、実験に使った。", "error_description": "名詞「量」を修飾するので連体形「微小な」が必要。「微小の」は誤り（な→の）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "微小", "is_correct": true, "explanation": "「微小で」の語幹。活用の元になる部分。"}, {"text": "微小だった", "is_correct": false, "explanation": "過去形で、文末の述語として使う形。"}, {"text": "微小である", "is_correct": false, "explanation": "文語的な断定の形で、名詞を直接修飾しない。"}, {"text": "微小だろう", "is_correct": false, "explanation": "推量の形で、ここでは文を続ける形として合わない。"}], "correct_form": "微小", "base_form": "微小だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"微小": "「微小で」の語幹。活用の元になる部分。", "微小だった": "過去形で、文末の述語として使う形。", "微小である": "文語的な断定の形で、名詞を直接修飾しない。", "微小だろう": "推量の形で、ここでは文を続ける形として合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
