INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37203, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ごく小さいこと。または、目に見えないほど小さいこと。", "primary_collocate": null, "pronunciation": "びしょう", "ipa": "biɕoː", "syllable_count": 3, "sentences": [{"text": "我々大人が往々にして見落とす微小な営みを、彼は無心に、そして厳粛に刻み続けているのである。", "target_word": "微小", "complexity_tier": "T4", "furigana": "我々(われわれ)大人(おとな)が往々(おうおう)にして見落(みお)とす微小(びしょう)な営(いとな)みを、彼(かれ)は無心(むしん)に、そして厳粛(げんしゅく)に刻(きざ)み続(つづ)けているのである。", "sentence_source": "mined"}, {"text": "顕微鏡で見ると、水の中に微小な生物がたくさんいた。", "target_word": "微小", "complexity_tier": "T3", "furigana": "顕微鏡(けんびきょう)で見(み)ると、水(みず)の中(なか)に微小(びしょう)な生物(せいぶつ)がたくさんいた。", "sentence_source": "generated"}, {"text": "この装置は、微小な振動も逃さずに測定できる。", "target_word": "微小", "complexity_tier": "T3", "furigana": "この装置(そうち)は、微小(びしょう)な振動(しんどう)も逃(のが)さずに測定(そくてい)できる。", "sentence_source": "generated"}, {"text": "計算の誤差は微小なので、結果にはほとんど影響しない。", "target_word": "微小", "complexity_tier": "T3", "furigana": "計算(けいさん)の誤差(ごさ)は微小(びしょう)なので、結果(けっか)にはほとんど影響(えいきょう)しない。", "sentence_source": "generated"}, {"text": "微小な傷でも、精密機械には大きな問題になることがある。", "target_word": "微小", "complexity_tier": "T3", "furigana": "微小(びしょう)な傷(きず)でも、精密機械(せいみつきかい)には大(おお)きな問題(もんだい)になることがある。", "sentence_source": "generated"}, {"text": "空気中には、目に見えない微小な粒が浮かんでいる。", "target_word": "微小", "complexity_tier": "T3", "furigana": "空気中(くうきちゅう)には、目(め)に見(み)えない微小(びしょう)な粒(つぶ)が浮(う)かんでいる。", "sentence_source": "generated"}, {"text": "温度の変化は微小だったが、実験には十分な差だった。", "target_word": "微小", "complexity_tier": "T3", "furigana": "温度(おんど)の変化(へんか)は微小(びしょう)だったが、実験(じっけん)には十分(じゅうぶん)な差(さ)だった。", "sentence_source": "generated"}, {"text": "彼は微小な部品を、ピンセットで丁寧に取り付けた。", "target_word": "微小", "complexity_tier": "T3", "furigana": "彼(かれ)は微小(びしょう)な部品(ぶひん)を、ピンセットで丁寧(ていねい)に取(と)り付(つ)けた。", "sentence_source": "generated"}, {"text": "微小な隙間から水が入り、書類が濡れてしまった。", "target_word": "微小", "complexity_tier": "T3", "furigana": "微小(びしょう)な隙間(すきま)から水(みず)が入(はい)り、書類(しょるい)が濡(ぬ)れてしまった。", "sentence_source": "generated"}, {"text": "微小な違いに気づく観察力が、研究者には必要だ。", "target_word": "微小", "complexity_tier": "T3", "furigana": "微小(びしょう)な違(ちが)いに気(き)づく観察力(かんさつりょく)が、研究者(けんきゅうしゃ)には必要(ひつよう)だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "微小だ", "label": "終止形"}, {"form": "微小な", "label": "連体形"}, {"form": "微小に", "label": "連用形"}, {"form": "微小で", "label": "連用形（て形）"}], "register": "formal", "sense_fingerprint": "微小: extremely small, even too small to see (minute)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229fb64a-60c4-458a-8173-9276c7aa12bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37203, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微小", "is_correct": true, "explanation": "「微小な営み」で、極めて小さく目に留まりにくい様子を表す。文脈に合う唯一の語。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は人の気質を表し、「営み」の小ささを述べられない。"}, {"text": "清潔", "is_correct": false, "explanation": "清潔は汚れがないことで、大きさを表さない。"}, {"text": "鮮明", "is_correct": false, "explanation": "鮮明は輪郭のはっきりした様子で、営みの小ささとは合わない。"}], "explanations": {"微小": "「微小な営み」で、極めて小さく目に留まりにくい様子を表す。文脈に合う唯一の語。", "陽気": "陽気は人の気質を表し、「営み」の小ささを述べられない。", "清潔": "清潔は汚れがないことで、大きさを表さない。", "鮮明": "鮮明は輪郭のはっきりした様子で、営みの小ささとは合わない。"}, "sentence_index": 0, "correct_answer": "微小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この靴は微小で、子どもにはぴったりだ。", "explanation": "〈小型〉の意味。微小は肉眼で見えないほどの極小を表し、靴の大きさには使わない。"}, {"text": "あの橋は微小で、船が下を通れない。", "explanation": "〈巨大〉の意味。橋を微小とすると、船が通れないという話の筋が矛盾する。"}, {"text": "この草原は微小で、どこまでも続いている。", "explanation": "〈広大〉の意味。微小は極めて小さいことで、どこまでも続く広がりには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37203, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微小", "is_correct": true, "explanation": "「微小だった」で、変化の小ささを述べる。文脈に合う唯一の語。"}, {"text": "華麗", "is_correct": false, "explanation": "華麗は派手で美しい様子で、温度の変化には合わない。"}, {"text": "快適", "is_correct": false, "explanation": "快適は心地よさを表し、変化の大きさを述べられない。"}, {"text": "厳格", "is_correct": false, "explanation": "厳格は厳しさを表し、温度の変化とは合わない。"}], "explanations": {"微小": "「微小だった」で、変化の小ささを述べる。文脈に合う唯一の語。", "華麗": "華麗は派手で美しい様子で、温度の変化には合わない。", "快適": "快適は心地よさを表し、変化の大きさを述べられない。", "厳格": "厳格は厳しさを表し、温度の変化とは合わない。"}, "sentence_index": 6, "correct_answer": "微小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は微小な大金を、一晩で使い果たした。", "explanation": "〈莫大〉の意味。微小は極めて小さいことを表す語で、大金の大きさには使わない。"}, {"text": "彼の声は微小で、会場中に響き渡った。", "explanation": "〈大声〉の意味。微小は極めて小さいことなので、会場に響く声には合わない。"}, {"text": "参加者の人数が微小で、会場がいっぱいになった。", "explanation": "〈多数〉の意味。人数が微小なら会場はいっぱいにならず、話の筋が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37203, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "顕微鏡は、細胞の微小に動きも映し出す。", "corrected_sentence": "顕微鏡は、細胞の微小な動きも映し出す。", "error_description": "後ろの名詞「動き」を修飾するので連体形「微小な」が必要。連用形「微小に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "微小", "is_correct": true, "explanation": "「微小な」の語幹。連体形の「微小な」の形の元になる部分。"}, {"text": "微小だ", "is_correct": false, "explanation": "終止形で、名詞を直接修飾しない。"}, {"text": "微小に", "is_correct": false, "explanation": "連用形で、動詞や形容詞を修飾する形。"}, {"text": "微小で", "is_correct": false, "explanation": "て形で、文を続ける接続に使う形。"}], "correct_form": "微小", "base_form": "微小だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"微小": "「微小な」の語幹。連体形の「微小な」の形の元になる部分。", "微小だ": "終止形で、名詞を直接修飾しない。", "微小に": "連用形で、動詞や形容詞を修飾する形。", "微小で": "て形で、文を続ける接続に使う形。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37203, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "微小だ粒子が、空気中に浮かんでいる。", "corrected_sentence": "微小な粒子が、空気中に浮かんでいる。", "error_description": "名詞「粒子」を修飾するので連体形「微小な」が必要。終止形「微小だ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "微小", "is_correct": true, "explanation": "「微小な」の語幹。連体形の形の元になる部分。"}, {"text": "微小だった", "is_correct": false, "explanation": "過去形で、文末の述語として使う形。"}, {"text": "微小である", "is_correct": false, "explanation": "文語的な断定の形で、名詞を直接修飾しない。"}, {"text": "微小だろう", "is_correct": false, "explanation": "推量の形で、名詞を修飾しない。"}], "correct_form": "微小", "base_form": "微小だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"微小": "「微小な」の語幹。連体形の形の元になる部分。", "微小だった": "過去形で、文末の述語として使う形。", "微小である": "文語的な断定の形で、名詞を直接修飾しない。", "微小だろう": "推量の形で、名詞を修飾しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37204, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37204, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「粒子を絵で説明してくれました」の目的語として〈粒子〉に「を」がつく。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示し、粒子が説明するという不自然な文になるので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示し、絵で説明する部分に既に使われていて、粒子の目的語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や帰着を示すが、粒子は説明の相手にはならないので不自然な文になる。"}], "correct_answer": "を", "explanations": {"を": "正解。「粒子を絵で説明してくれました」の目的語として〈粒子〉に「を」がつく。", "が": "「が」は主語を示し、粒子が説明するという不自然な文になるので合わない。", "で": "「で」は手段を示し、絵で説明する部分に既に使われていて、粒子の目的語にはならない。", "に": "「に」は相手や帰着を示すが、粒子は説明の相手にはならないので不自然な文になる。"}, "error_tags": {"が": "主語", "で": "手段・場所", "に": "相手・帰着"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37204, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "とても小さなもののことです。空気の中をういているとても小さいつぶです。", "primary_collocate": null, "pronunciation": "りゅうし", "ipa": "ɾʲɯːɕi", "syllable_count": 3, "sentences": [{"text": "空気中には、目に見えない粒子がたくさん浮いています。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "空気中[くうきちゅう]には、目[め]に見[み]えない粒子[りゅうし]がたくさん浮[う]いています。", "sentence_source": "generated"}, {"text": "窓から光が入ると、粒子がきらきら光って見えます。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "窓[まど]から光[ひかり]が入[はい]ると、粒子[りゅうし]がきらきら光[ひか]って見[み]えます。", "sentence_source": "generated"}, {"text": "粒子が細かいので、風が吹くとすぐに飛んでいきます。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "粒子[りゅうし]が細[こま]かいので、風[かぜ]が吹[ふ]くとすぐに飛[と]んでいきます。", "sentence_source": "generated"}, {"text": "掃除をすると、ほこりの粒子が空気中に舞い上がります。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "掃除[そうじ]をすると、ほこりの粒子[りゅうし]が空気中[くうきちゅう]に舞[ま]い上[あ]がります。", "sentence_source": "generated"}, {"text": "雨雲は、水の粒子が集まってできています。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "雨雲[あまぐも]は、水[みず]の粒子[りゅうし]が集[あつ]まってできています。", "sentence_source": "generated"}, {"text": "花火の煙の粒子が、夜空にゆっくり広がりました。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "花火[はなび]の煙[けむり]の粒子[りゅうし]が、夜空[よぞら]にゆっくり広[ひろ]がりました。", "sentence_source": "generated"}, {"text": "粒子はとても小さいので、マスクをしないと吸い込んでしまいます。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "粒子[りゅうし]はとても小[ちい]さいので、マスクをしないと吸[す]い込[こ]んでしまいます。", "sentence_source": "generated"}, {"text": "先生は、空気の中の粒子を絵で説明してくれました。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "先生[せんせい]は、空気[くうき]の中[なか]の粒子[りゅうし]を絵[え]で説明[せつめい]してくれました。", "sentence_source": "generated"}, {"text": "工事の現場では、砂の粒子が飛ばないように水をまきます。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "工事[こうじ]の現場[げんば]では、砂[すな]の粒子[りゅうし]が飛[と]ばないように水[みず]をまきます。", "sentence_source": "generated"}, {"text": "空気清浄機は、空気中の粒子を取り除く機械です。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "空気清浄機[くうきせいじょうき]は、空気中[くうきちゅう]の粒子[りゅうし]を取[と]り除[のぞ]く機械[きかい]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "粒子", "label": "基本形"}], "register": "polite", "sense_fingerprint": "空気の中に浮いている、とても小さな粒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b809ef64-f595-4298-95cf-ff21c951f823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37204, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鍵", "is_correct": false, "explanation": "〈鍵〉は錠を開ける道具で、空気中に浮く小さなものとして合わない。"}, {"text": "指輪", "is_correct": false, "explanation": "〈指輪〉は装飾品で、空気中に浮く目に見えないものとしては合わない。"}, {"text": "手袋", "is_correct": false, "explanation": "〈手袋〉は手を覆う衣類で、空気中に浮くものとして合わない。"}, {"text": "粒子", "is_correct": true, "explanation": "正解。「空気中には、目に見えない＿がたくさん浮いています」の＿には、空気の中に浮く極小の粒を指す〈粒子〉が入る。"}], "explanations": {"鍵": "〈鍵〉は錠を開ける道具で、空気中に浮く小さなものとして合わない。", "指輪": "〈指輪〉は装飾品で、空気中に浮く目に見えないものとしては合わない。", "手袋": "〈手袋〉は手を覆う衣類で、空気中に浮くものとして合わない。", "粒子": "正解。「空気中には、目に見えない＿がたくさん浮いています」の＿には、空気の中に浮く極小の粒を指す〈粒子〉が入る。"}, "sentence_index": 0, "correct_answer": "粒子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大きな粒子が部屋中に響きました。", "explanation": "ここは〈声〉の意味（音）。〈粒子〉は目に見えない微細なものなので、響く音には合わないため誤り。"}, {"text": "ぶどうの粒子を一つずつ口に入れました。", "explanation": "ここは〈粒〉の意味（果物の小さなかたまり）。〈粒子〉は微細な物質を指すので、食べ物の実には合わない。"}, {"text": "朝ご飯に、粒子を焼いて食べた。", "explanation": "ここは〈パン〉の意味（焼いて食べる食品）。〈粒子〉は物質の微小な粒で、焼いて食べるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37204, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "時計", "is_correct": false, "explanation": "〈時計〉は大きさに関わらず、マスクをしないと吸い込んでしまうものではないので合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "〈椅子〉は大きく、人が吸い込んでしまう対象ではないので合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "〈教科書〉は紙の本で、吸い込んでしまう対象にはならないので合わない。"}, {"text": "粒子", "is_correct": true, "explanation": "正解。「＿はとても小さいので、マスクをしないと吸い込んでしまいます」の主語は、極小の粒を指す〈粒子〉。"}], "explanations": {"時計": "〈時計〉は大きさに関わらず、マスクをしないと吸い込んでしまうものではないので合わない。", "椅子": "〈椅子〉は大きく、人が吸い込んでしまう対象ではないので合わない。", "教科書": "〈教科書〉は紙の本で、吸い込んでしまう対象にはならないので合わない。", "粒子": "正解。「＿はとても小さいので、マスクをしないと吸い込んでしまいます」の主語は、極小の粒を指す〈粒子〉。"}, "sentence_index": 6, "correct_answer": "粒子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の花壇に粒子を植えて、芽が出るのを待った。", "explanation": "ここは〈種〉の意味（植えて芽を出すもの）。〈粒子〉は物質の微小な粒で、植えて芽を出すものではないので合わない。"}, {"text": "時計の粒子が正確に時刻を指しました。", "explanation": "ここは〈針〉の意味（時計の針）。〈粒子〉は時計の部品ではなく、時刻を指すものでもないので合わない。"}, {"text": "大きな鍋で、粒子を煮込みました。", "explanation": "ここは〈スープ〉などの料理の意味。〈粒子〉は食材や料理を指さないので、煮込む対象としては誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37204, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空気清浄機を使うと、部屋の中の粒子を減ります。", "corrected_sentence": "空気清浄機を使うと、部屋の中の粒子が減ります。", "error_description": "「粒子を減ります」は誤り。「減る」は自動詞で、主語に「が」をとるので、正しくは「粒子が減ります」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37204, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "マスクは、空気中の粒子を体に入るのを防ぎます。", "corrected_sentence": "マスクは、空気中の粒子が体に入るのを防ぎます。", "error_description": "「粒子を体に入る」は誤り。「入る」は自動詞で、主語に「が」をとるので、正しくは「粒子が体に入る」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37205, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「細かい粒子が大量に含まれている」の主語として〈粒子〉に「が」がつく。"}, {"text": "を", "is_correct": false, "explanation": "「含まれる」は受け身なので、主語に「が」を取る。「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、粒子が含まれる主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、ここでは主語を表さない。"}], "correct_answer": "が", "explanations": {"が": "正解。「細かい粒子が大量に含まれている」の主語として〈粒子〉に「が」がつく。", "を": "「含まれる」は受け身なので、主語に「が」を取る。「を」は合わない。", "で": "「で」は手段や場所を示し、粒子が含まれる主語にはならない。", "と": "「と」は並列や相手を示し、ここでは主語を表さない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37205, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「煙の粒子が細かいほど」の主語として〈粒子〉に「が」がつく。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、ここでは粒子の状態を述べる主語なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や帰着を示し、主語の位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「煙の粒子が細かいほど」の主語として〈粒子〉に「が」がつく。", "を": "「を」は目的語を示すが、ここでは粒子の状態を述べる主語なので合わない。", "に": "「に」は方向や帰着を示し、主語の位置には入らない。", "で": "「で」は手段や場所を示し、主語の位置には入らない。"}, "error_tags": {"を": "目的語", "に": "方向・帰着", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37205, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物質を構成する非常に小さな粒。特に、空気中に浮遊する微細な固体や液体の粒を指す。", "primary_collocate": null, "pronunciation": "りゅうし", "ipa": "ɾʲɯːɕi", "syllable_count": 3, "sentences": [{"text": "古い本のページをめくると、紙の粒子が舞い上がった。", "target_word": "粒子", "complexity_tier": "T4", "furigana": "古[ふる]い本[ほん]のページをめくると、紙[かみ]の粒子[りゅうし]が舞[ま]い上[あ]がった。", "sentence_source": "generated"}, {"text": "工場の排気には、目に見えない細かい粒子が大量に含まれている。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "工場[こうじょう]の排気[はいき]には、目[め]に見[み]えない細[こま]かい粒子[りゅうし]が大量[たいりょう]に含[ふく]まれている。", "sentence_source": "generated"}, {"text": "朝日が差し込むと、部屋の中を舞う粒子が光って見えた。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "朝日[あさひ]が差[さ]し込[こ]むと、部屋[へや]の中[なか]を舞[ま]う粒子[りゅうし]が光[ひか]って見[み]えた。", "sentence_source": "generated"}, {"text": "火山が噴火して、灰の粒子が空高く広がった。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "火山[かざん]が噴火[ふんか]して、灰[はい]の粒子[りゅうし]が空高[そらたか]く広[ひろ]がった。", "sentence_source": "generated"}, {"text": "マスクは空気中の粒子を吸い込むのを防いでくれる。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "マスクは空気中[くうきちゅう]の粒子[りゅうし]を吸[す]い込[こ]むのを防[ふせ]いでくれる。", "sentence_source": "generated"}, {"text": "霧は、空気中に浮かぶ水の粒子が集まったものだ。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "霧[きり]は、空気中[くうきちゅう]に浮[う]かぶ水[みず]の粒子[りゅうし]が集[あつ]まったものだ。", "sentence_source": "generated"}, {"text": "物質は、原子などの小さな粒子でできている。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "物質[ぶっしつ]は、原子[げんし]などの小[ちい]さな粒子[りゅうし]でできている。", "sentence_source": "generated"}, {"text": "煙の粒子が細かいほど、遠くまで流れていく。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "煙[けむり]の粒子[りゅうし]が細[こま]かいほど、遠[とお]くまで流[なが]れていく。", "sentence_source": "generated"}, {"text": "砂嵐の日は、細かい砂の粒子が窓の隙間から入ってきた。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "砂嵐[すなあらし]の日[ひ]は、細[こま]かい砂[すな]の粒子[りゅうし]が窓[まど]の隙間[すきま]から入[はい]ってきた。", "sentence_source": "generated"}, {"text": "研究者は、粒子の動きを顕微鏡で観察した。", "target_word": "粒子", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、粒子[りゅうし]の動[うご]きを顕微鏡[けんびきょう]で観察[かんさつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "粒子", "label": "基本形"}], "register": "plain", "sense_fingerprint": "物質を作る極小の粒、特に空気中に浮かぶ微細な固体・液体の粒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b809ef64-f595-4298-95cf-ff21c951f823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37205, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "布団", "is_correct": false, "explanation": "〈布団〉は寝具で、細かい粒として舞い上がるものには合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "〈靴下〉は衣類で、ページから舞い上がる細かいものとしては不自然。"}, {"text": "粒子", "is_correct": true, "explanation": "正解。「古い本のページをめくると、細かい＿が舞い上がった」の＿には、空気中に浮く微細な粒を指す〈粒子〉が入る。"}, {"text": "鍋", "is_correct": false, "explanation": "〈鍋〉は調理器具で、細かく舞い上がるものとしては合わない。"}], "explanations": {"布団": "〈布団〉は寝具で、細かい粒として舞い上がるものには合わない。", "靴下": "〈靴下〉は衣類で、ページから舞い上がる細かいものとしては不自然。", "粒子": "正解。「古い本のページをめくると、細かい＿が舞い上がった」の＿には、空気中に浮く微細な粒を指す〈粒子〉が入る。", "鍋": "〈鍋〉は調理器具で、細かく舞い上がるものとしては合わない。"}, "sentence_index": 0, "correct_answer": "粒子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お皿に残った米の粒子を、一つずつ数えた。", "explanation": "ここは〈粒〉の意味（目に見える小さなかたまり）。〈粒子〉は目に見えないほど微細なものなので、米粒には使わないため合わない。"}, {"text": "窓ガラスに雨の粒子がいくつもついていた。", "explanation": "ここは〈雨粒〉の意味。〈粒子〉は目に見えない微細なものを指すので、窓につく雨の水滴には合わない。"}, {"text": "ビールを注ぐと、粒子が勢いよく立ち上がった。", "explanation": "ここは〈泡〉の意味。液体の表面にできる気体の集まりを指すので、〈粒子〉では泡の様子を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37205, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "時計", "is_correct": false, "explanation": "〈時計〉は時刻を示す道具で、物質を構成する小さなものとして合わない。"}, {"text": "歌", "is_correct": false, "explanation": "〈歌〉は音楽作品で、物質の構成要素にはならない。"}, {"text": "粒子", "is_correct": true, "explanation": "正解。「物質は、原子などの小さな＿でできている」の＿には、物質を作る極小の粒を指す〈粒子〉が入る。"}, {"text": "雨具", "is_correct": false, "explanation": "〈雨具〉は雨をしのぐ道具で、物質の構成には合わない。"}], "explanations": {"時計": "〈時計〉は時刻を示す道具で、物質を構成する小さなものとして合わない。", "歌": "〈歌〉は音楽作品で、物質の構成要素にはならない。", "粒子": "正解。「物質は、原子などの小さな＿でできている」の＿には、物質を作る極小の粒を指す〈粒子〉が入る。", "雨具": "〈雨具〉は雨をしのぐ道具で、物質の構成には合わない。"}, "sentence_index": 6, "correct_answer": "粒子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "薬の粒子を一錠ずつ、水と一緒に飲んだ。", "explanation": "ここは〈錠剤〉の意味（薬を成形した塊）。〈粒子〉は目に見えないほど微細な粒なので、一錠ずつ飲む薬の形としては合わない。"}, {"text": "空気中の粒子が増殖して、部屋中に広がった。", "explanation": "ここは〈細菌〉の意味（生きて増える微生物）。〈粒子〉は増える生き物ではなく物質の微小な粒なので、増殖するという使い方は合わない。"}, {"text": "鍋の中で、粒子がふっくらと煮えた。", "explanation": "ここは〈豆〉の意味（煮ると柔らかくなる食材）。〈粒子〉は物質の微小な粒で、煮えて食べられる食材ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37205, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "機械は、空気中の粒子に集めて取り除く。", "corrected_sentence": "機械は、空気中の粒子を集めて取り除く。", "error_description": "「粒子に集めて」は誤り。「集める」は目的語に「を」をとるので、正しくは「粒子を集めて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37205, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日の窓辺には、細かい粒子を舞っているのが見える。", "corrected_sentence": "雨の日の窓辺には、細かい粒子が舞っているのが見える。", "error_description": "「粒子を舞っている」は誤り。「舞う」は自動詞で、主語に「が」をとるので、正しくは「粒子が舞っている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
