INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37206, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気の中のとても小さなごみのことです。", "primary_collocate": null, "pronunciation": "ぴーえむ", "ipa": "piːemɯ", "syllable_count": 4, "sentences": [{"text": "今日は空気中の PM が多いので、マスクをして出かけた。", "target_word": "PM", "complexity_tier": "T3", "furigana": "今日[きょう]は空気中[くうきちゅう]の PM が多[おお]いので、マスクをして出[で]かけた。", "sentence_source": "generated"}, {"text": "PM は、目に見えないほど小さなごみだ。", "target_word": "PM", "complexity_tier": "T3", "furigana": "PM は、目[め]に見[み]えないほど小[ちい]さなごみだ。", "sentence_source": "generated"}, {"text": "風が強い日は、PM が少なくなる。", "target_word": "PM", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]い日[ひ]は、PM が少[すく]なくなる。", "sentence_source": "generated"}, {"text": "天気予報で PM の量を調べてから、洗濯物を干す。", "target_word": "PM", "complexity_tier": "T3", "furigana": "天気予報[てんきよほう]で PM の量[りょう]を調[しら]べてから、洗濯物[せんたくもの]を干[ほ]す。", "sentence_source": "generated"}, {"text": "工場や車の煙から、PM が出ることがある。", "target_word": "PM", "complexity_tier": "T3", "furigana": "工場[こうじょう]や車[くるま]の煙[けむり]から、PM が出[で]ることがある。", "sentence_source": "generated"}, {"text": "PM が多い日は、外で長く運動しないほうがいい。", "target_word": "PM", "complexity_tier": "T3", "furigana": "PM が多[おお]い日[ひ]は、外[そと]で長[なが]く運動[うんどう]しないほうがいい。", "sentence_source": "generated"}, {"text": "部屋の空気から PM を取るために、空気清浄機を使う。", "target_word": "PM", "complexity_tier": "T3", "furigana": "部屋[へや]の空気[くうき]から PM を取[と]るために、空気清浄機[くうきせいじょうき]を使[つか]う。", "sentence_source": "generated"}, {"text": "母は PM のせいで、のどが痛くなったと言った。", "target_word": "PM", "complexity_tier": "T3", "furigana": "母[はは]は PM のせいで、のどが痛[いた]くなったと言[い]った。", "sentence_source": "generated"}, {"text": "窓を開けると、PM が家の中に入ってくる。", "target_word": "PM", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、PM が家[いえ]の中[なか]に入[はい]ってくる。", "sentence_source": "generated"}, {"text": "雨が降ると、空気中の PM が地面に落ちる。", "target_word": "PM", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ると、空気中[くうきちゅう]の PM が地面[じめん]に落[お]ちる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "PM", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "空気中にただよう目に見えないほど小さなごみ（天気予報などで聞くPM2.5など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1174785-6c89-4c94-b05d-420bafe00172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37206, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "PM", "is_correct": true, "explanation": "空気中の小さなごみを指す語で、「空気中のPMが多い」の文に合う。"}, {"text": "電話", "is_correct": false, "explanation": "通信機器のことなので、「空気中の電話が多い」は意味が通らない。"}, {"text": "辞書", "is_correct": false, "explanation": "言葉を調べる本のことなので、空気中には当てはまらない。"}, {"text": "家具", "is_correct": false, "explanation": "室内の道具のことなので、「空気中の家具が多い」は成り立たない。"}], "explanations": {"PM": "空気中の小さなごみを指す語で、「空気中のPMが多い」の文に合う。", "電話": "通信機器のことなので、「空気中の電話が多い」は意味が通らない。", "辞書": "言葉を調べる本のことなので、空気中には当てはまらない。", "家具": "室内の道具のことなので、「空気中の家具が多い」は成り立たない。"}, "sentence_index": 0, "correct_answer": "PM"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議は PM 2時に始まる。", "explanation": "ここは〈午後〉の意味。PM は時刻の略で、空気中のごみではない。"}, {"text": "新しいシステム開発で、PM を任された。", "explanation": "ここは〈プロジェクトマネージャー〉の意味。役割を指す語で、空気中のごみではない。"}, {"text": "英国の PM が来日して、首脳会談が開かれた。", "explanation": "ここは〈首相〉の意味（英語の prime minister の略）。空気中のごみではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37206, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "PM", "is_correct": true, "explanation": "空気中の小さな粒子を指すので、「部屋の空気からPMを取る」に合う。"}, {"text": "切符", "is_correct": false, "explanation": "乗車などに使う紙のことなので、空気から取るという文には合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "授業で使う本のことなので、空気から取る対象にならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電のことなので、空気から取るという文は成り立たない。"}], "explanations": {"PM": "空気中の小さな粒子を指すので、「部屋の空気からPMを取る」に合う。", "切符": "乗車などに使う紙のことなので、空気から取るという文には合わない。", "教科書": "授業で使う本のことなので、空気から取る対象にならない。", "冷蔵庫": "食品を冷やす家電のことなので、空気から取るという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "PM"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "締め切りは PM 5時です。", "explanation": "ここは〈午後〉の意味。PM は時刻の略で、空気中のごみではない。"}, {"text": "私は来年度から、このチームの PM になる。", "explanation": "ここは〈プロジェクトマネージャー〉の意味。役割を指すので、空気中のごみではない。"}, {"text": "ドイツの PM が、国会で演説した。", "explanation": "ここは〈首相〉の意味。英語の prime minister の略で、空気中のごみではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37206, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "PM が吸い込むと、のどが痛くなる。", "corrected_sentence": "PM を吸い込むと、のどが痛くなる。", "error_description": "「吸い込む」は他動詞なので、対象の PM は「を」で示す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37206, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "マスクをつけると、PM を作れる。", "corrected_sentence": "マスクをつけると、PM を防げる。", "error_description": "PM は「防ぐ」対象である。「作れる」は意味が合わず、動詞の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37207, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37207, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37207, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "大気中に浮遊する微小な粒子状物質のこと。健康や環境に影響を与える。", "primary_collocate": null, "pronunciation": "ぴーえむ", "ipa": "piːemɯ", "syllable_count": 4, "sentences": [{"text": "PM は大気中に浮遊する微小な粒子状物質であり、健康に影響を与える。", "target_word": "PM", "complexity_tier": "T3", "furigana": "PM は大気中[たいきちゅう]に浮遊[ふゆう]する微小[びしょう]な粒子状物質[りゅうしじょうぶっしつ]であり、健康[けんこう]に影響[えいきょう]を与[あた]える。", "sentence_source": "generated"}, {"text": "研究者は、都市部の PM の濃度を毎月測定している。", "target_word": "PM", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、都市部[としぶ]の PM の濃度[のうど]を毎月[まいつき]測定[そくてい]している。", "sentence_source": "generated"}, {"text": "PM を長く吸い込むと、呼吸器の病気になる危険が高まる。", "target_word": "PM", "complexity_tier": "T3", "furigana": "PM を長[なが]く吸[す]い込[こ]むと、呼吸器[こきゅうき]の病気[びょうき]になる危険[きけん]が高[たか]まる。", "sentence_source": "generated"}, {"text": "政府は PM の排出を減らすため、新しい基準を定めた。", "target_word": "PM", "complexity_tier": "T3", "furigana": "政府[せいふ]は PM の排出[はいしゅつ]を減[へ]らすため、新[あたら]しい基準[きじゅん]を定[さだ]めた。", "sentence_source": "generated"}, {"text": "冬は気温が低く風が弱いため、PM が地表付近にたまりやすい。", "target_word": "PM", "complexity_tier": "T3", "furigana": "冬[ふゆ]は気温[きおん]が低[ひく]く風[かぜ]が弱[よわ]いため、PM が地表付近[ちひょうふきん]にたまりやすい。", "sentence_source": "generated"}, {"text": "この装置は、空気中の PM を光で測ることができる。", "target_word": "PM", "complexity_tier": "T3", "furigana": "この装置[そうち]は、空気中[くうきちゅう]の PM を光[ひかり]で測[はか]ることができる。", "sentence_source": "generated"}, {"text": "国境をこえて飛んできた PM が、国内の観測値を押し上げた。", "target_word": "PM", "complexity_tier": "T3", "furigana": "国境[こっきょう]をこえて飛[と]んできた PM が、国内[こくない]の観測値[かんそくち]を押[お]し上[あ]げた。", "sentence_source": "generated"}, {"text": "ディーゼル車から出る PM は、環境への負担が大きい。", "target_word": "PM", "complexity_tier": "T3", "furigana": "ディーゼル車[しゃ]から出[で]る PM は、環境[かんきょう]への負担[ふたん]が大[おお]きい。", "sentence_source": "generated"}, {"text": "専門家は、PM の濃度が高い日には外出を控えるよう呼びかけた。", "target_word": "PM", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、PM の濃度[のうど]が高[たか]い日[ひ]には外出[がいしゅつ]を控[ひか]えるよう呼[よ]びかけた。", "sentence_source": "generated"}, {"text": "報告書によると、PM による健康被害は年々減っている。", "target_word": "PM", "complexity_tier": "T3", "furigana": "報告書[ほうこくしょ]によると、PM による健康被害[けんこうひがい]は年々[ねんねん]減[へ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "PM", "label": "基本形"}], "register": "formal", "sense_fingerprint": "大気汚染の指標となる粒子状物質（particulate matter）。濃度・測定・規制の文脈で使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1174785-6c89-4c94-b05d-420bafe00172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37207, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "PM", "is_correct": true, "explanation": "大気中の微小な粒子状物質を指し、この定義文の主語に合う。"}, {"text": "教科書", "is_correct": false, "explanation": "授業で使う本のことなので、大気中に浮遊する物質には当てはまらない。"}, {"text": "辞書", "is_correct": false, "explanation": "言葉を調べる本のことなので、大気中の物質の説明にはならない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車などに使う紙のことなので、「大気中に浮遊する」の主語にはならない。"}], "explanations": {"PM": "大気中の微小な粒子状物質を指し、この定義文の主語に合う。", "教科書": "授業で使う本のことなので、大気中に浮遊する物質には当てはまらない。", "辞書": "言葉を調べる本のことなので、大気中の物質の説明にはならない。", "切符": "乗車などに使う紙のことなので、「大気中に浮遊する」の主語にはならない。"}, "sentence_index": 0, "correct_answer": "PM"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議は PM 2時に開始される。", "explanation": "ここは〈午後〉の意味。時刻の略で、大気中の粒子ではない。"}, {"text": "新規事業の開発で、PM を務めることになった。", "explanation": "ここは〈プロジェクトマネージャー〉の意味。役割を指す語で、大気中の粒子ではない。"}, {"text": "英国の PM が来日し、首脳会談が行われた。", "explanation": "ここは〈首相〉の意味（英語の prime minister の略）。大気中の粒子ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37207, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "PM", "is_correct": true, "explanation": "国境を越えて飛んでくる大気中の粒子を指し、この文の主語に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電のことなので、飛んできて観測値を上げる主語にはならない。"}, {"text": "家具", "is_correct": false, "explanation": "室内の道具のことなので、国境を越えて飛んでくるという文には合わない。"}, {"text": "電話", "is_correct": false, "explanation": "通信機器のことなので、「飛んできた電話」は観測値に関係しない。"}], "explanations": {"PM": "国境を越えて飛んでくる大気中の粒子を指し、この文の主語に合う。", "冷蔵庫": "食品を冷やす家電のことなので、飛んできて観測値を上げる主語にはならない。", "家具": "室内の道具のことなので、国境を越えて飛んでくるという文には合わない。", "電話": "通信機器のことなので、「飛んできた電話」は観測値に関係しない。"}, "sentence_index": 6, "correct_answer": "PM"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "締め切りは PM 5時とされている。", "explanation": "ここは〈午後〉の意味。時刻の略で、大気中の粒子ではない。"}, {"text": "本件の担当として、PM が任命された。", "explanation": "ここは〈プロジェクトマネージャー〉の意味。役割を指すので、大気中の粒子ではない。"}, {"text": "ドイツの PM が、国会で施政方針を述べた。", "explanation": "ここは〈首相〉の意味。英語の prime minister の略で、大気中の粒子ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37207, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府は PM に規制する方針を発表した。", "corrected_sentence": "政府は PM を規制する方針を発表した。", "error_description": "「規制する」は他動詞で、対象の PM は「を」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37207, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "装置で PM を測量した。", "corrected_sentence": "装置で PM を測定した。", "error_description": "PM の濃度は「測定」する。「測量」は土地の距離や位置を調べることなので、動詞の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37208, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "病気", "is_correct": true, "explanation": "健康の対義語で、病気がないことと病気であることの関係にある。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠る行為や時間を指し、健康の対義語にはならない。"}, {"text": "体力", "is_correct": false, "explanation": "体を動かす力を指し、健康と対になる語ではない。"}, {"text": "活力", "is_correct": false, "explanation": "気力や勢いを表す語で、健康の対義語にはならない。"}], "correct_answer": "病気", "explanations": {"病気": "健康の対義語で、病気がないことと病気であることの関係にある。", "睡眠": "眠る行為や時間を指し、健康の対義語にはならない。", "体力": "体を動かす力を指し、健康と対になる語ではない。", "活力": "気力や勢いを表す語で、健康の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37208, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "病気", "is_correct": true, "explanation": "健康の対義語で、病気がないことと病気であることの関係にある。"}, {"text": "寝不足", "is_correct": false, "explanation": "睡眠が足りない状態で、健康の対義語にはならない。"}, {"text": "運動", "is_correct": false, "explanation": "体を動かす行為で、健康と対になる語ではない。"}, {"text": "休養", "is_correct": false, "explanation": "体を休めることで、健康の対義語にはならない。"}], "correct_answer": "病気", "explanations": {"病気": "健康の対義語で、病気がないことと病気であることの関係にある。", "寝不足": "睡眠が足りない状態で、健康の対義語にはならない。", "運動": "体を動かす行為で、健康と対になる語ではない。", "休養": "体を休めることで、健康の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37208, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "体や心が元気なこと。病気ではないこと。", "primary_collocate": null, "pronunciation": "けんこう", "ipa": "keŋkoː", "syllable_count": 4, "sentences": [{"text": "健康な体があれば、どこへでも行ける。", "target_word": "健康", "complexity_tier": "T2", "furigana": "健康[けんこう]な体[からだ]があれば、どこへでも行[い]ける。", "sentence_source": "generated"}, {"text": "おじいさんは健康で、毎朝元気に散歩しています。", "target_word": "健康", "complexity_tier": "T2", "furigana": "おじいさんは健康[けんこう]で、毎朝[まいあさ]元気[げんき]に散歩[さんぽ]しています。", "sentence_source": "generated"}, {"text": "風邪をひいてから、健康のありがたさがよくわかった。", "target_word": "健康", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいてから、健康[けんこう]のありがたさがよくわかった。", "sentence_source": "generated"}, {"text": "健康のために、毎晩十一時までに寝るようにしている。", "target_word": "健康", "complexity_tier": "T3", "furigana": "健康[けんこう]のために、毎晩[まいばん]十一時[じゅういちじ]までに寝[ね]るようにしている。", "sentence_source": "generated"}, {"text": "彼は病気もせず、とても健康に育った。", "target_word": "健康", "complexity_tier": "T3", "furigana": "彼[かれ]は病気[びょうき]もせず、とても健康[けんこう]に育[そだ]った。", "sentence_source": "generated"}, {"text": "健康を守るには、食事と運動と睡眠が大切だ。", "target_word": "健康", "complexity_tier": "T3", "furigana": "健康[けんこう]を守[まも]るには、食事[しょくじ]と運動[うんどう]と睡眠[すいみん]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "入院していた母は、今ではすっかり健康を取りもどした。", "target_word": "健康", "complexity_tier": "T3", "furigana": "入院[にゅういん]していた母[はは]は、今[いま]ではすっかり健康[けんこう]を取[と]りもどした。", "sentence_source": "generated"}, {"text": "健康を第一に考えて、無理な仕事は断ることにした。", "target_word": "健康", "complexity_tier": "T4", "furigana": "健康[けんこう]を第一[だいいち]に考[かんが]えて、無理[むり]な仕事[しごと]は断[ことわ]ることにした。", "sentence_source": "generated"}, {"text": "友だちの健康を心配して、毎日メッセージを送っている。", "target_word": "健康", "complexity_tier": "T3", "furigana": "友[とも]だちの健康[けんこう]を心配[しんぱい]して、毎日[まいにち]メッセージを送[おく]っている。", "sentence_source": "generated"}, {"text": "健康でいるために、私は毎日野菜をたくさん食べる。", "target_word": "健康", "complexity_tier": "T2", "furigana": "健康[けんこう]でいるために、私[わたし]は毎日[まいにち]野菜[やさい]をたくさん食[た]べる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "健康", "label": "基本形"}, {"form": "健康な", "label": "連体形"}, {"form": "健康で", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "体や心が元気で、病気ではないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37208, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "健康", "is_correct": true, "explanation": "「〜な体」の形で、元気で病気ではない体を表し、どこへでも行けるという文脈に合う。"}, {"text": "病気", "is_correct": false, "explanation": "「病気な体」とは言わず、体の良い状態を表せない。"}, {"text": "秘密", "is_correct": false, "explanation": "隠しごとを表し、体の状態を述べる文に合わない。"}, {"text": "無縁", "is_correct": false, "explanation": "かかわりがないという意味で、体の状態には使えない。"}], "explanations": {"健康": "「〜な体」の形で、元気で病気ではない体を表し、どこへでも行けるという文脈に合う。", "病気": "「病気な体」とは言わず、体の良い状態を表せない。", "秘密": "隠しごとを表し、体の状態を述べる文に合わない。", "無縁": "かかわりがないという意味で、体の状態には使えない。"}, "sentence_index": 0, "correct_answer": "健康"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この傘は健康で、強い風でも壊れない。", "explanation": "ここは〈丈夫〉の意味。健康は人や動物の心身について言い、傘の頑丈さには使わない。"}, {"text": "健康な財政を立て直すため、予算を見直した。", "explanation": "ここは〈健全〉の意味。健康は人の体や心について言い、財政の健全さには使わない。"}, {"text": "寝不足でも、彼女は健康な声で明るく挨拶した。", "explanation": "ここは〈元気〉の意味。健康は体や心の状態を表し、声の張りや調子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37208, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "健康", "is_correct": true, "explanation": "「取りもどす」の目的語で、病後に体が元の良い状態に戻ったことを表す。"}, {"text": "不足", "is_correct": false, "explanation": "足りないことを表し、取りもどすものとして合わない。"}, {"text": "留守", "is_correct": false, "explanation": "家を空けている状態で、取りもどす対象ではない。"}, {"text": "噂", "is_correct": false, "explanation": "世間の話で、体の状態として取りもどす対象ではない。"}], "explanations": {"健康": "「取りもどす」の目的語で、病後に体が元の良い状態に戻ったことを表す。", "不足": "足りないことを表し、取りもどすものとして合わない。", "留守": "家を空けている状態で、取りもどす対象ではない。", "噂": "世間の話で、体の状態として取りもどす対象ではない。"}, "sentence_index": 6, "correct_answer": "健康"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行は健康に終わった。", "explanation": "ここは〈無事〉の意味。健康は人の体や心の状態を表し、旅行の経過には使わない。"}, {"text": "ずっと言えずにいたが、ついに健康を出して告白した。", "explanation": "ここは〈勇気〉の意味。「勇気を出す」とは言うが、「健康を出す」とは言わない。"}, {"text": "会社では健康な服装が求められる。", "explanation": "ここは〈清潔〉の意味。健康は人の体や心の状態に使い、服装の清潔さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37208, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は健康を気をつけて、毎晩十時には寝ている。", "corrected_sentence": "母は健康に気をつけて、毎晩十時には寝ている。", "error_description": "「気をつける」は「〜に」を取るので、「健康を」は誤り（正しくは「健康に」）。誤りは健康に付く助詞。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37208, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "健康で体づくりは、毎日の食事から始まる。", "corrected_sentence": "健康な体づくりは、毎日の食事から始まる。", "error_description": "「体づくり」は名詞なので、直後の名詞を修飾する連体形「健康な」が必要。「健康で」では名詞に続かず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37209, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "病気", "is_correct": true, "explanation": "健康の対義語で、病気がないことと病気であることの関係にある。"}, {"text": "健全", "is_correct": false, "explanation": "健康に近い意味の語で、対義語ではない。"}, {"text": "活力", "is_correct": false, "explanation": "気力や勢いを表す語で、健康の対義語にはならない。"}, {"text": "体力", "is_correct": false, "explanation": "体を動かす力を指し、健康と対になる語ではない。"}], "correct_answer": "病気", "explanations": {"病気": "健康の対義語で、病気がないことと病気であることの関係にある。", "健全": "健康に近い意味の語で、対義語ではない。", "活力": "気力や勢いを表す語で、健康の対義語にはならない。", "体力": "体を動かす力を指し、健康と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37209, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "病気", "is_correct": true, "explanation": "健康の対義語で、病気がないことと病気であることの関係にある。"}, {"text": "疲労", "is_correct": false, "explanation": "体がだるい状態を指すが、健康と対になる語ではない。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠る行為や時間を指し、健康の対義語にはならない。"}, {"text": "栄養", "is_correct": false, "explanation": "体を養う要素で、健康と対になる語ではない。"}], "correct_answer": "病気", "explanations": {"病気": "健康の対義語で、病気がないことと病気であることの関係にある。", "疲労": "体がだるい状態を指すが、健康と対になる語ではない。", "睡眠": "眠る行為や時間を指し、健康の対義語にはならない。", "栄養": "体を養う要素で、健康と対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37209, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "体や心の状態が正常で、病気やけががないこと。また、そのような状態。", "primary_collocate": null, "pronunciation": "けんこう", "ipa": "keŋkoː", "syllable_count": 4, "sentences": [{"text": "日の出と共に目覚める鶏の健康こそが、栄養豊富な卵を産んでもらうための条件だからである。", "target_word": "健康", "complexity_tier": "T4", "furigana": "日[ひ]の出[で]と共[とも]に目覚[めざ]める鶏[にわとり]の健康[けんこう]こそが、栄養[えいよう]豊富[ほうふ]な卵[たまご]を産[う]んでもらうための条件[じょうけん]だからである。", "sentence_source": "mined"}, {"text": "毎日歩くことは、健康を保つためのいちばん簡単な方法だ。", "target_word": "健康", "complexity_tier": "T3", "furigana": "毎日[まいにち]歩[ある]くことは、健康[けんこう]を保[たも]つためのいちばん簡単[かんたん]な方法[ほうほう]だ。", "sentence_source": "generated"}, {"text": "祖父は九十歳になっても健康で、自分で畑仕事をしている。", "target_word": "健康", "complexity_tier": "T3", "furigana": "祖父[そふ]は九十歳[きゅうじゅっさい]になっても健康[けんこう]で、自分[じぶん]で畑仕事[はたけしごと]をしている。", "sentence_source": "generated"}, {"text": "夜ふかしを続けると、健康を害するおそれがある。", "target_word": "健康", "complexity_tier": "T4", "furigana": "夜[よる]ふかしを続[つづ]けると、健康[けんこう]を害[がい]するおそれがある。", "sentence_source": "generated"}, {"text": "健康のために、最近は甘い飲み物をやめて水を飲んでいる。", "target_word": "健康", "complexity_tier": "T3", "furigana": "健康[けんこう]のために、最近[さいきん]は甘[あま]い飲[の]み物[もの]をやめて水[みず]を飲[の]んでいる。", "sentence_source": "generated"}, {"text": "仕事も大切だが、体と心の健康のほうがもっと大切だ。", "target_word": "健康", "complexity_tier": "T3", "furigana": "仕事[しごと]も大切[たいせつ]だが、体[からだ]と心[こころ]の健康[けんこう]のほうがもっと大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "医者は「健康な人でも、年に一度は検査を受けたほうがいい」と言った。", "target_word": "健康", "complexity_tier": "T4", "furigana": "医者[いしゃ]は「健康[けんこう]な人[ひと]でも、年[とし]に一度[いちど]は検査[けんさ]を受[う]けたほうがいい」と言[い]った。", "sentence_source": "generated"}, {"text": "彼女は健康に気をつけていて、野菜を中心にした食事をとっている。", "target_word": "健康", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は健康[けんこう]に気[き]をつけていて、野菜[やさい]を中心[ちゅうしん]にした食事[しょくじ]をとっている。", "sentence_source": "generated"}, {"text": "長く旅行に行くときは、健康でなければ楽しめない。", "target_word": "健康", "complexity_tier": "T3", "furigana": "長[なが]く旅行[りょこう]に行[い]くときは、健康[けんこう]でなければ楽[たの]しめない。", "sentence_source": "generated"}, {"text": "子どもの健康を考えて、家族で空気のきれいな町に引っ越しを決めた。", "target_word": "健康", "complexity_tier": "T4", "furigana": "子[こ]どもの健康[けんこう]を考[かんが]えて、家族[かぞく]で空気[くうき]のきれいな町[まち]に引[ひ]っ越[こ]しを決[き]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "健康", "label": "基本形"}, {"form": "健康な", "label": "連体形"}, {"form": "健康で", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "体や心が正常で、病気やけががない状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37209, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "健康", "is_correct": true, "explanation": "鶏が卵を産むための体の条件として、体の良い状態を表し文脈に合う。"}, {"text": "電話", "is_correct": false, "explanation": "「鶏の電話」は意味をなさず、体の状態を表さないので文に合わない。"}, {"text": "羽色", "is_correct": false, "explanation": "羽の色を指し、健康な状態を表す条件とは結びつかない。"}, {"text": "名前", "is_correct": false, "explanation": "呼び名であり、体の状態を表さないので合わない。"}], "explanations": {"健康": "鶏が卵を産むための体の条件として、体の良い状態を表し文脈に合う。", "電話": "「鶏の電話」は意味をなさず、体の状態を表さないので文に合わない。", "羽色": "羽の色を指し、健康な状態を表す条件とは結びつかない。", "名前": "呼び名であり、体の状態を表さないので合わない。"}, "sentence_index": 0, "correct_answer": "健康"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このカバンは健康で、十年使っても壊れない。", "explanation": "ここは〈丈夫〉の意味。健康は人や動物の体・心の状態に使い、カバンの頑丈さには言わない。"}, {"text": "健康な経営を続けるため、会社は毎月帳簿を見直している。", "explanation": "ここは〈健全〉の意味。健康は人の体や心について言い、会社の経営の状態には使わない。"}, {"text": "教室で健康な返事をする。", "explanation": "ここは〈元気〉の意味。健康は体や心の状態を表し、返事の調子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37209, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "健康", "is_correct": true, "explanation": "「〜な人でも」の形で、健康な人が検査を受けるべきという文脈に合う。"}, {"text": "病気", "is_correct": false, "explanation": "「病気な人」とは言わず、文の形が成り立たない。"}, {"text": "不要", "is_correct": false, "explanation": "必要がないという意味で、検査の文脈が崩れる。"}, {"text": "秘密", "is_correct": false, "explanation": "隠されていることを表し、検査の文脈に合わない。"}], "explanations": {"健康": "「〜な人でも」の形で、健康な人が検査を受けるべきという文脈に合う。", "病気": "「病気な人」とは言わず、文の形が成り立たない。", "不要": "必要がないという意味で、検査の文脈が崩れる。", "秘密": "隠されていることを表し、検査の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "健康"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな問題もなく、試合は健康に終わった。", "explanation": "ここは〈無事〉の意味。健康は人や動物の体・心の状態を表し、試合の経過には使わない。"}, {"text": "試験に落ちたが、健康を出して次を目指そう。", "explanation": "ここは〈元気〉の意味。「元気を出す」とは言うが、「健康を出す」とは言わない。"}, {"text": "会議では健康な議論が続いた。", "explanation": "ここは〈活発〉の意味。健康は人の体や心の状態を言い、議論の盛んさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37209, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は八十歳を過ぎても健康な、毎朝散歩を続けている。", "corrected_sentence": "祖母は八十歳を過ぎても健康で、毎朝散歩を続けている。", "error_description": "「健康」は形容動詞なので、文中では「健康で」と連用形にする。「健康な」は後ろに名詞が続く形で、読点の前では文が切れてしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37209, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は健康が気をつけて、毎日二十分歩いている。", "corrected_sentence": "祖父は健康に気をつけて、毎日二十分歩いている。", "error_description": "「気をつける」は「〜に」を取るので、「健康が」は誤り（正しくは「健康に」）。誤りは健康に付く助詞。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
