INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37210, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "問題を解決するための方法や計画のことです。", "primary_collocate": null, "pronunciation": "さく", "ipa": "sakɯ", "syllable_count": 2, "sentences": [{"text": "この問題を解決する策が、まだ見つからない。", "target_word": "策", "complexity_tier": "T3", "furigana": "この問題[もんだい]を解決[かいけつ]する策[さく]が、まだ見[み]つからない。", "sentence_source": "generated"}, {"text": "先生は、遅刻を減らすための策を考えた。", "target_word": "策", "complexity_tier": "T3", "furigana": "先生[せんせい]は、遅刻[ちこく]を減[へ]らすための策[さく]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "町は、ごみを減らす策を発表した。", "target_word": "策", "complexity_tier": "T3", "furigana": "町[まち]は、ごみを減[へ]らす策[さく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "いい策が思いつかず、一晩中悩んだ。", "target_word": "策", "complexity_tier": "T3", "furigana": "いい策[さく]が思[おも]いつかず、一晩中[ひとばんじゅう]悩[なや]んだ。", "sentence_source": "generated"}, {"text": "値上げは、会社が選んだ最後の策だった。", "target_word": "策", "complexity_tier": "T3", "furigana": "値上[ねあ]げは、会社[かいしゃ]が選[えら]んだ最後[さいご]の策[さく]だった。", "sentence_source": "generated"}, {"text": "運休が増えたときの策として、代行バスを用意しておく。", "target_word": "策", "complexity_tier": "T3", "furigana": "運休[うんきゅう]が増えたときの策[さく]として、代行[だいこう]バスを用意[ようい]しておく。", "sentence_source": "generated"}, {"text": "事故を防ぐ策を、みんなで話し合った。", "target_word": "策", "complexity_tier": "T3", "furigana": "事故[じこ]を防[ふせ]ぐ策[さく]を、みんなで話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "彼女の出した策のおかげで、問題が早く片づいた。", "target_word": "策", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の出[だ]した策[さく]のおかげで、問題[もんだい]が早[はや]く片[かた]づいた。", "sentence_source": "generated"}, {"text": "水不足への策を、市長が説明した。", "target_word": "策", "complexity_tier": "T3", "furigana": "水不足[みずぶそく]への策[さく]を、市長[しちょう]が説明[せつめい]した。", "sentence_source": "generated"}, {"text": "策がなければ、また同じ失敗をくり返す。", "target_word": "策", "complexity_tier": "T3", "furigana": "策[さく]がなければ、また同[おな]じ失敗[しっぱい]をくり返[かえ]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "策", "label": "基本形"}], "register": "plain", "sense_fingerprint": "困った問題や課題に対して考える解決の方法・対策", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 片づい (Zipf 1.86)']::text[], 'e1174785-6c89-4c94-b05d-420bafe00172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37210, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "策", "is_correct": true, "explanation": "「解決する策」は問題を解く方法を表し、「見つからない」の対象として自然に入る。"}, {"text": "湿気", "is_correct": false, "explanation": "「湿気」は空気中の水分を指し、「問題を解決する」の対象にはならない。"}, {"text": "寝息", "is_correct": false, "explanation": "「寝息」は眠っている人の呼吸で、「解決する」の対象にはならない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気」は眠くなる感覚で、問題を解決する対象ではない。"}], "explanations": {"策": "「解決する策」は問題を解く方法を表し、「見つからない」の対象として自然に入る。", "湿気": "「湿気」は空気中の水分を指し、「問題を解決する」の対象にはならない。", "寝息": "「寝息」は眠っている人の呼吸で、「解決する」の対象にはならない。", "眠気": "「眠気」は眠くなる感覚で、問題を解決する対象ではない。"}, "sentence_index": 0, "correct_answer": "策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は最近、策がかゆくて眠れない。", "explanation": "策は計画を指すので、かゆくなる体の部分としては合わない。"}, {"text": "彼は策を切るために、美容院へ行った。", "explanation": "策は計画を指すので、切る対象の髪としては合わない。"}, {"text": "毎日走って、足の策を休ませた。", "explanation": "策は計画を指すので、休ませる体の部分としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37210, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "策", "is_correct": true, "explanation": "「事故を防ぐ策」は事故を防ぐための方法を表し、話し合う対象になる。"}, {"text": "湯気", "is_correct": false, "explanation": "「湯気」は熱い水から立つ蒸気で、「事故を防ぐ」の対象にはならない。"}, {"text": "寝床", "is_correct": false, "explanation": "「寝床」は寝るための場所で、「事故を防ぐ」の対象ではない。"}, {"text": "色合い", "is_correct": false, "explanation": "「色合い」は色の具合を指し、話し合って防ぐものではない。"}], "explanations": {"策": "「事故を防ぐ策」は事故を防ぐための方法を表し、話し合う対象になる。", "湯気": "「湯気」は熱い水から立つ蒸気で、「事故を防ぐ」の対象にはならない。", "寝床": "「寝床」は寝るための場所で、「事故を防ぐ」の対象ではない。", "色合い": "「色合い」は色の具合を指し、話し合って防ぐものではない。"}, "sentence_index": 6, "correct_answer": "策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長年の策で、仕事の流れがよく分かる。", "explanation": "策は計画を指すので、積み重ねた体験の意味では合わない。"}, {"text": "寒さで指先の策がなくなった。", "explanation": "策は計画を指すので、指先の感じ方には使わない。"}, {"text": "花の策が部屋に広がった。", "explanation": "策は計画を指すので、空間に広がるものとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
