INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37211, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある目的を達成するために考え出された方法や手段。", "primary_collocate": null, "pronunciation": "さく", "ipa": "sakɯ", "syllable_count": 2, "sentences": [{"text": "試合に勝つために、監督は新しい策を練った。", "target_word": "策", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]つために、監督[かんとく]は新[あたら]しい策[さく]を練[ね]った。", "sentence_source": "generated"}, {"text": "敵をだます策が成功し、城は守られた。", "target_word": "策", "complexity_tier": "T3", "furigana": "敵[てき]をだます策[さく]が成功[せいこう]し、城[しろ]は守[まも]られた。", "sentence_source": "generated"}, {"text": "彼は目的を果たすため、あらゆる策を使った。", "target_word": "策", "complexity_tier": "T3", "furigana": "彼[かれ]は目的[もくてき]を果[は]たすため、あらゆる策[さく]を使[つか]った。", "sentence_source": "generated"}, {"text": "客を増やす策として、店は夜も営業することにした。", "target_word": "策", "complexity_tier": "T3", "furigana": "客[きゃく]を増[ふ]やす策[さく]として、店[みせ]は夜[よる]も営業[えいぎょう]することにした。", "sentence_source": "generated"}, {"text": "策を立てても、実行しなければ意味がない。", "target_word": "策", "complexity_tier": "T3", "furigana": "策[さく]を立[た]てても、実行[じっこう]しなければ意味[いみ]がない。", "sentence_source": "generated"}, {"text": "彼の策にはまって、相手チームは大きく点を失った。", "target_word": "策", "complexity_tier": "T3", "furigana": "彼[かれ]の策[さく]にはまって、相手[あいて]チームは大[おお]きく点[てん]を失[うしな]った。", "sentence_source": "generated"}, {"text": "交渉を有利に進める策を、社長が示した。", "target_word": "策", "complexity_tier": "T3", "furigana": "交渉[こうしょう]を有利[ゆうり]に進[すす]める策[さく]を、社長[しゃちょう]が示[しめ]した。", "sentence_source": "generated"}, {"text": "小さな会社が大企業に勝つには、思い切った策が必要だ。", "target_word": "策", "complexity_tier": "T3", "furigana": "小[ちい]さな会社[かいしゃ]が大企業[だいきぎょう]に勝[か]つには、思[おも]い切[き]った策[さく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "最初の策がうまくいかなかったので、別の策に切り替えた。", "target_word": "策", "complexity_tier": "T3", "furigana": "最初[さいしょ]の策[さく]がうまくいかなかったので、別[べつ]の策[さく]に切[き]り替[か]えた。", "sentence_source": "generated"}, {"text": "優勝をねらう策は、守りをかためることだった。", "target_word": "策", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]をねらう策[さく]は、守[まも]りをかためることだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "策", "label": "基本形"}], "register": "plain", "sense_fingerprint": "勝つ・成功するなど目的を果たすために工夫した作戦・はかりごと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: ねらう (Zipf 2.41), かためる (Zipf 1.4)']::text[], 'e1174785-6c89-4c94-b05d-420bafe00172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37211, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "策", "is_correct": true, "explanation": "「新しい策を練った」は作戦を考えたという意味になり、「練る」の対象として自然。"}, {"text": "寝息", "is_correct": false, "explanation": "「寝息」は眠っている人の呼吸で、「練る」の対象にはならない。"}, {"text": "花びら", "is_correct": false, "explanation": "「花びら」は花の一部で、「練る」の対象ではない。"}, {"text": "霧雨", "is_correct": false, "explanation": "「霧雨」は細かい雨を指し、「練る」の対象にはならない。"}], "explanations": {"策": "「新しい策を練った」は作戦を考えたという意味になり、「練る」の対象として自然。", "寝息": "「寝息」は眠っている人の呼吸で、「練る」の対象にはならない。", "花びら": "「花びら」は花の一部で、「練る」の対象ではない。", "霧雨": "「霧雨」は細かい雨を指し、「練る」の対象にはならない。"}, "sentence_index": 0, "correct_answer": "策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "悲しい映画を見て、策を流した。", "explanation": "策は作戦を指すので、流すものとしては合わない。"}, {"text": "赤ちゃんの策が、静かに聞こえる。", "explanation": "策は作戦を指すので、耳に聞こえるものとしては合わない。"}, {"text": "熱が出て、策が上がった。", "explanation": "策は作戦を指すので、上がる・下がるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37211, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "策", "is_correct": true, "explanation": "「交渉を有利に進める策を示した」は、進め方として社長が示したものを表し、「示す」の対象として自然。"}, {"text": "湯気", "is_correct": false, "explanation": "「湯気」は熱い水から立つ蒸気で、「示す」の対象にはならない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気」は眠くなる感覚で、「示す」の対象ではない。"}, {"text": "汗", "is_correct": false, "explanation": "「汗」は体から出る水分で、「示す」の対象にはならない。"}], "explanations": {"策": "「交渉を有利に進める策を示した」は、進め方として社長が示したものを表し、「示す」の対象として自然。", "湯気": "「湯気」は熱い水から立つ蒸気で、「示す」の対象にはならない。", "眠気": "「眠気」は眠くなる感覚で、「示す」の対象ではない。", "汗": "「汗」は体から出る水分で、「示す」の対象にはならない。"}, "sentence_index": 6, "correct_answer": "策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全力で走って、策をたくさんかいた。", "explanation": "策は作戦を指し、体からかくものとしては合わない。"}, {"text": "お香の策が部屋に広がった。", "explanation": "策は作戦を指すので、空間に広がるものとしては合わない。"}, {"text": "遠くで鐘の策が鳴った。", "explanation": "策は作戦を指すので、鳴るものとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
