INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37212, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「飛行機での輸送」の「の」で、「飛行機で」の部分を「輸送」に結ぶ。"}, {"text": "が", "is_correct": false, "explanation": "「輸送が」は主語を示し、「での輸送」と名詞を結ぶ形には合わない。"}, {"text": "を", "is_correct": false, "explanation": "「飛行機でを輸送」は目的語の形にならず、文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「飛行機でに輸送」は位置を示す形にならず、「輸送」を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「飛行機での輸送」の「の」で、「飛行機で」の部分を「輸送」に結ぶ。", "が": "「輸送が」は主語を示し、「での輸送」と名詞を結ぶ形には合わない。", "を": "「飛行機でを輸送」は目的語の形にならず、文として成り立たない。", "に": "「飛行機でに輸送」は位置を示す形にならず、「輸送」を修飾できない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37212, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や物を、乗り物にのせて、遠くへはこぶこと。", "primary_collocate": null, "pronunciation": "ゆそう", "ipa": "jɯsoː", "syllable_count": 3, "sentences": [{"text": "台風のため、船による荷物の輸送が止まりました。", "target_word": "輸送", "complexity_tier": "T3", "furigana": "台風[たいふう]のため、船[ふね]による荷物[にもつ]の輸送[ゆそう]が止[と]まりました。", "sentence_source": "generated"}, {"text": "この会社は野菜を冷蔵トラックで輸送しています。", "target_word": "輸送", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は野菜[やさい]を冷蔵[れいぞう]トラックで輸送[ゆそう]しています。", "sentence_source": "generated"}, {"text": "災害のときは、けが人の輸送に救急車を使います。", "target_word": "輸送", "complexity_tier": "T3", "furigana": "災害[さいがい]のときは、けが人[にん]の輸送[ゆそう]に救急車[きゅうきゅうしゃ]を使[つか]います。", "sentence_source": "generated"}, {"text": "重い機械の輸送は、費用が高くなります。", "target_word": "輸送", "complexity_tier": "T3", "furigana": "重[おも]い機械[きかい]の輸送[ゆそう]は、費用[ひよう]が高[たか]くなります。", "sentence_source": "generated"}, {"text": "雪が多くて、鉄道の輸送が遅れています。", "target_word": "輸送", "complexity_tier": "T3", "furigana": "雪[ゆき]が多[おお]くて、鉄道[てつどう]の輸送[ゆそう]が遅[おく]れています。", "sentence_source": "generated"}, {"text": "海外への輸送に一週間かかるので、早めに注文してください。", "target_word": "輸送", "complexity_tier": "T3", "furigana": "海外[かいがい]への輸送[ゆそう]に一週間[いっしゅうかん]かかるので、早[はや]めに注文[ちゅうもん]してください。", "sentence_source": "generated"}, {"text": "牛乳は新しいうちに、店へ輸送されます。", "target_word": "輸送", "complexity_tier": "T3", "furigana": "牛乳[ぎゅうにゅう]は新[あたら]しいうちに、店[みせ]へ輸送[ゆそう]されます。", "sentence_source": "generated"}, {"text": "飛行機での輸送は速いですが、船より高いです。", "target_word": "輸送", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]での輸送[ゆそう]は速[はや]いですが、船[ふね]より高[たか]いです。", "sentence_source": "generated"}, {"text": "輸送の途中で、箱がつぶれてしまいました。", "target_word": "輸送", "complexity_tier": "T3", "furigana": "輸送[ゆそう]の途中[とちゅう]で、箱[はこ]がつぶれてしまいました。", "sentence_source": "generated"}, {"text": "大雨で道路が通れず、輸送ができませんでした。", "target_word": "輸送", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で道路[どうろ]が通[とお]れず、輸送[ゆそう]ができませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "輸送", "label": "辞書形（名詞）"}, {"form": "輸送する", "label": "サ変動詞・基本形"}, {"form": "輸送した", "label": "過去形"}, {"form": "輸送される", "label": "受身形"}], "register": "polite", "sense_fingerprint": "人や物を乗り物にのせて遠くへ運ぶこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1174785-6c89-4c94-b05d-420bafe00172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37212, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "輸送", "is_correct": true, "explanation": "「荷物の輸送が止まる」は、乗り物での運搬が止まったという意味になり自然。"}, {"text": "通院", "is_correct": false, "explanation": "「通院」は病院に通うことで、「荷物の通院」は成り立たない。"}, {"text": "入学", "is_correct": false, "explanation": "「入学」は学校に入ることで、「荷物の入学」は成り立たない。"}, {"text": "休憩", "is_correct": false, "explanation": "「休憩」は一息つくことで、「荷物の休憩が止まる」は意味が通らない。"}], "explanations": {"輸送": "「荷物の輸送が止まる」は、乗り物での運搬が止まったという意味になり自然。", "通院": "「通院」は病院に通うことで、「荷物の通院」は成り立たない。", "入学": "「入学」は学校に入ることで、「荷物の入学」は成り立たない。", "休憩": "「休憩」は一息つくことで、「荷物の休憩が止まる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "輸送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電話で輸送をとり、予定を決めた。", "explanation": "輸送は物や人を乗り物で運ぶことなので、連絡をとる相手にはならない。"}, {"text": "映画に輸送した。", "explanation": "輸送は運ぶことなので、心が動く場面では使わない。"}, {"text": "新人が輸送を受ける。", "explanation": "輸送は物や人を運ぶことで、教育を受けるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37212, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "輸送", "is_correct": true, "explanation": "「店へ輸送されます」は、店まで運ばれるという意味になり自然。"}, {"text": "採点", "is_correct": false, "explanation": "「採点」は答案に点をつけることで、「店へ採点される」は成り立たない。"}, {"text": "出産", "is_correct": false, "explanation": "「出産」は子どもを産むことで、「店へ出産される」は成り立たない。"}, {"text": "運動", "is_correct": false, "explanation": "「運動」は体を動かすことで、「店へ運動される」は意味が通らない。"}], "explanations": {"輸送": "「店へ輸送されます」は、店まで運ばれるという意味になり自然。", "採点": "「採点」は答案に点をつけることで、「店へ採点される」は成り立たない。", "出産": "「出産」は子どもを産むことで、「店へ出産される」は成り立たない。", "運動": "「運動」は体を動かすことで、「店へ運動される」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "輸送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暑いので、公園で輸送した。", "explanation": "輸送は物や人を乗り物で運ぶことなので、一息つく行動には使わない。"}, {"text": "毎朝、窓の輸送をした。", "explanation": "輸送は物を乗り物で遠くへ運ぶことなので、窓をふく行為には使わない。"}, {"text": "寝る前に輸送をする。", "explanation": "輸送は運ぶことを指すので、本を読む行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37212, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大量の部品を、貨物列車で輸送しる。", "corrected_sentence": "大量の部品を、貨物列車で輸送している。", "error_description": "「輸送する」の活用は「輸送している」。「輸送しる」は活用が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37212, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "製品の輸送を大型トラックを使います。", "corrected_sentence": "製品の輸送に大型トラックを使います。", "error_description": "「輸送に〜を使う」の「に」は目的を示す。「輸送を」にすると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37214, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「が」は主語を示す。「距離が遠い」で、距離の遠さを述べる自然な形になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「遠い」は状態を表す形容詞なので「距離を遠い」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や場所を示す。「距離に遠い」は文として成り立たず、遠いの主語にもならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「距離で遠い」は文にならず、状態を述べられない。"}], "correct_answer": "が", "explanations": {"が": "「が」は主語を示す。「距離が遠い」で、距離の遠さを述べる自然な形になる。", "を": "「を」は目的語を示すが、「遠い」は状態を表す形容詞なので「距離を遠い」は成り立たない。", "に": "「に」は方向や場所を示す。「距離に遠い」は文として成り立たず、遠いの主語にもならない。", "で": "「で」は手段や場所を示す。「距離で遠い」は文にならず、状態を述べられない。"}, "error_tags": {"を": "目的語の格", "に": "方向・場所の格", "で": "手段・場所の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37214, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」は目的語を示す。「距離をはかる」で、はかる対象を示す自然な形になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「距離へはかります」でははかる対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「距離とはかります」では目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す語で、「距離よりはかります」は文として意味を成さない。"}], "correct_answer": "を", "explanations": {"を": "「を」は目的語を示す。「距離をはかる」で、はかる対象を示す自然な形になる。", "へ": "「へ」は方向を示すが、「距離へはかります」でははかる対象を示せない。", "と": "「と」は並列や相手を示すが、「距離とはかります」では目的語にならない。", "より": "「より」は比較を示す語で、「距離よりはかります」は文として意味を成さない。"}, "error_tags": {"へ": "方向の格", "と": "並列・相手の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37214, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つの場所や物の間の長さのことです。", "primary_collocate": null, "pronunciation": "きょり", "ipa": "kʲoɾi", "syllable_count": 2, "sentences": [{"text": "家から駅までの距離は、約一キロです。", "target_word": "距離", "complexity_tier": "T3", "furigana": "家[いえ]から駅[えき]までの距離[きょり]は、約[やく]一[いち]キロです。", "sentence_source": "generated"}, {"text": "この二つの町は距離が遠いので、車で行きます。", "target_word": "距離", "complexity_tier": "T3", "furigana": "この二[ふた]つの町[まち]は距離[きょり]が遠[とお]いので、車[くるま]で行[い]きます。", "sentence_source": "generated"}, {"text": "先生は、走る距離を毎日少しずつ長くしました。", "target_word": "距離", "complexity_tier": "T3", "furigana": "先生[せんせい]は、走[はし]る距離[きょり]を毎日[まいにち]少[すこ]しずつ長[なが]くしました。", "sentence_source": "generated"}, {"text": "前の車との距離をあけて走ってください。", "target_word": "距離", "complexity_tier": "T3", "furigana": "前[まえ]の車[くるま]との距離[きょり]をあけて走[はし]ってください。", "sentence_source": "generated"}, {"text": "距離が近いので、歩いて行きましょう。", "target_word": "距離", "complexity_tier": "T3", "furigana": "距離[きょり]が近[ちか]いので、歩[ある]いて行[い]きましょう。", "sentence_source": "generated"}, {"text": "地図で、東京と大阪の距離を調べました。", "target_word": "距離", "complexity_tier": "T3", "furigana": "地図[ちず]で、東京[とうきょう]と大阪[おおさか]の距離[きょり]を調[しら]べました。", "sentence_source": "generated"}, {"text": "毎朝、長い距離を自転車で通っています。", "target_word": "距離", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、長[なが]い距離[きょり]を自転車[じてんしゃ]で通[かよ]っています。", "sentence_source": "generated"}, {"text": "ボールが飛んだ距離を、メジャーではかります。", "target_word": "距離", "complexity_tier": "T3", "furigana": "ボールが飛[と]んだ距離[きょり]を、メジャーではかります。", "sentence_source": "generated"}, {"text": "距離が長いので、タクシー代が高くなりました。", "target_word": "距離", "complexity_tier": "T3", "furigana": "距離[きょり]が長[なが]いので、タクシー代[だい]が高[たか]くなりました。", "sentence_source": "generated"}, {"text": "二つの駅の距離は、思ったより短かったです。", "target_word": "距離", "complexity_tier": "T3", "furigana": "二[ふた]つの駅[えき]の距離[きょり]は、思[おも]ったより短[みじか]かったです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "距離", "label": "辞書形（名詞）"}, {"form": "距離が", "label": "主格"}, {"form": "距離を", "label": "目的格"}], "register": "標準（丁寧体）", "sense_fingerprint": "二つの場所や物の間の長さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1174785-6c89-4c94-b05d-420bafe00172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37214, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "距離", "is_correct": true, "explanation": "「距離」は二つの場所の間の長さを表す。「家から駅までの距離は、約一キロです」で、長さを示すこの語が入る。"}, {"text": "速度", "is_correct": false, "explanation": "速度は進む速さを表す語で、「約一キロです」という長さの説明には合わない。"}, {"text": "時間", "is_correct": false, "explanation": "時間は長さではないので、「家から駅までの時間は約一キロです」は意味が通らない。"}, {"text": "料金", "is_correct": false, "explanation": "料金は支払う金額を表す語で、一キロという長さとは結びつかない。"}], "explanations": {"距離": "「距離」は二つの場所の間の長さを表す。「家から駅までの距離は、約一キロです」で、長さを示すこの語が入る。", "速度": "速度は進む速さを表す語で、「約一キロです」という長さの説明には合わない。", "時間": "時間は長さではないので、「家から駅までの時間は約一キロです」は意味が通らない。", "料金": "料金は支払う金額を表す語で、一キロという長さとは結びつかない。"}, "sentence_index": 0, "correct_answer": "距離"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家から駅までは、歩くと距離がかかります。", "explanation": "ここは〈時間〉の意味。「かかる」のは時間で、距離は長さなので「距離がかかる」とは言わない。"}, {"text": "会議の距離を二週間にしました。", "explanation": "ここは〈時間の間隔〉の意味。日を空けることは「間隔」で表し、空間の隔たりである距離は時間には使わない。"}, {"text": "タクシーの距離が高くなりました。", "explanation": "ここは〈料金〉の意味。「高くなる」が合うのは料金で、距離は長さなので「距離が高くなる」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37214, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "距離", "is_correct": true, "explanation": "「長い距離」は、毎朝通う道のりの隔たりを表す。自転車で通う区間の長さとして自然に入る。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは物の目方を表すので、「長い重さを自転車で通う」は意味が通らない。"}, {"text": "費用", "is_correct": false, "explanation": "費用は支払う金額を表すので、通うという動作の対象にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表し、「長い」という長さの形容と結びつかない。"}], "explanations": {"距離": "「長い距離」は、毎朝通う道のりの隔たりを表す。自転車で通う区間の長さとして自然に入る。", "重さ": "重さは物の目方を表すので、「長い重さを自転車で通う」は意味が通らない。", "費用": "費用は支払う金額を表すので、通うという動作の対象にはならない。", "天気": "天気は空模様を表し、「長い」という長さの形容と結びつかない。"}, "sentence_index": 6, "correct_answer": "距離"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋の距離は三十度です。", "explanation": "ここは〈温度〉の意味。「三十度」は温度を表す語で、二つの点の隔たりである距離とは言わない。"}, {"text": "この電車の距離は、時速百キロです。", "explanation": "ここは〈速さ〉の意味。時速で表すのは速さで、距離を時速で表すことはない。"}, {"text": "このペットボトルの距離は五百ミリリットルです。", "explanation": "ここは〈容量〉の意味。ミリリットルで量を示すのは容量で、二つの点の隔たりである距離とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37214, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校と図書館の距離を近いので、毎日歩いて行きます。", "corrected_sentence": "学校と図書館の距離が近いので、毎日歩いて行きます。", "error_description": "誤：距離を近い　正：距離が近い。「近い」は形容詞で、その主語になる「距離」には「が」を付ける。「を」は目的語を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37214, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校から駅までの距離に測りました。", "corrected_sentence": "学校から駅までの距離を測りました。", "error_description": "誤：距離に測りました　正：距離を測りました。「測る」は測る対象を「を」で示す。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37216, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「に」は存在の場所を示す。「この辺りには、コンビニがありません」で、場所の範囲を表す自然な形になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「この辺りを、コンビニがありません」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「この辺りへ、コンビニがありません」は存在の文にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「この辺りと、コンビニがありません」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「に」は存在の場所を示す。「この辺りには、コンビニがありません」で、場所の範囲を表す自然な形になる。", "を": "「を」は目的語を示すが、「この辺りを、コンビニがありません」は文として成り立たない。", "へ": "「へ」は方向を示すが、「この辺りへ、コンビニがありません」は存在の文にならない。", "と": "「と」は並列や相手を示すが、「この辺りと、コンビニがありません」は意味が通らない。"}, "error_tags": {"を": "目的語の格", "へ": "方向の格", "と": "並列・相手の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37216, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「に」は存在の場所を示す。「あの大きな木の辺りに、鳥の巣があります」で、存在する場所を表す自然な形になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作が行われる場所を示す。存在を表す「ある」には「に」が必要なので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「辺りから、鳥の巣があります」は存在の場所を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「辺りより、鳥の巣があります」は比較の文にならない。"}], "correct_answer": "に", "explanations": {"に": "「に」は存在の場所を示す。「あの大きな木の辺りに、鳥の巣があります」で、存在する場所を表す自然な形になる。", "で": "「で」は動作が行われる場所を示す。存在を表す「ある」には「に」が必要なので合わない。", "から": "「から」は起点を示す。「辺りから、鳥の巣があります」は存在の場所を示せない。", "より": "「より」は比較を示す。「辺りより、鳥の巣があります」は比較の文にならない。"}, "error_tags": {"で": "動作の場所の格", "から": "起点の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37216, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かがどこにあるか、その場所のことを言います。「机の辺り」は、机の近くのところです。", "primary_collocate": null, "pronunciation": "あたり", "ipa": "ataɾi", "syllable_count": 3, "sentences": [{"text": "机の辺りに、さいふを置いたはずです。", "target_word": "辺り", "complexity_tier": "T3", "furigana": "机[つくえ]の辺[あた]りに、さいふを置[お]いたはずです。", "sentence_source": "generated"}, {"text": "この辺りには、コンビニがありません。", "target_word": "辺り", "complexity_tier": "T3", "furigana": "この辺[あた]りには、コンビニがありません。", "sentence_source": "generated"}, {"text": "公園の辺りで、子どもたちが遊んでいます。", "target_word": "辺り", "complexity_tier": "T3", "furigana": "公園[こうえん]の辺[あた]りで、子[こ]どもたちが遊[あそ]んでいます。", "sentence_source": "generated"}, {"text": "音は、ドアの辺りから聞こえました。", "target_word": "辺り", "complexity_tier": "T3", "furigana": "音[おと]は、ドアの辺[あた]りから聞[き]こえました。", "sentence_source": "generated"}, {"text": "駅の辺りは、夜でも明るいです。", "target_word": "辺り", "complexity_tier": "T3", "furigana": "駅[えき]の辺[あた]りは、夜[よる]でも明[あか]るいです。", "sentence_source": "generated"}, {"text": "ソファの辺りを探しましたが、かぎは見つかりませんでした。", "target_word": "辺り", "complexity_tier": "T3", "furigana": "ソファの辺[あた]りを探[さが]しましたが、かぎは見[み]つかりませんでした。", "sentence_source": "generated"}, {"text": "家の辺りは、とても静かで住みやすいです。", "target_word": "辺り", "complexity_tier": "T3", "furigana": "家[いえ]の辺[あた]りは、とても静[しず]かで住[す]みやすいです。", "sentence_source": "generated"}, {"text": "あの大きな木の辺りに、鳥の巣があります。", "target_word": "辺り", "complexity_tier": "T3", "furigana": "あの大[おお]きな木[き]の辺[あた]りに、鳥[とり]の巣[す]があります。", "sentence_source": "generated"}, {"text": "川の辺りを歩くと、気持ちがいいです。", "target_word": "辺り", "complexity_tier": "T3", "furigana": "川[かわ]の辺[あた]りを歩[ある]くと、気持[きも]ちがいいです。", "sentence_source": "generated"}, {"text": "窓の辺りが、急に暗くなりました。", "target_word": "辺り", "complexity_tier": "T3", "furigana": "窓[まど]の辺[あた]りが、急[きゅう]に暗[くら]くなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "辺り", "label": "辞書形（名詞）"}, {"form": "辺りに", "label": "場所格"}, {"form": "辺りは", "label": "主題"}], "register": "標準（丁寧体）", "sense_fingerprint": "あるものの近くの、だいたいの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1174785-6c89-4c94-b05d-420bafe00172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37216, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辺り", "is_correct": true, "explanation": "「辺り」は何かの周辺の場所を表す。「机の辺りに置いた」で、さいふのあった場所の範囲を示す。"}, {"text": "色", "is_correct": false, "explanation": "色は物の見た目を表す語で、置く場所を示せないので「机の色に置いた」は合わない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は金額を表す語で、物を置く場所にはならない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは目方を表す語で、場所を示せないので「机の重さに置いた」は意味が通らない。"}], "explanations": {"辺り": "「辺り」は何かの周辺の場所を表す。「机の辺りに置いた」で、さいふのあった場所の範囲を示す。", "色": "色は物の見た目を表す語で、置く場所を示せないので「机の色に置いた」は合わない。", "値段": "値段は金額を表す語で、物を置く場所にはならない。", "重さ": "重さは目方を表す語で、場所を示せないので「机の重さに置いた」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "辺り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議は三時辺りに始まります。", "explanation": "ここは〈時刻の目安〉の意味。辺りを時間の大まかな目安に使うのは別の用法で、場所の周囲を指すこの語義には合わない。"}, {"text": "お礼は三千円辺りです。", "explanation": "ここは〈金額の目安〉の意味。辺りを金額の大まかな目安に使うのは別の用法で、場所を指すこの語義とは合わない。"}, {"text": "彼女は四十歳辺りです。", "explanation": "ここは〈年齢の目安〉の意味。辺りを年齢の大まかな目安に使うのは別の用法で、場所を指すこの語義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37216, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辺り", "is_correct": true, "explanation": "「家の辺り」は家の周辺の地域を表す。「とても静かで住みやすい」という地域の様子を述べる文に合う。"}, {"text": "形", "is_correct": false, "explanation": "形は物の姿を表す語で、地域の静かさや住みやすさを主語として示せない。"}, {"text": "数", "is_correct": false, "explanation": "数は量を表す語で、「家の数は、静かで住みやすい」は意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期を表す語で、場所の性質を述べる主語にはならない。"}], "explanations": {"辺り": "「家の辺り」は家の周辺の地域を表す。「とても静かで住みやすい」という地域の様子を述べる文に合う。", "形": "形は物の姿を表す語で、地域の静かさや住みやすさを主語として示せない。", "数": "数は量を表す語で、「家の数は、静かで住みやすい」は意味が通らない。", "季節": "季節は時期を表す語で、場所の性質を述べる主語にはならない。"}, "sentence_index": 6, "correct_answer": "辺り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この作業は一時間辺りで終わります。", "explanation": "ここは〈所要時間の目安〉の意味。辺りを所要時間の大まかな目安に使うのは別の用法で、場所を指すこの語義とは合わない。"}, {"text": "来週の金曜日辺りに電話します。", "explanation": "ここは〈日付の目安〉の意味。辺りを日付の大まかな目安に使うのは別の用法で、場所を指すこの語義とは合わない。"}, {"text": "参加者は十人辺りです。", "explanation": "ここは〈人数の目安〉の意味。辺りを人数の大まかな目安に使うのは別の用法で、場所を指すこの語義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37216, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店の辺りで、駐車場があります。", "corrected_sentence": "店の辺りに、駐車場があります。", "error_description": "誤：辺りで　正：辺りに。存在を表す「ある」には、場所に「に」を付ける。「で」は動作が行われる場所なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37216, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍵は窓の辺りをあります。", "corrected_sentence": "鍵は窓の辺りにあります。", "error_description": "誤：辺りを　正：辺りに。存在を表す「ある」には場所に「に」を付ける。「を」は目的語を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad4f78e-d837-4816-91f0-5f421e8fde46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37218, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "並列の「と」。「二と三を足した」の形で、数を並べる文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」が二つ並ぶ。「二を三を足した」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "移動の方向を表す「へ」。数の並列には使えず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「二より三を足した」となり、並列の意味に合わない。"}], "correct_answer": "と", "explanations": {"と": "並列の「と」。「二と三を足した」の形で、数を並べる文に合う。", "を": "目的語の「を」が二つ並ぶ。「二を三を足した」は文が成り立たない。", "へ": "移動の方向を表す「へ」。数の並列には使えず、文が成り立たない。", "より": "比較の「より」。「二より三を足した」となり、並列の意味に合わない。"}, "error_tags": {"を": "目的語の重複", "へ": "移動の方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37218, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37218, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "かずの、ふたつ。", "primary_collocate": null, "pronunciation": "に", "ipa": "ni", "syllable_count": 1, "sentences": [{"text": "三から一を引くと、二になります。", "target_word": "二", "complexity_tier": "T3", "furigana": "三[さん]から一[いち]を引[ひ]くと、二[に]になります。", "sentence_source": "generated"}, {"text": "五は二と三を足した数です。", "target_word": "二", "complexity_tier": "T3", "furigana": "五[ご]は二[に]と三[さん]を足[た]した数[かず]です。", "sentence_source": "generated"}, {"text": "四の半分は二です。", "target_word": "二", "complexity_tier": "T3", "furigana": "四[よん]の半分[はんぶん]は二[に]です。", "sentence_source": "generated"}, {"text": "十を五で割ると、答えは二です。", "target_word": "二", "complexity_tier": "T3", "furigana": "十[じゅう]を五[ご]で割[わ]ると、答[こた]えは二[に]です。", "sentence_source": "generated"}, {"text": "一の次の数は二です。", "target_word": "二", "complexity_tier": "T3", "furigana": "一[いち]の次[つぎ]の数[かず]は二[に]です。", "sentence_source": "generated"}, {"text": "二に二をかけると、四になる。", "target_word": "二", "complexity_tier": "T3", "furigana": "二[に]に二[に]をかけると、四[よん]になる。", "sentence_source": "generated"}, {"text": "一、二、三と声に出して数えましょう。", "target_word": "二", "complexity_tier": "T3", "furigana": "一[いち]、二[に]、三[さん]と声[こえ]に出[だ]して数[かぞ]えましょう。", "sentence_source": "generated"}, {"text": "二は一より大きく、三より小さい数です。", "target_word": "二", "complexity_tier": "T3", "furigana": "二[に]は一[いち]より大[おお]きく、三[さん]より小[ちい]さい数[かず]です。", "sentence_source": "generated"}, {"text": "一に一を足すと二になります。", "target_word": "二", "complexity_tier": "T3", "furigana": "一[いち]に一[いち]を足[た]すと二[に]になります。", "sentence_source": "generated"}, {"text": "九から七を引くと、残りは二です。", "target_word": "二", "complexity_tier": "T3", "furigana": "九[きゅう]から七[なな]を引[ひ]くと、残[のこ]りは二[に]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "二", "label": "基本形"}, {"form": "二つ", "label": "助数詞つき"}], "register": "neutral", "sense_fingerprint": "数としての、ふたつ分の量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3049333-685e-4b1b-9295-162778d51a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37218, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二", "is_correct": true, "explanation": "数の二。「三から一を引くと二になります」で、計算の答えとして成り立つ。"}, {"text": "引き", "is_correct": false, "explanation": "「引く」の連用形。「〜になります」の前に名詞として置けず、文が成り立たない。"}, {"text": "足し", "is_correct": false, "explanation": "「足す」の連用形。計算の答えを表す名詞の位置には入らず、文が成り立たない。"}, {"text": "割り", "is_correct": false, "explanation": "「割る」の連用形。計算の答えを表す名詞の位置には入らず、文が成り立たない。"}], "explanations": {"二": "数の二。「三から一を引くと二になります」で、計算の答えとして成り立つ。", "引き": "「引く」の連用形。「〜になります」の前に名詞として置けず、文が成り立たない。", "足し": "「足す」の連用形。計算の答えを表す名詞の位置には入らず、文が成り立たない。", "割り": "「割る」の連用形。計算の答えを表す名詞の位置には入らず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "二"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は二目で目標を見つめた。", "explanation": "ここは〈両〉の意味。両目で見る意味は〈両目〉で言い、〈二目〉は囲碁の用語なので、目で見る動作には使わない。"}, {"text": "彼は今日のテストで二を取り、すぐに合格した。", "explanation": "ここは〈点〉の意味。テストの得点は〈二点〉のように数えるので、〈二〉だけでは得点を表せない。"}, {"text": "両手を広げるかわりに、二手を広げた。", "explanation": "ここは〈どちらも〉の意味。〈二手〉は囲碁や将棋の一手を指すので、体の部位には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37218, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二", "is_correct": true, "explanation": "数の二。「一、二、三と声に出して数える」の一部で、数の順番として正しい。"}, {"text": "測り", "is_correct": false, "explanation": "「測る」の連用形。数を数える文に入ると、文が成り立たない。"}, {"text": "比べ", "is_correct": false, "explanation": "「比べる」の連用形。数の並びの位置には入らず、文が成り立たない。"}, {"text": "並べ", "is_correct": false, "explanation": "「並べる」の連用形。数の並びの位置には入らず、文が成り立たない。"}], "explanations": {"二": "数の二。「一、二、三と声に出して数える」の一部で、数の順番として正しい。", "測り": "「測る」の連用形。数を数える文に入ると、文が成り立たない。", "比べ": "「比べる」の連用形。数の並びの位置には入らず、文が成り立たない。", "並べ": "「並べる」の連用形。数の並びの位置には入らず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "二"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その選手は、片足のかわりに二足で跳んだ。", "explanation": "ここは〈両足〉の意味。足を両方使う動作は〈両足〉で言い、〈二足〉は靴や靴下を数える語なので、動作の言い方としては使わない。"}, {"text": "彼女は箱の二を開けた。", "explanation": "ここは〈ふた〉の意味。箱のふたは〈ふた〉で言い、〈二〉は数字なので箱の部分は指せない。"}, {"text": "彼は荷物を二で運んだ。", "explanation": "ここは〈二人で〉の意味。人数を表すなら〈二人〉を使い、〈二〉だけでは手段を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37218, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "八を二を割ると四になる。", "corrected_sentence": "八を二で割ると四になる。", "error_description": "「割る」の手段・基準を表すには「で」が必要。「二を割る」は誤りで、「二で割る」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37218, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "四は二に大きい。", "corrected_sentence": "四は二より大きい。", "error_description": "比較には「より」を使う。「二に大きい」は誤りで、「二より大きい」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37219, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「二で終わる」は、最後の数字が2であることを示す自然な形。正解。"}, {"text": "と", "is_correct": false, "explanation": "引用・並列の「と」。「二と終わります」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。終わる先を示す語ではないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。比べる相手がないので「二より終わります」は不自然。"}], "correct_answer": "で", "explanations": {"で": "「二で終わる」は、最後の数字が2であることを示す自然な形。正解。", "と": "引用・並列の「と」。「二と終わります」では文が成り立たない。", "へ": "方向を表す「へ」。終わる先を示す語ではないので合わない。", "より": "比較の「より」。比べる相手がないので「二より終わります」は不自然。"}, "error_tags": {"と": "引用", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37219, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「二を指す」の目的語を示す「を」。「指す」は対象を「を」で取るので正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「二が指す」では指す対象を示せず不自然。"}, {"text": "に", "is_correct": false, "explanation": "方向・位置の「に」。「二に指す」とは言わない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。指す対象を示せないので文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「二を指す」の目的語を示す「を」。「指す」は対象を「を」で取るので正解。", "が": "主語を示す「が」。「二が指す」では指す対象を示せず不自然。", "に": "方向・位置の「に」。「二に指す」とは言わない。", "から": "起点の「から」。指す対象を示せないので文が成り立たない。"}, "error_tags": {"が": "主語", "に": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37219, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数字の2。", "primary_collocate": null, "pronunciation": "に", "ipa": "ni", "syllable_count": 1, "sentences": [{"text": "この暗証番号の最初の数字は二です。", "target_word": "二", "complexity_tier": "T3", "furigana": "この暗証番号[あんしょうばんごう]の最初[さいしょ]の数字[すうじ]は二[に]です。", "sentence_source": "generated"}, {"text": "電話番号の最後は二で終わります。", "target_word": "二", "complexity_tier": "T3", "furigana": "電話番号[でんわばんごう]の最後[さいご]は二[に]で終[お]わります。", "sentence_source": "generated"}, {"text": "黒板に大きく「二」と書きました。", "target_word": "二", "complexity_tier": "T3", "furigana": "黒板[こくばん]に大[おお]きく「二[に]」と書[か]きました。", "sentence_source": "generated"}, {"text": "漢数字の二は、横線だけで書けます。", "target_word": "二", "complexity_tier": "T3", "furigana": "漢数字[かんすうじ]の二[に]は、横線[よこせん]だけで書[か]けます。", "sentence_source": "generated"}, {"text": "私の出席番号は二で、名簿の最初の方にあります。", "target_word": "二", "complexity_tier": "T3", "furigana": "私[わたし]の出席番号[しゅっせきばんごう]は二[に]で、名簿[めいぼ]の最初[さいしょ]の方[ほう]にあります。", "sentence_source": "generated"}, {"text": "答えの欄に二と書いてください。", "target_word": "二", "complexity_tier": "T3", "furigana": "答[こた]えの欄[らん]に二[に]と書[か]いてください。", "sentence_source": "generated"}, {"text": "数字の二と五は、形が少し似ています。", "target_word": "二", "complexity_tier": "T3", "furigana": "数字[すうじ]の二[に]と五[ご]は、形[かたち]が少[すこ]し似[に]ています。", "sentence_source": "generated"}, {"text": "時計の針が二を指しています。", "target_word": "二", "complexity_tier": "T3", "furigana": "時計[とけい]の針[はり]が二[に]を指[さ]しています。", "sentence_source": "generated"}, {"text": "くじ引きで二が出たら、私の勝ちです。", "target_word": "二", "complexity_tier": "T3", "furigana": "くじ引[び]きで二[に]が出[で]たら、私[わたし]の勝[か]ちです。", "sentence_source": "generated"}, {"text": "エレベーターの二のボタンを押してください。", "target_word": "二", "complexity_tier": "T3", "furigana": "エレベーターの二[に]のボタンを押[お]してください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "二", "label": "基本形"}, {"form": "二つ", "label": "助数詞つき"}], "register": "neutral", "sense_fingerprint": "数字や番号として書き表す2", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3049333-685e-4b1b-9295-162778d51a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37219, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二", "is_correct": true, "explanation": "数字の2を表す語。「最初の数字は二です」と言えるので正解。"}, {"text": "二人", "is_correct": false, "explanation": "人数を数える語。「最初の数字は二人です」では数字の話にならない。"}, {"text": "二階", "is_correct": false, "explanation": "建物の階を指す語。「最初の数字は二階です」は意味が通らない。"}, {"text": "二回", "is_correct": false, "explanation": "回数を表す語。数字の値を述べる文の空欄には入らない。"}], "explanations": {"二": "数字の2を表す語。「最初の数字は二です」と言えるので正解。", "二人": "人数を数える語。「最初の数字は二人です」では数字の話にならない。", "二階": "建物の階を指す語。「最初の数字は二階です」は意味が通らない。", "二回": "回数を表す語。数字の値を述べる文の空欄には入らない。"}, "sentence_index": 0, "correct_answer": "二"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その選手は二足でしっかり立って、ボールを待った。", "explanation": "ここは〈両足〉（左右の足）の意味。〈二足〉は靴などの組を数える言葉で、足の数には使わないので合わない。"}, {"text": "旅行の計画を二回に分けて話し合った。", "explanation": "ここは回数の〈二回〉の意味。数字の2の記号を指す使い方ではないので定義に合わない。"}, {"text": "二月に入ると、寒さが一段と厳しくなる。", "explanation": "ここは〈二月〉（月の名前）の意味。数字の2を表す使い方ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37219, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二", "is_correct": true, "explanation": "数字の2を表す語。「数字の___と五」として形を比べる対象になるので正解。"}, {"text": "二羽", "is_correct": false, "explanation": "鳥を数える語。数字の2とは言えず、ここでは不自然。"}, {"text": "二枚", "is_correct": false, "explanation": "薄いものを数える語。数字の種類を表さないので合わない。"}, {"text": "二杯", "is_correct": false, "explanation": "容器の中身を数える語。数字として形を比べる文には入らない。"}], "explanations": {"二": "数字の2を表す語。「数字の___と五」として形を比べる対象になるので正解。", "二羽": "鳥を数える語。数字の2とは言えず、ここでは不自然。", "二枚": "薄いものを数える語。数字の種類を表さないので合わない。", "二杯": "容器の中身を数える語。数字として形を比べる文には入らない。"}, "sentence_index": 6, "correct_answer": "二"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "財布を二色に塗り分けたら、見た目がおしゃれになった。", "explanation": "ここは〈二色〉（色の数）の意味。数字の2の記号を指す語ではないので定義に合わない。"}, {"text": "この薬は二回に分けて飲んでください。", "explanation": "ここは回数の〈二回〉の意味。数字の記号ではなく、飲む回数を表すので合わない。"}, {"text": "財布に千円札が二枚入っていた。", "explanation": "ここは紙幣を数える〈二枚〉の意味。数字そのものを表す使い方ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37219, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "りんごを二買いました。", "corrected_sentence": "りんごを二つ買いました。", "error_description": "物の数を言うときは助数詞「つ」を付けて「二つ」とする。「二」だけでは不自然で、「二つ」が正しい形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37219, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "サイコロで二を出たら、私の勝ちです。", "corrected_sentence": "サイコロで二が出たら、私の勝ちです。", "error_description": "「出る」は主語に「が」を取る自動詞なので、「二を出たら」は誤り。「二が出たら」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37220, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「車両」の後に続く主語を示す正しい格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「車両をこわれた」は、壊れる動作の主語に目的語を使う誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「車両へこわれた」は方向を示すが、壊れる動作の向きにはならない。"}, {"text": "と", "is_correct": false, "explanation": "「車両とこわれた」は共同の意味になり、ここでは成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「車両」の後に続く主語を示す正しい格助詞。", "を": "「車両をこわれた」は、壊れる動作の主語に目的語を使う誤り。", "へ": "「車両へこわれた」は方向を示すが、壊れる動作の向きにはならない。", "と": "「車両とこわれた」は共同の意味になり、ここでは成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37220, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「調べる」の対象を示す正しい格助詞。"}, {"text": "の", "is_correct": false, "explanation": "「車両の調べている」は動詞の主語や目的語にならず、成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「車両に調べている」は対象を示せず、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「車両と調べている」は共同の意味になり、ここでは成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「調べる」の対象を示す正しい格助詞。", "の": "「車両の調べている」は動詞の主語や目的語にならず、成り立たない。", "に": "「車両に調べている」は対象を示せず、成り立たない。", "と": "「車両と調べている」は共同の意味になり、ここでは成り立たない。"}, "error_tags": {"の": "連体修飾", "に": "相手・到達点", "と": "相手・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37220, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "道路を走る自動車やトラックなど、陸上を走る乗り物のこと。", "primary_collocate": null, "pronunciation": "しゃりょう", "ipa": "ɕaɾʲoː", "syllable_count": 3, "sentences": [{"text": "この道路は、大型の車両は通行できない。", "target_word": "車両", "complexity_tier": "T3", "furigana": "この道路[どうろ]は、大型[おおがた]の車両[しゃりょう]は通行[つうこう]できない。", "sentence_source": "generated"}, {"text": "事故で車両がこわれたため、会社は新しいものを買った。", "target_word": "車両", "complexity_tier": "T3", "furigana": "事故[じこ]で車両[しゃりょう]がこわれたため、会社[かいしゃ]は新[あたら]しいものを買[か]った。", "sentence_source": "generated"}, {"text": "工事現場には、重い荷物を運ぶ車両が何台も入っている。", "target_word": "車両", "complexity_tier": "T3", "furigana": "工事現場[こうじげんば]には、重[おも]い荷物[にもつ]を運[はこ]ぶ車両[しゃりょう]が何台[なんだい]も入[はい]っている。", "sentence_source": "generated"}, {"text": "消防の車両が、サイレンを鳴らして走っていった。", "target_word": "車両", "complexity_tier": "T3", "furigana": "消防[しょうぼう]の車両[しゃりょう]が、サイレンを鳴[な]らして走[はし]っていった。", "sentence_source": "generated"}, {"text": "この駐車場は、車両の高さが二メートルまでだ。", "target_word": "車両", "complexity_tier": "T3", "furigana": "この駐車場[ちゅうしゃじょう]は、車両[しゃりょう]の高[たか]さが二[に]メートルまでだ。", "sentence_source": "generated"}, {"text": "雪の日は、車両の事故が多いので、ゆっくり走る。", "target_word": "車両", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、車両[しゃりょう]の事故[じこ]が多[おお]いので、ゆっくり走[はし]る。", "sentence_source": "generated"}, {"text": "荷物をのせた車両が、橋の手前で止まっている。", "target_word": "車両", "complexity_tier": "T3", "furigana": "荷物[にもつ]をのせた車両[しゃりょう]が、橋[はし]の手前[てまえ]で止[と]まっている。", "sentence_source": "generated"}, {"text": "警察は、事件に使われた車両を調べている。", "target_word": "車両", "complexity_tier": "T3", "furigana": "警察[けいさつ]は、事件[じけん]に使[つか]われた車両[しゃりょう]を調[しら]べている。", "sentence_source": "generated"}, {"text": "運送会社は、毎年古い車両を新しいものに替えている。", "target_word": "車両", "complexity_tier": "T3", "furigana": "運送会社[うんそうがいしゃ]は、毎年[まいとし]古[ふる]い車両[しゃりょう]を新[あたら]しいものに替[か]えている。", "sentence_source": "generated"}, {"text": "この通りは、朝七時から九時まで車両の進入が禁止される。", "target_word": "車両", "complexity_tier": "T3", "furigana": "この通[とお]りは、朝[あさ]七時[しちじ]から九時[くじ]まで車両[しゃりょう]の進入[しんにゅう]が禁止[きんし]される。", "sentence_source": "generated"}], "morphological_forms": [{"form": "車両", "label": "基本形"}], "register": "標準・常体", "sense_fingerprint": "道路を走る自動車・トラックなどの乗り物全般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37220, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "車両", "is_correct": true, "explanation": "「大型の車両は通行できない」は、道路を通る乗り物を指して自然に成り立つ。"}, {"text": "雑誌", "is_correct": false, "explanation": "「大型の雑誌は通行できない」は意味が通らない。雑誌は通行する対象ではない。"}, {"text": "電柱", "is_correct": false, "explanation": "「大型の電柱は通行できない」は不自然。電柱は道路を通るものではない。"}, {"text": "食材", "is_correct": false, "explanation": "「大型の食材は通行できない」は意味が合わない。食材は通行の対象にならない。"}], "explanations": {"車両": "「大型の車両は通行できない」は、道路を通る乗り物を指して自然に成り立つ。", "雑誌": "「大型の雑誌は通行できない」は意味が通らない。雑誌は通行する対象ではない。", "電柱": "「大型の電柱は通行できない」は不自然。電柱は道路を通るものではない。", "食材": "「大型の食材は通行できない」は意味が合わない。食材は通行の対象にならない。"}, "sentence_index": 0, "correct_answer": "車両"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末、家族で車両に乗って海へ出た。", "explanation": "ここは〈船〉の意味。車両は陸を走る乗り物を指すので、海を進む船の代わりには使わない。"}, {"text": "学校の車両で、子どもたちが宿題をした。", "explanation": "ここは〈教室〉の意味。車両は乗り物を指すので、勉強する部屋の代わりには使わない。"}, {"text": "車両を敷く工事が始まった。", "explanation": "ここは〈線路〉の意味。車両は乗り物そのもので、線路を敷く対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37220, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "車両", "is_correct": true, "explanation": "「荷物をのせた車両が止まっている」は、橋の手前で止まる乗り物として自然に成り立つ。"}, {"text": "手紙", "is_correct": false, "explanation": "「荷物をのせた手紙が止まっている」は意味が合わない。手紙は止まる主体にならない。"}, {"text": "植木", "is_correct": false, "explanation": "「荷物をのせた植木が止まっている」は不自然。植木は走って止まるものではない。"}, {"text": "看板", "is_correct": false, "explanation": "「荷物をのせた看板が止まっている」は意味が通らない。看板は走らない。"}], "explanations": {"車両": "「荷物をのせた車両が止まっている」は、橋の手前で止まる乗り物として自然に成り立つ。", "手紙": "「荷物をのせた手紙が止まっている」は意味が合わない。手紙は止まる主体にならない。", "植木": "「荷物をのせた植木が止まっている」は不自然。植木は走って止まるものではない。", "看板": "「荷物をのせた看板が止まっている」は意味が通らない。看板は走らない。"}, "sentence_index": 6, "correct_answer": "車両"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この滑走路は、朝七時から九時まで車両の離陸が禁止される。", "explanation": "ここは〈飛行機〉の意味。車両は地上を走る乗り物を指し、空を飛ぶものや離陸には使わない。"}, {"text": "車両が泣き止むまで、母親があやした。", "explanation": "ここは〈赤ちゃん〉の意味。車両は乗り物や機械を指し、泣く人には使わない。"}, {"text": "築五十年の車両を建て直して、家族が住み始めた。", "explanation": "ここは〈家〉の意味。車両は走る乗り物を指すので、人が住む建物の代わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37220, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この橋は、重い車両が通行を禁止している。", "corrected_sentence": "この橋は、重い車両の通行を禁止している。", "error_description": "「車両の通行」の「の」は関係を表す。「が」は主語を示すが、禁止する主体は車両ではないため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37220, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工場は、古い車両に処分する計画を立てた。", "corrected_sentence": "この工場は、古い車両を処分する計画を立てた。", "error_description": "「処分する」の対象は「を」で示す。「に」は誤りで、正しくは「車両を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37221, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「車両」が主語として連結の状態を表す正しい格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「車両をつながっている」は目的語になれず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「車両のつながっている」は動詞に続かず、文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「車両よりつながっている」は比較の意味になり、成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「車両」が主語として連結の状態を表す正しい格助詞。", "を": "「車両をつながっている」は目的語になれず、不自然。", "の": "「車両のつながっている」は動詞に続かず、文として成り立たない。", "より": "「車両よりつながっている」は比較の意味になり、成り立たない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
