INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37221, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電車や列車を構成する、一つ一つの車体のこと。", "primary_collocate": null, "pronunciation": "しゃりょう", "ipa": "ɕaɾʲoː", "syllable_count": 3, "sentences": [{"text": "電車の先頭車両は、朝でもあまりこんでいない。", "target_word": "車両", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の先頭[せんとう]車両[しゃりょう]は、朝[あさ]でもあまりこんでいない。", "sentence_source": "generated"}, {"text": "この列車は八つの車両がつながっている。", "target_word": "車両", "complexity_tier": "T3", "furigana": "この列車[れっしゃ]は八[やっ]つの車両[しゃりょう]がつながっている。", "sentence_source": "generated"}, {"text": "女性専用の車両に、男性は乗れない。", "target_word": "車両", "complexity_tier": "T3", "furigana": "女性専用[じょせいせんよう]の車両[しゃりょう]に、男性[だんせい]は乗[の]れない。", "sentence_source": "generated"}, {"text": "一番後ろの車両まで歩いて、空いた席を探した。", "target_word": "車両", "complexity_tier": "T3", "furigana": "一番[いちばん]後[うし]ろの車両[しゃりょう]まで歩[ある]いて、空[あ]いた席[せき]を探[さが]した。", "sentence_source": "generated"}, {"text": "古い車両は、来月から新しいものに入れ替わる。", "target_word": "車両", "complexity_tier": "T3", "furigana": "古[ふる]い車両[しゃりょう]は、来月[らいげつ]から新[あたら]しいものに入[い]れ替[か]わる。", "sentence_source": "generated"}, {"text": "事故の後、車両の点検が終わるまで電車は動かなかった。", "target_word": "車両", "complexity_tier": "T3", "furigana": "事故[じこ]の後[あと]、車両[しゃりょう]の点検[てんけん]が終[お]わるまで電車[でんしゃ]は動[うご]かなかった。", "sentence_source": "generated"}, {"text": "真ん中の車両にはレストランがあり、旅行客に人気だ。", "target_word": "車両", "complexity_tier": "T3", "furigana": "真[ま]ん中[なか]の車両[しゃりょう]にはレストランがあり、旅行客[りょこうきゃく]に人気[にんき]だ。", "sentence_source": "generated"}, {"text": "ホームの案内を見て、乗る車両の番号を確かめた。", "target_word": "車両", "complexity_tier": "T3", "furigana": "ホームの案内[あんない]を見[み]て、乗[の]る車両[しゃりょう]の番号[ばんごう]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "夜のあいだ、作業員が車両をきれいに洗っている。", "target_word": "車両", "complexity_tier": "T3", "furigana": "夜[よる]のあいだ、作業員[さぎょういん]が車両[しゃりょう]をきれいに洗[あら]っている。", "sentence_source": "generated"}, {"text": "雨の日は、車両の中がぬれた傘でいっぱいになる。", "target_word": "車両", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、車両[しゃりょう]の中[なか]がぬれた傘[かさ]でいっぱいになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "車両", "label": "基本形"}], "register": "標準・常体", "sense_fingerprint": "電車・列車を構成する一両一両の箱（鉄道の車両）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37221, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "車両", "is_correct": true, "explanation": "「先頭車両」は電車の一番前の車両を指し、混み具合の主語として自然。"}, {"text": "改札", "is_correct": false, "explanation": "「先頭改札」は意味が通らない。改札は電車の先頭にあるものではない。"}, {"text": "運転士", "is_correct": false, "explanation": "「先頭運転士は、朝でもあまりこんでいない」は主語として不自然。"}, {"text": "線路", "is_correct": false, "explanation": "「先頭線路は、朝でもあまりこんでいない」は電車の混雑を言う文に合わない。"}], "explanations": {"車両": "「先頭車両」は電車の一番前の車両を指し、混み具合の主語として自然。", "改札": "「先頭改札」は意味が通らない。改札は電車の先頭にあるものではない。", "運転士": "「先頭運転士は、朝でもあまりこんでいない」は主語として不自然。", "線路": "「先頭線路は、朝でもあまりこんでいない」は電車の混雑を言う文に合わない。"}, "sentence_index": 0, "correct_answer": "車両"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "車両を棚に載せて、席に座った。", "explanation": "ここは〈荷物〉の意味。車両は電車の車体を指し、棚に載せるものではない。"}, {"text": "車両が青に変わって、電車が動き出した。", "explanation": "ここは〈信号〉の意味。車両は車体を指し、色が変わるものではない。"}, {"text": "車両が値上げされて、通勤費が増えた。", "explanation": "ここは〈運賃〉の意味。車両は乗り物なので、値段が上がる対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37221, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "車両", "is_correct": true, "explanation": "「真ん中の車両」は電車の中央の車両を指し、レストランがある場所として自然。"}, {"text": "屋根", "is_correct": false, "explanation": "「真ん中の屋根にはレストランがあり」は不自然。屋根はレストランのある場所ではない。"}, {"text": "座席", "is_correct": false, "explanation": "「真ん中の座席にはレストランがあり」は、一席を指すので成り立たない。"}, {"text": "切符", "is_correct": false, "explanation": "「真ん中の切符にはレストランがあり」は意味が通らない。"}], "explanations": {"車両": "「真ん中の車両」は電車の中央の車両を指し、レストランがある場所として自然。", "屋根": "「真ん中の屋根にはレストランがあり」は不自然。屋根はレストランのある場所ではない。", "座席": "「真ん中の座席にはレストランがあり」は、一席を指すので成り立たない。", "切符": "「真ん中の切符にはレストランがあり」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "車両"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "川で車両を釣って、夕食に焼いた。", "explanation": "ここは〈魚〉の意味。車両は乗り物や機械を指すので、釣って食べる生き物の代わりには使わない。"}, {"text": "車両が切符を確認して回った。", "explanation": "ここは〈車掌〉の意味。車両は乗り物で、切符を確かめる人のように動く主体にはならない。"}, {"text": "車両が大きく育って、庭に日陰を作っている。", "explanation": "ここは〈木〉の意味。車両は乗り物を指すので、育って日陰を作る植物の代わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37221, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電車の先頭車両で非常ボタンがついている。", "corrected_sentence": "電車の先頭車両に非常ボタンがついている。", "error_description": "「ボタンがついている」の場所は「に」で示す。「で」は場所や手段の助詞で、付着の場所には使わない。正しくは「車両に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37221, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜になると、車両を照明が消える。", "corrected_sentence": "夜になると、車両の照明が消える。", "error_description": "「車両を」の「を」は誤り。照明の所属は「の」で示す。正しくは「車両の照明が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37222, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「水準がぐんと上がった」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「水準を上がった」とは言えず、「上がる」は対象を取らない自動詞なので「を」は入らない。"}, {"text": "で", "is_correct": false, "explanation": "「水準で上がった」は場所や手段の「で」になり、上がる主体を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「水準と上がった」は相手や並列の「と」で、変化の主体を表せない。"}], "correct_answer": "が", "explanations": {"が": "「水準がぐんと上がった」の主語を示す「が」。", "を": "「水準を上がった」とは言えず、「上がる」は対象を取らない自動詞なので「を」は入らない。", "で": "「水準で上がった」は場所や手段の「で」になり、上がる主体を示せない。", "と": "「水準と上がった」は相手や並列の「と」で、変化の主体を表せない。"}, "error_tags": {"が": "主語（正解）", "を": "対象（上がるに不適）", "で": "場所・手段（不適）", "と": "相手・並列（不適）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37222, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「水準に大きな差がある」の「に」で、差の対象となる基準を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「水準へ差がある」は方向を表し、差の対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「水準から差がある」は起点を表し、差の対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の表現になり、差の対象を述べる文意には合わない。"}], "correct_answer": "に", "explanations": {"に": "「水準に大きな差がある」の「に」で、差の対象となる基準を示す。", "へ": "「水準へ差がある」は方向を表し、差の対象を示せない。", "から": "「水準から差がある」は起点を表し、差の対象を示せない。", "より": "「より」は比較の表現になり、差の対象を述べる文意には合わない。"}, "error_tags": {"に": "基準・差（正解）", "へ": "方向（不適）", "から": "起点（不適）", "より": "比較（文意に合わない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37222, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の高さや程度のこと。", "primary_collocate": null, "pronunciation": "すいじゅん", "ipa": "sɯiʑɯɴ", "syllable_count": 4, "sentences": [{"text": "この大学は研究の水準が高いことで知られている。", "target_word": "水準", "complexity_tier": "T3", "furigana": "この大学[だいがく]は研究[けんきゅう]の水準[すいじゅん]が高[たか]いことで知[し]られている。", "sentence_source": "generated"}, {"text": "最近は彼の日本語の水準がぐんと上がった。", "target_word": "水準", "complexity_tier": "T3", "furigana": "最近[さいきん]は彼[かれ]の日本語[にほんご]の水準[すいじゅん]がぐんと上[あ]がった。", "sentence_source": "generated"}, {"text": "この店の料理は水準が高く、どれもおいしい。", "target_word": "水準", "complexity_tier": "T3", "furigana": "この店[みせ]の料理[りょうり]は水準[すいじゅん]が高[たか]く、どれもおいしい。", "sentence_source": "generated"}, {"text": "給料の水準が低いので、働く人が集まらない。", "target_word": "水準", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]の水準[すいじゅん]が低[ひく]いので、働[はたら]く人[ひと]が集[あつ]まらない。", "sentence_source": "generated"}, {"text": "世界の水準に追いつくために、毎日練習している。", "target_word": "水準", "complexity_tier": "T3", "furigana": "世界[せかい]の水準[すいじゅん]に追[お]いつくために、毎日[まいにち]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "質問の水準が高すぎて、私には答えられなかった。", "target_word": "水準", "complexity_tier": "T3", "furigana": "質問[しつもん]の水準[すいじゅん]が高[たか]すぎて、私[わたし]には答[こた]えられなかった。", "sentence_source": "generated"}, {"text": "選手たちの水準がそろっているので、試合はいつも接戦になる。", "target_word": "水準", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちの水準[すいじゅん]がそろっているので、試合[しあい]はいつも接戦[せっせん]になる。", "sentence_source": "generated"}, {"text": "二つの学校は教え方の水準に大きな差がある。", "target_word": "水準", "complexity_tier": "T3", "furigana": "二[ふた]つの学校[がっこう]は教[おし]え方[かた]の水準[すいじゅん]に大[おお]きな差[さ]がある。", "sentence_source": "generated"}, {"text": "彼女の絵は子どもとは思えない水準だ。", "target_word": "水準", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の絵[え]は子[こ]どもとは思[おも]えない水準[すいじゅん]だ。", "sentence_source": "generated"}, {"text": "同じ水準の品物なら、安いほうを買いたい。", "target_word": "水準", "complexity_tier": "T3", "furigana": "同[おな]じ水準[すいじゅん]の品物[しなもの]なら、安[やす]いほうを買[か]いたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水準", "label": "基本形"}], "register": "一般", "sense_fingerprint": "物事の質や能力がどの程度かという高さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f48066bd-2190-4cb8-bbf1-f08443cd7da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37222, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水準", "is_correct": true, "explanation": "「研究の水準が高い」と合う、物事の程度を表す語。"}, {"text": "人数", "is_correct": false, "explanation": "人数は数の話で、「研究の人数が高い」とは言えない。"}, {"text": "気温", "is_correct": false, "explanation": "気温は空気の温度で、大学の研究の程度には合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は人の重さで、研究の質を述べる文脈には入らない。"}], "explanations": {"水準": "「研究の水準が高い」と合う、物事の程度を表す語。", "人数": "人数は数の話で、「研究の人数が高い」とは言えない。", "気温": "気温は空気の温度で、大学の研究の程度には合わない。", "体重": "体重は人の重さで、研究の質を述べる文脈には入らない。"}, "sentence_index": 0, "correct_answer": "水準"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜になって水準がぐっと下がり、窓が凍った。", "explanation": "ここは〈気温〉の意味。空気の冷え込みは気温で、「水準」は物事の程度を表すので言えない。"}, {"text": "ダイエットの結果、水準が三キロ減った。", "explanation": "ここは〈体重〉の意味。「水準」は物事の程度を表すので、体の重さが減ったことは言えない。"}, {"text": "彼は水準がずっと若く見えて、五歳は下に思われる。", "explanation": "ここは〈年齢〉の意味。「水準」は程度を表す語で、人の年の若さを言う場面では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37222, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水準", "is_correct": true, "explanation": "「選手たちの水準がそろっている」と合う、能力の程度を表す語。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様で、選手の能力がそろうという文脈には合わない。"}, {"text": "足音", "is_correct": false, "explanation": "足音は歩く音で、選手の能力を述べる文脈には入らない。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝癖は髪の乱れで、選手の実力のそろい方とは関係しない。"}], "explanations": {"水準": "「選手たちの水準がそろっている」と合う、能力の程度を表す語。", "天気": "天気は空模様で、選手の能力がそろうという文脈には合わない。", "足音": "足音は歩く音で、選手の能力を述べる文脈には入らない。", "寝癖": "寝癖は髪の乱れで、選手の実力のそろい方とは関係しない。"}, "sentence_index": 6, "correct_answer": "水準"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもが熱を出して、水準が急に上がった。", "explanation": "ここは〈体温〉の意味。熱の高さは体温と言い、水準では表せない。"}, {"text": "急に天気が変わって、水準が悪くなった。", "explanation": "ここは〈天気〉の意味。空模様は天気で、物事の程度を表す水準は使えない。"}, {"text": "語彙の水準が多く、いろいろな言葉を使い分けられる。", "explanation": "ここは〈語彙〉の意味。言葉の数は語彙で、「水準が多い」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37222, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この宿は接客の水準を高く、また来たくなる。", "corrected_sentence": "この宿は接客の水準が高く、また来たくなる。", "error_description": "「水準」に続く助詞は「が」。「高い」の主語を示すので「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37222, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の英語は水準に高く、ネイティブとも自然に話せる。", "corrected_sentence": "彼の英語は水準が高く、ネイティブとも自然に話せる。", "error_description": "「水準」に続く助詞は「が」。「高い」の主語を示すので「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37223, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「水準を満たしていない」の目的語を示す「を」で、満たす対象である水準を示すので正しい。"}, {"text": "で", "is_correct": false, "explanation": "「水準で満たしていない」は手段・場所の「で」になり、満たす対象を示せないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「水準へ満たしていない」は方向の「へ」になり、満たす対象にはならないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「水準から満たしていない」は起点の「から」になり、満たす対象を示せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「水準を満たしていない」の目的語を示す「を」で、満たす対象である水準を示すので正しい。", "で": "「水準で満たしていない」は手段・場所の「で」になり、満たす対象を示せないので合わない。", "へ": "「水準へ満たしていない」は方向の「へ」になり、満たす対象にはならないので合わない。", "から": "「水準から満たしていない」は起点の「から」になり、満たす対象を示せないので合わない。"}, "error_tags": {"を": "目的語（正解）", "で": "手段・場所の誤り", "へ": "方向の誤り", "から": "起点の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37223, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37223, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある基準や目標に対して、どのくらいの高さや程度にあるかを示す言葉。", "primary_collocate": null, "pronunciation": "すいじゅん", "ipa": "sɯiʑɯɴ", "syllable_count": 4, "sentences": [{"text": "今年の成績は、去年の水準を少し上回った。", "target_word": "水準", "complexity_tier": "T3", "furigana": "今年[ことし]の成績[せいせき]は、去年[きょねん]の水準[すいじゅん]を少[すこ]し上回[うわまわ]った。", "sentence_source": "generated"}, {"text": "この製品は、国の決めた水準を満たしていない。", "target_word": "水準", "complexity_tier": "T3", "furigana": "この製品[せいひん]は、国[くに]の決[き]めた水準[すいじゅん]を満[み]たしていない。", "sentence_source": "generated"}, {"text": "川の水の汚れは、安全な水準まで下がった。", "target_word": "水準", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]の汚[よご]れは、安全[あんぜん]な水準[すいじゅん]まで下[さ]がった。", "sentence_source": "generated"}, {"text": "目標の水準に届かなかったので、もう一度練習する。", "target_word": "水準", "complexity_tier": "T3", "furigana": "目標[もくひょう]の水準[すいじゅん]に届[とど]かなかったので、もう一度[いちど]練習[れんしゅう]する。", "sentence_source": "generated"}, {"text": "彼の点数は合格の水準にぎりぎり届いた。", "target_word": "水準", "complexity_tier": "T3", "furigana": "彼[かれ]の点数[てんすう]は合格[ごうかく]の水準[すいじゅん]にぎりぎり届[とど]いた。", "sentence_source": "generated"}, {"text": "物価が高い水準のままで、生活が苦しい。", "target_word": "水準", "complexity_tier": "T3", "furigana": "物価[ぶっか]が高[たか]い水準[すいじゅん]のままで、生活[せいかつ]が苦[くる]しい。", "sentence_source": "generated"}, {"text": "新しい薬で、血圧は正常な水準に戻った。", "target_word": "水準", "complexity_tier": "T3", "furigana": "新[あたら]しい薬[くすり]で、血圧[けつあつ]は正常[せいじょう]な水準[すいじゅん]に戻[もど]った。", "sentence_source": "generated"}, {"text": "会社の売り上げは、以前の水準まで回復した。", "target_word": "水準", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の売[う]り上[あ]げは、以前[いぜん]の水準[すいじゅん]まで回復[かいふく]した。", "sentence_source": "generated"}, {"text": "空気の汚れが、決められた水準を超えたので、注意が出た。", "target_word": "水準", "complexity_tier": "T3", "furigana": "空気[くうき]の汚[よご]れが、決[き]められた水準[すいじゅん]を超[こ]えたので、注意[ちゅうい]が出[で]た。", "sentence_source": "generated"}, {"text": "この試験は、日本語の中級の水準を調べるためのものだ。", "target_word": "水準", "complexity_tier": "T3", "furigana": "この試験[しけん]は、日本語[にほんご]の中級[ちゅうきゅう]の水準[すいじゅん]を調[しら]べるためのものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水準", "label": "基本形"}], "register": "一般", "sense_fingerprint": "基準や目標と比べて、数値や状態がどの程度にあるか", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f48066bd-2190-4cb8-bbf1-f08443cd7da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37223, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水準", "is_correct": true, "explanation": "「上回る」の対象として、基準となる高さや程度を表す「水準」が入る。"}, {"text": "感情", "is_correct": false, "explanation": "感情は「上回る」の対象にならないので、去年の感情を上回ったとは言えない。"}, {"text": "方角", "is_correct": false, "explanation": "方角は数値や程度ではないので、「上回る」とは結びつかない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は比べて上回る対象にはならないので、文が成り立たない。"}], "explanations": {"水準": "「上回る」の対象として、基準となる高さや程度を表す「水準」が入る。", "感情": "感情は「上回る」の対象にならないので、去年の感情を上回ったとは言えない。", "方角": "方角は数値や程度ではないので、「上回る」とは結びつかない。", "季節": "季節は比べて上回る対象にはならないので、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "水準"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この床は水準が狂っているので、ボールが転がる。", "explanation": "ここは「水平」の意味。傾いていない状態は「水平」と言い、「水準」は高さや程度を表すので合わない。"}, {"text": "工事は今、最後の水準に入った。", "explanation": "ここは「段階」の意味。工事の進み具合の区切りは「段階」と言い、「水準」は高さや程度を表すので合わない。"}, {"text": "この工場は生産の水準がとても大きい。", "explanation": "ここは「規模」の意味。「水準」は大きい・小さいではなく高い・低いで言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37223, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水準", "is_correct": true, "explanation": "「正常な」で修飾され、基準となる状態に戻る対象として「水準」が入る。"}, {"text": "天気", "is_correct": false, "explanation": "血圧が天気の状態に戻るとは言えないので不自然。"}, {"text": "性格", "is_correct": false, "explanation": "血圧は性格のような状態には戻らないので文が成り立たない。"}, {"text": "気温", "is_correct": false, "explanation": "血圧は気温のような状態に戻る対象ではないので合わない。"}], "explanations": {"水準": "「正常な」で修飾され、基準となる状態に戻る対象として「水準」が入る。", "天気": "血圧が天気の状態に戻るとは言えないので不自然。", "性格": "血圧は性格のような状態には戻らないので文が成り立たない。", "気温": "血圧は気温のような状態に戻る対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "水準"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この机は水準になっていないので、ボールが転がる。", "explanation": "ここは「水平」の意味。傾いていない状態は「水平」と言い、「水準」とは言わない。"}, {"text": "家の水準を地図で確かめた。", "explanation": "ここは「位置」の意味。場所を地図で確かめるので、「水準」は合わない。"}, {"text": "この倉庫は商品の水準が多い。", "explanation": "ここは「数量」の意味。「水準」は数えられないので、多いとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37223, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年の売り上げは、目標の水準に上回った。", "corrected_sentence": "去年の売り上げは、目標の水準を上回った。", "error_description": "「上回る」は「〜を上回る」の形で目的語に「を」を取る。「に」が誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37223, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この部品は、求められる水準を届いた。", "corrected_sentence": "この部品は、求められる水準に届いた。", "error_description": "「届く」は「〜に届く」の形で到達点に「に」を取る。「を」が誤りで、正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
