INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37224, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「疲れた乗客が少しだけ乗っていた」で、乗っている主体を示す「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「乗客を乗っていた」は目的語として不自然で、乗る動作の対象にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「乗客に乗っていた」は乗る先を示す「に」になり、人を乗り物の場所にしてしまうので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「乗客へ乗っていた」は方向を示すが、乗客が方向の目標になる文ではない。"}], "correct_answer": "が", "explanations": {"が": "「疲れた乗客が少しだけ乗っていた」で、乗っている主体を示す「が」が正しい。", "を": "「乗客を乗っていた」は目的語として不自然で、乗る動作の対象にはならない。", "に": "「乗客に乗っていた」は乗る先を示す「に」になり、人を乗り物の場所にしてしまうので不自然。", "へ": "「乗客へ乗っていた」は方向を示すが、乗客が方向の目標になる文ではない。"}, "error_tags": {"が": "主格（正解）", "を": "目的語の誤り", "に": "着点・相手の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37224, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電車やバスに乗っている人。", "primary_collocate": null, "pronunciation": "じょうきゃく", "ipa": "dʑoːkjakɯ", "syllable_count": 4, "sentences": [{"text": "電車が急に止まったので、乗客は驚いた。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が急[きゅう]に止[と]まったので、乗客[じょうきゃく]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "バスの乗客は、みな静かに本を読んでいた。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "バスの乗客[じょうきゃく]は、みな静[しず]かに本[ほん]を読[よ]んでいた。", "sentence_source": "generated"}, {"text": "この路線は朝の乗客がとても多い。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "この路線[ろせん]は朝[あさ]の乗客[じょうきゃく]がとても多[おお]い。", "sentence_source": "generated"}, {"text": "運転手は、乗客に次の駅を知らせた。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]は、乗客[じょうきゃく]に次[つぎ]の駅[えき]を知[し]らせた。", "sentence_source": "generated"}, {"text": "雨の日は、乗客が傘を持って乗り込んでくる。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、乗客[じょうきゃく]が傘[かさ]を持[も]って乗[の]り込[こ]んでくる。", "sentence_source": "generated"}, {"text": "満員で、乗客が降りるのも大変だった。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "満員[まんいん]で、乗客[じょうきゃく]が降[お]りるのも大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "乗客は荷物を足もとに置いて、座った。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "乗客[じょうきゃく]は荷物[にもつ]を足[あし]もとに置[お]いて、座[すわ]った。", "sentence_source": "generated"}, {"text": "終電には、疲れた乗客が少しだけ乗っていた。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "終電[しゅうでん]には、疲[つか]れた乗客[じょうきゃく]が少[すこ]しだけ乗[の]っていた。", "sentence_source": "generated"}, {"text": "乗客の一人が、倒れた人を助けた。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "乗客[じょうきゃく]の一人[ひとり]が、倒[たお]れた人[ひと]を助[たす]けた。", "sentence_source": "generated"}, {"text": "新しい電車は、乗客のために席を広くした。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "新[あたら]しい電車[でんしゃ]は、乗客[じょうきゃく]のために席[せき]を広[ひろ]くした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "乗客", "label": "基本形"}], "register": "一般", "sense_fingerprint": "電車やバスなどの乗り物に乗っている客", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f48066bd-2190-4cb8-bbf1-f08443cd7da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37224, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乗客", "is_correct": true, "explanation": "驚く主体は人なので、電車に乗っていた人を指す「乗客」が入る。"}, {"text": "切符", "is_correct": false, "explanation": "切符は物なので驚かず、主語として不自然。"}, {"text": "座席", "is_correct": false, "explanation": "座席は驚く主体にならないので文が成り立たない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は驚かないので、この文の主語にはならない。"}], "explanations": {"乗客": "驚く主体は人なので、電車に乗っていた人を指す「乗客」が入る。", "切符": "切符は物なので驚かず、主語として不自然。", "座席": "座席は驚く主体にならないので文が成り立たない。", "天井": "天井は驚かないので、この文の主語にはならない。"}, "sentence_index": 0, "correct_answer": "乗客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合が始まり、乗客は大声で応援した。", "explanation": "ここは「観客」の意味。「乗客」は乗り物に乗る人なので、試合の応援には合わない。"}, {"text": "夕方の商店街は、歩く乗客が多い。", "explanation": "ここは「通行人」の意味。「乗客」は乗り物に乗っている人なので、歩いている人には使わない。"}, {"text": "店の奥で、乗客が商品を並べている。", "explanation": "ここは「店員」の意味。「乗客」は乗り物の利用者で、店で働く人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37224, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乗客", "is_correct": true, "explanation": "荷物を足もとに置いて座る主体は人なので、「乗客」が入る。"}, {"text": "網棚", "is_correct": false, "explanation": "網棚は座らないので、主語として文が成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は荷物を置いて座らないので不自然。"}, {"text": "車輪", "is_correct": false, "explanation": "車輪は座る主体にならないので文が成り立たない。"}], "explanations": {"乗客": "荷物を足もとに置いて座る主体は人なので、「乗客」が入る。", "網棚": "網棚は座らないので、主語として文が成り立たない。", "窓": "窓は荷物を置いて座らないので不自然。", "車輪": "車輪は座る主体にならないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "乗客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この雑誌の乗客が増えた。", "explanation": "ここは「読者」の意味。「乗客」は乗り物に乗る人で、雑誌を読む人には言わない。"}, {"text": "図書館の乗客が増えた。", "explanation": "ここは「利用者」の意味。「乗客」は乗り物の利用者で、図書館の利用者とは言えない。"}, {"text": "このアパートの乗客は、みな静かに暮らしている。", "explanation": "ここは「入居者」の意味。「乗客」は乗り物に乗る人で、住んでいる人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37224, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝の電車は、乗客に混み合っていた。", "corrected_sentence": "朝の電車は、乗客で混み合っていた。", "error_description": "「混み合う」は「〜で混み合う」の形で原因や状態を「で」で示す。「に」が誤りで、正しくは「で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37224, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "バスの運転手は、乗客が降ろす場所を確かめた。", "corrected_sentence": "バスの運転手は、乗客を降ろす場所を確かめた。", "error_description": "「降ろす」の目的語は「乗客」なので「を」を取る。「が」が誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
