INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37225, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電車やバス、飛行機などの乗り物に乗っている人のこと。", "primary_collocate": null, "pronunciation": "じょうきゃく", "ipa": "dʑoːkʲakɯ", "syllable_count": 4, "sentences": [{"text": "バスが急に止まったので、乗客は驚いた。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "バスが急[きゅう]に止[と]まったので、乗客[じょうきゃく]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "事故のあと、乗客は全員無事に降りた。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、乗客[じょうきゃく]は全員[ぜんいん]無事[ぶじ]に降[お]りた。", "sentence_source": "generated"}, {"text": "飛行機の乗客は、出発の前に荷物を預けた。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]の乗客[じょうきゃく]は、出発[しゅっぱつ]の前[まえ]に荷物[にもつ]を預[あず]けた。", "sentence_source": "generated"}, {"text": "雨の日は、電車の乗客が多くなる。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、電車[でんしゃ]の乗客[じょうきゃく]が多[おお]くなる。", "sentence_source": "generated"}, {"text": "運転手は、乗客に次の駅を知らせた。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]は、乗客[じょうきゃく]に次[つぎ]の駅[えき]を知[し]らせた。", "sentence_source": "generated"}, {"text": "船が大きくゆれて、乗客の何人かが気分を悪くした。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "船[ふね]が大[おお]きくゆれて、乗客[じょうきゃく]の何人[なんにん]かが気分[きぶん]を悪[わる]くした。", "sentence_source": "generated"}, {"text": "この路線は乗客が少ないので、本数が減った。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "この路線[ろせん]は乗客[じょうきゃく]が少[すく]ないので、本数[ほんすう]が減[へ]った。", "sentence_source": "generated"}, {"text": "乗客の安全を守ることが、運転手の大事な仕事だ。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "乗客[じょうきゃく]の安全[あんぜん]を守[まも]ることが、運転手[うんてんしゅ]の大事[だいじ]な仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "駅員は、迷っている乗客にやさしく道を教えた。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "駅員[えきいん]は、迷[まよ]っている乗客[じょうきゃく]にやさしく道[みち]を教[おし]えた。", "sentence_source": "generated"}, {"text": "朝のバスは、通勤する乗客でいっぱいだった。", "target_word": "乗客", "complexity_tier": "T3", "furigana": "朝[あさ]のバスは、通勤[つうきん]する乗客[じょうきゃく]でいっぱいだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "乗客", "label": "基本形"}, {"form": "乗客たち", "label": "複数"}], "register": "neutral", "sense_fingerprint": "電車・バス・飛行機などの乗り物に乗っている人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f48066bd-2190-4cb8-bbf1-f08443cd7da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37225, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乗客", "is_correct": true, "explanation": "驚く主体は人なので、バスに乗っていた人を指す「乗客」が入る。"}, {"text": "車内放送", "is_correct": false, "explanation": "放送は驚かないので、主語として文が成り立たない。"}, {"text": "運賃", "is_correct": false, "explanation": "運賃は驚く主体にならないので不自然。"}, {"text": "停留所", "is_correct": false, "explanation": "停留所は驚かないので、この文の主語にはならない。"}], "explanations": {"乗客": "驚く主体は人なので、バスに乗っていた人を指す「乗客」が入る。", "車内放送": "放送は驚かないので、主語として文が成り立たない。", "運賃": "運賃は驚く主体にならないので不自然。", "停留所": "停留所は驚かないので、この文の主語にはならない。"}, "sentence_index": 0, "correct_answer": "乗客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テレビの乗客が多くなる。", "explanation": "ここは「視聴者」の意味。「乗客」は乗り物の利用者で、テレビを見る人には使わない。"}, {"text": "大会の乗客が増えた。", "explanation": "ここは「参加者」の意味。「乗客」は乗り物に乗る人で、大会に参加する人には使わない。"}, {"text": "町の乗客が減った。", "explanation": "ここは「住民」の意味。「乗客」は乗り物に乗る人で、町に住む人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37225, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乗客", "is_correct": true, "explanation": "路線に乗る人の少なさを表す主語として、「乗客」が入る。"}, {"text": "天気", "is_correct": false, "explanation": "路線に天気が少ないとは言えないので不自然。"}, {"text": "季節", "is_correct": false, "explanation": "路線に季節が少ないとは言えないので文が成り立たない。"}, {"text": "紅葉", "is_correct": false, "explanation": "紅葉の少なさが本数の減少につながる関係が成り立たない。"}], "explanations": {"乗客": "路線に乗る人の少なさを表す主語として、「乗客」が入る。", "天気": "路線に天気が少ないとは言えないので不自然。", "季節": "路線に季節が少ないとは言えないので文が成り立たない。", "紅葉": "紅葉の少なさが本数の減少につながる関係が成り立たない。"}, "sentence_index": 6, "correct_answer": "乗客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "美術館の乗客が多い。", "explanation": "ここは「来館者」の意味。「乗客」は乗り物の利用者で、美術館に来る人には使わない。"}, {"text": "舞台の乗客が多い。", "explanation": "ここは「出演者」の意味。「乗客」は乗り物に乗る人で、舞台に立つ人には使わない。"}, {"text": "この病院は、乗客が多い。", "explanation": "ここは「患者」の意味。「乗客」は乗り物の利用者で、病院にかかる人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37225, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方の駅は、乗客に多く集まっていた。", "corrected_sentence": "夕方の駅は、乗客が多く集まっていた。", "error_description": "「集まる」は主語に「が」を取る。「に」が誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37225, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい路線で、乗客を数を数えた。", "corrected_sentence": "新しい路線で、乗客の数を数えた。", "error_description": "「乗客の数」は名詞句なので「の」が正しい。「を」を重ねると「数を」の目的語が二重になり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37226, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「足りなくなる」の主語を示す。「エネルギーが足りない」で自然。"}, {"text": "を", "is_correct": false, "explanation": "「足りなくなる」は目的語を取らないので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」を続けると「エネルギーに足りなくなる」となり、文の中で働かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「エネルギーと足りなくなる」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「足りなくなる」の主語を示す。「エネルギーが足りない」で自然。", "を": "「足りなくなる」は目的語を取らないので、「を」は合わない。", "に": "「に」を続けると「エネルギーに足りなくなる」となり、文の中で働かない。", "と": "「と」は並列や相手を示すが、「エネルギーと足りなくなる」は不自然。"}, "error_tags": {"が": "主語", "を": "対象", "に": "位置", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37226, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使い切る」の対象を示す。「エネルギーを使い切る」で自然。"}, {"text": "に", "is_correct": false, "explanation": "「エネルギーに使い切る」は不自然で、対象を示す働きをしない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「エネルギーと使い切る」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "向かう先を示す「へ」は、「使い切る」とは結びつかない。"}], "correct_answer": "を", "explanations": {"を": "「使い切る」の対象を示す。「エネルギーを使い切る」で自然。", "に": "「エネルギーに使い切る」は不自然で、対象を示す働きをしない。", "と": "「と」は相手や並列を示すが、「エネルギーと使い切る」は不自然。", "へ": "向かう先を示す「へ」は、「使い切る」とは結びつかない。"}, "error_tags": {"を": "対象", "に": "位置", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37226, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "動かしたり、物を温めたり、電気を作ったりするのに必要な力のことです。", "primary_collocate": null, "pronunciation": "えねるぎー", "ipa": "eneɾiɡiː", "syllable_count": 5, "sentences": [{"text": "太陽の光は、電気を作るエネルギーになる。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "太陽(たいよう)の光(ひかり)は、電気(でんき)を作(つく)るエネルギーになる。", "sentence_source": "generated"}, {"text": "朝ごはんを食べないと、午前中に使うエネルギーが足りなくなる。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "朝(あさ)ごはんを食(た)べないと、午前中(ごぜんちゅう)に使(つか)うエネルギーが足(た)りなくなる。", "sentence_source": "generated"}, {"text": "風の力を使ってエネルギーを作る発電所が、海の近くにできた。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "風(かぜ)の力(ちから)を使(つか)ってエネルギーを作(つく)る発電所(はつでんしょ)が、海(うみ)の近(ちか)くにできた。", "sentence_source": "generated"}, {"text": "走ったあと、体のエネルギーがなくなって動けなくなった。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "走(はし)ったあと、体(からだ)のエネルギーがなくなって動(うご)けなくなった。", "sentence_source": "generated"}, {"text": "冬は部屋を暖めるのに、たくさんのエネルギーが必要だ。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "冬(ふゆ)は部屋(へや)を暖(あたた)めるのに、たくさんのエネルギーが必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "電気自動車は、ガソリンを燃やす代わりに、電池から取り出したエネルギーで走る。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "電気(でんき)自動車(じどうしゃ)は、ガソリンを燃(も)やす代(か)わりに、電池(でんち)から取(と)り出(だ)したエネルギーで走(はし)る。", "sentence_source": "generated"}, {"text": "お風呂のふたを閉めると、水を温めるエネルギーを節約できる。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "お風呂(ふろ)のふたを閉(し)めると、水(みず)を温(あたた)めるエネルギーを節約(せつやく)できる。", "sentence_source": "generated"}, {"text": "子どもは遊びでエネルギーを使い切り、夜はすぐ眠る。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "子(こ)どもは遊(あそ)びでエネルギーを使(つか)い切(き)り、夜(よる)はすぐ眠(ねむ)る。", "sentence_source": "generated"}, {"text": "国は、石油にたよらないエネルギーを増やそうとしている。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "国(くに)は、石油(せきゆ)にたよらないエネルギーを増(ふ)やそうとしている。", "sentence_source": "generated"}, {"text": "バッテリーにためたエネルギーで、ライトが一晩光りつづけた。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "バッテリーにためたエネルギーで、ライトが一晩(ひとばん)光(ひか)りつづけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エネルギー", "label": "基本形"}, {"form": "エネルギーを", "label": "目的格形（を）"}], "register": "中立", "sense_fingerprint": "エネルギー：動かす・温める・発電に必要な力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 使い切り (Zipf 2.41)','sentence 8 above tier T2: contains vocabulary far above tier T2: たよら (Zipf 1.5)']::text[], '61ac7907-efd1-469f-94eb-3a83e671f0a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37226, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エネルギー", "is_correct": true, "explanation": "電気を作るための力の意味で、「電気を作るエネルギーになる」は自然。"}, {"text": "砂糖", "is_correct": false, "explanation": "食べ物の甘味料で、電気を作る材料にはならず文が成り立たない。"}, {"text": "紙", "is_correct": false, "explanation": "材料の名前で、電気を作るものにはならないので意味が通らない。"}, {"text": "布", "is_correct": false, "explanation": "衣類や布製品を指す語で、電気を作るという文脈には合わない。"}], "explanations": {"エネルギー": "電気を作るための力の意味で、「電気を作るエネルギーになる」は自然。", "砂糖": "食べ物の甘味料で、電気を作る材料にはならず文が成り立たない。", "紙": "材料の名前で、電気を作るものにはならないので意味が通らない。", "布": "衣類や布製品を指す語で、電気を作るという文脈には合わない。"}, "sentence_index": 0, "correct_answer": "エネルギー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この契約は、三年間のエネルギーを持つ。", "explanation": "エネルギーは物を動かしたり温めたりする力で、契約の効き目や法律上の効果には使わない。"}, {"text": "卵を食べると、体にじんましんが出るエネルギーがある。", "explanation": "エネルギーは体を動かす力で、じんましんのような反応を表す語ではない。"}, {"text": "この本には、役立つエネルギーがたくさん書いてある。", "explanation": "エネルギーは物を動かしたり温めたりする力で、本に書かれる内容には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37226, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エネルギー", "is_correct": true, "explanation": "水を温めるための力で、節約の対象として自然。"}, {"text": "声", "is_correct": false, "explanation": "「水を温める声」を節約するという文は意味が通らない。"}, {"text": "色", "is_correct": false, "explanation": "「水を温める色」は節約の対象にならず、文がおかしい。"}, {"text": "髪", "is_correct": false, "explanation": "「水を温める髪」を節約するとは言わない。"}], "explanations": {"エネルギー": "水を温めるための力で、節約の対象として自然。", "声": "「水を温める声」を節約するという文は意味が通らない。", "色": "「水を温める色」は節約の対象にならず、文がおかしい。", "髪": "「水を温める髪」を節約するとは言わない。"}, "sentence_index": 6, "correct_answer": "エネルギー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鍋にエネルギーを入れて、三十分煮た。", "explanation": "エネルギーは力を表す語で、鍋に入れる食材の名前としては使えない。"}, {"text": "この地図には、道のエネルギーが描かれている。", "explanation": "エネルギーは力を表すので、地図に描かれる道の位置は表せない。"}, {"text": "午後三時になり、部屋のエネルギーが鳴った。", "explanation": "エネルギーは力を表す語で、音を出して鳴るものではないので、鳴るという動詞とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37226, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏は、冷房を動かすためにたくさんのエネルギーを必要だ。", "corrected_sentence": "夏は、冷房を動かすためにたくさんのエネルギーが必要だ。", "error_description": "「必要だ」は必要なものを「が」で示す。「を」は動作の対象に使うので、「必要だ」には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37226, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ダムの水の流れは、発電に使えるエネルギーを食べる。", "corrected_sentence": "ダムの水の流れは、発電に使えるエネルギーを生む。", "error_description": "エネルギーは「生む」「取り出す」で表す。「食べる」は食べ物に使う動詞なので、エネルギーとは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37228, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見せる」の目的語を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「パフォーマンスが見せる」では主語と動詞の関係が合わず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞をつなぐだけで、「パフォーマンスの見せます」は動詞の目的語にならず成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」だが、「パフォーマンスから見せる」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「見せる」の目的語を示す正しい助詞。", "が": "「パフォーマンスが見せる」では主語と動詞の関係が合わず、文が成り立たない。", "の": "連体修飾の「の」は名詞をつなぐだけで、「パフォーマンスの見せます」は動詞の目的語にならず成り立たない。", "から": "起点を示す「から」だが、「パフォーマンスから見せる」は成り立たない。"}, "error_tags": {"が": "主語", "から": "起点", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37228, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「パフォーマンスが落ちる」の主語を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「落ちる」は目的語を取らない自動詞なので、「を」では不自然。"}, {"text": "で", "is_correct": false, "explanation": "原因や手段を示す「で」だが、「パフォーマンスで落ちる」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列の相手を示す「と」だが、「パフォーマンスと落ちる」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「パフォーマンスが落ちる」の主語を示す正しい助詞。", "を": "「落ちる」は目的語を取らない自動詞なので、「を」では不自然。", "で": "原因や手段を示す「で」だが、「パフォーマンスで落ちる」は意味が通らない。", "と": "並列の相手を示す「と」だが、「パフォーマンスと落ちる」は文として成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37228, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときの、どれだけ上手にできるかという力のことを言います。", "primary_collocate": null, "pronunciation": "ぱふぉーまんす", "ipa": "paɸoːmaɴsɯ", "syllable_count": 6, "sentences": [{"text": "疲れていると、いつものパフォーマンスが出せません。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "疲[つか]れていると、いつものパフォーマンスが出[だ]せません。", "sentence_source": "generated"}, {"text": "彼は本番に強く、練習よりよいパフォーマンスを見せます。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "彼[かれ]は本番[ほんばん]に強[つよ]く、練習[れんしゅう]よりよいパフォーマンスを見[み]せます。", "sentence_source": "generated"}, {"text": "食事と運動に気をつけて、体のパフォーマンスを保っています。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "食事[しょくじ]と運動[うんどう]に気[き]をつけて、体[からだ]のパフォーマンスを保[たも]っています。", "sentence_source": "generated"}, {"text": "先生は、テストでのパフォーマンスだけで成績をつけません。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "先生[せんせい]は、テストでのパフォーマンスだけで成績[せいせき]をつけません。", "sentence_source": "generated"}, {"text": "緊張しすぎて、発表のパフォーマンスが下がってしまいました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "緊張[きんちょう]しすぎて、発表[はっぴょう]のパフォーマンスが下[さ]がってしまいました。", "sentence_source": "generated"}, {"text": "水をこまめに飲むと、練習のパフォーマンスが上がります。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "水[みず]をこまめに飲[の]むと、練習[れんしゅう]のパフォーマンスが上[あ]がります。", "sentence_source": "generated"}, {"text": "新しい靴を履いたら、走るパフォーマンスがよくなりました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "新[あたら]しい靴[くつ]を履[は]いたら、走[はし]るパフォーマンスがよくなりました。", "sentence_source": "generated"}, {"text": "騒がしい部屋では、集中できずパフォーマンスが落ちます。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "騒[さわ]がしい部屋[へや]では、集中[しゅうちゅう]できずパフォーマンスが落[お]ちます。", "sentence_source": "generated"}, {"text": "監督は選手のパフォーマンスを見て、出場する人を決めました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "監督[かんとく]は選手[せんしゅ]のパフォーマンスを見[み]て、出場[しゅつじょう]する人[ひと]を決[き]めました。", "sentence_source": "generated"}, {"text": "毎日少し練習すれば、本番のパフォーマンスはきっと安定します。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "毎日[まいにち]少[すこ]し練習[れんしゅう]すれば、本番[ほんばん]のパフォーマンスはきっと安定[あんてい]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パフォーマンス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事をどれだけ上手にこなせるかという力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e92d26c-8372-4048-8f6a-0ae56306fb40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37228, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パフォーマンス", "is_correct": true, "explanation": "「いつもの〜が出せる」で、力を発揮した結果を表す語として自然に入る。"}, {"text": "湿気", "is_correct": false, "explanation": "空気中の水分を表す語で、力を出すものではない。「いつもの湿気が出せません」は意味が通らない。"}, {"text": "寿命", "is_correct": false, "explanation": "物の使える期間を表す語で、「出せない」とは続かない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、人が出せるものではない。「いつもの天気が出せません」は不自然。"}], "explanations": {"パフォーマンス": "「いつもの〜が出せる」で、力を発揮した結果を表す語として自然に入る。", "湿気": "空気中の水分を表す語で、力を出すものではない。「いつもの湿気が出せません」は意味が通らない。", "寿命": "物の使える期間を表す語で、「出せない」とは続かない。", "天気": "空模様を表す語で、人が出せるものではない。「いつもの天気が出せません」は不自然。"}, "sentence_index": 0, "correct_answer": "パフォーマンス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日のテストで、パフォーマンスを取った。", "explanation": "ここは〈点数〉の意味との混同。点数は取るものだが、この語は力量を指すので「取る」とは合わない。"}, {"text": "マラソンに備えて、毎日パフォーマンスを蓄えている。", "explanation": "ここは〈体力〉の意味との混同。体力は蓄えるものだが、この語は上手にこなす力を指すので、蓄えるとは合わない。"}, {"text": "やる気が出なくても、なぜかパフォーマンスがわいてきた。", "explanation": "ここは〈気力〉の意味との混同。気力はわいてくるものだが、この語は気持ちの力ではなく、こなす力を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37228, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パフォーマンス", "is_correct": true, "explanation": "走るときの動きの出来栄えを表し、「よくなる」と合う。空所に入るのはこの語だけ。"}, {"text": "味", "is_correct": false, "explanation": "食べ物などの感じを表す語で、走る力には使わない。「走る味がよくなりました」は意味が通らない。"}, {"text": "色", "is_correct": false, "explanation": "見た目の色合いを表す語で、走る力の状態は表せない。「走る色がよくなりました」は不自然。"}, {"text": "寿命", "is_correct": false, "explanation": "物の使える期間を表す語で、「よくなる」とは合わない。"}], "explanations": {"パフォーマンス": "走るときの動きの出来栄えを表し、「よくなる」と合う。空所に入るのはこの語だけ。", "味": "食べ物などの感じを表す語で、走る力には使わない。「走る味がよくなりました」は意味が通らない。", "色": "見た目の色合いを表す語で、走る力の状態は表せない。「走る色がよくなりました」は不自然。", "寿命": "物の使える期間を表す語で、「よくなる」とは合わない。"}, "sentence_index": 6, "correct_answer": "パフォーマンス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "怖かったが、パフォーマンスを振り絞って高い所から飛び込んだ。", "explanation": "ここは〈勇気〉の意味との混同。勇気は振り絞るものだが、この語は上手にこなす力を指すので、振り絞るとは合わない。"}, {"text": "パフォーマンスが尽きて、途中であきらめた。", "explanation": "ここは〈根気〉の意味との混同。根気は尽きるものだが、この語は力量を指すので、尽きるとは合わない。"}, {"text": "パフォーマンスが旺盛な子どもで、いつも新しいことを試している。", "explanation": "ここは〈好奇心〉の意味との混同。「旺盛」は気持ちの強さに使うが、この語は気持ちではなく力量を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37228, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "練習を続けたので、本番で安定したパフォーマンスに出せた。", "corrected_sentence": "練習を続けたので、本番で安定したパフォーマンスを出せた。", "error_description": "「出す」は目的語を「を」で示す。「に」では「出せた」の目的語にならず、文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37228, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい靴にしてから、走るパフォーマンスが安定ました。", "corrected_sentence": "新しい靴にしてから、走るパフォーマンスが安定しました。", "error_description": "「安定する」は「安定し」と連用形で活用する。「安定ました」は活用の誤りで、正しくは「安定しました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37229, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「パフォーマンスが高い」の主語を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「高い」は目的語を取らない形容詞なので、「パフォーマンスを高いので」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「高い」に向かう方向や対象を示す「に」は、この文では不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」だが、「パフォーマンスで高い」とは続かない。"}], "correct_answer": "が", "explanations": {"が": "「パフォーマンスが高い」の主語を示す正しい助詞。", "を": "「高い」は目的語を取らない形容詞なので、「パフォーマンスを高いので」は成り立たない。", "に": "「高い」に向かう方向や対象を示す「に」は、この文では不自然。", "で": "手段や場所を示す「で」だが、「パフォーマンスで高い」とは続かない。"}, "error_tags": {"を": "目的語", "に": "方向・対象", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37229, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37229, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある活動や機械などが、どれだけ効率よく、または優れた結果を出せるかを示す能力や実績。", "primary_collocate": null, "pronunciation": "ぱふぉーまんす", "ipa": "paɸoːmaɴsɯ", "syllable_count": 6, "sentences": [{"text": "この機械は、熱がこもるとパフォーマンスが落ちます。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "この機械[きかい]は、熱[ねつ]がこもるとパフォーマンスが落[お]ちます。", "sentence_source": "generated"}, {"text": "このパソコンはパフォーマンスが高いので、動画の編集も速いです。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "このパソコンはパフォーマンスが高[たか]いので、動画[どうが]の編集[へんしゅう]も速[はや]いです。", "sentence_source": "generated"}, {"text": "新しいソフトに変えてから、機械のパフォーマンスが大きく上がりました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "新[あたら]しいソフトに変[か]えてから、機械[きかい]のパフォーマンスが大[おお]きく上[あ]がりました。", "sentence_source": "generated"}, {"text": "睡眠が足りないと、仕事のパフォーマンスが下がってしまいます。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "睡眠[すいみん]が足[た]りないと、仕事[しごと]のパフォーマンスが下[さ]がってしまいます。", "sentence_source": "generated"}, {"text": "費用の割に、このエアコンはパフォーマンスがよくありません。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "費用[ひよう]の割[わり]に、このエアコンはパフォーマンスがよくありません。", "sentence_source": "generated"}, {"text": "選手は大事な試合で最高のパフォーマンスを出しました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "選手[せんしゅ]は大事[だいじ]な試合[しあい]で最高[さいこう]のパフォーマンスを出[だ]しました。", "sentence_source": "generated"}, {"text": "古いスマホは電池が弱く、パフォーマンスが落ちてきました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "古[ふる]いスマホは電池[でんち]が弱[よわ]く、パフォーマンスが落[お]ちてきました。", "sentence_source": "generated"}, {"text": "部屋が暑すぎると、勉強のパフォーマンスが悪くなるそうです。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "部屋[へや]が暑[あつ]すぎると、勉強[べんきょう]のパフォーマンスが悪[わる]くなるそうです。", "sentence_source": "generated"}, {"text": "先月の会議では、チームのパフォーマンスを数字で確認しました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "先月[せんげつ]の会議[かいぎ]では、チームのパフォーマンスを数字[すうじ]で確認[かくにん]しました。", "sentence_source": "generated"}, {"text": "朝ごはんを食べると、午前中のパフォーマンスが上がると言われています。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんを食[た]べると、午前中[ごぜんちゅう]のパフォーマンスが上[あ]がると言[い]われています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パフォーマンス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "活動や機械の効率・成果の水準", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e92d26c-8372-4048-8f6a-0ae56306fb40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37229, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パフォーマンス", "is_correct": true, "explanation": "機械の働きの良し悪しを表し、熱がこもると落ちる対象になる。空所に入るのはこの語だけ。"}, {"text": "締め切り", "is_correct": false, "explanation": "期限を表す語で、機械の働きは表せない。「熱がこもると締め切りが落ちます」は不自然。"}, {"text": "義務", "is_correct": false, "explanation": "従うべき務めを表す語で、機械の働きは表せない。「熱がこもると義務が落ちます」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、機械の働きには使わない。「熱がこもると天気が落ちます」は不自然。"}], "explanations": {"パフォーマンス": "機械の働きの良し悪しを表し、熱がこもると落ちる対象になる。空所に入るのはこの語だけ。", "締め切り": "期限を表す語で、機械の働きは表せない。「熱がこもると締め切りが落ちます」は不自然。", "義務": "従うべき務めを表す語で、機械の働きは表せない。「熱がこもると義務が落ちます」は成り立たない。", "天気": "空模様を表す語で、機械の働きには使わない。「熱がこもると天気が落ちます」は不自然。"}, "sentence_index": 0, "correct_answer": "パフォーマンス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女はパフォーマンスを固めて、留学を決めた。", "explanation": "ここは〈決意〉の意味との混同。決意は固めるものだが、この語は能力や成果の水準を指すので「固める」とは合わない。"}, {"text": "彼はパフォーマンスが豊富で、歴史の質問に何でも答える。", "explanation": "ここは〈知識〉の意味との混同。知識は豊富にあるものだが、この語は効率や成果の水準を指すので「豊富」とは合わない。"}, {"text": "彼はパフォーマンスがあるので、毎日遅くまで練習している。", "explanation": "ここは〈やる気〉の意味との混同。やる気があるから練習するという文脈で、この語は成果の水準を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37229, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パフォーマンス", "is_correct": true, "explanation": "スマホの処理の出来栄えを表し、落ちる対象になる。空所に入るのはこの語だけ。"}, {"text": "宿題", "is_correct": false, "explanation": "落ちてくるものではなく、「宿題が落ちてきました」は文として成り立たない。"}, {"text": "景色", "is_correct": false, "explanation": "見る対象であり、落ちてくるものではない。「景色が落ちてきた」は不自然。"}, {"text": "相談", "is_correct": false, "explanation": "持ちかけるものであり、落ちてくるものではない。「相談が落ちてきた」は意味が通らない。"}], "explanations": {"パフォーマンス": "スマホの処理の出来栄えを表し、落ちる対象になる。空所に入るのはこの語だけ。", "宿題": "落ちてくるものではなく、「宿題が落ちてきました」は文として成り立たない。", "景色": "見る対象であり、落ちてくるものではない。「景色が落ちてきた」は不自然。", "相談": "持ちかけるものであり、落ちてくるものではない。「相談が落ちてきた」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "パフォーマンス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験中はパフォーマンスが切れて、答えを何度も見直せなかった。", "explanation": "ここは〈集中力〉の意味との混同。集中力は途切れて「切れる」と言うが、この語は効率や成果の水準を指すので合わない。"}, {"text": "山登りでパフォーマンスが尽きて、途中で引き返した。", "explanation": "ここは〈体力〉の意味との混同。体力は使い果たして「尽きる」と言うが、この語は尽きるものとしては使わない。"}, {"text": "パフォーマンスが旺盛な子どもで、いつも新しいことを試している。", "explanation": "ここは〈好奇心〉の意味との混同。「旺盛」は気持ちの強さに使うが、この語は気持ちではなく効率や成果の水準を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37229, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この車はパフォーマンスを高いので、燃費もよいです。", "corrected_sentence": "この車はパフォーマンスが高いので、燃費もよいです。", "error_description": "「高い」の主語を示すのは「が」。「を」は目的語を示す助詞なので、形容詞「高い」には続かない。正しくは「パフォーマンスが高い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37229, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい電池にしてから、スマホのパフォーマンスが上がりる。", "corrected_sentence": "新しい電池にしてから、スマホのパフォーマンスが上がりました。", "error_description": "「上がる」の過去の形は「上がりました」。「上がりる」は活用の誤りで、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
