INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37230, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ずっと続けられること。", "primary_collocate": null, "pronunciation": "さすていなぶる", "ipa": "sasɯteinabɯɾɯ", "syllable_count": 7, "sentences": [{"text": "無理な計画では、サステイナブルな活動にはなりません。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "無理[むり]な計画[けいかく]では、サステイナブルな活動[かつどう]にはなりません。", "sentence_source": "generated"}, {"text": "毎日少しずつ続ける、サステイナブルなダイエットがいい。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "毎日[まいにち]少[すこ]しずつ続[つづ]ける、サステイナブルなダイエットがいい。", "sentence_source": "generated"}, {"text": "収入が少ないと、サステイナブルな経営は難しい。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]が少[すく]ないと、サステイナブルな経営[けいえい]は難[むずか]しい。", "sentence_source": "generated"}, {"text": "長く続けたいので、サステイナブルなペースで走ります。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "長[なが]く続[つづ]けたいので、サステイナブルなペースで走[はし]ります。", "sentence_source": "generated"}, {"text": "サステイナブルな練習方法を見つけることが大切だ。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "サステイナブルな練習方法[れんしゅうほうほう]を見[み]つけることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "一度だけのイベントより、サステイナブルな仕組みを作りたい。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "一度[いちど]だけのイベントより、サステイナブルな仕組[しく]みを作[つく]りたい。", "sentence_source": "generated"}, {"text": "毎日三時間も勉強するのは、サステイナブルではない。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "毎日[まいにち]三時間[さんじかん]も勉強[べんきょう]するのは、サステイナブルではない。", "sentence_source": "generated"}, {"text": "このクラブは、会費で運営するサステイナブルな形にした。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "このクラブは、会費[かいひ]で運営[うんえい]するサステイナブルな形[かたち]にした。", "sentence_source": "generated"}, {"text": "続けられるように、サステイナブルな働き方を考えた。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "続[つづ]けられるように、サステイナブルな働[はたら]き方[かた]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "無理をしない家計は、サステイナブルだと言える。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "無理[むり]をしない家計[かけい]は、サステイナブルだと言[い]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サステイナブル", "label": "基本形"}, {"form": "サステイナブルな", "label": "連体形"}, {"form": "サステイナブルだ", "label": "終止形"}, {"form": "サステイナブルではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "無理なく長く続けられること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3049333-685e-4b1b-9295-162778d51a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37230, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サステイナブル", "is_correct": true, "explanation": "「無理な計画では、〇〇な活動にはなりません」に入る形容動詞。「無理なく続けられる」活動の意味に合う。"}, {"text": "カジュアル", "is_correct": false, "explanation": "気楽な・略式のという意味。活動が続くかどうかの話には合わない。"}, {"text": "ダイナミック", "is_correct": false, "explanation": "力強い・迫力のある様子。無理な計画の文脈とは逆で、続かない活動を表してしまう。"}, {"text": "ヘルシー", "is_correct": false, "explanation": "健康的な意味。文の論理（計画が無理だと活動にならない）とつながらない。"}], "explanations": {"サステイナブル": "「無理な計画では、〇〇な活動にはなりません」に入る形容動詞。「無理なく続けられる」活動の意味に合う。", "カジュアル": "気楽な・略式のという意味。活動が続くかどうかの話には合わない。", "ダイナミック": "力強い・迫力のある様子。無理な計画の文脈とは逆で、続かない活動を表してしまう。", "ヘルシー": "健康的な意味。文の論理（計画が無理だと活動にならない）とつながらない。"}, "sentence_index": 0, "correct_answer": "サステイナブル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この対策はサステイナブルな応急処置だ。", "explanation": "ここは〈一時的〉の意味。応急処置は一時しのぎで、ずっと続けられることを表すサステイナブルとは合わない。"}, {"text": "流行の服を、サステイナブルに次々と買い替えた。", "explanation": "ここは〈素早く〉の意味。サステイナブルは続けられることを表し、速さや頻度を表す語ではないので合わない。"}, {"text": "その場かぎりのサステイナブルな返事をした。", "explanation": "ここは〈とりあえずの〉の意味。長く続く意味のサステイナブルとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37230, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サステイナブル", "is_correct": true, "explanation": "「〜ではない」の前に入る語。毎日三時間の勉強が続かないという文脈に合う。"}, {"text": "ラグジュアリー", "is_correct": false, "explanation": "豪華なという意味。勉強の継続性の話とはつながらない。"}, {"text": "ドラスティック", "is_correct": false, "explanation": "大胆で急進的という意味。勉強量を評価する文には合わない。"}, {"text": "エレガント", "is_correct": false, "explanation": "上品なという意味。勉強時間の話とは結びつかない。"}], "explanations": {"サステイナブル": "「〜ではない」の前に入る語。毎日三時間の勉強が続かないという文脈に合う。", "ラグジュアリー": "豪華なという意味。勉強の継続性の話とはつながらない。", "ドラスティック": "大胆で急進的という意味。勉強量を評価する文には合わない。", "エレガント": "上品なという意味。勉強時間の話とは結びつかない。"}, "sentence_index": 6, "correct_answer": "サステイナブル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボーナスで旅行に行った月は、家計がサステイナブルだった。", "explanation": "ここは〈一度きり〉の意味。一時的な出費の話に続けられる意味のサステイナブルを当てると、語の意味が合わない。"}, {"text": "店で一番安い物ばかり選ぶ、サステイナブルな食事だ。", "explanation": "ここは〈安い〉の意味。値段の話ではなく、無理なく続くことを表す語として合わない。"}, {"text": "今月だけ食費を切り詰めるのは、サステイナブルな対応だ。", "explanation": "ここは〈一時しのぎ〉の意味。長く続ける話ではないので、サステイナブルの意味と反対になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37230, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仕事と休みのバランスが取れた、サステイナブルの働き方が理想だ。", "corrected_sentence": "仕事と休みのバランスが取れた、サステイナブルな働き方が理想だ。", "error_description": "「サステイナブル」は形状詞なので、名詞を修飾するときは「な」を付ける。「の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "サステイナブル", "is_correct": true, "explanation": "「〜な」の前に来る語幹の形。文中の「サステイナブルな」に対応する正しい形。"}, {"text": "サステイナブルだ", "is_correct": false, "explanation": "終止形。「〜な」で名詞を修飾する位置には使えない。"}, {"text": "サステイナブルではない", "is_correct": false, "explanation": "否定形。文は肯定の判断を述べているので合わない。"}, {"text": "サステイナブルではなかった", "is_correct": false, "explanation": "過去の否定形。「ダイエットがいい」という現在の判断と時制が合わない。"}], "correct_form": "サステイナブル", "base_form": "サステイナブル", "form_label": "語幹", "sentence_index": 1, "explanations": {"サステイナブル": "「〜な」の前に来る語幹の形。文中の「サステイナブルな」に対応する正しい形。", "サステイナブルだ": "終止形。「〜な」で名詞を修飾する位置には使えない。", "サステイナブルではない": "否定形。文は肯定の判断を述べているので合わない。", "サステイナブルではなかった": "過去の否定形。「ダイエットがいい」という現在の判断と時制が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37230, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "無理をしない働き方は、サステイナブルだ言える。", "corrected_sentence": "無理をしない働き方は、サステイナブルだと言える。", "error_description": "「〜だと言える」の「と」が抜けている。「サステイナブルだと言える」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "サステイナブル", "is_correct": true, "explanation": "「〜な」の前に来る語幹の形。文中の「サステイナブルな形」に対応する正しい形。"}, {"text": "サステイナブルだった", "is_correct": false, "explanation": "過去の断定形。「〜な形」で名詞を修飾する位置には使えない。"}, {"text": "サステイナブルで", "is_correct": false, "explanation": "中止形。名詞を修飾できず、この文には合わない。"}, {"text": "サステイナブルでない", "is_correct": false, "explanation": "否定形。クラブの形を説明する文の中では合わない。"}], "correct_form": "サステイナブル", "base_form": "サステイナブル", "form_label": "語幹", "sentence_index": 7, "explanations": {"サステイナブル": "「〜な」の前に来る語幹の形。文中の「サステイナブルな形」に対応する正しい形。", "サステイナブルだった": "過去の断定形。「〜な形」で名詞を修飾する位置には使えない。", "サステイナブルで": "中止形。名詞を修飾できず、この文には合わない。", "サステイナブルでない": "否定形。クラブの形を説明する文の中では合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
