INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37231, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "環境や社会を壊さずに、長く続けられること。", "primary_collocate": null, "pronunciation": "さすていなぶる", "ipa": "sasɯteinabɯɾɯ", "syllable_count": 7, "sentences": [{"text": "この店は、サステイナブルな素材だけで服を作っている。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "この店[みせ]は、サステイナブルな素材[そざい]だけで服[ふく]を作[つく]っている。", "sentence_source": "generated"}, {"text": "森を守りながら木を使う、サステイナブルな林業が広がっている。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "森[もり]を守[まも]りながら木[き]を使[つか]う、サステイナブルな林業[りんぎょう]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "サステイナブルな社会のために、ごみを減らしましょう。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "サステイナブルな社会[しゃかい]のために、ごみを減[へ]らしましょう。", "sentence_source": "generated"}, {"text": "海の魚を取りすぎないことは、サステイナブルな漁業につながる。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "海[うみ]の魚[さかな]を取[と]りすぎないことは、サステイナブルな漁業[ぎょぎょう]につながる。", "sentence_source": "generated"}, {"text": "彼女はサステイナブルな暮らしを目指して、電気を節約している。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はサステイナブルな暮[く]らしを目指[めざ]して、電気[でんき]を節約[せつやく]している。", "sentence_source": "generated"}, {"text": "町では、サステイナブルな観光を進めている。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "町[まち]では、サステイナブルな観光[かんこう]を進[すす]めている。", "sentence_source": "generated"}, {"text": "自然を壊す工場は、サステイナブルとは言えない。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "自然[しぜん]を壊[こわ]す工場[こうじょう]は、サステイナブルとは言[い]えない。", "sentence_source": "generated"}, {"text": "サステイナブルな農業は、土をいためない。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "サステイナブルな農業[のうぎょう]は、土[つち]をいためない。", "sentence_source": "generated"}, {"text": "この会社はサステイナブルな商品を増やしている。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]はサステイナブルな商品[しょうひん]を増[ふ]やしている。", "sentence_source": "generated"}, {"text": "資源を使い切らない方法が、サステイナブルな開発だ。", "target_word": "サステイナブル", "complexity_tier": "T3", "furigana": "資源[しげん]を使[つか]い切[き]らない方法[ほうほう]が、サステイナブルな開発[かいはつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サステイナブル", "label": "基本形"}, {"form": "サステイナブルな", "label": "連体形"}, {"form": "サステイナブルだ", "label": "終止形"}, {"form": "サステイナブルではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "環境や社会を壊さず、資源を守りながら長く続けられること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3049333-685e-4b1b-9295-162778d51a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37231, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サステイナブル", "is_correct": true, "explanation": "環境や資源を守って続けられる、という意味の素材。店の方針として自然。"}, {"text": "ユーモラス", "is_correct": false, "explanation": "おかしみのある様子。素材を説明する語として不自然。"}, {"text": "バーチャル", "is_correct": false, "explanation": "仮想の・実体のないという意味。素材の説明としては文が成り立たない。"}, {"text": "グラマラス", "is_correct": false, "explanation": "魅力的で豊満な様子を表す語。素材を説明する文には合わない。"}], "explanations": {"サステイナブル": "環境や資源を守って続けられる、という意味の素材。店の方針として自然。", "ユーモラス": "おかしみのある様子。素材を説明する語として不自然。", "バーチャル": "仮想の・実体のないという意味。素材の説明としては文が成り立たない。", "グラマラス": "魅力的で豊満な様子を表す語。素材を説明する文には合わない。"}, "sentence_index": 0, "correct_answer": "サステイナブル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "資源を使い切るまで続ける、サステイナブルな採掘だ。", "explanation": "ここは〈枯渇させる〉の意味。資源を守って続けるサステイナブルとは反対で、語の意味が合わない。"}, {"text": "被害の直後に、サステイナブルな応急処置をほどこした。", "explanation": "ここは〈一時しのぎ〉の意味。環境や資源を守って続ける意味とは違い、応急処置は一時的な対応。"}, {"text": "在庫をサステイナブルに売り切って、棚を空にした。", "explanation": "ここは〈素早く〉の意味。環境や資源を守って続けるという意味のサステイナブルは、売り切る速さには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37231, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サステイナブル", "is_correct": true, "explanation": "自然を壊す工場には当てはまらない、という否定の文に入る語。正解。"}, {"text": "ドラマチック", "is_correct": false, "explanation": "劇的な様子を表す語。工場の環境評価の文には合わない。"}, {"text": "ミステリアス", "is_correct": false, "explanation": "神秘的な様子を表す語。工場と自然破壊の話とは結びつかない。"}, {"text": "ノスタルジック", "is_correct": false, "explanation": "懐かしい感じを表す語。工場の評価の文には合わない。"}], "explanations": {"サステイナブル": "自然を壊す工場には当てはまらない、という否定の文に入る語。正解。", "ドラマチック": "劇的な様子を表す語。工場の環境評価の文には合わない。", "ミステリアス": "神秘的な様子を表す語。工場と自然破壊の話とは結びつかない。", "ノスタルジック": "懐かしい感じを表す語。工場の評価の文には合わない。"}, "sentence_index": 6, "correct_answer": "サステイナブル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "使い捨てのペットボトルを毎回買い替えるのは、サステイナブルな習慣だ。", "explanation": "ここは〈使い捨て〉の意味。捨て続ける習慣はサステイナブルの意味（環境を壊さず続く）と逆になるので誤り。"}, {"text": "流行の服を次々と買い替えるのは、サステイナブルな買い物だ。", "explanation": "ここは〈流行〉（その時々のはやり）の意味。続けられる仕組みを表す語とは合わない。"}, {"text": "生産ラインをサステイナブルにして、速度を三倍に上げた。", "explanation": "ここは〈スピード〉の意味。サステイナブルは速さではなく、環境や資源を守って続けられることを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37231, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "森を守るために、サステイナブルで林業を広げる。", "corrected_sentence": "森を守るために、サステイナブルな林業を広げる。", "error_description": "形状詞「サステイナブル」が名詞を修飾するときは「な」を付ける。「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "サステイナブル", "is_correct": true, "explanation": "「〜な」の前に来る語幹の形。文中の「サステイナブルな林業」に対応する正しい形。"}, {"text": "サステイナブルだ", "is_correct": false, "explanation": "終止形。名詞を修飾する位置には使えない。"}, {"text": "サステイナブルではない", "is_correct": false, "explanation": "否定形。林業が広がっているという肯定の文には合わない。"}, {"text": "サステイナブルでした", "is_correct": false, "explanation": "過去の丁寧形。「広がっている」の現在の状況と時制が合わない。"}], "correct_form": "サステイナブル", "base_form": "サステイナブル", "form_label": "語幹", "sentence_index": 1, "explanations": {"サステイナブル": "「〜な」の前に来る語幹の形。文中の「サステイナブルな林業」に対応する正しい形。", "サステイナブルだ": "終止形。名詞を修飾する位置には使えない。", "サステイナブルではない": "否定形。林業が広がっているという肯定の文には合わない。", "サステイナブルでした": "過去の丁寧形。「広がっている」の現在の状況と時制が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37231, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場は、資源をサステイナブルへ使うことにした。", "corrected_sentence": "工場は、資源をサステイナブルに使うことにした。", "error_description": "「使う」の方法を表す「に」が必要。「へ」は方向を示すので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "サステイナブル", "is_correct": true, "explanation": "「〜な」の前に来る語幹の形。文中の「サステイナブルな農業」に対応する正しい形。"}, {"text": "サステイナブルでした", "is_correct": false, "explanation": "過去の丁寧形。「土をいためない」という現在の説明と時制が合わない。"}, {"text": "サステイナブルに", "is_correct": false, "explanation": "連用形。名詞を修飾する位置には使えず、文が成り立たない。"}, {"text": "サステイナブルでない", "is_correct": false, "explanation": "否定形。農業の良い点を述べる文の内容と反対になる。"}], "correct_form": "サステイナブル", "base_form": "サステイナブル", "form_label": "語幹", "sentence_index": 7, "explanations": {"サステイナブル": "「〜な」の前に来る語幹の形。文中の「サステイナブルな農業」に対応する正しい形。", "サステイナブルでした": "過去の丁寧形。「土をいためない」という現在の説明と時制が合わない。", "サステイナブルに": "連用形。名詞を修飾する位置には使えず、文が成り立たない。", "サステイナブルでない": "否定形。農業の良い点を述べる文の内容と反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37232, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「雨が降らないという前提で進めた」の「で」で、準備を進める基礎となる考えを示すので正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「前提へ進めた」は方向を示す「へ」になり、基礎を示せないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「前提を、準備を進めた」では前提が動詞の目的語になれず、基礎を示せないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「前提が準備を進めた」は前提を主語にしてしまい、進めたのは人なので合わない。"}], "correct_answer": "で", "explanations": {"で": "「雨が降らないという前提で進めた」の「で」で、準備を進める基礎となる考えを示すので正しい。", "へ": "「前提へ進めた」は方向を示す「へ」になり、基礎を示せないので合わない。", "を": "「前提を、準備を進めた」では前提が動詞の目的語になれず、基礎を示せないので合わない。", "が": "「前提が準備を進めた」は前提を主語にしてしまい、進めたのは人なので合わない。"}, "error_tags": {"で": "基礎・前提（正解）", "へ": "方向の誤り", "を": "目的語の誤り", "が": "主語の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37232, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「前提で授業を進めた」の「で」で、授業を進める基礎となる考えを示すので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「前提が授業を進めた」は前提を主語にしてしまい、授業を進めたのは先生なので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「前提より授業を進めた」は比較の「より」になり、基礎を示す意味にならない。"}, {"text": "の", "is_correct": false, "explanation": "「前提の授業を進めた」は名詞を修飾する形になり、動詞「進めた」の基礎を示せない。"}], "correct_answer": "で", "explanations": {"で": "「前提で授業を進めた」の「で」で、授業を進める基礎となる考えを示すので正しい。", "が": "「前提が授業を進めた」は前提を主語にしてしまい、授業を進めたのは先生なので合わない。", "より": "「前提より授業を進めた」は比較の「より」になり、基礎を示す意味にならない。", "の": "「前提の授業を進めた」は名詞を修飾する形になり、動詞「進めた」の基礎を示せない。"}, "error_tags": {"で": "基礎・前提（正解）", "が": "主語の誤り", "より": "比較の誤り", "の": "連体修飾の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37232, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これからすることを決めるための、もとになる考え。", "primary_collocate": null, "pronunciation": "ぜんてい", "ipa": "dzeɴtei", "syllable_count": 4, "sentences": [{"text": "この計画は、客が増えるという前提で立てた。", "target_word": "前提", "complexity_tier": "T3", "furigana": "この計画[けいかく]は、客[きゃく]が増[ふ]えるという前提[ぜんてい]で立[た]てた。", "sentence_source": "generated"}, {"text": "雨が降らないという前提で、旅行の準備を進めた。", "target_word": "前提", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]らないという前提[ぜんてい]で、旅行[りょこう]の準備[じゅんび]を進[すす]めた。", "sentence_source": "generated"}, {"text": "前提が違えば、出す答えも変わってくる。", "target_word": "前提", "complexity_tier": "T3", "furigana": "前提[ぜんてい]が違[ちが]えば、出[だ]す答[こた]えも変[か]わってくる。", "sentence_source": "generated"}, {"text": "彼は、全員が賛成するという前提で話を始めた。", "target_word": "前提", "complexity_tier": "T3", "furigana": "彼[かれ]は、全員[ぜんいん]が賛成[さんせい]するという前提[ぜんてい]で話[はなし]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "予算が足りないことを前提に、別の方法を考えよう。", "target_word": "前提", "complexity_tier": "T3", "furigana": "予算[よさん]が足[た]りないことを前提[ぜんてい]に、別[べつ]の方法[ほうほう]を考[かんが]えよう。", "sentence_source": "generated"}, {"text": "前提を確かめてから、次の仕事を決めよう。", "target_word": "前提", "complexity_tier": "T3", "furigana": "前提[ぜんてい]を確[たし]かめてから、次[つぎ]の仕事[しごと]を決[き]めよう。", "sentence_source": "generated"}, {"text": "景気がよくなる前提で作った計画は、見直しが必要だ。", "target_word": "前提", "complexity_tier": "T3", "furigana": "景気[けいき]がよくなる前提[ぜんてい]で作[つく]った計画[けいかく]は、見直[みなお]しが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "先生は、生徒が宿題をしてくる前提で授業を進めた。", "target_word": "前提", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]が宿題[しゅくだい]をしてくる前提[ぜんてい]で授業[じゅぎょう]を進[すす]めた。", "sentence_source": "generated"}, {"text": "台風が来る前提で、運動会の日を変えることにした。", "target_word": "前提", "complexity_tier": "T3", "furigana": "台風[たいふう]が来[く]る前提[ぜんてい]で、運動会[うんどうかい]の日[ひ]を変[か]えることにした。", "sentence_source": "generated"}, {"text": "間違った前提から始めると、よい決定はできない。", "target_word": "前提", "complexity_tier": "T3", "furigana": "間違[まちが]った前提[ぜんてい]から始[はじ]めると、よい決定[けってい]はできない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "前提", "label": "基本形"}, {"form": "前提として", "label": "〜として"}], "register": "neutral", "sense_fingerprint": "これから行動を決める土台となる考え・仮定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f48066bd-2190-4cb8-bbf1-f08443cd7da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37232, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前提", "is_correct": true, "explanation": "「〜という」に続いて計画の土台となる考えを表す「前提」が入る。"}, {"text": "結果", "is_correct": false, "explanation": "「客が増えるという結果で計画を立てた」とは言えないので不自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気を根拠に計画を立てるのは不自然で、文の意味が通らない。"}, {"text": "地図", "is_correct": false, "explanation": "地図で計画を立てるとは言わないので、この文には合わない。"}], "explanations": {"前提": "「〜という」に続いて計画の土台となる考えを表す「前提」が入る。", "結果": "「客が増えるという結果で計画を立てた」とは言えないので不自然。", "天気": "天気を根拠に計画を立てるのは不自然で、文の意味が通らない。", "地図": "地図で計画を立てるとは言わないので、この文には合わない。"}, "sentence_index": 0, "correct_answer": "前提"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大きな地震の前提があった。", "explanation": "ここは「前触れ」の意味。「前提」は前もって置く仮定で、前触れの意味はないので合わない。"}, {"text": "彼は、前提を達成するために努力した。", "explanation": "ここは「目標」の意味。「前提」は達成するものではなく、「目標を達成する」と言う。"}, {"text": "彼は、リーダーとしての前提を果たした。", "explanation": "ここは「役割・義務」の意味。「前提」は果たすものではなく、「役割を果たす」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37232, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前提", "is_correct": true, "explanation": "「景気がよくなる〜で作った」の基礎となる考えとして「前提」が入る。"}, {"text": "日記", "is_correct": false, "explanation": "景気がよくなる日記で計画を作ったとは言えないので不自然。"}, {"text": "季節", "is_correct": false, "explanation": "季節を根拠に計画を作ったとは言えないので文が成り立たない。"}, {"text": "花火", "is_correct": false, "explanation": "花火で計画を作るのは不自然で、文の意味が通らない。"}], "explanations": {"前提": "「景気がよくなる〜で作った」の基礎となる考えとして「前提」が入る。", "日記": "景気がよくなる日記で計画を作ったとは言えないので不自然。", "季節": "季節を根拠に計画を作ったとは言えないので文が成り立たない。", "花火": "花火で計画を作るのは不自然で、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "前提"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、悲しい前提を抑えた。", "explanation": "ここは「感情」の意味。「前提」は抑えるものではなく、抑えるのは「感情」なので合わない。"}, {"text": "私は明日の前提を受ける。", "explanation": "ここは「試験」の意味。「前提」は受けるものではなく、「試験を受ける」と言う。"}, {"text": "この薬は病気の前提を治す。", "explanation": "ここは「原因」の意味。病気の原因を取り除く場合は「原因」を対象にし、「前提」は治す対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37232, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この予算は、景気がよくなるという前提に組んだ。", "corrected_sentence": "この予算は、景気がよくなるという前提で組んだ。", "error_description": "「組む」は「〜で組む」の形で、基礎となる前提を「で」で示す。「に」が誤りで、正しくは「で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37232, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、雨が上がるという前提を出発した。", "corrected_sentence": "彼は、雨が上がるという前提で出発した。", "error_description": "「出発する」は前提を「で」で示す。「を」が誤りで、正しくは「で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37233, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「前提になる」の形で、前提という条件がそのまま結果につながることを示す「に」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「前提がなる」は成り立たない。主語を示す「が」では、条件の変化を表す「になる」に続かない。"}, {"text": "で", "is_correct": false, "explanation": "「前提でなる」は文として成り立たない。手段や場所を示す「で」では条件を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「前提へなる」は方向を示す「へ」で、条件の成立を表せない。"}], "correct_answer": "に", "explanations": {"に": "「前提になる」の形で、前提という条件がそのまま結果につながることを示す「に」が正しい。", "が": "「前提がなる」は成り立たない。主語を示す「が」では、条件の変化を表す「になる」に続かない。", "で": "「前提でなる」は文として成り立たない。手段や場所を示す「で」では条件を表せない。", "へ": "「前提へなる」は方向を示す「へ」で、条件の成立を表せない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37233, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「前提に料金が決められている」の形で、加入者が健康であることを条件として示す「に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「前提を料金が決められている」は成り立たない。対象を示す「を」では条件を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「前提と料金が決められている」は条件を示せず、並列の意味にもならない。"}, {"text": "で", "is_correct": false, "explanation": "「前提で料金が決められている」は根拠を示す形として不自然。「で」は手段や場所を表す。"}], "correct_answer": "に", "explanations": {"に": "「前提に料金が決められている」の形で、加入者が健康であることを条件として示す「に」が正しい。", "を": "「前提を料金が決められている」は成り立たない。対象を示す「を」では条件を表せない。", "と": "「前提と料金が決められている」は条件を示せず、並列の意味にもならない。", "で": "「前提で料金が決められている」は根拠を示す形として不自然。「で」は手段や場所を表す。"}, "error_tags": {"を": "対象（目的語）", "と": "並列", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37233, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄が成り立つための、基礎となる条件や考え。", "primary_collocate": null, "pronunciation": "ぜんてい", "ipa": "dzeɴtei", "syllable_count": 4, "sentences": [{"text": "信頼があることが、協力の前提だ。", "target_word": "前提", "complexity_tier": "T3", "furigana": "信頼[しんらい]があることが、協力[きょうりょく]の前提[ぜんてい]だ。", "sentence_source": "generated"}, {"text": "この計算は、水の温度が一定であることが前提になる。", "target_word": "前提", "complexity_tier": "T3", "furigana": "この計算[けいさん]は、水[みず]の温度[おんど]が一定[いってい]であることが前提[ぜんてい]になる。", "sentence_source": "generated"}, {"text": "結婚を前提に、二人は付き合い始めた。", "target_word": "前提", "complexity_tier": "T3", "furigana": "結婚[けっこん]を前提[ぜんてい]に、二人[ふたり]は付[つ]き合[あ]い始[はじ]めた。", "sentence_source": "generated"}, {"text": "全員が規則を守ることを前提に、このゲームは成り立つ。", "target_word": "前提", "complexity_tier": "T3", "furigana": "全員[ぜんいん]が規則[きそく]を守[まも]ることを前提[ぜんてい]に、このゲームは成[な]り立[た]つ。", "sentence_source": "generated"}, {"text": "理解の前提には、基本的な言葉の知識が必要だ。", "target_word": "前提", "complexity_tier": "T3", "furigana": "理解[りかい]の前提[ぜんてい]には、基本的[きほんてき]な言葉[ことば]の知識[ちしき]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "相手の話を聞くことは、よい会話の前提だ。", "target_word": "前提", "complexity_tier": "T3", "furigana": "相手[あいて]の話[はなし]を聞[き]くことは、よい会話[かいわ]の前提[ぜんてい]だ。", "sentence_source": "generated"}, {"text": "練習を続けられることが、上達の前提となる。", "target_word": "前提", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を続[つづ]けられることが、上達[じょうたつ]の前提[ぜんてい]となる。", "sentence_source": "generated"}, {"text": "この保険は、加入者が健康であることを前提に料金が決められている。", "target_word": "前提", "complexity_tier": "T3", "furigana": "この保険は、加入者が健康であることを前提[ぜんてい]に料金が決められている。", "sentence_source": "generated"}, {"text": "自由に意見を言える場が、民主的な話し合いの前提だ。", "target_word": "前提", "complexity_tier": "T3", "furigana": "自由[じゆう]に意見[いけん]を言[い]える場[ば]が、民主的[みんしゅてき]な話[はな]し合[あ]いの前提[ぜんてい]だ。", "sentence_source": "generated"}, {"text": "この制度は、税金を払うことを前提に作られている。", "target_word": "前提", "complexity_tier": "T3", "furigana": "この制度[せいど]は、税金[ぜいきん]を払[はら]うことを前提[ぜんてい]に作[つく]られている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "前提", "label": "基本形"}, {"form": "前提として", "label": "〜として"}], "register": "neutral", "sense_fingerprint": "物事が成り立つための基礎となる条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f48066bd-2190-4cb8-bbf1-f08443cd7da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37233, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前提", "is_correct": true, "explanation": "「協力の前提だ」で、信頼が協力を成り立たせる基礎の条件を指し、文の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「協力の天気」は意味が通らない。天気は協力が成り立つ条件にはならない。"}, {"text": "手紙", "is_correct": false, "explanation": "「協力の手紙」は合わない。手紙は協力の基礎条件を表さない。"}, {"text": "駐車場", "is_correct": false, "explanation": "「協力の駐車場」は意味が通らない。場所を表す名詞で、条件は表せない。"}], "explanations": {"前提": "「協力の前提だ」で、信頼が協力を成り立たせる基礎の条件を指し、文の意味に合う。", "天気": "「協力の天気」は意味が通らない。天気は協力が成り立つ条件にはならない。", "手紙": "「協力の手紙」は合わない。手紙は協力の基礎条件を表さない。", "駐車場": "「協力の駐車場」は意味が通らない。場所を表す名詞で、条件は表せない。"}, "sentence_index": 0, "correct_answer": "前提"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この前提は千円だ。", "explanation": "ここは〈値段〉の意味。前提は条件を指す言葉で、金額を表すことはない。"}, {"text": "ピアノの前提を毎日練習している。", "explanation": "ここは〈基礎〉の意味。前提は成り立つための条件で、練習して身につける対象にはならない。基礎なら練習の対象になる。"}, {"text": "来週の土曜は、友達と会う前提が入っている。", "explanation": "ここは〈予定〉の意味。予定は日時に入れるものだが、前提は話の土台となる条件で、日程には入らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
